with v(numero,viejo,nuevo,sec) as (values
(1,'12ad7f8cee2a604fbdee89b1bc054702','3883b0cd289533d4427dad77d158e8e4',$q$[{"titulo": "Idea central", "texto": "Èjìogbè es luz, camino abierto y equilibrio. Es el primero de los Odù y el padre de todos: habla de paz, prosperidad, hijos, victoria sobre los enemigos, despertar espiritual y larga vida. Todo eso llega por la vía de la verdad: Ifá pide aquí, antes que nada, honestidad y buen carácter, y que la persona consulte siempre antes de tomar decisiones importantes.", "pasajes": [{"titulo": "Frase clave", "texto": "Ogbe crea un camino abierto.", "origen_id": "7e049425b59a4890fc9e6a9e"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere empezar un proyecto o hacer crecer un negocio que no ha despegado; está buscando otra forma de trabajar o de vender.", "Busca paz y estabilidad, además de dinero. Ve oportunidades, pero alguien o algo le estorba el paso.", "Desea tener hijos o agrandar la familia (relato de la familia de Àgbọnnìrègún).", "Se acerca un viaje o un cambio de lugar que puede endulzarle la vida si se prepara antes (relato de Odunkun, el camote).", "Hay chismes o calumnias en la casa, el trabajo o la calle, pero puede salir adelante (relato de Òrúnmìlà acusado).", "Recibió un bien y no lo está valorando (relato del agricultor y el plátano).", "Se le abre un camino y debe decidir cómo aprovecharlo sin volverse soberbio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Negocios nuevos y grandes, ampliación de lo que ya se tiene y nuevas formas de ganarse la vida.", "Hijos y crecimiento de la familia.", "Victoria sobre los enemigos que bloqueaban el camino; derrota de la calumnia en la casa y en la calle.", "Un viaje que endulza la vida y hace brillar a la persona por encima de los demás.", "Paz mental, salud y larga vida, si la persona se cuida.", "Nuevas amistades, nuevas relaciones y experiencias espirituales."]}, {"titulo": "Ibi y advertencias", "puntos": ["La ingratitud: pagar con mal el bien recibido, como el agricultor que cortó al plátano que lo alimentaba.", "Perder la cabeza: decidir por impulso, euforia o pasión en lugar de pensar.", "Celos obsesivos que solo se curan con sentido común.", "Calumnias dentro y fuera de la casa.", "Trabajar o negociar sin ganancia mientras no se hace la ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "La honestidad es lo más importante en la vida de una persona: quien vive en la verdad nunca queda sin raíz. Los honestos son pocos y los deshonestos muchos, pero Ifá pide sumarse a los pocos. Junto con eso, Èjìogbè enseña gratitud: el que recibe bien debe saber reconocerlo, porque el ingrato termina destruyendo lo que lo sostenía."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Este Odù habla de buena luz, de bienestar general, de la victoria sobre los enemigos, de un despertar espiritual, de larga vida y paz mental (tranquilidad).", "origen_id": "557ad6e6c1bfc20297951942"}, {"titulo": "Características generales", "texto": "Èjìogbè es el Odù más importante. Simboliza el principio masculino y por lo tanto se mira como el padre de los Odù. En el orden fijo de Ọ̀rúnmìlà, Èjìogbè ocupa la primera posición.\nEn Èjìogbè, los dos lados del Odù son idénticos: Ogbè está en los lados izquierdos y derechos. El Odù se debe llamar \"Ogbè Méjì\", pero es universalmente conocido como Èjìogbè, porque èjì significa \"dos\". Hay un equilibrio de fuerzas en Èjìogbè, que es siempre un buen presagio.\nDurante una sesión de adivinación, el cliente para quien se adivina Èjìogbè está buscando paz y prosperidad. El cliente ha consultado Ifá porque él o ella desean tener hijos (ampliación familiar o en cualquier otro sentido) o desea emprender un nuevo proyecto. Ifá dice que si el cliente hace un ofrecimiento, todas sus demandas serán satisfechas y todas sus empresas y proyectos serán acertados.\nEl sacrificio es necesario para ganar la victoria sobre los enemigos que pudieran bloquear al cliente. Si él o ella han estado trabajando sin progreso o ha estado negociando sin beneficio, se predice prosperidad o abundancia si la persona hace los sacrificios necesarios.\nEn Èjìogbè, Ifá predice larga vida si el cliente se ocupa y cuida de su salud. Las personas encarnadas en este Odù Èjìogbè deben consultar siempre el oráculo antes de tomar cualquier decisión importante en vida.", "origen_id": "d99d0a8c447f02aea70db111"}, {"titulo": "Interpretación tradicional", "texto": "Ogbe es una manifestación de luz pura. Es la expansión de luz de un origen hacia fuera. En términos prácticos, es un movimiento sin oposición o un camino abierto. Ogbe como una expresión de crecimiento espiritual, representa una alineación perfecta con el destino. Ifá enseña que cada persona elige un destino antes de regresar a la tierra en el ciclo de reencarnación (atunwa). Ifá enseña que si una persona vive en armonía con su destino, la Naturaleza proveerá una bendición de larga vida, abundancia y familia. Fallar vivir en armonía con el destino, genera enfermedad, pobreza y soledad. Ifá enseña que si una persona está insegura acerca de su destino, debe vivir en alineación con los principios de un buen carácter porque se cree que todos somos hereditariamente buenos. Cuando una persona está en alineación perfecta con su destino, el problema más inminente es la posibilidad de moverse fuera de alineación. Cuando Ogbe aparece, trae una admonición para quedarse vigilando en el proceso de que se manifieste el buen carácter. La manifestación negativa de Ogbe en términos personales es la arrogancia.", "origen_id": "e58c01447f5ab1cf1fb2b92c"}, {"titulo": "Orientación complementaria", "texto": "La referencia a un camino abierto es un símbolo para el concepto de estar en alineación con el destino personal. Ifá enseña que viviendo en alineación con el destino crea bendiciones.", "origen_id": "f7858cc98ccfee9100e777d7"}]}, {"titulo": "Relatos reunidos", "puntos": ["Eleremojú y el Ifá de su hijo. Tres adivinos, Ọwọ́ t'ara (las manos pertenecen al cuerpo), Ẹsẹ̀ t'ara (los pies pertenecen al cuerpo) y Ọtaratara, consultaron para Eleremojú, la madre de Àgbọnnìrègún, cuando ella enfrentaba problemas. Le marcaron dos gallinas, dos palomas y 3,200 cauríes para apaciguar el Ifá de su hijo, y le aseguraron que su vida sería próspera. Ella cumplió y prosperó.", "Eleremojú y los hijos de Ikin. Otro adivino, Òtítọ́l'omifi-ntẹ'lẹ-ìṣà, consultó también para Eleremojú y le dijo que los hijos de Ikin, las dieciséis nueces sagradas de su hijo, la iban a levantar si seguía haciendo sus ofrendas. Le marcó una rata awosin, una gallina o una chiva, y medicina de Ifá: dieciséis hojas de egbee machacadas en agua para lavarle la cabeza. Ella obedeció.", "Àgbọnnìrègún y los hijos sin número. Las esposas de Àgbọnnìrègún no lograban embarazarse. Los adivinos le dijeron que si ofrendaba tendría tantos hijos que nunca sabría cuántos, en vida y después de su muerte. Le marcaron una chiva y medicina de Ifá: una sopa con hojas de yẹnmẹyẹnmẹ y àgbọnyin, condimentada con semillas de irugba u ogiri y pimienta iyèré, cocinada con las trompas de la chiva; la olla se pone delante del Ifá y ahí comen las esposas. Él cumplió y tuvo muchos hijos.", "El agricultor y el plátano. Ökùnkùn-birimubirimu consultó para Ẹniunkokunjú, que quiere decir 'el que no tiene consideración', y le advirtió que nadie le había hecho un bien que él no hubiera pagado con un mal. Le marcaron un machete y una escalera de mano, y se negó a ofrendar. Ẹniunkokunjú es el agricultor: el plátano lo alimentó y le dio todo lo bueno que tenía, y al final el agricultor le cortó el tallo. Por eso este Odù advierte contra la ingratitud y contra perder la cabeza.", "Odunkun, el camote, viaja a la tierra. Odunkun iba de viaje a la tierra donde vivían el ñame (Isu) y el maíz (Agbado). Ifá le aconsejó ofrendar para que su vida fuera más dulce que la de ellos. Cumplió. Cuando la gente de la tierra probó al ñame y al maíz, ninguno resultó tan dulce como el camote. Feliz, Odunkun quiso repetir la ofrenda una y otra vez, pero Ifá le dijo que no hacía falta. Cantó: 'Vida de camote, más dulce que la miel; que los inmortales hagan dulce mi vida'. Quien saca este Odù está por viajar y le espera vida larga, abundancia e hijos; su estrella brillará por encima de los que encuentre en el camino, y debe comer camote como medicina de buena fortuna.", "La calumnia en la casa y en la calle. Ifá consultó para la Calumnia de la casa, para la Calumnia de la calle y para Ọ̀rúnmìlà, y les pidió a todos ofrendar. Las dos calumnias se negaron; Ọ̀rúnmìlà cumplió y venció a sus enemigos dentro y fuera de su casa. Cantó: 'Calumnia de la casa, calumnia de la calle, ¿qué te compré yo?'. Hay quien habla mal de la persona en el hogar y en el trabajo; con la ofrenda se impone y recibe abundancia. Los inmortales insisten en la justicia.", "Ògo tééré y el origen de los hijos. Ifá consultó para Ògo tééré cuando iba a llevar la guerra a una ciudad. Le pidieron ofrecer, ofreció, y le mandaron hacer una guerra sin tregua, tomar hombres y mujeres y traer al mundo 'cautivos sin dientes'. Es la imagen de la unión del hombre y la mujer: la ciudad es la mujer, Ògo tééré es el hombre, y los cautivos sin dientes son los recién nacidos. Así Olódùmarè dio esposas, esposos e hijos a cada quien, y desde entonces la vida se hizo placentera.", "Los honestos son menos de veinte. Ifá consultó para Ọ̀rúnmìlà cuando estaba triste por tanta maldad en el mundo: los honestos eran menos de veinte y los malvados más de ciento cuarenta mil. Le pidieron ofrecer siempre para que no faltaran personas honestas en la Tierra. Ofrecieron, y al poco tiempo empezaron a aparecer los honestos y la vida se equilibró. Las divinidades no aceptan que se comprometa la verdad."], "pasajes": [{"titulo": "Verso 1.1", "texto": "(Ọwọ́ t'ara) \"Las manos pertenecen al cuerpo\",\n(Ẹsẹ̀ t'ara) \"Los pies pertenecen al cuerpo\",\nỌtaratara:\nadivinaron Ifá para Eleremojú,\nla madre de Àgbọnnìrègún.\nLe aconsejaron sacrificar:\ndos gallinas, dos palomas\ny tres mil doscientos cowries,\npara ser usados en apaciguar el Ifá de su hijo.\nEllos dijeron:\n\"su vida (de ella) será próspera\".\nElla obedeció e hizo el sacrificio.", "comentario": "Ọwọ́ t'ara, Ẹsẹ̀ t'ara y Ọtaratara son los nombres de los tres adivinos que consultaron el Oráculo de Ifá para Eleremojú, la madre de Àgbọnnìrègún (uno de los títulos de la alabanza de Ọ̀rúnmìlà), cuando ella estaba confrontando problemas. Ella convino en realizar el sacrificio y apaciguó el Ifá de su hijo (Ikin, las dieciséis nueces de palma). Ella se hizo próspera porque sacrificó las cosas que estaban prescritas.\nEl sacrificio juega un papel importante y esencial en el sistema de creencias Yorùbá y de la religión tradicional. Haciendo los sacrificios necesarios los seres humanos pueden vivir una larga y pacífica vida en la Tierra, atrayendo la buena fortuna y alejando las desgracias.", "origen_id": "eab023d2882f351942b5d495"}, {"titulo": "Verso 1.2", "texto": "Òtítọ́l'omifi-ntẹ'lẹ-ìṣà:\nadivinó Ifá para Eleremojú,\nla madre de Àgbọnnìrègún.\nIfá le dijo:\n\"los hijos de Ikin podrían ayudarla (levantarla)\",\npor eso ella debía sacrificar:\nuna rata awosin,\nuna gallina o una chiva,\ny medicina de Ifá.\nElla obedeció e hizo el sacrificio.", "comentario": "Otro adivino llamado Òtítọ́l'omifi-ntẹ'lẹ-ìṣà también adivinó Ifá para Eleremojú, la madre de Àgbọnnìrègún. Ifá confirmó que sus hijos (los dieciséis Ikines de palma) la ayudarían si ella si continuaba con sus sacrificios.\nLos adivinos de Ifá también son botánicos. Ellos están bien instruidos en la medicina tradicional, porque saben que todas las plantas, hierbas y hojas en el mundo pertenecen a Ifá. Los conocimientos sobre los valores medicinales y espirituales de estas pueden ser encontrados en las enseñanzas de Ifá. Por eso en muchas ocasiones los adivinos de Ifá prescriben trabajos con hierbas y plantas para curar o prevenir enfermedades. En este verso del Odù se recomienda lavar la cabeza (Orí) del cliente con hojas de egbee; Orí es quien se cree controla el destino de cada persona.\n1 egbee (egbèé): LACCOSPERMA SECUNDIFLORUM (P. Beauv.) Kuntze, Palmae.; TRACHYPHRYNIUM sp., Maranthaceae.", "origen_id": "c1378a653e019bcc2c257654"}, {"titulo": "Verso 1.3", "texto": "Ọtọ̀ọ̀tọ̀,\nỌrọ̀ọ̀rọ̀,\n¿Comemos por separado ẹpà?\n¿Comemos por separado ìmùmù?\nExcesivamente queremos a Ọba'Mákin, el rey de la tierra Ìrànjé:\nadivinaron Ifá para Àgbọnnìrègún.\nLos adivinos dijeron:\n\"si él sacrifica será bendecido con tantos hijos\nque nunca sabrá la cantidad de hijos\nque llegará a tener durante y después de su vida\".\nLe aconsejaron sacrificar\nuna chiva (cabra hembra) y medicina de Ifá.\nSi él ofrecía el sacrificio,\nse debía preparar una medicina de Ifá\npara que sus esposas comieran.\nÉl obedeció y sacrificó.", "comentario": "Las esposas de Àgbọnnìrègún hallaron muy duro conseguir embarazarse y producir niños. Los cinco adivinos hicieron énfasis en la importancia del sacrificio; le dijeron que si realizaba el sacrificio tendría muchos hijos durante su vida y después de su muerte. Los adivinos emplearon sus conocimientos de la medicina tradicional para cocinar las hojas de àgbọnyin con las trompas de Falopio de la cabra sacrificada. Esta medicina fue comida por las esposas de Àgbọnnìrègún para tener muchos hijos, tal como lo predice Ifá.\n2 èpà: maní, cacahuete. ALCHORNEA CORDIFOLIA (Schumach. & Thonn.) Mull.Arg., Euphorbiaceae.\n3 imumu: Tipo de nuez, CYPERUS ESCULENTUS L., Cyperaceae.\n4 Ọba'Makin: nombre de alabanza de Òrìṣà-nlá.\n5 Ìrànjé: pueblo natal de Ọbàtálá.\n6 yẹnmẹyẹnmẹ: planta no identificada.\n7 àgbọnyin: PIPTADENIASTRUM AFRICANUM (Hook. f.) Brenan, Leguminosae Mimosoideae.\n8 Nota: irugba: PARKIA BIGLOBOSA (Jacq.) Benth., Leguminosae Mimosoideae. De la planta irugba se emplean las hojas, corteza, flores, pulpa del fruto y semillas. Las semillas se usan como condimento en sopas y salsas. Como esta medicina no dice qué parte de la planta usar, hay que deducir que se usan las semillas para aderezar la sopa. El verso original yoruba dice: “lọ ewé yẹnmẹyẹnmẹ, àgbọnyin, irugba tabi ogiri pẹlu iyèré”, donde “lọ” es el verbo “triturar”, yẹnmẹyẹnmẹ, àgbọnyin y irugba son plantas, “tabi” es la conjunción “o” que significa alternativa entre dos cosas, en este caso entre irugba y el condimento “ogiri pẹlu iyèré” (ver nota de página siguiente) de lo cual se deduce que de la planta irugba se usa un elemento que sirva para condimentar, y son sus semillas machacadas las que se emplean para condimentar las sopas.\n9 ogiri: condimento que se prepara reduciendo a polvo las pepitas de las semillas de “bàrà” después de tostadas o fritas.\n10 bàrà: tipo de melón o calabaza. CITRULLUS COLOCYNTHIS (L.) Schrad., Cucurbitaceae; Citrullus lanatus (Thunb.) Mansf., Cucurbitaceae.\n11 iyèré: pimienta negra africana: PIPER CAPENSE L.f., Piperaceae. PIPER GUINEENSE Shumach. & Thonn., Piperaceae.", "origen_id": "d16dcd2c5b95e1b65bdc2f6b"}, {"titulo": "Verso 1.4", "texto": "Ökùnkùn-birimubirimu:\nadivinó Ifá para Ẹniunkokunjú (la ingratitud).\nEllos dijeron:\n\"nadie ha tenido para él un bien\nque él no hubiera pagado con un mal\".\nEllos pidieron que sacrificara:\nun machete y una escalera de mano.\nÉl rechazó sacrificar.\nEniunkokunjú,\nes el nombre con que llamamos al granjero.\nTodas las cosas buenas que Ọgèdẹ̀ (el plátano)\nproporcionó al granjero, no fueron apreciadas.\nEl granjero finalmente decapitó a Ọgèdè\n(le cortó el tallo).", "comentario": "Ifá a menudo habla en parábolas. Esta historia relata la relación entre el plátano (Ọgẹ̀dẹ̀), que fue amable y agradable con el granjero (Àgbẹ̀), quien resultó ser un ingrato al devolver los favores de Ọgẹ̀dẹ̀ con maldad. Sin importar cuán bueno es Ọgẹ̀dẹ̀, al final el plátano es cortado y destruido.\nEn épocas remotas, cualquier persona que encarnara este Odù se le decía que podía ser decapitado al final de su vida en la Tierra. En épocas modernas se refiere más a alguien “sin cabeza” o que “pierde la cabeza”.\n12 Ẹniunkokunjú: Aquel que no tiene consideración; la ingratitud.\n13 Nota: La frase “perder la cabeza” significa tomar malas decisiones, motivadas por estados emocionales, el entusiasmo, la euforia, la excitación o la pasión, en vez de decidir usando la inteligencia, la lógica y la razón. La persona con este Odù paga un alto costo social por sus errores.", "origen_id": "a9b6fb198cb2640ce569695d"}, {"titulo": "Versos complementarios 1", "texto": "Este verso de Ifá es de hecho el más importante\npara todos los que practican Ifá y para las personas\ndel Mundo. Ifá nos pide ser honestos y decentes. La\nverdad es la cosa más importante en la vida del ser\nhumano. Si se vive dentro de la verdad, nunca se\ncaerá en desarraigo.\nEn los momentos que vivimos la mayor parte de los\nseres humanos son deshonestos y solo una pequeña\nparte viven dentro de la sinceridad.\n\n                   Òtóótó\n                   Òróóró\n              Òtòòtò làá jèpà\n             Òtòòtò làá jèmumu\n  Lótò lótó ni wóón folú esunsuun sénu\n              Ohun torí ni torí\n             Ohun tòòri ni tòòri\n Ohun torí tòòri làá rò fÒba Mòkín ní òde\n                    Ìrànjé\n  Kí Onirànjé ó lè baà fòtòtò èèyàn tani\n                     lórẹ\n            Béèrún bá jà tó bá tà\n             Wón a fòwó lówòó\n             Wón a fi giyàn balè\n            A dífá fún Ògo tééré\n  Èyi ti ń gbóguún lợ ilú gbèňdù gbẹndu\n               èyin ợwợnràn\n         Wón ni kí Ògo tééré ó rúbợ\n            Ògo tééré si gbó ẹbợ\n                     Ó rú\n                 Ó gbó èèrù\n                     Ó tu\n\n    Lódò okùnrin ni Ògo tééré wá\n    Ìlú gbèňdù gbẹndu ń bẹ lódò\n            Èyi obinrin kan\n               Ìlú kan ni\nWón ni kí Ògo tééré ó lòó jagun nílùú\n            gbèňdù gbẹndu\n             Ó jagun jagun\n           Ó fokùnrin sèmú\n             Ó jagun jagun\n            Ó obinrin sèmú\n    Ó lòó mú ará ilú àìheyín wáyé\n        Kó móo lòó di ìgbèkùn\n         Ìgbèkùn táa bá di yíí\n         Ợmợ láá mùú bó ńbè\nÌgbèkùn òhún náà lá ń di lódò obìnrin\n                Tée dòní\n  Olódùmarè yóó fi obìnrin rere ké\n             ẹnìkòòkan wa\n     Yó si fì ợmợ rere ké wa pèlú\n             Àwợn ń şe béè\n             Ó dáa fún wợn\n           N ní wón wá ń jó\n            Ní wón wá ń yò\n      Wón ń yin àwợn babaláwo\n       Àwợn babaláwo ń yin Ifá\nWón ni béè làwợn babaláwo tàwón wi\n                 Òtóótó\n                 Òróóró\n            Òtòòtò làá jèpà\n          Òtòòtò làá jèmumu\nLótò lótó ni wóón folú esunsuun sénu\n            Ohun torí ni torí\n          Ohun tòòri ni tòòri\n\n Ohun torí tòòri làá rò fÒba Mòkín ní òde\n                     Ìrànjé\n  Kí Onirànjé ó lè baà fòtòtò èèyàn tani\n                      lórẹ\n            Béèrún bá jà tó bá tà\n              Wón a fòwó lówòó\n             Wón a fi giyàn balè\n             A dífá fún Ògo tééré\n  Èyi ti ń gbóguún lợ ilú gbèňdù gbẹndu\n                 èyin ợwợnràn\n                  Yóó jà jàà jà\n            Yóó fợmợkùnrin sèmú\n                  Yóó jà jàà jà\n            Yóó fợmợbìnrin sèmú\n       Yóó mùú ará ìlú àìheyín wáyé\n               Ìgbèkùn táa bá di\n                Ợmợ ní a rí níbẹ\n              Ìgbèkùn táa bá di.\n\nÒtóótó\nÒróóró\nSeparadamente, uno tiene que comer chufas\nSeparadamente, uno tiene que comer cerezas\nEn alimentos separados, se deberá poner Olú\nEsunsun en la boca\nLas entidades de Orírí pertenecen a Orírí\nLas entidades de Òrìrì pertenecen a Òrìrì\nEn los hechos de Orírí y Orírí, se tendrá que\nrelacionar al rey Mòkín de la ciudad de Ìrànjé\nY ese mismo Onirànjé dio como regalo a uno, una\npersona especial\nCuando los soldados hormigas, pusieron sitio a algo\ny le picaban\nY entrarían con un ejército que nos arrasaría\ncompletamente\n\nLlenando de terror a sus cautivos\nLanzaron Ifá para Ògo tééré, quien traía la guerra a\nla ciudad de gbèňdù gbẹndu èyin ợwợnràn\nLe pidieron que sacrificase\nÉl escuchó y sacrificó. También escuchó acerca de\nlibres botines.\nY los cedió a la vez que lo permitía\nÒgo tééré está con el hombre\nLa ciudad de gbèňdù gbẹndu está con la mujer. La\nparte de atrás de una mujer\nEs una acuñación separada de otra ciudad\nEllos le pidieron a Ògo tééré, ir y establecer la\nguerra en la ciudad de gbèňdù gbẹndu\nÉl debía establecer una guerra implacable\nY tomar como prisioneros a los hombres y a las\nmujeres\nY brindarle a la tierra, esos cautivos sin dientes\nAdemás formar los artilugios que hasta hoy forman\ny dan fuerza a nuestros hijos. Los mismos que forma\nel hombre dentro de la mujer en nuestros días\nY así Olódùmarè entregó a cada uno, esposas y\nesposos, al igual que los hijos\nEllos continuaron este orden y la vida les fue más\nplacentera\nEllos bailaron y alabaron a sus babaláwo\nLos babaláwo alabaron a Ifá\nÒtóótó\nÒróóró\nSeparadamente, uno tiene que comer chufas\nSeparadamente, uno tiene que comer cerezas\nEn alimentos separados, se deberá poner Olú\nEsunsun en la boca\nLas entidades de Orírí pertenecen a Orírí\nLas entidades de Òrìrì pertenecen a Òrìrì\nEn los hechos de Orírí y Orírí, se tendrá que\nrelacionar al rey Mòkín de la ciudad de Ìrànjé\n\nY ese mismo Onirànjé dio como regalo a uno, una\npersona especial\nCuando los soldados hormigas, pusieron sitio a algo\ny le picaban\nY entrarían con un ejército que nos arrasaría\ncompletamente\nLlenando de terror a sus cautivos\nLanzaron Ifá para Ògo tééré, quien traía la guerra a\nla ciudad de gbèňdù gbẹndu èyin ợwợnràn\nÉl vino al combate y capturó mujeres y hombres\nLos artilugios formados por nosotros, se ruega se\nconviertan en niños\n\n           Olóòótó ti ń bẹ layé\n            Wón ò pógún mó\n          Sìkàsìkà ti ń bẹ níbè\n                 Wón pò\n         Wón si ju ẹgbàábèje lợ\n           A dífá fún Òrúnmìlà\n  Nijó òrò gbogbo ó mó dùn ún nínú\n        Ifá pé òótó ni ká móợ sợ\n    Irúnmợlè ò níí jé á sợ òótó nu o\n Wón ni ki wón ó móợ rúbợ ki Olóòótó ó\n                    pò\n              Wón ba rúbợ\n        Olóòótó bèrè síí wà láyé\n              Ayé ba ń gún\n      Wón ní Olóòótó ti ń bẹ layé\n            Wón ò pógún mó\n          Sìkàsìkà ti ń bẹ níbè\n                 Wón pó\n         Wón si ju ẹgbàábèje lợ\n           A dífá fún Òrúnmìlà\n  Nijó òrò gbogbo ó mó dùn ún nínú\n\n          Ire ajé ni bá ń dùn wá\n            Kó móợ dun ipíin wa\n               Ká rájé rere ni\n             Òrò tí bá ń dunni\n             Kó jé àrankàn ẹni\n          Ire aya ni bá ń dùn wá\n            Kó móợ dun ipíin wa\n               Ká ráya rere fẹ\n      Òrò tí bá ń dunni làrankàn ẹni\n         Ire ợmợ ni bá ń dùn wá\n            Kó móợ dun ipíin wa\n              Ká rómợ rere bí\n      Òrò tí bá ń dunni làrankàn ẹni\n           Ire ilé ni bá ń dùn wá\n            Kó móợ dun ipíin wa\n               Ká rílé rere kợ\n      Òrò tí bá ń dunni làrankàn ẹni\n    Gbogbo ire ti bá ń dùn wá nílé ayé\n            Kó móợ dun ipíin wa\n             Ká rí rere gbámú\n        Gbogbo Òrò tí bá ń dunni\n               N làrankàn ẹni\n\nLa honestidad está en la tierra en número menor de\nveinte\nLos deshonestos y malos son muchos más de ciento\ncuarenta mil\nLanzaron Ifá para Òrúnmìlà\nCuando se entristecía por todos, debido a la\ncompilación de malos sucesos e incidencias\nhumanas malignas.\nIfá nos exhorta a ser honestos.\nLas divinidades no permitirán comprometer a la\nverdad.\n\nA ellos se les pidió ofrecer siempre en busca de que\nsiempre existieran hombres honestos en la Tierra.\nEllos sacrificaron y poco tiempo después, los\nhombres honestos comenzaron a aparecer sobre la\nTierra.\nLa vida se volvió algo bien balanceado.\nEllos dijeron que la honestidad está en la tierra en\nnúmero menor de veinte.\nLos deshonestos y malos son muchos más de ciento\ncuarenta mil.\nLanzaron Ifá para Òrúnmìlà.\nCuando se entristecía por todos, debido a la\ncompilación de malos sucesos e incidencias\nhumanas malignas.\nEs la necesidad de riquezas, lo que nos entristece.\nDéjanos entristecer nuestro destino. Porque\ncualquiera podrá lograr buenas fortunas, pero\nsiempre será un punto triste de referencia.\nLa buena suerte de esposas nos entristece.\nDéjanos entristecer nuestro destino. Porque\ncualquiera podrá lograr buenas esposas, pero\nsiempre será un punto triste de referencia.\nLa buena suerte de tener hijos nos entristece.\nDéjanos entristecer nuestro destino. Porque\ncualquiera podrá lograr buenos hijos, pero siempre\nserá un punto triste de referencia.\nLa buena suerte de poseer vivienda nos entristece.\nDéjanos entristecer nuestro destino. Porque\ncualquiera podrá lograr un buen hogar, pero\nsiempre será un punto triste de referencia.\nLas buenas bendiciones nos entristecen.\nDéjanos entristecer nuestro destino.\nPorque siempre será un punto triste de referencia,\nla persistencia por lograr las buenas cosas de la\nvida.", "origen_id": "58abeee8b07f0b66288628a9"}, {"titulo": "Relatos y ofrendas", "texto": "EJIOGBE\n\nNo -hay -un -lugar -en -la -tierra -donde -pueda -ir -que —no-encuentre -la -felicidad, consulta Ifá\npara Odunkun (Camote) en el día en que realizaría el viaje a la tierra de Isu (Name) y Agbádo\n(Maíz). Ifá aconsejó a Odunkun hacer ebo para que su vida fuera más dulce que las de Isu y\nAgbado. Isu y Agbado fueron probados por las personas de la tierra y no fueron tan dulces como\nOdunkun. Fue en ese día que Odunkun bailó y cantó por felicidad diciendo que él haría el Ebo\nuna y otra vez. Ifá aconsejó que no hubiera valor en repetir el Ebo. Odunkun cantó y bailó en\nalabanza del Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a Olodumare. Cuando\nOdunkun empezó a cantar, Esu puso una canción en la boca de Odunkun. Odunkun empezo a\ncantar;\nAyé Sénrén ti dun, o dunju oyin lo.\nAyé Sénrén ti dun, o dunju oyin lo.\nOrisá je aye mi o dun, Aláyun Gbáláyun.\nOrisá je aye mi o dun, Aláyun Gbáláyun.\nVida de Camote, más dulce que la miel.\nVida de Camote, más dulce que la miel\nInmortales dejen que mi vida sea dulce, o Aláyun Gbáláyun.\nInmortales dejen que mi vida sea dulce, o Aláyun Gbáláyun.\n\nComentario:\n\nIfa dice que esta persona esta a punto de irse a un viaje. Ifa dice que habra una bendicion de vida\nlarga, abundancia e hijos. Ifa dice que la estrella de esta persona brillara encima de todos otros\nquienes esan encontrados en el viaje. Ifa dice que esta persona debe comer camotes como\nmedicina de la buena fortuna.\n\nEtutu (ofrecimiento): 4 eiyele (pichón), 4 akuko (gallo), 1 epo (botella de aceite palma), 1 plato\nblanco, 4 eko (pastel de harina de maiz) áádun (harina de maíz revuelta con aceite), y muchas\ncosas dulces (miel, azúcar, dulce) y 25 nira (dinero), ofrecido a Obátálá y a Ogun.\n\n(Etùù (oferenda); 4 eiyelé (pombo), 4 akukó (galo), 1 epo (garrafa de azeite de dendé),\n1prato branco, 4 ekó (bolos de milho), 4adún (farinha de milho misturada com óleo),\nbastante coisas doces (mel, acúcar, doces) e 25 nira (dinheiro nigeriano), oferecidos a\nÓbatálá e Ògún)\n\nAcogí- l'apa -se -amarró -a -si -mismo -con -una -cuerda. Consulta a Ifá por la calumnia en el\nhogar. La calumnia afuera en la calle y a Orúnmila en el dia en que le dijeron a todos hacer Ebo\nadentro del hogar y afuera en la calle. La calumnia en el hogar y la calumnia afuera en la calle se\nrehusaron hacer Ebo. Orunmila hizo Ebo y fue victorioso sobre sus enemigos en su casa y sobre\nsus enemigos afuera en la calle. Orunmila estaba muy feliz, empezó a cantar ya bailar en\nalabanza del Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a Olodumare.. Cuando\nOrunmila empezó a cantar, Esu puso una canción en su boca. Orunmila cantó:\n\nElénini Ile, Eléniní ode o.\n\nElénini llé, Elénini ode 0.\n\nKini mo ra lowo yin,\nElénini llé, Elénini ode 0.\n\n83\n\nCalumnia en el hogar, Calumnia afuera en la calle.\nCalumnia en el hogar. Calumnia afuera en la calle.\n¿Qué te compré?\n\nCalumnia en el hogar, Calumnia afuera en la calle.\n\nComentario:\n\nIfá dice que los inmortales insisten en la justicia. .1fá dice que esta persona recibirá una bendición\nde abundancia.\n\nIfá dice que hay mucha gente diciendo cosas calumniadoras acerca de esta persona, en ambos, en\nel hogar y en el trabajo.\n\nIfá dice que esta persona se sobrepondrá a sus enemigos. Ifá dice que esta persona debe adorar a\nIfá.\n\nEtutu (ofrecimiento): 3 eiyele (pichón) 1 epo (botella de aceite de palma), 3 eko (pastel de\nharína de maíz) 16 nira (dinero) ofrecidos a Obatala y a Ogun.\n\n(ÉEtùtù (oferenda); 3 eiyelé (pombos), 1 epo (garrafa de azeite de dendé), 3 ekó (bolos de\nmilho) 16 nira (dinheiro nigeriano), oferecidos a Óbatálá e Ògún. Eòwò (tabu): sementes do\ncháo, cogumelos e panos pretos.)\n\nII Tr\n\nII Tr\n\nII Tr\n\nII Tr", "origen_id": "b04a16e8da8a19f6a905b17f"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ejiogbe habla de la buena luz del bienestar, la victoria sobre los\n enemigos, despertares espirituales, larga vida y paz mental (tranquilidad).\n                      WO – Negocios nuevos o de altura (grandes) relaciones o\n                                experiencias espirituales pueden ser esperadas.\n                 Hay posibilidad de un comportamiento de celos obsesivos que\n                                     requieren sentido común para salir de eso.\n            Ejiogbe es el Odu más importante. Simboliza el principio masculino\ny por lo tanto es reconocido como el padre de los Odus. En el orden exacto\n                               de Orunmila, Ejiogbe ocupa la primera posición.\n            En Ejiogbe, los dos lados del Odu son idénticos, Ogbe está tanto en\nel lado derecho como en el izquierdo, por lo tanto el Odu debería llamarse\nOgbe Meji, sin embargo es conocido universalmente como Ejiogbe porque\nel prefijo “Eji” también significa “dos”. Ese es el balance de las fuerzas en\n                                   Ejiogbe, el cual siempre es de buen augurio.\n             En una sesión de adivinación, el cliente a quien le aparece Ejiogbe\n     está buscando paz y prosperidad. El cliente ha consultado Ifá porque él o\n ella quieren tener un niño o desean embarcarse en un nuevo proyecto. Ifá\n        dice que si el cliente hace una ofrenda, todas las peticiones del cliente\n             serán conocidas y todos sus intentos o proyectos serán un éxito. Es\n\nnecesario el sacrificio para obtener la victoria sobre enemigos quienes\n         están obstaculizando al cliente. Si el cliente ha estado trabajando sin\n progresar o comerciando sin beneficios, Ifá predice prosperidad o salud si\n       la persona hace los sacrificios necesarios. En Ejiogbe, Ifá predice vida\n                 larga al cliente si éste se ocupa y toma previsión de su salud.\n         Personas encarnadas en el Odu de Ejiogbe debe siempre consultar el\n       oráculo de Ifá antes de tomar cualquier decisión importante en su vida.\n\n\n1.1 · Las manos pertenecen al cuerpo – los pies pertenecen al cuerpo –\n      Otaratara adivinó Ifá para Eleremoju – la madre de Agbonniregun – ella\n fue preguntada para sacrificar – dos gallinas, dos palomas y 3200 cawries\n  – para ser usados para calmar el Ifá de su hijo – Ellos dijeron que la vida\n               de ella sería próspera – ella obedeció e hizo el sacrificio (☼).\n\n\n1.2 · Otitol omifi-nte´le-isa adivinó Ifá para Eleremoju – la madre de\n       Agbonniregun – Ifá dijo que los ikines de su hijo la ayudaría – ella\n       fue preguntada para sacrificar – una rata awosin, una gallina o una\n  chiva, - y hojas de Ifá (16 hojas de egbee, que se machacan en agua y\n          se usa para lavar la cabeza del cliente). – ella obedeció e hizo el\n                                                               sacrificio (☼).\n\n\n1.3 · Ototooto. Ororooro. Nosotros separadamente comemos groundnut.\n      Nosotros separadamente comemos imumu (nuez especial). Nosotros\n        somos cabeza sobre el inclinado en amor con Oba´Makin. Todos\n               ellos adivinaron para Agbonniregun. Ellos dijeron que si él\n         sacrificaba, él sería bendecido con hijos; él no podría conocer la\n        cantidad de hijos durante y después de su vida. Él fue preguntado\n      para sacrificar una chiva y hojas de Ifá. Si él ofrecía el sacrificio, él\n  tendría que cocinar las hojas de Ifá para que su esposa lo comiera. Él\n       obedeció y sacrificó. Hojas de Ifá: moler las hojas de yenmeyenme\n             (agbonyin), irugba o ogiri (condimentos) con cloves y otros\n        condimentos. Cocinar todo junto con las trompas de falopio de la\n       chiva. Colocar la taza de sopa frente al trono de Ifá y dejar que sus\n           esposas tomen la sopa ahí. Cuando terminen de tomar la sopa,\n                                                 tendrán muchos niños (☼).\n\n\n1.4 · Okunkun-birimubirimu adivinó Ifá para Eniunkokunju – ellos dijeron\n            que nadie le había hecho a él algún favor – que él no haya devuelto\n                con maldad – nosotros le preguntamos a él para sacrificar – un\n        machete y una escalera – él se rehusó para sacrificar - Eniunkokunju,\n              el nombre con que llamamos al granjero – todas las cosas buenas\n            provistas por la banana – para el granjero no fueron apreciadas – el\n                                     granjero decapitó a la banana al final (☼).", "origen_id": "57a8b3b87909e726903ec91a"}, {"titulo": "Relato en inglés 1", "texto": "Qrunmila says it should be done bit by bit; I say it is bit by bit that we should\neat the head of the rat; it is bit by bit that we should eat the head of the fish. The\none who comes from the sea, who comes from the lagoon to receive the head of\nthe cow was not unimportant at Ifẹ! long ago. We are not as large as the elephant\nnor as stout as the buffalo. The sash that is worn underneath is not as fine as the\nsash that is tied on top. No king is as great as the Qni. No string of cowries is\nas long as that of Yemideregbe; Yemideregbe is what we call the Sea Goddess?\n\nQrunmila says that we should measure the length and measure the breadth.\nThe hand reaches much higher than the head; young palm fronds reach much\nhigher than old palm fronds. No forest is so dense that the iroko tree? cannot be\nseen; no music is so loud that the gong cannot be heard. “Mine is important,\nmine is important” is the cry of the Grey Heron.\n\n“Well then, whose affair is most important?\n\n“Clearly Palm Tree’s affair is most important, clearly.\n\n“Qkan sprouts, it reaches the road;\n\n“Clearly Palm Tree’s affair is most important, clearly.\n\n“Qgan sprouts,® it reaches the road;\n\n“Clearly Palm Tree’s affair is most important, clearly.\n\n\"'Mine is important, mine is important’ is the cry of the Grey Heron;\n“Clearly Palm Tree’s affair is most important, clearly.\n\n“No music is so loud that the gong cannot be heard;\n“Clearly Palm Tree’s affair is most important, clearly.”®", "comentario": "1. Ifẹ is the Yoruba city where these verses were recorded, and Qsa is the\nlagoon to the south along the Nigerian coast. The Qni, mentioned below, is the\nking (gba) of Ife. According to Yoruba mythology it was at Ifẹ that the earth was\ncreated by Odua (or Oduduwa), a deity from whom the Qni and other Yoruba kings\nclaim descent. °\n\nAccording to If¢ diviners, this is the first verse of Ifa. It is also the first\nIfa verse written in a santeria note book from Cuba. See Bascom, 1952: 174-176.\n\n2, Olokun is considered to be masculine by some Yoruba groups, but femi-\nnine in Ifẹ. The reference here is to her reputed wealth (Cf. n. 2, verse 249-2),\nNote also the pun on sea (okun) and the cord (okun) on which cowries and beads\nare strung. Y\n\n3. New palm fronds grow out at the top of the oil palm tree (Elaeis guine-\nensis) and stand up, while the old fronds fall down at its side.\n\n4. The iroko or African Oak or African Teak (Chlorophora excelsa) is one\nof the largest trees of the West African rain forest.\n\n5. Both ggan and ọkan were described by informants as vines or creeping\nplants, the former being thorny. Dalziel gives ggan as a name for Combretum\nPlatypterum, C. bracteatum, and C. racemosum; and ọkan for C. mucronatum and\nC. micranthum. He describes the latter as a small tree which often forms thick-\nets. In any event, from the context here and in verse 35-3, it would seem that\nthey are noted for spreading quickly.\n\nThe word yọ is used in this verse with a number of different meanings: to\nappear above, or be higher than; to be heard above; to be more important than;\nto sprout; and as a part of the cry of the Grey Heron.\n6. The importance of the affairs of Palm Tree refers to the use of palm\nnuts in Ifa divination, Otherwise the meaning of this entire verse is obscure,\nprobably because no story accompanies it. It consists solely of phrases compa-\nrable to the names of diviners which introduce other verses (Cf. n. 1, verse 35-\n3); but no divination is cited as a precedent, no sacrifice is specifically stated,\nand there is no specific prediction. However, the implication is that the client\nwill live for a long time, that no one will excell him, that he will be prominent\namong his associates, and that he will succeed in whatever he undertakes. The\nrat and fish mentioned in the verse are the sacrifice, to which snail, kola nut,\nand cold water are usually added.", "origen_id": "f87c827e154f4c089436cc2c"}, {"titulo": "Relato en inglés 2", "texto": "Qrunmila says each should take his own row;1 I say each should take his own\nrow; he says that Twenty Cowries takes his row but cannot finish it.\n\nQrunmila says each should take his own row; I say each should take his own\nrow; he says that Thirty Cowries takes his row but cannot finish it.\n\nQrunmila says each should take his own row; I say each should take his own\nrow; he says that Forty Cowries takes his row but cannot finish it.\n\nI say, “Well then, my father Agbgnnire,? who can complete his row?” He says\nFifty Cowries alone can complete his row, because we cannot count money and for-\nget Fifty Cowries.\n\nIfa says he will not allow the person for whom¢his figure was cast to be for-\ngotten. This person wants to do something; he will “complete his row” in the thing\nhe wants to do.", "comentario": "1, The row (ẹsẹ) refers to a row in the fields to be hoed or weeded. Here,\nand elsewhere in these verses, it is often used in a broader sense to mean any\nundertaking, so that “completing one’s row” means being successful in a given\nventure.\n\n2. Agbgnnire is a shortened form of Agbgnniregun, another name for Qrun-\nmila or Ifa.", "origen_id": "aafb269cb7266ddd0f034406"}, {"titulo": "Relato en inglés 3", "texto": "“The deadfall punishes the ground by striking it and then dragging the game\nalong it, raising dust” was the one who cast Ifa for Qlgmgagbiti! when she cast\nIfa because she wanted children. They said she should sacrifice four pots,? four\nrats, and four fish. Qlgmgagbiti is what we call the Banana, She heard and of-\nfered the sacrifice.\n\nQlomgagbiti had been trying and trying to have children but had not had any;\nshe took five cowries and went to the diviners, and asked what she had to do in\norder to have children. They said she should sacrifice, and she did sacrifice.\nShe sacrificed those things we have mentioned, and she became the mother of\nmany children. From that time on, one always finds young children on the ba-\nnana plant. Children will not be wanting at the hand of the mother, young chil-\ndren will not be wanting at the foot of the banana.\n\nIfa says it is for the sake of children that this person has cast Ifa; if she\nmakes a sacrifice, children will never be wanting on her verandah.*", "comentario": "1. Analyzed as Q-1(i)-gmg-agbiti or One:who-has-child-agbiti. The mean-\ning of agbiti was not known to informants,\n\n2. A small narrow-mouthed pot, holding about a cup. These are generally\nused as containers for the oil applied to the hands and arms.\n\n3. The fruit and the new sprouts are spoken of as the children of the ba-\nnana plant. This verse thus explains why banana bears so much fruit, and why\nso many new plants spring up around it.\n\n4. Note the pun here on verandah (ọdẹdẹ) and banana (ọgẹdẹ).", "origen_id": "9164a1c5be413d00260eca71"}, {"titulo": "Relato en inglés 4", "texto": "“Forest is the forest of fire” and “Grassland! is the grassland of the sun”\nwere the ones who cast Ifa for Qrunmila on the day that he? went to bury medicine\nagainst abiku? in a hole in a refuse heap. When Ọrunmila was troubled by abiku,\nhe went to the diviners “Forest is the forest of fire” and “Grassland is the grass-\n\nland of the sun.”* They told him that he should make a sacrifice, and he sacri-\nficed. From that time on, his wives stopped bearing abiku.\n\nIfa says that abiku are “fighting with” this person; if he is able to sacrifice,\nthey will stop.", "comentario": "1, Qdan is the open grassland north of the rain forests (igbo) of the coast of\nWest Africa.\n\n2, From the literal translation it is obvious that in this verse Qrunmila and\nIfa are the same individual, See also n. 1, verse 18-5,\n\n3, Children who are destined to die, or “born to die.” See Chapter XI, Far-\nrow (1926: 84), and Ellis (1894: 111-114). Another diviner explained that Qrun-\nmila was told to put leaves of Ifa in a pot of water, have his wife pour it over a\nhe-goat, and bury the goat in a refuse heap,\n4. In this verse it is clear that two diviners are referred to, because of the\nuse of “awgn babalawo” and “ati.”", "origen_id": "d0ea04f819a2595ba2a6f082"}, {"titulo": "Relato en inglés 5", "texto": "“Bitter-kola! of the Ogboni society;? very tight ceiling of the smithy” was\nthe one who cast Ifa for Vulture, the child of “Olojongboloro who beats the afin\ndrum’ with those who live at the town of Qra.” Vulture’s children are never seen\non the refuse heap.* Feeble, feeble bitter-kola,® feeble at the town of Ifẹ, feeble\nbitter-kola. Ifa says this person will live to be very old. He says that as we\nnever see young vultures, even so this person will become very old.\n\nVulture asked what he had to do in order to live to old age. He went to the\ndiviners, and they said he should make a sacrifice and sprinkle divining powder\non his head. When Vulture sacrificed and sprinkled the divining powder on his\nhead, it became white, like a person whose hair is turning grey. From that time\non, Vulture’s head has always been white, and it looks like he has grey hair. We\ncannot tell the difference between young and old vultures, because the heads of\nboth are bald.”\n\n\"", "comentario": "1. Garcinia kola.\n\n2. Ogugbo is often an alternate name for the Ogboni society, but in Ifẹ it is\nsaid to be the name of a particular status within the society. Cf. n. 3, verse 181-\n1. . .\n\n3. Informants could not describe this type of drum.\n\n4. This is not literally true. The statement refers to the fact, elaborated\nlater, that all vultures appear to be old,\n\n5. Note the pun here on bitter-kola (orogbo), and old person (arugbo) which\nappears later. This pun is emphasized by applying the adjective “feeble” to the\n\n. bitter-kola, instead of to the old person.\n\n6. In making a sacrifice, the figure (odu) is usually marked in the divining\npowder on the tray. Then some is given to the client to eat, or to put in a line\ndown the center of his head. See Plate 20.\n\n7, This verse explains how Vulture’s head came to be white, and why one\ncannot tell old and young Vultures apart.", "origen_id": "9d67f28efde0c8f366d8840b"}, {"titulo": "Relato en inglés 6", "texto": "1-6 .\n\n“Thin fire on the side of the sky, thin evening star! in the crescent of the\nmoon” was the one who cast Ifa for “One who is widely known,” the name that we\nuse for Sun.’ Ifa says this person will make a name for himself* in the matter\nfor which he has cast Ifa, but that he should sacrifice one rat, one fish, one cock\nwith a comb® on its head, one penny five oninis,® and palm oil. We will take the\nhead of the rat and the fish, and a small piece cut from the comb of the cock. We\nwill put these in an ela leaf,” and grind them together. We will cut twenty-two\nsmall incisions® on the head of the person for whom this figure was cast, and rub\nthis mixture into them.\n\nVenus, the planet which is seen near the new moon,\nLiterally “month”; the moon is usually referred to as ogupa.\nLiterally “day”; the usual word for sun is orun.", "comentario": "4, It is not necessary to add that.the Sun made the sacrifice, and therefore\nbecame known round the world. This is referred to in the title given to him,\n“One who is widely known,” and is brought out more specifically in verses 52-1\nand 103-1,\n\n5. Note that a cock with a comb (ogbe) is required as sacrifice for the figure\nOgbe Meji.\n\n6. The onini is a Nigerian coin worth one-tenth of a penny.\n\n7, Epiphytic Orchidaceae.\n\n8. Medicines are frequently administered by rubbing them into small inci-\nsions (gbere) on the body.\n\nto o e", "origen_id": "aa006135719ef3d6f225f6fb"}, {"titulo": "Relato en inglés 7", "texto": "\"Ifa's bell has a pointed mouth\"1 was the one who cast Ifa for Ore, the wife\nof Agbonniregun.” Ifa says there is a woman who is insolent to her husband. She\nshould be very considerate of her husband, because he is planning to punish her.\nTherefore she should make six loaves® of pounded yams; she should wash her\nhusband’s clothes; she should rub the walls and floor of his house; and she should\ntake a pot of maize beer today to the place where he keeps his Ifa.\n\nOre was Agbgnniregun’s only wife at this time, but she did not love him at\nall. When he went out in public Ore would insult him,\n\nand she refused to prepare food for him, When Agbgnniregun saw his wife’s true\ncharacter, he got ready and gave her away to death, disease, loss, poverty, and\npunishment.‘ On that very day Ore went to sleep and had a dream; when dawn\ncame and she awoke, she took five cowries and went to the diviners to be examined.\nThey said she had had a bad dream because her husband had given her away to\ndeath, disease, loss, poverty, and punishment, Therefore she should take her hus-\nband’s clothes and wash them; she should rub his house twice; and she should pre-\npare six loaves of pounded yams and take them to the place where her husband\nkept his Ifa.\n\nWhen Ore had done all these things, Agbgnniregun came home, When he saw\nthat his wife had washed his clothes and had rubbed the walls and floor of the\nhouse, and as he entered the house and found the six loaves of pounded yams where\nhe kept his Ifa, Agbgnniregun said:\n\n\"Oooooh shoko”; they answered “Bani.”®\n\n“Death do not trouble Ore any more, oh;\n\n“Ore has made pounded yams; Ore has made stew, Ore.\n“Disease do not trouble Ore any more, oh;\n\n“Ore has made pounded yams; Ore has made stew, Ore.\n“Loss, do not trouble Ore any more, oh;\n\n“Ore has made pounded yams; Ore has made stew, Ore.\n“Punishment, do not trouble Ore any more, oh;\n“Ore has made pounded yams; Ore has made stew, Ore.”\n\nIt was in this way that Ore escaped from the things which Agbgnniregun had set\nagainst her in order to punish her,", "comentario": "1. Ifa’s bell is the instrument with which the diviner taps the tray before he\nbegins to divine (see Chapter III and Plate 13). Its tusklike end is referred to here\nas a “pointed mouth.” See also verse 4-3.\n\n2. Qrunmila, Ifa.\n\n3. Pounded yams (iyan or dgmbai) are made into lumps referred to as loaves\n(igba or araba).\n4. He made bad “medicine” so that she would suffer all of these evils.\n\n5. These words, which could not be translated and were not understood by\ninformants, are the introduction to many of the songs and recitations which ap-\npear in the Ifa verses. Even where it is not stated as explicitly as it is here,\nthey always follow the traditional leader-chorus pattern, with the diviner saying\n“Oooooh shoko” and his students and assistants and others who have gathered to\nwatch the divination responding “Bani.” ka", "origen_id": "2e9807095aff4bff9cd7ee13"}, {"titulo": "Relato en inglés 8", "texto": "Qrunmila says we should sigh ‘hin’; I say we should take a breath and rest;\nhe says that the one who sacrifices water will have a breathing spell.\n\nQrunmila says we should sigh ‘hin’; I say we should take a breath and rest;\nhe says that the one who sacrifices ochra will have honor.\n\nQrunmila says we should sigh ‘hin’; I say we should take a breath and rest;\nhe says that the one who sacrifices salt will find satisfaction in his affairs.”\n\nOne calabash of cold water is required. We will pour salt into it; we will\nslice ochra into it also, We will mark Eji Ogbe? in the divining powder; we will\nadd the divining powder to the water also. The person for whom this figure was\ncast will drink of the water, and anyone else who wishes may drink of it also.\nAfterward we will pour whatever is left at the bage of Eshu. Ifa says that the per-\nson for whom we cast this figure wants a breathing spell; he will get a breathing\nspell, and will gain honor also.*", "comentario": "1, “Hin” represents the sound of exhaling air as in sighing.\n\n2. Note the word magic in this verse. Water (omi) is sacrificed so as to\nget a chance to breathe (imi); Ochra (ila) is sacrificed to gain honor (gla). The\nplay on words with reference to salt is once removed. Salt is added to food to\nseason it properly, to make it “sweet” (dun), and is sacrificed here so that one’s\naffairs will go well, so they will be “sweet” (dun).\n\n3. An alternate form of Ogbe Meji, the name of the figure.\n\n4. There is also the clear implication that he will also find satisfaction in\nthe way things are going for him.", "origen_id": "69f47edc81d21c3c334f35ae"}, {"titulo": "Relato en inglés 9", "texto": "“Ponripgn shigidi\"l the diviner inside the forest, “Ogogoro” the diviner of\nIjamg,? and “If a friend is exceedingly dear, he is like the child of one’s own moth-\ner” were the ones who cast Ifa for Qrunmila when he was going to befriend Eshu.\n\n“Those who befriend Eshu are not troubled by want of money;\n“Eshu, you are the one I am going to befriend.\n\n“Those who befriend Eshu are not troubled by want of wives;\n“Eshu, you are the one I am going to befriend.\n\n“Those who befriend Eshu are not troubled by want of children;\n“Eshu, you are the one I am going to befriend.”\n\nWe will kill a cock by tearing it open at the breast. We will break open a snail\nand pour it and palm oil into the cock. We will carry it to the base of Eshu. Ifa\n\nsays this person desires to make a new friendship; the new friend will be of bene-\nfit to him?", "comentario": "1. This phrase could not be translated by informants. Shigidi here is some-\nthing very dangerous, but is not the image (shigidi) used by the Yoruba in sorcery,\nPgnripgn in another connection means thick; but pọn describes the degree of red-\nness of anything, and redness is associated with things which are dangerous or\npowerful.\n\n2. This could be the name of a town, or of a person.\n\n3. There is also the implication of a blessing of money, wives, and children\nin this verse.", "origen_id": "a3bb6785674409e5e9834119"}, {"titulo": "Relato en inglés 10", "texto": "“Because of pounded yams the fingers develop humps;' the thumb stiffens its\nback to split kola nuts”? was the one who cast Ifa for Qrunmila when he was in\nlove with Earth, child of “The one with the pleasing gown.” They said Qrunmila\nshould sacrifice one rat, one shilling three pence, and two hens so that he might\nmarry her, We will tie. any kind of beads about the waist of the rat; we will\n\ntake the rat and stick it into the ground® inside the forest. Qrunmila sacrificed.\n\nEarth was the daughter of the king. She wore two hundred cloths about her\nwaist, and she said that she would marry anyone who saw her bare buttocks. On\nthe morning of the day after Qrunmila had stuck the rat into the ground, Earth\nwent into the forest to defecate. Eshu clapped his hands‘ and the rat came to\nlife, and the beads that Qrunmila had tied about its waist became segi beads.®\nWhen Earth saw the rat with segi beads on its waist, she began to chase it about.\nAs she chased it, all two hundred of the cloths fell from her waist, and she was\nnaked. At the same time Qrunmila came to examine his sacrifice, and he met\nEarth running around naked. When Earth saw Qrunmila, she said, “That does it!”\nShe said she had agreed to marry anyone who saw her bare buttocks, So Earth\nbecame Qrunmila’s wife; Qrunmila brought all her possessions to his house, and\nEarth settled down with him. When Qrunmila had married Earth, he began to sing\nand dance, rejoicing:\n\n“We captured Earth;\n“We will never leave her, oh, ay, ay.”®\n\nIfa says we will find a woman to marry, and that through her we will receive\na blessing. The woman will bring us two hundred of every kind of goods.”", "comentario": "1. Pounded yam is served in large loaves. Since it is tough, the knuckles\nof the fingers appear as humps when small pieces are broken off to eat.\n\n2. Kola nuts are broken into sections before eating. For this the thumbnail\nis used, and the thumb is held rigid, with the thumb making a right angle.\n3. The dried rats used in sacrifices are impaled on sticks. In this case it\nis the stick itself which is stuck into the ground, so that the rat stands up.\n\n4. By clapping his hands, Eshu accomplished this magical transformation.\nCf. verse 244-2.\n\n5. Segi are very valuable beads which are found buried in the ground.\n\n6. There is a double meaning to this’song. The obvious meaning is that we\nlove Earth; our wife, so much that we never wan@to leave her. The second is\nthat we enjoy life on this earth so much that we never want to die,\n\n7, The number 200 is derived from the number of cloths worn by Earth,\nand is not to be taken literally. It simply means that we will come to have a\ngreat many possessions. Cf. verse 14-1. .", "origen_id": "3064237509e22ed982651130"}, {"titulo": "Relato en inglés 11", "texto": "“Ejinrin! spreads and spreads until it enters the town” was the one who cast\nIfa for Qrunmila when he was going to marry Narrow, child of the Sea Goddess,\nThey said Qrunmila should sacrifice two cocks, one hen, a rat, a fish, two bags,”\nand three shillings so that he might be able to marry her.‘ He made the sacrifice.\nWhen Qrunmila went to the Sea Goddess’ house, he took two bags with him. When\nhe arrived, Eshu blinked his eyes? at him, making him very handsome. When\nNarrow saw Qrunmila, she said he was the one she would marry. The Sea God-\ndess said all the Four Hundred Deities had wanted Narrow, but she had refused\nthem; where then could Qrunmila take Narrow to escape their anger? Qrunmila\nsaid he would take her away. Then the Sea Goddess began to be hospitable to\nQrunmila. She said that all the Four Hundred Deities had wanted to marry Nar-\nrow; but finally she had found someone she was willing to marry.\n\nWhen the Four Hundred Deities saw that Narrow loved Qrunmila, they were\nangry; they got ready and dug a pit on the right side; they dug an abyss on the\nleft side; and in front they dug a hole as deep as heaven is high.\n\nWhen Eshu saw this, he took the two cocks that Qrunmila had sacrificed,\n\nHe threw one into the pit on the right, and it closed; he threw the other into the\nabyss on the left, and it closed; he threw the hen‘ into the hole in front, which\nwas as deep as heaven is high, and it closed. The Four Hundred Deities had al-\nready told the ferrymen at the river Qrunmila had to cross that if a diviner\n\ntraveling with a woman should come to them, they must not ferry them across.\nWhen Qrunmila was approaching the ferrymen, he put his wife, Narrow, inside\nof one bag and he put the other bag over her head. He tied her up, and carried\nher. When he came to the river, the ferryman did not know that this was the\ndiviner of whom the Four Hundred Deities had spoken, and he paddled them\nacross the river. When Qrunmila arrived at the market in Ife, he put the bags\ndown and untied them; and his wife stepped out. All of the Four Hundred Deities\nwere disappointed and they were angry; but Qrunmila was dancing and rejoicing.\nHe said:\n\n“Oooooh Shoko.” \"Bani.\"\n\n“Ejinrin spreads and spreads until it enters the town; oh,\n“Was the one who cast Ifa for me, Qrunmila,\n\n“When I was going to marry Narrow, the child of the Sea Goddess.\n“The Four Hundred Deities dug a pit on the right side;\n“The Four Hundred Deities dug an abyss on the left side;\n“In front they dug a hole as deep as heaven is high.\n“They can dig a pit on the right side, oh;\n\n“They can dig an abyss on the left side;\n\n“They can dig a hole in front, as deep as heaven is high;\n“They didn’t say one can’t go to his own house, ‘gbain.’®\n\n“Qrunmila, carry me in your bag; carry me in your purse,\n“So that we may go together slowly;\n“So that wherever we may be going, we may go together.”\n\nIfa says we will marry a woman. Everyone will try to twist us and turn us,\n\nand they will conspire against us; but we should not be afraid. We will marry\nthe woman.", "comentario": "1, A creeping vine (Momordica Balsamina, M, Charantia, or M. foetida).\n\n2. Two empty matlike bags used in carrying and storing money and clothing.\n\n3. This is different from our wink; both eyes are flicked lightly shut at the\nsame time, By doing this, Eshu has the power to fransform a person by making\nthem very ugly or, as in this case, very beautiful.\n\n4. The two cocks, the hen, and the two bags included in the sacrifice are in-\nstrumental in making it possible for Qrunmila to attain his goal.\n5. The traditional introduction to Ifa songs and recitations, See n. 4, verse\n1-7.\n6.. An ekclamation, the meaning of which is not clear.", "origen_id": "11c5b99803fec74301a94737"}, {"titulo": "Relato en inglés 12", "texto": "“He is lost to us through death, is a cry full of pain; I will walk, talking to\nmyself in a very low voice; Cat is the one that dresses in style with raphia\ncloth\"? was the one who cast Ifa for “He scatters dirt with very long feet.\"?\nThey asked, “Is he going to take a slender woman as his wife?” They said it\nwould be bad for him unless he sacrificed sixteen kola nuts, three hens, a new\nblack plate,* a new calabash for covering drinks, and ẹ̀ne penny eight oninis.\nHe did not sacrifice.\n\nHe took the woman as his wife. Afterward sores confined him to his house,\nand he died. Ifa says that if the person for whom this figure was cast does not\nmake a sacrifice, witches? will spoil something he has.\n\nThese two phrases are recited in mourning the death of a relative.\nQdun is a cloth woven of both cotton and raphia.\n\nThe “long” feet referred to here are those of the cat.\nA plate of locally made black ware.\n\nAra-(a)iye is a euphemism for witches.\n\nOni ob 09 bo e", "origen_id": "3f3d5f2c28d112c6ae8eceac"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Eleremojú: dos gallinas, dos palomas y 3,200 cauríes para el Ifá de su hijo.", "Eleremojú (segunda consulta): una rata awosin, una gallina o una chiva y medicina de Ifá; lavado de cabeza con dieciséis hojas de egbee.", "Àgbọnnìrègún: una chiva y sopa medicinal de yẹnmẹyẹnmẹ, àgbọnyin, irugba u ogiri e iyèré para las esposas.", "Ẹniunkokunjú (rechazado): un machete y una escalera de mano.", "Odunkun: 4 palomas, 4 gallos, aceite de palma, un plato blanco, 4 ẹ̀kọ, harina de maíz con aceite (àádùn), cosas dulces (miel, azúcar) y dinero, a Ọbàtálá y Ògún.", "Contra la calumnia: 3 palomas, aceite de palma, 3 ẹ̀kọ y dinero, a Ọbàtálá y Ògún. Prohibido: semillas del suelo, hongos y telas negras."], "pasajes": [{"titulo": "Ofrenda en el verso 1.1", "texto": "(Ọwọ́ t'ara) \"Las manos pertenecen al cuerpo\",\n(Ẹsẹ̀ t'ara) \"Los pies pertenecen al cuerpo\",\nỌtaratara:\nadivinaron Ifá para Eleremojú,\nla madre de Àgbọnnìrègún.\nLe aconsejaron sacrificar:\ndos gallinas, dos palomas\ny tres mil doscientos cowries,\npara ser usados en apaciguar el Ifá de su hijo.\nEllos dijeron:\n\"su vida (de ella) será próspera\".\nElla obedeció e hizo el sacrificio.", "origen_id": "0e550fa164b9e2485d39c8b3"}, {"titulo": "Ofrenda en el verso 1.2", "texto": "Òtítọ́l'omifi-ntẹ'lẹ-ìṣà:\nadivinó Ifá para Eleremojú,\nla madre de Àgbọnnìrègún.\nIfá le dijo:\n\"los hijos de Ikin podrían ayudarla (levantarla)\",\npor eso ella debía sacrificar:\nuna rata awosin,\nuna gallina o una chiva,\ny medicina de Ifá.\nElla obedeció e hizo el sacrificio.", "origen_id": "585f9bd6a8a6570aa0c80bd1"}, {"titulo": "Ofrenda en el verso 1.3", "texto": "Ọtọ̀ọ̀tọ̀,\nỌrọ̀ọ̀rọ̀,\n¿Comemos por separado ẹpà?\n¿Comemos por separado ìmùmù?\nExcesivamente queremos a Ọba'Mákin, el rey de la tierra Ìrànjé:\nadivinaron Ifá para Àgbọnnìrègún.\nLos adivinos dijeron:\n\"si él sacrifica será bendecido con tantos hijos\nque nunca sabrá la cantidad de hijos\nque llegará a tener durante y después de su vida\".\nLe aconsejaron sacrificar\nuna chiva (cabra hembra) y medicina de Ifá.\nSi él ofrecía el sacrificio,\nse debía preparar una medicina de Ifá\npara que sus esposas comieran.\nÉl obedeció y sacrificó.", "origen_id": "24f350dd60db5e16f1b7c79f"}, {"titulo": "Ofrenda en el verso 1.4", "texto": "Ökùnkùn-birimubirimu:\nadivinó Ifá para Ẹniunkokunjú (la ingratitud).\nEllos dijeron:\n\"nadie ha tenido para él un bien\nque él no hubiera pagado con un mal\".\nEllos pidieron que sacrificara:\nun machete y una escalera de mano.\nÉl rechazó sacrificar.\nEniunkokunjú,\nes el nombre con que llamamos al granjero.\nTodas las cosas buenas que Ọgèdẹ̀ (el plátano)\nproporcionó al granjero, no fueron apreciadas.\nEl granjero finalmente decapitó a Ọgèdè\n(le cortó el tallo).", "origen_id": "9871033289fca4decde65f71"}, {"titulo": "Ofrenda complementaria 1", "texto": "4 eiyelé (pichón), 4 akuko (gallo), 1 epo (botella de aceite de palma), 1 plato blanco, 4 eko (pastel de harina de maíz) adún (harina de maíz revuelta con aceite), y muchas cosas dulces (miel, azúcar, dulce) y 25 nira (dinero)\n\nDestinatario: Obátálá y Ogun", "origen_id": "a11f271b380d3053cfb8c782"}, {"titulo": "Ofrenda complementaria 2", "texto": "3 eiyelé (pichón), 1 epo (botella de aceite de palma), 3 eko (pastel de harina de maíz) y 16 nira (dinero)\n\nDestinatario: Obatalá y Ogun", "origen_id": "1ee9ec6cef5f9f67105ecb36"}]}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Ọ̀rúnmìlà, con su título Àgbọnnìrègún, están en el centro del signo. Ọbàtálá y Ògún reciben las ofrendas de prosperidad y de victoria sobre la calumnia. Orí, la cabeza, decide el destino y se lava con hojas de Ifá. Èṣù pone el canto en la boca de quien cumplió. Olódùmarè es quien reparte esposas, esposos e hijos.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Obatala; Ori", "origen_id": "34083f1b8be117d7c06a6336"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Egbee (lavado de cabeza), yẹnmẹyẹnmẹ, àgbọnyin, irugba u ogiri, pimienta iyèré, camote (Odunkun), ñame, maíz, plátano, cacahuate (ẹ̀pà), chufa (ìmùmù), miel, aceite de palma, ẹ̀kọ y àádùn."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 1.2", "texto": "Triturar dieciséis hojas de egbee en agua, para lavar la cabeza de cualquiera a quien este Odù sea adivinado.", "origen_id": "3f5a469953814682d0dc54cf"}, {"titulo": "Verso 1.3", "texto": "Machacar hojas de yẹnmẹyẹnmẹ y hojas de àgbọnyin con irugba u ogiri (tipo de condimento hecho con semillas de bàrà), con iyèré (tipo de condimento) y otros sazones para dar buen sabor a una sopa (también se pueden usar clavos de olor). Cocinar todo junto con las trompas de Falopio de la chiva. Colocar el pote de sopa delante del trono de Ifá y permitir que las esposas coman allí. Cuando ellas terminen de comer esta medicina, él tendrá muchos hijos.", "origen_id": "11236379c4f4a46390073709"}]}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 2", "texto": "semillas del suelo; cogumelos/champiñones; paños negros", "origen_id": "eb8abf03ecfaf23c93697e62"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 1.1 (yorùbá): Ọwọ́ t'ara, / Ẹsẹ̀ t'ara, Ọtaratara: / ló dífá f'Eleremojú / tí í ṣe Ìyá Àgbọnnìrègún. / Wọ́n ní kí ó rú: / Abo adìyẹ Méjì, ẹyẹlé Méjì / àti Alesan ẹgbẹ̀rìndínlógún owó / Kí ó fi bọ Ifá ọmọ rẹ̀ / Wọ́n ní: / Ìwà rẹ̀ a s'ùrẹ / Ó gbọ́ ó rú.", "Verso 1.2 (yorùbá): Òtítọ́l'omifi-ntẹ'lẹ-ìṣà: / ló dífá f'Eleremojú / tí í ṣe Ìyá Àgbọnnìrègún. / Ifá ní: / Ikin ọmọ rẹ̀ ni yóò gbé e / nítorínáà kí ó rú: / Eku-awosin, / abo adìyẹ tàbí ewúrẹ́ / àti ewé Ifá / Ó gbọ́ ó rú.", "Verso 1.3 (yorùbá): Ọtọ̀ọ̀tọ̀, / Ọrọ̀ọ̀rọ̀, / Ọtọ̀ọ̀tọ̀ ni a í j'ẹpà, / Ọtọ̀ọ̀tọ̀ ni a í jẹ ìmùmù, / Tọ̀ritirú l'afi nfẹ́ Ọba'Mákin l'óde Ìrànjé: / Ló dífá f'Àgbọnnìrègún / Wọ́n ní: / \"kí ó rúbọ, a rẹ / kò tilẹ̀ níí mọ iye ọmọ rẹ̀ l'ójú rẹ̀ / àti lẹ́hìn rẹ̀ pẹ̀lú\". / Wọ́n ní kí ó rú: / ewúrẹ́ àti ewé Ifá. / B'ó bá rúbọ, / kí a ṣe ewé Ifá fún un kí ó / fún àwọn ìyàwó rẹ̀ jẹ. / Ó gbọ́ ó rú.", "Verso 1.4 (yorùbá): Ökùnkùn-birimubirimu: / li o dífá f'Ẹniunkokunjú. / Wọ̀n ni: / \"kosi eniti o maa fi oore sẹ / ti ko maa fi ibi suu\" / A niki ó rú: / àdá ati akaso. / Ó kọ ko rú. / Eniunkokunjú-orukọ ti a npe Àgbẹ̀ / Gbogbo oore ti gèdẹ̀ se f' Àgbẹ̀ / Ko kun lojú / Bibẹ ni Agbẹ̀ bẹ Ôgèdẹ̀ lorí nikẹhin.", "REZO: BABA EJIOGBE ALOKUYE IRE MOWADE ABATA BUTU AYE ERU OSHE BANU OBARANIREGUN IRU OBATALA OGBONI ASIFAFUN GBOGBO ORUN GBOGBO LOWO ESHU OMA ATOTOLO OLE AFEKAN ADIFAFUN OBATALA OSHEREIGBO OBI ITANA AMBIAMA ITANA AMBIAMA EYELE MEDILOGUN ELEBO.", "SUYERE: ASHINIMA ASHINIMA IKU FURIBUYEMA ” ” ARUN ” ” ” OFO ” ” ” EYO ” ” ” EGUO ” ” ” ONA ” ” ” ARAYE ” AWO OSHEMINIE, OSHEMINMIE, …", "REZO: ORUNMILA NI ODI ELESE MESA, MONI ODI MESE ONI OKO MESE TIRE KO BAJA.", "REZO: BABA EJIOGBE ORUNMILA MIGBATI OLOGBA ASHE LAWO OLODU- MARE ORUBO. OLORDUMARE MEWA FI ASHO FUN MIGBATI GBOGBO KIYE GBOGBO OTIGBA ASHE LOWO OLORDUMARE AWON NIWO TO- GBOGBO EYI TI SHINSHE LATI IBA MOWA NI AMUPE ASHO.", "REZO: BABA EJIOGBE ONI WAYU OWO OBA OÑI ODE ADIFAFUN IFE LOYA TINSHOMOBE GBOGBO KOEYEBO AGBOBOADIE LEBO, ONI LENO OWO BOYURINA ONA DAKE ADIFAFUN ORIBIDE, ADA, ARIDA, TUTU AGUTAN LEBO, OPOLOPO OWO ADASILA KOSILE, INSHERI LEBO.", "REZO: BABA EJIOGBE ALALOKUN MONI LEKUN OKO, AYA LALA OMODU ABOSHUN OMO ONIKOSHE OISHE KAMU ILEKE OMO LERI ADIFAFUN ALADESHE IMAPAPORO TIMBALORDI AGOGO.", "SUYERE: BABA EJIOGBE ORUNMILA NIODERE LEYERI ERAN ” ” ” ” ” EKU ” ” ” ” ” EYA ” ” ” ” ” EPO ” ” ” ” ” ADIE ” ” ” ” ” EURE", "NIODRE LEYERI ASHANA IKU ” ” ” ARUN ” ” ” OFO ” ” ” EYO, ONA, OGU, ETC.", "REZO: BABA EJIOGBE ALALAKUN OBA ONI FAKUN BABA AUN BINIYA OKUN DABA ALALA BI OKU BABA OTOKO BABA ARARRORO ATONO NISHE IFA BABA OFIDEYABA LODAFUN BARABAIREGUN.", "REZO: BABA EJIOGBE IBE ALAPILI YOKO DIDO BABALAWO LODAFUN BARABA ODDUN ONIRE DAFUN.", "REZO: ETA ONI BABALAWO LODAFUN ARDERE. AWO ARDERETE ORUBO AUN META.", "REZO: ERIN ONO BABALAWO LODAFUN AREBE OKO AWO AREBEOKO KORUBO NI ARAYE AFIBORAN SHE UNYO. IFA ONI BABALAWO LODAFUN ADFA ORUBO AUN MEFA. EYI ONO BABALAWO LOFAFUN BARABARIREGUN ONI BABALAWO ONI BARABANIREGUN ORUBO AUN MESAN MEFAKI AYA OBANIRI KOBESA LASHARE.EWA ONI BABALAWO LODAFUN BARABANIREGUN AWO BARABANIREGUN ORUBO AUN MEWA LAWAGIRO ADO AWO LAWAGORI ILE AWO.", "REZO: BABA EJIOGBE ONI TEGUN ONI TOSAN ENLO SODE ONI YERI ENLALO OFE OYE ODUWA TANI AUN SOYE KETEFA AYA TOYA TAMI OBA OPA OLOKUN KOTAKUN KITAKUN OMI GODO AWO APALOKUN BANILU BANLORUN GBOGBO LOWAYU PETUKIE SODE ALAGUEDE OMA ORIKU BABAWA.", "SUYERE: TINI YOBI ABE OBILENA ADAFUN GBOGBO TENUYEN ABANSHE-KE ASHOKO ODUFUO BEWA."], "pasajes": [{"titulo": "Canto complementario 5", "texto_ritual": "Ayé Sénrén ti dun, o dunju oyin lo.\nAyé Sénrén ti dun, o dunju oyin lo.\nOrisá je aye mi o dun, Aláyun Gbáláyun.\nOrisá je aye mi o dun, Aláyun Gbáláyun.", "traduccion": "Vida de Camote, más dulce que la miel.\nVida de Camote, más dulce que la miel.\nInmortales dejen que mi vida sea dulce, o Aláyun Gbáláyun.\nInmortales dejen que mi vida sea dulce, o Aláyun Gbáláyun.", "origen_id": "563478466d8c9e0986468847"}, {"titulo": "Canto complementario 6", "texto_ritual": "Elénini Ilé, Elénini ode o.\nElénini Ilé, Elénini ode o.\nKíni mo ra lọ́wọ́ yín,\nElénini Ilé, Elénini ode o.", "traduccion": "Calumnia en el hogar, calumnia afuera en la calle.\nCalumnia en el hogar, calumnia afuera en la calle.\n¿Qué te compré?\nCalumnia en el hogar, calumnia afuera en la calle.", "origen_id": "f21482bfd73a8fedf28adc9e"}, {"titulo": "Incisiones para ver el fruto de su trabajo (Ejiogbé)", "texto_ritual": "Eku igbó kíí nikán se igbó Eja ibu kíí nikán se ibu Ewé aduro susu kíí duro ni oh un nikán soso giro giro ifá mo njé ki emi iagbaja orno iagbaja Ó nikán se ayé iiio bibo ominsin kíí won ni inú iié ogan ifá mo njé ki n nikán sayé Eji ogbé wá i o re e gbé opo payan wá Ki won se mo wá sinmi", "traduccion": "El ratón del bosque no está solo en el bosque. El pez de las profundidades no está solo en el agua. Las hierbas de aduro nunca están ellas solas. Ifá, no me dejes vivir solo a mí.... hijo de...... El omisinsin nunca se encuentra solo en la casa de ogan. Ifá, yo te doy de comer, para que Ejiogbe me traiga mucha gente que me venga a servir a mí.", "origen_id": "bb09543f35c2e3bf4aec6e96"}, {"titulo": "Éjíogbé — encantación para camino libre", "texto_ritual": "Igbá nlá monladi monladiro Agbá gogo loná oja E yago fún loná komo awo mo ribi Koja eyun arolu kiije kí won ó le gbá awolu Loju owo orno ilu kíí je Kí won ó le té oro ilu monle lówó lówó ni tolówó E je kí olówó ó lo owo e je Kí olówó ó lo owo", "traduccion": "Una calabaza grande, moladi monladiro. El agbá gogo en el camino del mercado. Deja libre el camino para que pase el hijo del sacerdote. Egun arolu no deja que la gente abofetee a arolu. Lo que pasa en el pueblo no dejará que brillen mis palabras en el pueblo. El honor se busca con honor. Que él tenga honor, sea honorable siempre.", "origen_id": "fe251c0aac7296d8f7803b91"}, {"titulo": "Ayajo aseta (Éjí Ogbé) — para la prosperidad", "texto_ritual": "Ewure fi dudu sola lá npé Ifá Agbo fi roro iya bale lá npé ogun Onokun mondun mondun A ninu agbá ohun gbágbo si lá npé iwo ile Orno kékére fu món orúko ilé Kí ilé o pa agbálagbá kíí món orúko ilé kí ilé ó pa Emi món orúko iwo ¡le lié komo pami komo araye ó mon le rimú mi taya taya Tomo tomo Babalawo ni won bá be lowe timi Afi bi ó bá duro lorile tobé duro lorile komon lee rimi mú taya taya tomo tomo eewo Órisás atéémi kíí ni aya ilé mi obi ni kí efi bi áwon ota témi sorun Éjí ogbé kó gbe ota témi morun Alakeji", "traduccion": "La chiva que usó color negro como el orgullo es el nombre que le damos a Ifá. El carnero que pone el pelo en la escoba es el nombre que le damos a ogun. Onokun mondun mondun. La persona que tiene estómago para todo es el nombre que le damos a la tierra. La tierra debe matar a............ Nadie que conozca el nombre de la tierra la puede matar. (Se dice tu nombre) conoce el nombre de la tierra. Que la tierra no me mate. Que la gente no me pueda capturar a mí ni a mis hijos. Si fuera que mandasen un sacerdote a hacerme daño, si solo estuviese él en la tierra, que ni él pudiera hacerme daño a mí ni a mis hijos. Es un tabú para las deidades hacerle daño a mí y a los míos. Es el obi ábátá que debes tomar para librarme del mal. Éjí ogbé, llévate a todos mis enemigos al cielo.", "origen_id": "4bb95e75f45a76b45309de9d"}, {"titulo": "Ejiogbe — para protección y alejar malas intenciones y chismes", "texto_ritual": "Akigun igi kakó Emi akú gun ope ta kó emiyan Ókete ati ikún won kíijé pádé aago kan Os un a ti Oru won kú pá dé ibi /ai tai Owu dudu ati owu funfun won kíijana Won éniyán gbogbo ibi tó bá ra Ioná pala kí remi lagbaja orno ¡agbaja Ó ni pádé re ejiogbe ró ni kí ó pé ibi kúro ioná fun emi iagbeji orno lagbaja", "traduccion": "Subimos a la mata para ver a alguien que viene por el camino. No subimos a una palma para ver a alguien que viene por el camino. La okete y el ikun no se encuentran en la encrucijada del camino. Entre la 1:00 de la madrugada y la 1:00 de la tarde no nos vemos. El hilo blanco y el negro no se detienen a discutir entre ellos. Que los males que vienen en camino no me hagan daño a mí.", "origen_id": "b344a64487fffe4bfc644d24"}, {"titulo": "Ose awuré (Éjí Ogbé) — para la suerte", "texto_ritual": "Ola mi tooro Ola tooromi Ela monje kin se egbe Egbe mi oke ohun ela monje Kí egbe mi oke hin ó yori jumi Igunnungun nbe loko kíí se egbe orogbá ejo kejo Iduro ni won n fi ohun odo fún odo Ibere ni won n fi ohun odo fún odo Ibere ni won n fi ohun olo fún olo Ooro gan-an gan-an ni won fi ohun esu fún esu Ifá kifá kíí bori éjí ogbé B¡ a bá peran nile bia si peran loko odo isaasun ni won n k obo", "traduccion": "Ola mi tooro, ola tooromi. Ela no me dejará ser igual que los demás de arriba. Ela no deje que la gente de abajo sea mayor que yo. La tiñosa de la finca no es igual que las aves de la finca. La ojola (una serpiente grande) está en la corriente. Es lo que le da honor a las piedras. Es doblándose como se le da honor a la piedra de esmeril. Donde está posicionado Esu es todo de él. Ningún odu puede derribar a éjí ogbé. Si uno mata a un animal en la casa, debe llevarse a la caldera de cocinar.", "origen_id": "bedcc66e2d24172ab2a60d47"}, {"titulo": "Sigidi awuré (Éjí Ogbé) — para la riqueza", "texto_ritual": "Bi a bá n se agbe agbe amon daro món oró Se B¡ aba n se aluko aloku amon kun osun món osun Bi a bá n se odidere Iko ¡si re amon ke riri ke bebe B¡ a bá n se olosusu (¡le ode) amon món ¡lé kunle Baba re gbogbo eyi tí won n so wipe emi oní le se Bábá oya gbáyo wá bami se", "traduccion": "Si uno hace al agbe, uno va a producir la muerte. Si uno busca a aluko, uno va a usar polvo de osun. Si uno hace al odidere, las plumas van a salir volando. Si uno hace el olosun (nido de odidere), uno va a construir más casas que su padre. Que todo lo que yo diga sea capaz de hacerlo. El padre de oya gbánjo venga y lo haga por mí.", "origen_id": "8f90e5aa4c9dbc51732a1744"}, {"titulo": "Incisiones para tener mucha popularidad (Ejiogbé)", "texto_ritual": "Afemi afemi ni agbe n ke ni gbo Ti fi n gbá igbó iówó onígbo Afemi afemi ni aiuko N ke ni odan ti fi n gbá odan iówó otodan Afemi afemi ni odidere N ke ni iiu ti fi n pa iiu iówó oniiu Afemi afemi, a fe o ni orúko méji Afe ni a fe n jé atare atagbá ni won n só pé ejiogbe Ni obá ifá ifá jé ki okiki emi iagbájá orno iagbája Ó kan si rere laye", "traduccion": "Afemi afemi es el sonido del agbe en el bosque. Es el que puede recolectar en el bosque lo del dueño del bosque. Afemi afemi es el sonido del aluko. Es el que puede recolectar en el bosque lo del dueño del bosque. Afemi afemi es el sonido del odidere. Es el que puede recolectar en el pueblo lo del dueño del pueblo. Excepto yo, la rata de afe no tiene dos nombres. Afe es el nombre para todos. Que todos, jóvenes y mayores, llamen a Ejiogbe para que Ifá me dé toda la popularidad de la tierra.", "origen_id": "da4867e31c1b5c97d333147f"}, {"titulo": "Ejiogbe — rezo del ebo", "texto_ritual": "Ayoyo go Ayoyo go Ayoyo go mangoman Adifa fun orunmila Ifa nloree ni iyo yora Awa ti amu iyo yora oro ayo lobawa Oyo ibanujekan ki ba iyo", "traduccion": "Ayoyo go, ayoyo go, ayoyo go mangoman. Hicieron adivinación para orunmila. Ifá iba a hacer algo de feliz. Nosotros que hemos hecho algo de feliz somos felices. La sal siempre se encuentra.", "origen_id": "8071eef213d975b0b16b1bac"}, {"titulo": "Sigidí ijá (Éjí Ogbé) — para vencer a los enemigos", "texto_ritual": "Ají láija lorúko tí npé iwo ikú iwo bkü yí wá lo réé bá Igbája orno ¡á kiirrio ni kofi lu pa tabi ada ni kofi gun pa tábi igo ni kofi gun pa toba wá n pada bo wá orúko tábi ákükó adire ti nbe ni ni kí ó gbá mo nse bami já nigbá kóó kan", "traduccion": "Aji laluja es el nombre que le damos a la muerte. Que tú (diga el nombre de la persona muerta) vaya a pelear con ........(diga el nombre de la persona o el suyo). Es el machete lo que se usa para matar. La botella rota es la que marca la muerte. Y cuando regrese a mi casa encontraras un chivo amarrado o un gallo amarrado. Cógelo y no te fajes nunca conmigo.", "origen_id": "7f5754ae5fbe82505ed45e87"}]}]$q$::jsonb),
(2,'8218a6acd4563b6fbf3278285a577904','8f487bde3d957239a698233b07b13219',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Méjì es el segundo de los Odù y representa el principio femenino; junto con Èjìogbè dio vida a los demás. Habla de oscuridad, tristeza, enfermedad y peligro de muerte, pero trae en sí misma la solución a todo eso. Cuando la persona está en mala fortuna solo encuentra obstáculos; cuando está en buena, tiene un fuerte respaldo de sus ancestros.", "pasajes": [{"titulo": "Frase clave", "texto": "Oyeku crea y termina a un ciclo.", "origen_id": "11cf377c4301a783ef154eb9"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que una etapa se cierra antes de dar fruto: tristeza, obstáculos o incertidumbre.", "Le preocupa la salud o la vida de un hijo o de alguien de la familia (relato de Onibijé).", "Busca prosperidad en su trabajo y no ve el valor de algo que tiene enfrente (relato de Òyè y el amanecer).", "La casa y el trabajo van cada uno por su lado; cuando se unen, llega la alegría (relato de Onikabidun).", "Hay celos o relaciones que le frenan; le conviene escuchar a los mayores.", "Necesita resistir sin quebrarse ante un viento fuerte (relato de la palma).", "Debe distinguir qué ciclo le toca cerrar y cuál le toca proteger."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza que llega desde el lugar de trabajo.", "Larga vida para la persona y para sus hijos.", "Algo que hoy no valora se convertirá en su fortuna.", "Alegría duplicada en la casa y en el trabajo, con abundancia e hijos.", "Paz después de haber luchado, y conservar lo ganado.", "Hijos que, aun con alguna limitación física, triunfarán en la vida."]}, {"titulo": "Ibi y advertencias", "puntos": ["Muerte repentina, enfermedad y preocupaciones si no se atiende la ofrenda.", "Depresión: hay que atender la cabeza (Orí) de vez en cuando.", "Tener relaciones con muchas parejas trae celos y problemas que frenan el progreso.", "No escuchar a los mayores ni honrar a los ancestros.", "Una vida que va en zigzag de la buena a la mala fortuna, y la dificultad para aceptar la alegría."]}, {"titulo": "Enseñanza principal", "texto": "La oscuridad no es el final: el amanecer llega aunque la noche sea larga. Ọ̀yẹ̀kú Méjì pide constancia en la ofrenda, respeto a los mayores y a los ancestros, y fidelidad a una sola pareja. Así como la palma resiste el tornado porque ofreció, quien cumple aguanta los vientos de la vida."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ọ̀yẹ̀kú Méjì significa oscuridad, tristeza e infelicidad. El Odù advierte un peligro de muerte para la persona, enfermedades y preocupaciones. Es un Odù de mal agüero, sin embargo tiene la solución a lodos esos problemas.", "origen_id": "ee5178c13560dea6993e896d"}, {"titulo": "Características generales", "texto": "Otros nombres: Ọ̀yẹ̀kú Méjì; Èjiòyẹ̀kú/ Èjiọ̀yẹ̀.\nỌ̀yẹ̀kú Méjì es el segundo Odù principal (Olódù), simboliza el principio femenino. Èjìogbè y Ọ̀yẹ̀kú Méjì dieron vida a los otros catorce Odu principales. El Odù Ọ̀yẹ̀kú Méjì tiene un Ọ̀yẹ̀kú en el lado derecho que es la fuerza masculina y el otro Ọ̀yẹ̀kú en el lado izquierdo es la fuerza femenina.\nLas personas que pertenecen a este Odù deben crear el hábito de ofrecer sacrificios y apaciguar sus cabezas (Orí) de vez en cuando para así evitar sentir depresión. Además deben oír y respetar los puntos de vista de los mayores. Deben honrar a sus ancestros regularmente.\nEn Ọ̀yẹ̀kú Méjì, Ifá advierte del daño de tener relaciones con muchas mujeres. Las mujeres serán celosas y los problemas creados por ellas impedirán el progreso del cliente. De este Odù, aprendemos que es mejor tener una sola mujer o un solo hombre.", "origen_id": "2ee3c74964997d86fe9ed1d0"}, {"titulo": "Interpretación tradicional", "texto": "Oyeku es una omisión de la frase O yeyé ikú significando, Espíritu de la Madre de la Muerte. En términos simples Oyeku es oscuridad, la contracción completa de materia en lo que la física llama un agujero negro. En términos humanos, esto puede significar la muerte física. Más comúnmente se refiere al final de un ciclo. Cuando un bebé nace, hay un ciclo final de vivir dentro del vientre. Cuando un joven se vuelve adulto, hay un ciclo final de dependencia con los padres. En Ifá, el final de la vida en la tierra marca el principio de vida en el reino de los ancestros (Orun). La palabra Yoruba para negro es dudu y es asociado con Oyeku como un símbolo para la dimensión invisible, el Origen de la Creación. Oyeku como final de ciclo, puede traernos bendiciones de paz. En su manifestación negativa, Oyeku representa un final prematuro de un ciclo que no puede resultar en completa madurez o beneficio.", "origen_id": "af36a1e0f06d6ac022c30cb0"}, {"titulo": "Orientación complementaria", "texto": "La terminación del ciclo expresado en Oyeku puede ser la terminación de una etapa de desarrollo personal, puede ser la terminación de un proyecto y puede ser la terminación del proceso de aprender una lección de vida. Oyeku también se puede referir a la terminación de vida del ciclo y está asociado con la literal muerte física. Cuando Oyeku se refiere a la posibilidad de la muerte prematura, esto incluye instrucciones específicas en cómo evitar ésta situación. Oyeku en su manifestación negativa, es el fracaso para completar una tarea o la terminación prematura a un ciclo.", "origen_id": "4aedc8b20469efb8a21344da"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́fin y la tela negra. Ọ̀yè dúdú, el adivino de Orí Bìjé, consultó para Ọlọ́fin y le marcó una tela negra, una chiva y hojas y frutos de bìjé, para que ni la muerte se lo llevara a él ni la muerte repentina a sus hijos. Ọlọ́fin cumplió. Por eso, cuando sale este Odù, la familia se marca la cara con bìjé y cubre su Ifá con tela negra y hojas de bìjé: la muerte no reconoce a quien lleva la medicina de bìjé.", "La palma y el tornado. Eesin gbona l'ewé tutu l'egbo consultó para los 165 árboles. A la palma y al árbol de àyìnrẹ̀ les marcó un pollo que debía pasearse alrededor de los árboles. La palma cumplió, y desde entonces, cuando un tornado arrasa, la palma joven dice: 'Yo hice la ofrenda para escapar del peligro'. Ningún viento la tumba.", "Los dos hijos de Ọlọ́fin. Dos Ọ̀yẹ̀ consultaron para Ọlọ́fin y le dijeron que dos de sus hijos se fracturarían las piernas, pero que no se entristeciera, porque los dos triunfarían en la vida. Le marcaron una tela kẹlẹku para cubrir a sus hijos. Cumplió, y la limitación de los hijos no estorbó su prosperidad.", "Òrìṣà-ńlá pregunta por sus hijos. Òrìṣà-ńlá fue a ver a Ọ̀rúnmìlà y le preguntó qué hacer por los hijos que había traído a recorrer el mundo, para que no padecieran frío, dolores de cabeza, fiebres ni otras enfermedades. Ọ̀rúnmìlà le mandó marcar Ọ̀yẹ̀kú Méjì en iyẹ̀rosùn, moler hojas tiernas de pèrègún, mezclarlas con manteca de òrí y untarlas en el cuerpo, diciendo: 'El siempre verde pèrègún echa agua sobre la muerte furiosa; el siempre verde pèrègún echa agua sobre la enfermedad furiosa'.", "El amanecer que quería ser rico. Ifá consultó para Ọ̀yè, el amanecer, que brillaba desde el cielo y preguntaba si llegaría a ser rico. Le pidieron ofrecer para que sus rayos brillaran. Ofreció, sus rayos se volvieron muy brillantes y la vida le sonrió: Ọ̀yè se volvió dos mitades iguales y la bandeja de Ifá se llenó hasta el borde.", "Los campesinos y la chufa. Ifá consultó para un grupo de campesinos que iban a escoger tierra para sembrar dentro del monte y querían saber si volverían con buenas ganancias. Ọ̀rúnmìlà les pidió ofrecer y les dijo que sembraran chufa. Al cosechar, las semillas parecían cuentas de coral (iyùn), y la vida les fue muy provechosa. Cantaron: 'Sembramos chufa y nos llevamos cuentas a casa'.", "Onikabidun y las azadas. Ifá consultó para Onikabidun cuando quería aumentar su felicidad, y le marcó cinco azadas tratadas con medicina de Ifá. Llevó las azadas a su casa; la gente de la casa las llevó a la granja y la gente de la granja llevó las suyas a la casa. Se encontraron a medio camino: los de la granja dijeron que sus azadas servían para cavar fortuna y los de la casa que servían para enterrar placentas de recién nacidos. Feliz, cantó: 'Que la gente venga a mí con alegría: alegría en la casa, alegría en la granja'. Esta persona tiene problema para aceptar la alegría y debe cambiar esa actitud.", "La mona que no suelta a su hijo. Ifá consultó para la mona (Ape) el día que no quería perder lo que tenía, y le aconsejó ofrecer. Ofreció, y desde entonces, cuando la mona se columpia de árbol en árbol con su cría a la espalda, la cría nunca se cae. Cantó: 'Ofrezco ñame machacado; la casa no tiene infortunio'."], "pasajes": [{"titulo": "Verso 2.1", "texto": "Ọ̀yè dúdú el adivino de Orí Bijé:\nadivinó Ifá para Ọlófin.\nLe pidieron que sacrificara:\nuna tela negra, una chiva, hojas y frutos de bijé.\nLe dijeron que esto le impediria a la muerte matarlo,\ntampoco la muerte repentina mataría a sus hijos,\nsi él hacia este sacrificio.\nEl obedeció y sacrificó.", "comentario": "Si aparece este Odù, la familia del cliente debe marcar con bijé\" (yerba africana) sus caras y cubrir su Ifá con tela negra y hojas de bijé. De esta forma se les asegura que la muerte, la enfermedad y otros males no los reconocerán, ya que la muerte no reconoce a Onibijé (alguien que usa medicinas bijé prescritas por el adivino).\n''Nota: c: la frase \"ewé ati eso bijé\" significa \"hojas y frutos de bijé\", o sea, el sacrificio debe ser tela negra, una chiva, hojas y frutos de bijé. Para su conocimiento la traducción original del libro en yoruba-inglés dice: \"a black cloth, a she-goat, and bijé leaves and seeds\", , indicando que el sacrificio es: \"una tela negro, una chiva, y hojas y semillas de bìjé\"", "origen_id": "9012ac50ed63f94d7c0020b3"}, {"titulo": "Verso 2.2", "texto": "Eesin gbona l'ewé tutu l'egbo:\nadivinó Ifá para los 165 árboles.\nA la Palma y al árbol de Ayinrẹ\nle aconsejaron sacrificar:\nun pollo alrededor de los arboles.\nDesde entonces, cuando un tornado está arrasando,\nla palma joven declarará:\n\"yo hice el sacrificio para escapar del peligro\".", "comentario": "El árbol de Palma nunca es afectado por el viento o los tornados porque él realizó el sacrificio requerido en este Odù. Todos los daños son rechazados por el árbol de Palma.\nbijo: pla", "origen_id": "af5c0293ec430e51b783e2b7"}, {"titulo": "Verso 2.3", "texto": "Tủ eres yẹ̀,\nYo soy Qyẹ̀.\nDos ọyẹ̀:\nadivinaron Ifá para Ọlófin.\nEllos dijeron:\n\"dos de sus hijos se fracturarán sus piernas,\npero no debe sentirse triste por esto\nporque ellos serán exitosos en sus vidas\".\nLe aconsejaron sacrificar:\ntela de Kelẹku,\ny usarla para cubrir sus hijos.\nEl obedeció y sacrificó", "comentario": "Ifà predijo que la discapacidad (minusvalía) que podrían sufrir lon hijos de Ọlofin no obstaculizarian su prosperidad y éxito en la vida. Todo lo que el necesitaba era hacer el sacrificio y proveerse de la tela especifica que sirve para proteger y cubrir los hijos.", "origen_id": "9f797cdcace22b9cf447e52f"}, {"titulo": "Verso 2.4", "texto": "Cuando me desperté en la mañana\nvi una multitud de niños,\nyo pregunté por el reino de la Tierra,\nyo conoci a los mayores en su mayor esplendor,\nyo pregunté por el reino del Cielo.\nCuando Oriṣà-ńlá fue a visitar a Ọ̀rúnmìlà,\nél preguntó:\n¿ qué es de tus hijos que me llevé a recorrer el mundo?\n¿Deben tener frio?.\n¿Deben padecer dolores de cabeza?.\n¿Deben sufrir la malaria y otras enfermedades?.\n¿ Que debo hacer por ellos?\nỌ̀rúnmìlà le ordenó recibir medicina de Ifá:\nmarcar el Odù Ọ̀yẹ̀kú Méjì en iyẹ̀-Ìrosùn,\narrancar algunas hojas tiernas de Pèrègún y molerlas,\nmezclarlas con manteca de cacao\ny usarlo para embadurnar sus cuerpos.\nEl vivaz (siempre verde) Pèrègún\nderramará agua a la rabiosa muerte.\nEl vivaz Pèrègún\nderramará agua a la rabiosa enfermedad.", "origen_id": "5de2f6dc8835e93c4d593963"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que desea lo mejor para esta persona, que\nserá rico en su vida. Ifá enmendará su vida y no\npermitirá que mueran jóvenes sus descendientes, ni\nél (ella). Ellos tendrán una larga vida (longevidad,\naikú). Ifá dice que esta persona traerá la riqueza de\nsu lugar de trabajo. Existe algo que no considera\nvalioso y se tornará en un imponderable que le\ntraiga la buena fortuna de la riqueza.\n\n              Òye ń làá bò lókè\n            Mó şe bójúmó ní ń mó\n                A dífá fún Òyè\n   Èyí ti yóó gbóju ợrun là bí Ợba ẹrékẹ\n               Òún le là báyìí?\n                Wón ní ó rúbợ\n          Wón ní òyee rè ó móợ là\n                   O bá rúbợ\n                 Oyee rè bá là\n                   Ayé yẹ é\n           N ní wá ń jó ní wá ń yò\n           Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n              Òyè ń làá bò lókè\n            Mó şe bójúmó ní ń mó\n                A dífá fún Òyè\n   Èyí ti yóó gbóju ợrun là bí Ợba ẹrékẹ\n                   Ìwợ ò yè\n                   Èmi ò yè\n                 Òyé di púpò\n            Ojú ợpón kún tétéété\n\nEl amanecer está aclarando brillante sobre el\nhorizonte\nEs la indicación de la llegada de un nuevo día\nLanzó Ifá para Òyè\nAquel quien desde el Cielo brillaba, como el Rey del\nalgodón\nY se preguntaba: ¿Podré ser rico?\nSe le pidió que ofrendase, para que sus rayos\npudieran brillar\nÉl sacrificó y sus rayos se tornaron muy brillantes\nLa vida le fue muy agraciada\nÉl comenzó a bailar y alabó a sus babaláwos\nLos babaláwos alabaron a Ifá\nÉl hizo como tal le dijeron que hiciera\nEl amanecer está aclarando brillante sobre el\nhorizonte\nEs la indicación de la llegada de un nuevo día\nLanzó Ifá para Òyè\nAquel quien desde el Cielo brillaba, como el Rey del\nalgodón\nTú no has cambiado ni yo tampoco\nÒyè se volvió un par (dos mitades iguales)\nY la bandeja se llena hasta el tope\n\n             Ìgbá ńlá abìdí yèkú\n            Mo lárúgbó ẹmi lóko\n             Oori abìdí gbàdàgì\n               Apá aborí pétékí\n        Níí fón ợmợợ rè ká inú igbó\n             A dífá fún Òňyàgbè\n     Èyí ti ń lợ rèé bá wợn múlè légàn\n     Àwợn mú nňkan tó dáa bợ lóko?\n           Wón bá tợ Òrúnmìlà lợ\n         Òrúnmìlà ní kí wón ó rúbợ\n                 Wón bá rúbợ\n       Wón ní kí wợn ó lòó gbin èpà\n\n              Wón bá kợrí sí oko\n                 Wón gbin èpà\n        Ńgbáa wón ó móo kórè èpà\n                 Ìrúbợ ti ợn şe\n                     Ệbợ pé\n          Béèyàn bá ti ri ợmợ èpà\n               Yóó rò pé iyùn ní\n       Ayé yẹ Òňyàgbè tó múlè légàn\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n              Ìgbá ńlá abìdí yèkú\n             Mo lárúgbó ẹmi lóko\n              Oori abìdí gbàdàgì\n               Apá aborí pétékí\n         Níí fón ợmợợ rè ká inú igbó\n              A dífá fún Òňyàgbè\n       Ti ń lợ rèé bá wợn múlè légàn\n                  Kín níí múni?\n                  Oko níí múni\n                   Àjùbà èpà\n              Níí múni kéyìn lóko\n                   Àjùbà èpà\n            Àjùbà èpà ní mo gbin\n          Mo wáá yinyùn wánú ilé\n     Ire gbogbo to mí lówó porongodo\n\nEl árbol de Ìgbá con un sólido y extenso tronco, así\ncomo raíces\nPoseo un viejo árbol Ệmi en la granja\nEl árbol de Oori con una extensa base de raíces\nEl árbol de Apá con una copa frondosa, pero\nallanada\n\nAl igual que ella esparce sus hijos dentro del bosque\nLanzaron adivinación para el grupo de campesinos\nCuando venían a escoger buenas tierras para\ncosechar dentro de los arbustos\n¿Regresaremos con buenos ingresos del campo?,\nellos se preguntaron\nIfá les pidió sacrificar y así ellos hicieron\nSe les dijo que sembraran “chufas”, y así lo hicieron\nal llegar al interior del bosque y elegir las tierras\npara cosechar\nCuando llegó la época de la recolección, ellos\nsacrificaron como debían\nSi uno examina las semillas de la chufa, puede\nconfundirlas con cuentas iyùn La vida les fue muy\nprovechosa a los campesinos\nEl árbol de Ìgbá con un sólido y extenso tronco, así\ncomo raíces\nPoseo un viejo árbol Ệmi en la granja\nEl árbol de Oori con una extensa base de raíces\nEl árbol de Apá con una copa frondosa, pero\nallanada\nAl igual que ella esparce sus hijos dentro del bosque\nLanzaron adivinación para el grupo de campesinos\nCuando venían a escoger buenas tierras para\ncosechar dentro de los arbustos\n¿Qué es lo que nos cautiva y embelesa?\nEs la cosecha generosa y llena de beneficios lo que\nnos cautiva\nLa fresca y generosa granja de chufas, hará que\nvivamos siempre en el campo\nSembramos una granja de chufas y llevamos las\ncuentas a casa\nY realmente nos llegaron en multitud, todas las\nbuenas cosas de la vida", "origen_id": "a8f8fdcc30f824bb17a531ae"}, {"titulo": "Relatos y ofrendas", "texto": "OYEKU MEJI\n\nAlegría -recibida -en -el -hogar -no -es -tan -fuerte- como -la -alegría - recibida -en -la -granja.\nConsulta Ifá para Onikabidun en el día en que Onikabidun quería incrementar su felicidad.\nIfá aconsejó a Onikabidun recibir cinco azadas tratadas con la medicina de Ifá. Onikabidun llevó\nlas azadas a su hogar. Las personas de su casa llevaron las azadas a la granja, mientras las\npersonas de su granja llevaron sus azadas a su casa.\nAmbos grupos de personas se encontraron en el camino entre la casa y la granja. Las personas de\nla granja dijeron que sus azadas fueron usadas para cavar fortuna. Las personas de la casa dijeron\nque sus azadas fueron usadas para enterrar placentas. Onikabidun estaba muy feliz, empezó a\ncantar y bailar en alabanza del Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a\nOlodumare. Cuando Onikabidun empezó a cantar Esu puso palabras en su boca. Omkabidun\ncantó:\nIyoyo ke wa yo fun mi o.\nIyoyo ke wa yo fun mi o.\nA mi yo nile, a mi yo lajo.\nIyoyo Aye e, Iyoyo.\nAlegre, deja que las personas vengan a mí con alegría.\nAlegre, deja que las personas vengan a mí con alegría.\nAlegría en el hogar; alegría en la granja.\nAlegre, deja que tas personas vengan a mi con .alegría.\n\nComentario:\n\nIfá dice que esta persona recibirá una bendición de alegría. Ifá dice que cualquier alegría que está\nen la vida de esta persona será duplicada. Ifá dice que la bendición de alegria incluye abundancia\ne hijos. 1fá dice que las cosas no han ido bien para esta persona, antes de hacer ebo. Ifá dice que la\n\n84\n\nvida de esta persona ha ido en un patrón de zigzag de buena fortuna a mala fortuna. Ifá dice que\nesta persona tiene problema en aceptar la alegría en su vída y esta actitud debe cambiar.\n\nEtutu (ofrecimiento): 4 Eiyele (pichón), 4 Abo Adie (gallina) 1 eku (rata), 1 Eja aro (bagre\nnegro), 1 epo (botella de aceite de palma), 1 plato blanco, dinero determinado por el Awo,\nofrecido a Ibejí, El Awo marcará este Odu con iyerosun en cinco azadas para ser guardadas en la\ncasa, y cinco azadas para ser guardadas afuera.\n\n(Etùù (oferendas); 4 eiyelé (pombo), 4 Abo adie (galinha), 1 Eku (rato), 1 Eja aro (bagre), 1\nepo (garrafa de azeite de dendé), 1 prato branco, certa quantia em dinheiro determinada\npelo 4wo, que será oferecida a Ìbejì. O Awo marcará este Odú com iyerosun em cinco\nenxadas a serem guardadas na casa, e cinco enxadas serem mantidas fora da casa.)\n\nMi -mano -derecha -Oye -mi -mano -izquierda -Oye -dos -Oye -se - volverán -ciertas -enfrente -\nde -la -tina -consulta /fá para Ape con la cabeza de epo y Alagoro Opero en el día que Ape no\nquiso perder todo lo que tenia, Ifa aconsejo a Ape hacer Ebo. Ape hizo Ebo en el dia que él\nguardó las cosas que le pertenecían Desde ese dia, cuando el Ape se mece a través de los árboles\ncon su hijo en su espalda, el hijo no se cae, El Ape estaba muy feliz, empezó a cantar y bailar en\nalabanza del Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a Olodumare .Cuando El Ape\nempezo a cantar, Esu puso sus palabras en su boca\nMo ru iyan, mo ru iyan o.\nIle edun pa poju, ile edun pa poju.\nMo ru iyan, mo ru iyan o.\nIle edun pa poju.\nOfrezco fiame molido.\nLa casa no tiene infortunio\nOfrezco ñame molido.\nLa casa no tiene infortunio\n\nComentario:\n\nIfá dice que la persona debe hacer Ebo para asegurar que no pierdan lo que han ganado. Ifá dice\nque adimu ofrecimientos de ñame molido debe ser presentado al Orisa de esta persona. Ifá dice\nque la lana debe de estar enrollada alrededor de la olla del\n\nOrisa de esta persona. Ifá dice qué rezos deben ser ofrecidos para desviar la muerte inesperada y\nel infortunio.\n\nIfá dice que esta persona ha luchado en el pasado y recibirá una bendición de paz.\n\nEtutu (ofrecimiento): 5 eiyele (pichon), 4abo adie (gallina), 1 plato blanco. 1 epo (botella de\naceite de palma), iyan (ñame molido), cantidad de dínero establecido por el Awo, ofrecido a Ibeji.\nÉewo (tabú) rata gris no cubras la cabeza con hojas cuando llueva.\n\n(Eta (oferendas); 5 eiyelé (pombo), 4 Abo adie (galinha), 1 prato branco, 1 epo (garrafa de\nazeite de dendé), iyán (inhame pilado), uma quantia em dinheiro estabelecida pelo 4wo, que\nserá oferecida a Ibeji. Eéwó (tabu): rato cinzento; náo cobrir a cabeca com folhas quando\nchover.)\n\nI n\n\nI I\n\nI I\n\ntr n", "origen_id": "59060c43c099873025246aeb"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oyeku Meji significa tristeza e infelicidad y advierte sobre la\nmuerte, la enfermedad, las preocupaciones y el mal agüero, además cargar\n                                      con la solución de todos esos problemas.\n             WO – El cliente con mala fortuna encuentra obstáculos, el cliente\n                               con buena fortuna tiene fuerte soporte ancestral.\n                Oyeku Meji es el segundo principal Odu (Olode). Simboliza el\n     principio femenino Ejiogbe y Oyeku dieron vida a los otros catorce Odu\n                                                                   principales.\n               En Odu Oyeku Meji hay un Oyeku en el lado derecho que es la\n             fuerza masculina y el otro Oyeku en el lado izquierdo es la fuerza\n                                                                     femenina.\n              Las personas que pertenecen a este Odu deben crear el hábito de\nofrecer sacrificios y apaciguar sus cabezas (ori) de vez en cuando para así\n\nevitar sentirse depresivos. Además deben oir y respetar los puntos de vista\n                 de los mayores. Deben honrar a sus ancestros regularmente.\n         El Odu Oyeku Meji, Ifá advierte contra el daño de tener relaciones\n  con muchas mujeres. Las mujeres serán celosas y los problemas creados\n por ellas impedirán el progreso del cliente. De este Odu, aprendemos que\n                             es mejor tener una sola mujer o un solo hombre.\n\n\n2.1 · Oye Dodu Awo Ori Bije adivinó Ifá para Olofin. Le preguntamos\n      para ofrecer un un pedazo de tela negra, una chiva y hojas y semillas\n              de bije. Le dijimos que esto es para que la muerte inminente no\n       pudiera matarlo, ni tampoco matar a sus hijos, si Él hace la ofrenda.\n                                                El obedeció y sacrificó (☼).\n\n\n2.2 · Eesin Gbona I’ ewi tutu i’egbo adivinó Ifá para 165 árboles. El árbol\n       de palma y el árbol de Ayinre sacrificaron un pollo alrededor de los\n      árboles. Entonces si un tornado aparece la palma joven declararía yo\n                              hice el sacrificio para escapar del peligro (☼).\n\n\n2.3 · Tú eres Oye, yo soy Oye, 2 Oye adivinaron Ifá por Olofin. Ellos\n         dijeron que dos de sus hijos (los hijos de Olofin) se fracturarán sus\n       muslos, pero Él no debe sentirse triste por esto porque ellos tendrán\n      éxito en sus vidas. Él fue preguntado para sacrificar tela keloku para\n               ser usada para cubrir a los niños. El obedeció y sacrificó (☼).\n\n\n2.4 · Cuando me desperté en la mañana vi una multitud de niños. Yo\n              pregunté por el reino de la tierra. Yo conocí a los mayores en su\n          mayor esplendor. Yo pregunté por el reino del cielo. Orişa-Nlá iba a\n          visitar a Orunmila. Él preguntó ¿qué son de tus hijos que me llevé a\n                recorrer el mundo?. ¿debe haber frío? ¿deben haber dolores de\n      cabeza? ¿debe haber malaria y otras enfermedades? ¿qué debo hacer\n          por ellos? Orunmila le ordenó marcar Odu Oyeku Meji en polvo de\n             iyerosun. Arrancar algunas hojas jóvenes de peregun y molerlas.\n               Mezclarlas con manteca de cacao y usarlo para embadurnar sus\n          cuerpos. Peregun siempre descargará abundante agua sobre muerte.\n               Peregun siempre descargará abundante agua sobre enfermedad.", "origen_id": "e89252c348ecff2a5e55a1cf"}, {"titulo": "Relato en inglés 1", "texto": "“Toy swords have hollow chests”! was the one who cast Ifa for Qlasumogbe\nwhen she was weeping and moaning because she had no child. They said she\nshould sacrifice one she~goat, the tail of a horse, her homespun? underclothing,\nand eleven shillings.\n\nQlasumogbe listened and she made the sacrifice. They said she would bear a: son\nand that she would live to see her child take a title. Ifa says that this is a woman\nwho is seeking children; if she is able to make a sacrifice, she will bear a son.\nShe will live to see her child take a title.\n\nWhen Qlasumogbe was seeking children and could not find any, she consulted\nthe diviners. They told her that she would give birth to a child, but that she\nshould make a second sacrifice so that she might also live to see her child take\na title. Soon afterward Qlasumogbe became pregnant and gave birth to a boy.\nWhen he grew up, he was made the chief priest of Qsara.? On the day that he was\ngoing to receive his title, rain began to fall. He wanted to stop to greet his moth-\ner,? but the rain would not let him. The rain began to fall and to beat down \"giri,\"\nand he began to sing:\n\n“Qlasumogbe, I cannot stop to see you;\n\n\"'He lives in the rain’ knows the king, rain comes.”®\n\nF'rom that day on, the people of Mọrẹ ward have sung this song whenever they\n\"tie the coconut\"? and dance.", "comentario": "1. Agada is a toy wooden sword made for children. It is shaped like a short\ncutlass, and has a groove running along the length of the blade. It is to this\ngroove that the “hollow chest” refers.\n\n2, A type of cloth made locally of coarse, unevenly spun cotton thread,\nwhich in Lagos is looked down upon as “back-woods” or “up-country cloth,” aṣọ\noke (cloth of the hill).\n3. A deity. See n. 4, verse 6-5.\n\n4, When a chief or priest is installed, he goes about town accompanied by\nhis friends and followers, visiting and greeting his relatives and the town of-\nficials.\n\n5.. The sound made by rain falling heavily. Cf. n. 2, verse 17-2.\n\n6. Informants, with considerable uncertainty, interpreted this as meaning\nthat someone by this name saw the king for the first time when it was raining.\n\n7. During the Coconut Festival (ọdun agbọn), which is performed by the\npeople of More ward in the city of Ifẹ in honor of the deities Qsara and Qlọshẹ\n(cf. verses 6-2, 6-5, 6-6), the dancers tie to their enkles rattles made of peb-\nbles enclosed in dried coconut leaves. This verse explains the origin of one of\nthe songs used in this festival.", "origen_id": "a30e2eebf1bb903104cd0912"}, {"titulo": "Relato en inglés 2", "texto": "“Smoke is the glory of fire; lightning is the glory of rain; a big cloth is the\nglory of Egungun\"? was the one who cast Ifa for Tree Bear,® the child of “One who\nhas had wealth\n\nsince the morning of his youth.\" They said he should make a sacrifice against\nsickness, of one he-goat, three shillings, and one black cloth.\n\nWhen Tree Bear consulted the diviners and they told him that he should sac-\nrifice because of a serious illness, Tree Bear heard the sacrifice, but did not\nmake it. Not long afterward, Tree Bear fell ill; he nearly died. Then he again\nconsulted the diviners, and they told him that things would be bad unless he could\nmake the sacrifice they had prescribed for him, and that now he must make it\ntwo-fold. Tree Bear made the sacrifice as soon as he could. They told him that\nsince his illness had been so great, he would make himself heard, and that there\nwould be no tree within his reach that he would not be able to climb to the very\ntop.\"\n\nIfa says that this is a gentleman.\" He should make a sacrifice lest he be-\ncome so ill that his house and home must be sold® before the illness is cured,\nand lest the illness drive him out of town.”", "comentario": "1. In the same sense that we speak of hair as a woman’s crowning glory,\nbut also with the meaning “Where there’s smoke there’s fire.”\n\n2, This refers, of course, to the costumes beneath which the Egungun danc-\ners conceal their bodies. Cf. n. 6, verse 7-5.\n\n3. The gfafa or gwawa (Tree Hyrax) is an herbivorous animal that lives in\ntrees. It is said to eat the leaves of the trees, but only those leaves which do\nnot have holes. Its call, “wa wa wa wa,” can be clearly heard at night.\n4. This verse explains why the tree bear can be heard so clearly at night,\nand why it can climb so well. The idiom“to have a voice” means also “to be\nlistened to” and thus implies that the client will become a person whose opinions\nare respected.\n\n5. A person of moderate means, but good reputation.\n\n6. To pay the doctor's fees. “House and road” is an idiom for all the proper-\nty that one owns,\n\n7, That is, so that he may not contract a contagious disease like leprosy, be-\ncause of which he would have to be isolated, and leave town.", "origen_id": "1f2bb8eef95e0bdfee14782b"}, {"titulo": "Relato en inglés 3", "texto": "“The rich man states his case in court,’ water near the house of the Alake;!\n‘The rich man is not judged guilty,’ water on the road to Ijero;? ‘There is no wa-\nter in which we kill a poor man,\"? water of Ijero, water of Ojugbe” was the one\nwho cast Ifa for “Diviner comes,” the child of the King of Qyg, the one who ate\nshea butter in the farm because of poverty long, long ago.\n\nThey said that the Sky God would kindle the fire of destiny for him during that\nyear. Four pigeons, two shillings six pence, and the trousers from his waist was\nthe sacrifice.\n\nWhen “Diviner comes,” the child of the King of Ọyọ, had made this sacrifice,\nthe King of Qyg died soon afterward, and they took “Diviner comes” and made\nhim King of Qyg. Ifa says someone is living in poverty and is being driven here\nand there by troubles. Ifa says he will return a rich man; everyone will gather\nto serve him, and he will take a title in the house of his father.", "comentario": "1. The king of Abegokuta.\n\n2. A town in Ekiti, east of Ife.\n\n3. The names of these three bodies of water, taken together, have the fol-\nlowing meaning: A creditor, or the “one who owns the money” is always given a\nchance to present his side of the case in a trial, and he is never judged guilty in\na suit to collect money, since loaning of money is not a crime. However, in\nspite of the fact that the courts may operate in favor of the rich, a person cannot\nbe condemned to death simply because he is poor and cannot pay his debts.", "origen_id": "decbbe0fd1d7e08adaa697ee"}, {"titulo": "Relato en inglés 4", "texto": "“When it is held in front, even a short staff brushes the dew from the path;\nthe soles of both feet strive hard with one another to win the road;! the sword?\nof the women’s loom has a dull edge” was the one who cast Ifa for the 165 kinds\nof cloths, and who shared it? with Calico. They said the 165 kinds of cloths\nshould make a sacrifice, and that Calico should also sacrifice lest they all meet\ndeath at the same time. The 165 kinds of cloths did not sacrifice, but Calico\nalone sacrificed.\n\nSoon afterward the owner of these cloths died, and the people of his house\ncalled all the cloths together to get ready to accompany their owner to heaven.\nThey laid out all the cloths on the ground, putting Calico among them. But\nEshu said:\n\n°\n\n“Oh shoko”;\nand the people answered:\n“Bani.”\nHe said:\n\n“Calico sacrificed, oh;\n“Calico propitiated;\n“The fashionable cloth® should not be taken to heaven.”\n\nWhen Eshu finished speaking, the people set Calico apart from the other cloths\nin which the corpse was to be buried. From that time on, we have been for-\nbidden to bury the dead in a red cloth or any cloth which has red in it.\" The\nsacrifice is one red cloth, one he-goat, and three shillings.\n\nIfa says that the person for whom this figure was cast should make a sacri-\nfice in order that he and his relatives should not meet death at the same time,\nand especially that the Bale® of this person’s house should sacrifice with him,\nthat he should not meet death during this year.", "comentario": "1. That is, to get ahead of one another, to compete as in a race.\n\n2. Cf. n. 9, verse 7-5.\n\n3. Many things are spoken of as having 165 varieties. There are said also\nto be 165 kinds of trees (verses 33-2, 183-1); 165 kinds of animals (166-1, 249-6);\n165 kinds of rats (246-4); and 165 kinds of leaves (250-3).\n\n4. This means that the prediction also applies to a person other than the\nactual client, as where, later in this verse, a prediction is made about the head\n\nof the client’s lineage. The word “bu” is also used with reference to the sharing\nof food.\n5. Cf. n. 4, verse 1-7.\n\n6. Calico is compared here to humans who are neat, well-dressed, and care-\nful about their appearance; to a man of fashion.\n\n7. This verse thus explains why no cloths that have any red coloring may be\nused by the Yoruba in burials, but the usual reason given is that if cloth with red\nin it were used, the deceased would be reborn as a leper,\n\n8. The lineage head; eldest male member of the lineage of the compound.\n\nLa", "origen_id": "e3d1e92b1b51f300ed03dc36"}, {"titulo": "Relato en inglés 5", "texto": "Qrunmila said he would beget something great; they said Ifa should beget\nsomething great; when he begat, he begat Farm.!\n\nQrunmila said he would beget something great; they said Ifa should beget\nsomething great; when he begat, he begat Market.\n\nQrunmila said he would beget something great; they said Ifa should beget\nsomething great; when he begat, he begat War.\n\nQrunmila said he would beget something great; they said Ifa should beget\nsomething great; when he begat, he begat Road.\n\nQrunmila said he would beget something great; they said Ifa should beget\nsomething great; when he begat, he begat House last of all.\n\nAfter this Qrunmila went to the house of the Sea Goddess to divine, and he\nlived there sixteen years before he returned. When he was coming home, War\nwas the first one he stopped to visit. War greeted his father at great length,\nand gave him lots of food. When Qrunmila had finished eating and drinking, he\ntold his child, War, that he wanted to defecate.? War told him that no one could\ndefecate in his house. Qrunmila then got ready and went to visit Market, who al-\nso was his child. He did the same things at the house of Market: he ate and drank\nand then said he wanted to defecate, and Market told him that there was no place\nto defecate. Then he\n\nwent to visit Farm, and did likewise; and Farm told him the same thing that the\nothers had. Then he went to visit Road and exactly the same things happened to\nhim at Road’s house. Finally Qrunmila got ready and went to visit House.\n\nWhen he arrived and House saw his father, he killed a she-goat and cooked\nlots of food; he pounded yams and he told his friends to come and help him enter-\ntain his father. When Qrunmila had finished eating and drinking, he said he want-\ned to defecate. House ran and opened a room for his father. He said, “You are\nthe owner of my house. My father can defecate anywhere that he pleases in this\nroom.” When Qrunmila entered the room, he closed the door after him and he\ndefecated in the room. When he came out, he shut the door again. Not long after-\nwards he told House that he wanted to defecate again, and House opened another\nroom for him, so that he might go to defecate in it. When Qrunmila went in, he\nagain closed the door after him and again he defecated as he had the first time.\n\nWhen Qrunmila finished defecating, he said that House should go and open\nthe door of the first room. He said House should go and clean up the excrement\nthat he had left there. When he went in, he found that the room was piled high\nwith money. When he opened the door of the second room, he found many dif-\nferent kinds of beads. Then Qrunmila said that from that day henceforth, the\nprofits of everything that\n\nFarm, Road, Market, and War should do would be enjoyed by House?\n\nIfa says that a visitor is coming; we should take good care of him lest his\nkindness and goodness pass us by, because the visitor brings something that can\nbenefit us.", "comentario": "1. In this verse also it is clear that Qrunmila and Ifa are the same person.\nSee also n. 2, verse 1-4.\n2. To “shake your feet” is a Yoruba euphemism for defecation.\n3. The verse thus explains why the produce of the farm, the profit of trading\nin the market and in other towns, and the spoils of war are all brought back to the\nhouse to be consumed.", "origen_id": "ab403ab863184296253d1eaf"}, {"titulo": "Relato en inglés 6", "texto": "“Unsteady is the boat; so also are human beings”?\nfor Qna Ishokun? who was the child of the king of Qyg.\n\n“Black death rubs his body with black camwood;$ red death rubs his body with\nred camwood; one who doesn’t know how, rubs his body with the red earth of the\nfar distant sky;* words like this, like this” was the one who cast Ifa for Itu, the\nhusband of She- goat and who shared it® with Husky Ram, the husband of “The one\nwho licks flour,’® and who cast Ifa for “Very tall cock of the town of Ọta,\" the hus-\nband of “Very good” hen.”\n\n“One who is a coward should not talk like a hero; one who is a hero should\nnot talk like a coward; the king does not allow us to make war upon a town of wom-\nen,® that I. go with them; one should behave gently so that he may die quietly, and\nhis children be able to come to bury him\"? was the one who cast Ifa for the chief\nof Apa-Moru, the child of “The one who wakes every dawn to sacrifice a big fish\nbecause she does not have children.”\n\nwas the one who cast Ifa\n\n“Then for the first time I come to the town of Aro.\n\n“I say, What are they doing at Aro? '\n\n\"They say they are taking a new title at Aro.\n\n“I say, The chief will grow old like Oluyẹyẹ? has grown old;\n\n“I say, The chief will grow old like Oluyẹyẹtuyẹ.\n\n“He will grow as old as Oluaso, the young wife,\n\n“Who was both beautiful and brave,\n\n“Who used blacksmith’s hammers” as beads for her neck,\n\n“And the hammers wore down and down and down until they were as\nthin as needles?”\n\n“Go softly, 18 people of the town of Apa,\n\n“Child of One who every morning begets children like birds,\n\n“Chief of Apa, child of fish,\n\n“Child of fish, child of fish is what we call the Chief of Apa,\n\n“Chief of Apa, child of fish.”\n\nOne big fish, one she-goat, and one hen\" is the sacrifice. Ifa says that this\nperson will bear many children.", "comentario": "1, A fickle person who denies tomorrow. what be says today is as unreliable\nand unsteady as a canoe being tossed upon the waves.\n\n2. Translated by the informants as “Road to Igokun,” this was later identified\nas the title of an important chief and a member of the royal family at the town of\nQyg. Cf. S. Johnson (1921: 42).\n\n3. According to the informant, “black camwood” means charcoal. However\nDalziel (1937: 357-358) gives osun dudu as a name for Pterocarpus erinaceus and\nosun pupa, “red camwood” (or, better, barwood), for Pterocarpus osun.\n\n4. The meaning of this entire passage is obscure. Neither charcoal nor\ncamwood are used to rub the body of the dead before burial in Ifẹ, though cam-\nwood is used by living people to decorate themselves. The red earth and the far\ndistant sky, however, are said to refer to interment after death, and the passage\nof the soul to heaven. The only meaning that informants could read into this pas-\nsage is: “Anyone who doesn’t know how to behave correctly must die.”\n\n5. See n. 4, verse 18-4,\n\n6. “The one who licks flour” is a praise name of a female sheep; “Husky\nRam” is that of a male sheep; and Itu, that of a male goat.\n\n7. Yanran-yanran represents the sound made by a brick which has been cor-\nrectly baked when it is tested by tapping; it means “good” or “up to the required\nstandard.”\n\n8, That is, he will not let us attack a town composed only of women, or take\nthe women of our own town as slaves.\n\n9. This means that a person who lives a good life and treats others consid-\nerately will die quietly at home; but a person who behaves badly is apt to die in\njail or far from home, so that his children cannot bury him,\n10. The names Oluyey¢ and Oluyeyetuye, whose tones are different, have no\nmeaning, but they apparently stand for someone who lived to a ripe old age.\n\n11. The blacksmith’s large hammer is known as owu; the smaller one is\nknown as the “child” of owu.\n\n12. That is, Oluaso lived so long that her beads, even though they were made\nof blacksmith’s hammers, almost wore away.\n\n13. This phrase is used as a salutation in much the same way as the English\n“hello.”\n\n14, Note that all these appear in the names ofthe legendary characters.", "origen_id": "6f85f8cecb5b955424a9d4f2"}, {"titulo": "Relato en inglés 7", "texto": "“One should not reveal secrets to women, women are liars, women\nare the ones who break oaths; Olojongbodu is what the wife of Death is called;+\n\nthe slender, fruitful palm tree beside a river ducks its head suddenly so that the\nbody? of Death falls to the ground ‘gbirimu’”’ was the one who cast Ifa for the Eji\nQye* when he was going to avoid Death on the head of Alayunre.\n\n“Well then, who avoids Death today on the head of the diviner?\n“Only divining powder avoids Death today on the head of the diviner.”\n\nWe will mark Qyeku Meji in the divining powder on the tray; we will put some\non the client’s head; or we will take some of it, grind it with cornstarch porridge,\nand drink it.\" Or we will take an arg leaf® and grind it; we will mark Qyeku Meji\nin it; we will drink it with cornstarch gruel.”\n\nThey consulted together. They called Olojongbodu, who was the wife of Death.\nThey asked her what Death ate. She said that Death ate rats, fish, and meat. They\ngave Death rats, fish, and meat, and when Death had finished eating, his hands and\nfeet began to tremble “riri,” and Death’s body fell down “gbirimu.”®\n\nWe will sacrifice rats, fish, and meat; we will carry the sacrifice to the base\nof Eshu.", "comentario": "1, . Note that this identification is repeated in the verse.\n2. Even when a living person falls down, it is said that his “corpse” (oku)\nfalls.\n\n3. The sound of a body falling to the ground. Cf. n. 2, verse 19-1,\n\n4. Eji Ọyẹ is an alternative name for the figure Qyeku Meji and here it ap-\npears as the name of the character. There is an involved pun on these two names\nfor the figure, “he avoids death” lo yẹ-(i)kuJ, and divining powder (iyẹ).\n\n5. Cf. n. 6, verse 1-5.\n\n6. Crossopteryx febrifuga.\n\n7. Cornstarch gruel (ekg mimu) is a hot liquid which frequently serves as\nbreakfast. Cornstarch porridge (ẹkọ tutu), mentioned earlier, is a solid which in\nthis case is mixed with cold water so that it may be drunk. Cf. Bascom (1951:\n128-129).\n\n8. Gbirimu refers to the sound made by the fall of Death’s body; riri de-\nscribes his trembling. The implication is that Death, having eaten their food, is\nafraid to kill them. Cf. “Death cannot eat a person's food and then kill him”\n(verse 6-2). It is further implied that the client, like Eji Qye, can escape death\nif he makes the prescribed sacrifice.", "origen_id": "8d024e7ae6b2ee359576c73d"}, {"titulo": "Relato en inglés 8", "texto": "“The fire is very hot on the face of the one who gathers honey;! the sun is\nvery, very hot on the buttocks of the farmer;? the one who gathers honey has\n\nlosses; the honey bee swarms, and the honey of the Ado bee® spoils; but the house\nof a diviner is never empty.”*\n\nIfa says he will not allow us to draw a blank in the thing for which we are\ndivining. Two hens and nine pence six oninis is the sacrifice.", "comentario": "1. The fire used to smoke out the bees. The one who gathers honey is al-\nways in danger of being burned.\n2. As he bends over, hoeing or weeding in the farm.\n3. There are two types of bees: (1) the igan or oyin, which lives in trees or\nhives and whose honey is known simply as oyin or oyin igan; and (2) the Ado bee,\nwhich lives underground and whose honey is known as oyin ado. The honey bee\nmoves to a new hive when its honey has been taken.\n\n4. This passage as a whole points out that the life of a diviner is to be pre-\nferred to that of the farmer and to that of the person who gathers honey. Note\nthat though these phrases resemble those usually interpreted as diviners’ names,\nno divination for a legendary character is cited.", "origen_id": "23636f47563e5ac9b946cc8b"}, {"titulo": "Relato en inglés 9", "texto": "“The man stands guard? over eggplant,” the eggplant dies, but the man still\nstands over it” was the one who cast Ifa for Aro of the house and beat the palm\nnuts for Aro of the farm. Ifa says that two people or two friends should sacri-\nfice one full-grown he-goat, three shillings, and one cloth to cover the body each,\nlest they both meet death at the same time.®\n\nAro of the house and Aro of the farm were two friends. The diviner said\nthat they should make a sacrifice, lest they both meet death at the same time.\nAro of the house refused to sacrifice, and Aro of the farm also failed to appease\nEshu. Aro of the house died in the house, and Aro of the farm died in the farm.\nThey said that Aro of the farm should be carried to the house. When they had\ncarried Aro of the farm to the house, they said that kgs children should come and\nbegin the entertainment for the dead‘ for their father. But they said that they had\nbeen so long in the farm that they no longer knew how the drums should be beaten.\nBecause of this the people of Ifẹ still say that “Aro stayed in the farm so long\nthat he no longer knew how the drums should be beaten.” And they also are the\nones whose children or the male relatives in the house® sing, when anyone dies,\n\n“Jorojorojo,” ‘He beats palm nuts and knows the future’;\n“Jo, Jo, ‘He beats palm nuts and knows the future’”®\n\nuntil this very day, in the town of Ifẹ.", "comentario": "1. To stand astride something to keep it from escaping.\n\n2, Solanum incanum.\n\n3, Miller (1902: 280) cites a similar prediction, also from Qyeku Meji,\nrecorded at Atakpame, Togo. Cf. verse 18-10.\n\n4. A part of the funeral ceremonies, spoken of as the “play of the dead,” is\nperformed to amuse the deceased; on the surface, at least, it is jolly.\n\n5. This verse thus explains the origin of this If¢ proverb, which is used to\nchide anycne who has forgotten the traditional rituals, It may also be used to\nridicule those who live most of the time in the farm and who are despised as\nignorant,\n\n6. In terms of age the male clan members of a compound are divided into\nthree groups: the elders (agba ile), the adult males (isggan) who have achieved\neconomic independence from their fathers, and the “children of the house” (ọmọ\nile)—the young men and boys who are still dependent on their fathers. The\nisggan are responsible for funerals of clan members.\n7. “Jorojorojo” and “Jo, Jo” in the following line have no meaning but are\nsaid to be included simply to “make the song sweet.”\n\n8. “He beats palm nuts and knows the future” is one of the praise names of\nQrunmila (see verse 6-3). This verse also explains the origin of a song associ-\nated with funerals in If¢.", "origen_id": "7489da47b27964f3d161b930"}, {"titulo": "Relato en inglés 10", "texto": "“Death alights on top of the eggplant, the eggplant falls to the ground “gbiria”;!\nthe alukunrin bird does not bathe, it does not rub its body, but it shines very bright-\nly like the child of one who makes palm kernel oil’* was the one who cast Ifa for\nAlapa of the house and beat palm nuts for Alapa of the farm. Ifa says that two\nfriends should make a sacrifice lest they both meet death at the same time. A full-\ngrown he-goat each, three shillings, and the red cloths which they had bought to-\ngether as comrades is the sacrifice.\n\nAlapa of the house and Alapa of the farm were two friends each of whom had\nbought a red cloth to cover his body at the same time. A sacrifice involved these\ntwo friends; they were told that they should sacrifice. They listened, but did not\nmake the sacrifice. Eshu pointed ebgn (medicine or “send to someone”*) at them,\nand they became ill on the same day.\n\nWhen Alapa of the house saw that his illness was*serious, he told his family\nthat if he should die, they should carry his body to Alapa of the farm, because he\nwas the one that knew the atonement that was to be made at his death. When\nAlapa of the farm also saw that his illness was serious, he said that if he should\ndie, his family should\n\ncarry his body to Alapa of the house, because he was the one who knew the atone-\nment that was to be made at his death.®\n\nNot long afterward both of them died; it was on the same day that they died.\nThe family of Alapa of the house wrapped him and set out carrying him to the\nfarm; to cover him they used the red cloth® that he had bought with his friend.\nAnd the family of Alapa of the farm also wrapped him when he died, and to cover\nhim they also used the red cloth that he had bought with his friend. They set out,\ncarrying him to the house. But before they could carry one to the other, they had\nto pass each other in the center of Ejigbomekun market. As they came out into\nthe market carrying the two dead bodies, one on this side and the other on that,\nand with both bodies covered with the same kind of red cloth, the people in the\nmarket said, “This is fitting for these two dead bodies, oh.\" The two dead bodies\nfor which it is fitting is what we call Qyeku-meji.”", "comentario": "1, The sound of falling to the ground. Cf. n. 2, verse 19-1, and n. 8, verse\n18-7.\n\n2. The oil (adi or adin) made from the kernels of the palm nut is used in rub-\nbing the body (cf. n. 2, verse 6-3). The members of the adin maker’s family are\nkept very shiny, since they have all the oil they wish to use.\n\n3. Friends, or the members of a club, frequently wear identical garments as\na symbol of their comradeship.\n\n4. A type or category of charm which, as its name indicates, works on the\nvictim at a distance.\n5. In accordance with the Yoruba institution of “best friends” (korikosun),\nthese two had confided in each other what rituals and sacrifices had to be made\nat their death. The refusal to sacrifice thus not only brought about their deaths,\nbut also caused them to be buried without the proper atonements.\n\n6. Red cloths are tabu for burial. Cf. verse 18-4.\n\n7. Note the pun on the name of the figure (Qyeku Meji), which takes the form\nof giving an etymological interpretation of its meaning: o-y¢-(o)ku-meji (it-suits-\ncorpse-two). Cf. the similar verse recorded by Epega (n.d.; III, 19) for Qyeku\nIwori.", "origen_id": "d7f30c609ae5eec9e4f6a739"}, {"titulo": "Relato en inglés 11", "texto": "“The first signs of dawn! are just appearing; people think that day is break-\ning” was the one who cast Ifa for Ewe of the town of Ipopo who did not have a rope\nabout her neck, of whom people said that she was no longer able to bear children.”\nTime passed, and she bore a great many children.\n\n“At Shopo-Agada she gave birth to Eyinkoto” was the one who cast Ifa for\nShopere, who was the mother of Rain.\n\n“It is in flocks that we meet rain,\n“Rain does not walk alone.”>\n\nIfa says that this person will have children and will have many followers.*", "comentario": "1. Note the pun on the alternative name of the figure, Eji Qye.\n\n2. Believing that she would never again be in heat, people felt that it was no\nlonger necessary for her to be tethered by a rope. Note the pun on “rope” (okun)\nand “endurance” (okun). Ewe is given as aguntan or agutan.\n3. Rain drops do not come singly.\n\n4. A person's followers includes both his friends and the members of his\nfamily —all those upon whom he can count for support in legal, financial, or\nsocial matters. Cf. n. 2, verse 7-4. A large personal following is one of the\nmain personal goals of the Yoruba. (See Chapter VII.) Though there are two\ndivinations cited as precedent in this verse, both imply the same prediction.\nBoth rain drops and the children of Ewe of the town of Ipopo are numberless\n(yindin-yindin). Cf. the versions of this verse recorded by Beyioku (1940: 5, 27).\n\n18 ~ 12\n\nQrunmila says there will be a crowd; I say there is a crowd. In crowds we\nfind ẹhan;! in crowds we find wild boars. We don't find “One who keeps silent’?\nwalking alone; we don’t find “Greedy” walking alone. “One who keeps silent” is\nthe name that we call Ewe; “Greedy” is the name that we call Cane Rat.>\n\nIfa says that this person will form a crowd‘ and will not walk alone. Ten\nrats, ten fish, and ten hens is the sacrifice.\n\n\"\n1, An unidentified wild animal living in the forest.\n\n2, One who can talk, but doesn’t want to. Cf. verse, 249-5.\n\n3. Thryonomys swinderianus, popularly called “Cutting Grass.” See Abra-\nham (1958: 533).\n\n4. That is, he will have many followers. Cf. n. 4, verse 18-11.", "origen_id": "7aff8d3d6384236e2f614626"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlọ́fin: tela negra, una chiva y hojas y frutos de bìjé; marcar la cara con bìjé y cubrir el Ifá con tela negra.", "La palma: un pollo paseado alrededor de los árboles.", "Los hijos de Ọlọ́fin: tela kẹlẹku para cubrirlos.", "Medicina de Òrìṣà-ńlá: hojas tiernas de pèrègún molidas con manteca de òrí e iyẹ̀rosùn marcado con el Odù, untadas en el cuerpo.", "Onikabidun: 4 palomas, 4 gallinas, una rata, un bagre negro, aceite de palma, un plato blanco y dinero, a Ìbejì; cinco azadas marcadas con iyẹ̀rosùn para la casa y cinco para afuera.", "La mona: 5 palomas, 4 gallinas, un plato blanco, aceite de palma, ñame machacado y dinero, a Ìbejì; ñame machacado al Òrìṣà de la persona y lana enrollada en la olla de su Òrìṣà. Prohibido: rata gris, y taparse la cabeza con hojas cuando llueve."], "pasajes": [{"titulo": "Ofrenda en el verso 2.1", "texto": "Ọ̀yè dúdú el adivino de Orí Bijé:\nadivinó Ifá para Ọlófin.\nLe pidieron que sacrificara:\nuna tela negra, una chiva, hojas y frutos de bijé.\nLe dijeron que esto le impediria a la muerte matarlo,\ntampoco la muerte repentina mataría a sus hijos,\nsi él hacia este sacrificio.\nEl obedeció y sacrificó.", "origen_id": "13d93be6d8c292a527bca376"}, {"titulo": "Ofrenda en el verso 2.2", "texto": "Eesin gbona l'ewé tutu l'egbo:\nadivinó Ifá para los 165 árboles.\nA la Palma y al árbol de Ayinrẹ\nle aconsejaron sacrificar:\nun pollo alrededor de los arboles.\nDesde entonces, cuando un tornado está arrasando,\nla palma joven declarará:\n\"yo hice el sacrificio para escapar del peligro\".", "origen_id": "06b593018865b439aa079809"}, {"titulo": "Ofrenda en el verso 2.3", "texto": "Tủ eres yẹ̀,\nYo soy Qyẹ̀.\nDos ọyẹ̀:\nadivinaron Ifá para Ọlófin.\nEllos dijeron:\n\"dos de sus hijos se fracturarán sus piernas,\npero no debe sentirse triste por esto\nporque ellos serán exitosos en sus vidas\".\nLe aconsejaron sacrificar:\ntela de Kelẹku,\ny usarla para cubrir sus hijos.\nEl obedeció y sacrificó", "origen_id": "d52c2606981a3bb125a50761"}, {"titulo": "Ofrenda complementaria 1", "texto": "5 eiyelé (pichón), 4 abo adie (gallina), 1 plato blanco, 1 epo (botella de aceite de palma), iyan (ñame molido) y cantidad de dinero establecida por el Awo\n\nDestinatario: Ibeji", "origen_id": "67f4619bc2b1d8879af334a7"}]}, {"titulo": "Relaciones espirituales", "texto": "Orí debe apaciguarse con frecuencia para no caer en la tristeza. Los ancestros sostienen a la persona cuando está en buena fortuna. Òrìṣà-ńlá y Ọ̀rúnmìlà aparecen cuidando a los hijos del mundo. Ìbejì recibe las ofrendas de alegría y de conservar lo ganado.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Egun", "origen_id": "28bb1b9b6f0ccec3ae19a887"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Bìjé (hojas y frutos), pèrègún, manteca de òrí, iyẹ̀rosùn, àyìnrẹ̀, palma, chufa, ñame machacado, tela negra y tela kẹlẹku."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 2.4", "texto": "Moler hojas tiernas de Pèrègún', , añadirle òrí e iyè- Ìrosùn del Odù Ṣyẹ̀kú Méjì con el siguiente encantamiento. Usar la medicina para untar en el cuerpo.\nEncantamiento: Pèrègún ṣuṣu a d'omi pa'nọ ikú Pèrègún-ṣuṣu a d'omi pa'no arùn.\nEl vivaz (siempre verde) Pèrègún derramará agua a la rabiosa muerte.\nEl vivaz Pérégún derramará agua a la rabiosa enfermedad.\n\" Pérègún: DRACAENA FRAGRANS (L.) Ker Gawl., Agavaceae.", "origen_id": "3d0cea15e9b8d7ef79552285"}]}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 1", "texto": "rata gris; no cubrir la cabeza con hojas cuando llueva", "origen_id": "6e3f5f560381c55892fe206b"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 2.1 (yorùbá): Oyè dúdú awo Orí Bijé: / li o dífá f’Ọlọ́fin. / A niki ò rú: / Aṣo dúdú, ewúrẹ, ewé ati eso bijé. / A ni ikú ti o nbọ yi ko niipaa, / ko niipa omo rè, / bi o ba rúbọ / Ó gbọ̀ ó rú.", "Verso 2.2 (yorùbá): Eesin gbona l'ewé tutu l'egbo: / li o dífá fún Márünlelogéjọ igi oko / Opẹ̀ ati Ayinrẹ li o ru: / Oromodie ninu wọn / Nitorinaa bi iji ba nja / Ọgọ mariwo a ni: / \"Oun ṣẹbọ Öyèkẹṣẹ\".", "Verso 2.3 (yorùbá): Two bye. / Emi ọ̀yọ̀, / Qyẹ̀ Méjì: / li o dífá f’Ọlọ́fin / Wọ̀n nì: / “Méjì a ṣe’tan ninu àwọn ọmọ rẹ̀ / ti o maabi ṣügbọ̀n kioma binu / nitoripe won a ri're\". / Wọ̀n niki ó wa rúbọ: / agp Kplẹku, / ki àwọn ọmọ na mafi bo'ra. / Ó gbọ̀ ó rú.", "Verso 2.4 (yorùbá): Jiji ni mo ji / mo b'omodé wẹrẹwerẹ, / mo bere Isalu Ayé, / mo b'awarẹ sokąsoko, / mo bere Isalu Orun. / Oriṣà-ńlá nlọ sọdọ Ọ̀rúnmìlà, / ò n: / Awọn omodé rẹ ti oun nko lo si Ayè yi? / Otutu mai dee? / Efori mai dee? / Ẹdunra ati bẹẹbẹẹ mai dee? / Kini ki oun maaṣe fún wọn? / Ọ̀rúnmìlà 1 kiotẹ / Odù Ọ̀yẹ̀kúméji ni iyè-iròsù, / kio ja aṣẹṣẹyo pèrègún ki o lọọ / ki o pa wọn pọ mọ òrí / ki o maa fi para fùn wọn / Pèrègún ṣuṣu a d'omi pa'ną ikú / Pèrègún-ṣuṣu a d'omi pa'no arùn.", "REZO: OSHEIWONO OSHEKU OMO OLOKU AWO ONI OGBONI OGUNGUN UMBOWNILE ORUNMILA OSORDE OYIYI EBBO ORINDILOGUA ABO KAN OSHEIWOMO KOBO IYAKU EGGUNGUN BABA ALAGBANAGBA OKUNI OLEJA IKONONIYE TADAGO ASHIKUELU OAJO OYEKUN AWO KOBO OSODE OSHEIWONO OSHEUNLO EGGUN ADIFAFUN OMO OLOKUN AWO KAFEREFUN EGGUN.", "REZO: BABA OYEKUN MEYI ARIKU MADAWA EYO OGGUN SIGUN MOLE POROREYARUN OÑI PO UN BABALAWO ADIFAFUN OGBE OLUWO AGOGO, ABO LEBO.", "REZO: BABA OYEKUN MEYI BABA OLOFIN OYU INLE EGBA NIYERUN EGBA AKUE LELE SHANGO OKO OMO ABBA AYE OWO ORINDILUGUN BEWA OYEKU IFA SHANGO ATEFA ODDUN IFA OKUE DARA ORUNMILA NI LARE IFA ODARA BABA MOKIO SHANGO MORARA OBBA OKUELELE OYEKU MEYI BOYOMIWO AWO KUELELE BABA OLOFIN ORUNMILA AYOYE ORUN OMI BARGABANI LEGUN.", "REZO: OYEKUN MEYI BABA OYEDI ADIFAFUN BAREOKO OYO OYIMI FUN OKANA REFU OKUDA.", "REZO: ADIFAFUN SHANGO OYIYI OPON EYA TUTU EKUADO EYA TUTU EYIGUMEKUN ARUYE OTENURE AYE AIYE CONYE AIKU OFO ARUN IKU OPA NI EGUNGUN KOPONI SHANGO KOPONI OLOFIN EYA BATUTO UMBO WAIYE SEKUN ODARA LODAFUN SHANGO EYA OMOLORUN KAFEREFUN OLEYE KAFEREFUN OLOFIN.", "REZO: AYAYA OMONIFUN AFON BALE BELELE IROKI ADIFAFUN AWOYENI OMOLUNI ORUN OSHUN AWONI ORUBO NATORI OMO OGBONI OFOJI OMI OSI OGBO ERI ATUKESHU OTUN KAKARA EBBO YAFUN AWON OÑI IFA INLE OSHUN OBAYEWO BEWA OBALU AYE OMOLU ORUNMILA ORUN LALA OSHUN KAFEREFUN OBALU AYE KAFEREFUN ORUNMILA.", "REZO: IWO OYE EMIOYE OYE SHESHENLA BOLOKE AWOSHE BOYUMO NIMO ADIFAFUN EYA TINSHOMO WO LADE ODO AWONI EYA ORUBO AWONI PIPO NIRE OMODE SHUGBO BORUKO KORUBO AREYE KORU ONI BAWO LAWO OTA ASHELE ONIRAN ARAWO OMO OUN LALE ODO OPAWO LEKE OPA ESHU LOLE OWORUN ÑAÑA BI ENITI ONIKU OKOTI OSHEBO TOMO ARAYE DIDE AWO NAWO OKO ADA ATI OGBUN AWO SE ODU AWO SIBERE SIGBONO IGBA TO MITALEÑ EYA ATI AWO OMO ORE NI AWO OMO ARBAMU AWO AGBA SIFI AGBALERI IÑA", "ASHE ESHU NI KOYEBI AWO OMO EYA OLE ELAYE ASHUGBO TITI DONI OLONI AWO OMO ARAYE IKO AWO OMO EYANI.", "REZO: OKUNI KIAGE KEKO MAMU OMI LOWO INLE SHISHE MANU OMO INSHE ILE LODAFUN ORUNMILA ADIFAFUN OKUNI KAFEREFUN ASHEDA.", "REZO: BABA OYIYI MEYI ADIKU MADAWA FOFO FORO ORANIYAN OMO OKUNI AKIO ALABARA MANA MANA SHANGO SHANGO OYA MINI BABA ALAFIA OBA EYO LAMORUN IFE ALORUN OLOYO OBANIYAN OBONIBOSHE AKINFA ADIE WAWASHE TI AGUEMA AKUA ODUDUWA WAWASHE TIBONI ASHE OSHA LOWA OSHAGRIÑAN AIGAN INLE IBARIBA EYOLA ORANIYAN OBA ALAIYELUNA.", "SUYERE: EYO PAPA FOCHO WAO SATORI ABORENSE BOBOIKU PAKOLEPA ATORI.", "SUYERE: BABA IKU OSHEUWOMO OSHE UNLO EGUNGUN.", "REZO: OSHEIWONO OSHEKU OMO OLOKU AWO ONI OGBONI OGUNGUN UMBOWNILE RUNMILA SORDE OYIYI EBBO ORINDILOGUA ABO EKAN OSHEIWOMO KOBO IYAKU EGGUN GUN BABA ALAGBANAGBA OKUNI OLEJA IKONONIYE TADAGO ASHIKUELU OAJO OLOKUN AWO KOBO OSODE OSHEIWONO OSHEUNLO EGGUN ADIFAFUN OMO OLOKUN AWO KAFEREFUN EGGUN.", "SUYERE: BABA IKU OSHEUWOMO OSHE UNLO EGUNGUN.", "REZO: OYEKUN MEYI BABA OYEDI ADIFAFUN BAREOKO OYO OYIMI FUN OKANA REFU OKUDA.", "SUYERE: “EYO PAPA FOCHO WAO SATORI ABORENSE BOBOIKU PAKOLEPA ATORI”.", "REZO: ADIFAFUN SHANGO OYIYI OPON EYA TUTU EKUADO EYA TUTO EYIGUMEKUN ARUYE OTENURE AYE AIYE CONYE AIKU OFO ARUN IKU OPA NI EGUNGUN KOPONI SHANGO KOPONI OLOFIN EYA BATUTO UMBO WAIYE SEKUN ODARA LODAFUN SHANGO EYA OMOLORUN KAFEREFUN OLEYE KAFEREFUN OLOFIN.", "REZO: AYAYA OMONIFUN AFON BALE BELELE IROKI ADIFAFUN AWOYENI OMOLUNI ORUN OSHUN AWONI ORUBO NATORI OMO OGBONI OFOJI OMI OSI OGBO ERI ATUKESHU OTUN KAKARA EBBO YAFUN AWON OÑI IFA INLE OSHUN OBAYEWO EWA OBALU AYE OMOLU", "ORUNMILA ORUN LALA OSHUN KAFEREFUN OBALU AYE KAFEREFUN ORUNMILA.", "REZO: IWO OYE EMIOYE OYE SHESHENLA BOLOKE AWOSHE BOYUMO NIMO ADIFAFUN EYA TINSHOMO WO LADE ODO AWONI EYA ORUGBO AWONI PIPO NIRE OMODE SHUGBO BORUKO KORUBO AREYE KORU ONI BAWO LAWO OTA ASHELE ONIRAN ARAWO OMO OUN LALE ODO OPAWO LEKE OPA ESHU LOLE OWORUN ÑAÑA BI ENITI ONIKU OKOTI OSHEBO TOMO ARAYE DIDE AWO NAWO OKO ADA ATI OGBUN AWO SE ODU AWO SIBERE SIGBONO IGBA TO MITALEÑ EYA ATI AWO OMO ORE NI AWO OMO ARBAMU AWO AGBA SIFI AGBALE RI ÑA ASHE ESHU NI KOYEBI AWO OMO EYA OLE ELAYE ASHUGBO TITI DONI OLONI AWO OMO ARAYE IKO AWO MO EYANI.", "REZO: OKUNI KIAGE KEKO MAMU OMI LOWO INLE SHISHE MANU OMO INSHE ILE LODAFUN ORUNMILA ADIFAFUN OKUNI KAFEREFUN OSHEDA."], "pasajes": [{"titulo": "Canto complementario 5", "texto_ritual": "Iyoyo ke wa yo fun mi o.\nIyoyo ke wa yo fun mi o.\nA mi yo nile, a mi yo lajo.\nIyoyo Aye e, Iyoyo.", "traduccion": "Alegre, deja que las personas vengan a mí con alegría.\nAlegre, deja que las personas vengan a mí con alegría.\nAlegría en el hogar; alegría en la granja.\nAlegre, deja que las personas vengan a mí con alegría.", "origen_id": "b89e5ea0bb784fc61ac396c3"}, {"titulo": "Canto complementario 6", "texto_ritual": "Mo ru iyan, mo ru iyan o.\nIle edun pa poju, ile edun pa poju.\nMo ru iyan, mo ru iyan o.\nIle edun pa poju.", "traduccion": "Ofrezco ñame molido.\nLa casa no tiene infortunio.\nOfrezco ñame molido.\nLa casa no tiene infortunio.", "origen_id": "f440f5e745831f4eb58fa332"}, {"titulo": "Oyeku Meji — para tener protección y no ser traicionado", "texto_ritual": "Ake káa káa ni orúko ti a npé ifá Ala káa káa ni orúko ti a npé Odu Aba ie orí Irofo mo yé ni orúko ti a npé iwo Ésú Ódara Ayé Edo eniyán mo bi ni orúko ti a npéeyin iyami ayé Otisi ti sí a kú bá ni mú nié ka dá emi iagbaja óru iagbaja Bá yin mú nié ióní e mo dáni ó fun owó fun iré gbogbo Ki e mo iée binu emi iagbaja qwó iagfbaja", "traduccion": "Alke kaa kaa es el nombre que le damos a Ifá. Ala kaa kaa es el nombre que le damos a Odu. Aba le on iroko mo ye es como llamamos a Esu Oodara. El que se come a su hígado sin vomitar es el nombre de las Iyami. Okisi kisi, no nos atrevamos a hacer un trato con alguien y traicionarlo. Yo -------------- he hecho un trato contigo hoy. No me traicionen, ni por dinero ni por todas las cosas buenas.", "origen_id": "600f82fa9c6eb8c648b524bf"}, {"titulo": "Oyeku Méji — para la salud de la espalda", "texto_ritual": "Kasia ni kosi jedi jedi kúró lara Jero iwo ni koyo gbigbo oró jebi jebi kúró lara Egbesini kolo si jedi jedi kúró lara iwo Oyeku méji iwo ni kolo Mun jedi jedi kúró lara", "traduccion": "Es kasia la que debe quitarle los dolores de columna a ——— (nombre de la persona). El millo es el que le va a quitar cualquier tipo de enfermedad de la columna de por vida. Es egbesi el que va a quitar las dolencias en la columna a ———.", "origen_id": "b96b985182ef01bcf55c21fc"}, {"titulo": "Oyeku Meji — para protección de los enemigos", "texto_ritual": "Ojo sure sese wpn o báa ojo Ojo ró sun-un surun wpn o bá ojo órun Suré ti ti ti wpn ó bá oióron pbá ibi se oiokoko ayé ibi di ibi wpn a re iwarun ¡kú témi titi ikú ó té bámi nu Di ewé owó tan gbogbo ajogun ibi témi titi bee ni won ó té bámi Di ewé owó kan konko wíke ibi oki téyin me Oyeku méji ókó bámi ye gbogbo ibi ara ni dami", "traduccion": "El día pasa rápido y no ven al día. En el día calmado no ven al día. El sol recorrió el camino por mucho tiempo y no ven al Rey. El mal le vino a oloroko en la tierra. El mal se convirtió en mal en Iwarun. La muerte que corre detrás de mí no me alcanza. Me convertí en la hierba de owo y todo lo malo salió corriendo. No me pueden coger porque la hierba de konko aleja el mal de mí. Oyeku Meji, debes hacer que todo este mal se aleje de mí.", "origen_id": "0afb8a8c08dcde01cbbd4fb8"}, {"titulo": "Sigidí aikú (Oyeku Meji) — para la prosperidad", "texto_ritual": "Ewu ni ogbo irun agbon ni agbá B¡ ahun bá gbogbo ahun amon reko bigbin bá dagbá Tan n rako ni ¡baigbo loní kí emi Ó gbo laye kí nto laye Koju mi ó món ri ibi wara loní kí n món báwon ku ikú ajoku wara wara Ape loní kí npé laye Oyeku meji wá té ikú ori mi danu Iyérósün loní kí gbogbo ohun buruku ó ye danu lori mi", "traduccion": "Las canas significan larga vida. La barba significa vejez, así como lo es la tortuga. La babosa se arrastra y llega a ser muy vieja. Que yo pueda crecer y llegar a ser muy viejo. Es ibaigbo el que dice que debo vivir muchos años en la tierra. Que no tenga nada que ver con wara wara. Ape dice que no podré vivir muchos años en la tierra. Pero el iyérósún hace que todos los males se alejen de mí.", "origen_id": "60eb37dc0ad66ae5b297a27c"}, {"titulo": "Oyeku Meji — para no ser traicionado (variante)", "texto_ritual": "Gbé se oiu Amu Kefe ibi se ibi semi, iá se niá san ni ategun má só nkó aso kó gbodo fi só eniyán Kí ibi o semi ki nse bi Oyeku Meji iwo ni kí ó yo gbogbo ¡bi dánu ¡era emi iagbaja orno iagbaja", "traduccion": "Gebse olu Amu kefe ibi se. La mala suerte es algo ordinario que prescribe Ategun. La ropa no se usa para votar a alguien. No debe pasar ni cosas buenas ni malas. Oyeku Meji, quítame todas las cosas malas a mí, se dice el nombre.", "origen_id": "389aed49cfcfd8f7417ce0b3"}, {"titulo": "Owo (el dinero) — Oyeku Meji", "texto_ritual": "Ola owo ni a npé owo Owo kí wón ó le fi ó se ohun laburu fúnmi Edarijin lá npé kumo kumo moje Kí wón ó le fi ó se laburu fúnmi Eki fori pohun lá npé gbogbo irin ada ni aake ni Ibón ni obe ni kí wón ó món le fi Wón se ohun buruku fúnmi Eni taba ni ohun o fi gbogbo Yin se ohun laburu fúnmi kí oro won ó di abojude Nitori pe abojude lá n he igbin Eni ó bá daju aburu komi kí iwa oluwa re ó baje Tori teyin borun kíí siju wo olodumare Nijó tio teyin borun bá siju wo olodumare ni iwa re n baje Oyeku meji wá lo réé ye ibi ota ni le lori", "traduccion": "La riqueza en la mano es lo que llamamos dinero. Lo que tengo en la mano no deja que me pase nada malo, perdón, es lo que llamamos al bastón. El bastón no dejará que nada malo me pase. Eki fori pohun es lo que llamamos el metal. Que el machete, el cuchillo y el hacha no permitan que me pase nada malo. Que sus planes sean en vano, porque es boca abajo que encontramos a la babosa. Que todo el que me vea con malos deseos sea destruido. Oyeku meji, ve y destruye el mal que hay para mí en la cabeza de mis enemigos.", "origen_id": "81b3c5d7509ba2df14828eb6"}]}]$q$::jsonb),
(3,'fbfc792be104945de8176598439dc0fc','1f8d9d3a585817218577a457f39a9951',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Méjì es el Odù de la gente que ve las cosas como son: sueñan, tienen visiones claras y pueden llegar a ser adivinos. En este signo Ifá confirma que los dieciséis ikin son la representación de Ọ̀rúnmìlà en la Tierra. La persona está revisando su vida y su estado espiritual; lo que se perdió se recupera, y lo bueno que no llegaba ya está cerca.", "pasajes": [{"titulo": "Frase clave", "texto": "Iwori crea transformación.", "origen_id": "43af8e5290b01c1b3f0a7bda"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está repensando su vida y siente que debe cambiar de rumbo, pero no sabe qué conservar.", "Perdió algo o una oportunidad y quiere recuperarla; lo que se veía lejos empieza a acercarse.", "Busca un ascenso o estabilidad en el trabajo y tiene detractores; un éxito rápido no es lo mismo que uno que dura.", "Piensa viajar o entrar en un ambiente desconocido (relato de Olu, que viaja y vuelve con abundancia).", "Le preocupa enfermarse él o alguien cercano (relato de Opakẹrẹ).", "Se siente solo, desea pareja o hijos (relatos de Òde Gbànňsàsà y de Ìwòrì Méjì).", "Tiene un enemigo del que necesita librarse (relato de Òde y Awasa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Larga vida, abundancia, pareja e hijos para quien adora a Ifá.", "Recuperar lo que se perdió.", "Un ascenso en el trabajo, si se ofrece contra los detractores.", "Un viaje del que se vuelve con abundancia, ganando en tierra ajena.", "Que el enfermo sane con la ofrenda correcta.", "Compañía para quien vivía solo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Éxitos que duran poco: riqueza, trabajo y alegría que se van pronto si no se ofrece por la estabilidad.", "Detractores que buscan degradarlo después de un ascenso.", "Ver cosas malas en un viaje.", "Una enfermedad que se acerca."]}, {"titulo": "Enseñanza principal", "texto": "Lo que llega rápido se va rápido si no se asegura. Òde ofreció para librarse de su enemigo, pero no quiso ofrecer para que su gente se quedara con él, y desde entonces la fiesta llega y se va. Hay que ofrecer también por lo que debe durar."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odu Ìwòrì Méjì habla de las personas dotadas con habilidades para ver las cosas con su verdadera perspectiva. Ellos sueñan a menudo, tienen visiones claras y se desarrollan hasta convertirse en adivinos o espiritistas. Los clientes para quienes este Odù es adivinado deben ser advertidos de adorar Ifá. Esto les traerá a ellos excelentes perspectivas y buena fortuna: larga vida (ire àikú), abundancia (ire ajé), una esposa (ire aya) e hijos (ire ọmọ).", "origen_id": "bf667abf1bf5f15d6394e96f"}, {"titulo": "Características generales", "texto": "Otros nombres: Ìwòrì Méjì; Ejiwori.\nEl Odù Ìwòrì Méjì ocupa el tercer lugar en el orden de los Odù como un Olódù. Ìwòrì Méjì consiste en Ìwòrì en el lado derecho (el principio masculino) y Ìwòrì en el izquierdo (el principio femenino).\nIfá dice que si algo se ha perdido, se le asegura al cliente que esa cosa será vista de nuevo o recuperada. Este signo habla de oportunidades para una buena promoción en el trabajo, pero el cliente necesita ofrecer un sacrificio para impedir detractores en su moción o ascenso y para evitar una posterior degradación.\nSi el cliente desea viajar fuera de la ciudad donde él vive o va a realizar un viaje de ultramar, debe sacrificar para que sus ojos no vean nada malo. Cuando el sacrificio correcto se realice, una persona enferma de seguro se pondrá bien.\nIfà confirma en el Odù Ìwòrì Méjì que las 16 nueces de palma (ikin Ifã) son la representación de Ọ̀rúnmìlà y su objeto de adoración en la Tierra. Por eso los adivinos de Ifá los usan para revelar los misterios de la vida.", "origen_id": "4d0f90d7a73cca33545931c4"}, {"titulo": "Interpretación tradicional", "texto": "Iwori es una omisión de iwa ori significando el carácter de conciencia, ó la esencia interna de la conciencia. Ifá enseña que todas las cosas en el universo tienen alguna forma de conciencia. La palabra Iwori implica una asociación con el proceso de conciencia que forma su propia identidad única. En términos sicológicos esto, es llamado individualización. En Ifá el concepto de Iwori es asociado con la transformación espiritual simbolizada por el elemento del fuego. En términos prácticos, Iwori es el fuego de la pasión. Pasión puede llevar al conflicto. En términos positivos, conflicto puede llevar a resolución y crecimiento. En términos negativos, conflicto puede llevar a más conflicto y derrota. Pasión es también asociada con el impulso hacia la procreación.", "origen_id": "916f037e13a8b18a5960aefb"}, {"titulo": "Orientación complementaria", "texto": "Iwori es el principio del fuego o pasión. La transformación ocurre como resultado de la pasión porque requiere coraje para salir de patrones viejos de comportamiento. La transformación nos trae más cerca de nuestro verdadero ser, revelando cuestiones de suma importancia. El símbolo del fuego es usado porque el fuego transforma todas las cosas en la Naturaleza. En su manifestación negativa, Iwori es la pasión del conflicto sin sentido, la necesidad de salvar cara y la necesidad de tener tu propia manera, aunque signifique usar la fuerza o violencia.", "origen_id": "b8ca3e8585244dedcf43a7a0"}]}, {"titulo": "Relatos reunidos", "puntos": ["Opakẹrẹ no enfermará. Mujimuwa, el adivino de Opakẹrẹ, le advirtió que ofreciera para no enfermarse: veinte anzuelos con veinte palomas. Cumplió, y le prepararon hojas de Ifá para lavarse la cabeza y lavar su Ifá. El adivino le aseguró que nunca estaría enfermo.", "Òde y Awasa. Gbẹgi jebete consultó para Òde, que tenía como enemigo a Awasa, y le marcó un garrote y una carga de ñames. Òde cumplió. Machacaron los ñames y los comieron en la noche; se fueron a dormir, y cuando llegó Awasa en la oscuridad, Òde lo mató con el garrote. A la mañana siguiente encontraron su cuerpo afuera.", "Ìwòrì se casa con la hija de Ọlọ́fin. Ògún-ribiti consultó para Ìwòrì Méjì cuando iba a casarse con Ọ̀pẹ, la hija de Ọlọ́fin, y le marcó una gallina para que su esposa nunca fuera estéril. Cumplió, y el adivino dijo: 'Ni la palma hembra ni la palma macho serán estériles'. Por eso los hijos de este Odù siempre tienen descendencia.", "Òde y la fiesta que no se queda. Ifá le dijo a Òde que ofreciera una piedra de afilar y una estera para que todos los que venían a festejar con él se quedaran a su lado. Òde no quiso y dijo que le bastaba con haberse librado de Awasa. Por eso la gente viene a celebrar con él, pero nadie se queda: los hijos de este Odù tienen éxitos de poca duración mientras no ofrezcan por la estabilidad.", "Òde Gbànňsàsà encuentra compañía. 'Grillo, que no se lamente más antes de que caiga la noche.' Así consultaron para Òde Gbànňsàsà, que lloraba porque no tenía compañera. Ofreció, y Èṣù le mandó las fortunas, entre ellas una compañera. Su éxito merecía que se bailara: 'Òde Gbànňsàsà, ven a bailar al ritmo del tambor'.", "La cola del búfalo. Ifá consultó para Ọ̀rúnmìlà cuando dijo que formaría una sombra que cubriera la Tierra y preguntaba si llegaría a ser grande. Ofreció, y no hay lugar en el mundo donde no se le conozca: donde se hace el bien se reconocen sus manos y sus enseñanzas, y su poder trajo paz firme.", "Olu juega ayo con Olókun y Ọlọ́sà. Ifá consultó para Olu cuando iba a la casa de Olókun, el espíritu del mar, y a la casa de Ọlọ́sà, el espíritu de la laguna, y le pidió ofrecer para que el viaje fuera bendecido. Cumplió. En casa de Olókun le ganó tres veces al ayo, y Olókun había prometido la mitad de sus bienes a quien le ganara. En casa de Ọlọ́sà pasó lo mismo. Así recibió la abundancia y cantó: 'Jugué ayo con Olu y recibí una bendición en casa del extranjero'. Esta persona encontrará buena fortuna con un extranjero.", "Los hijos que no son tratados como muertos. 'Lo que a ti te gusta a mí no me gusta.' Así consultaron para los hijos de Omimuti Ìwòrì, que temían ser tratados como si estuvieran muertos. Ofrecieron, y el adivino dijo que nunca se ha visto a un muerto cavando la tierra. Desde entonces se les reconoció entre los vivos."], "pasajes": [{"titulo": "Verso 3.1", "texto": "Mujimuwa el adivino de Opakẹrẹ\nadivinó Ifá para Opakẹrẹ.\nÉl fue advertido sacrificar\na fin de impedir enfermarse:\nveinte anzuelos de pescar\ncon veinte palomas.\nEl escuchó e hizo el sacrificio.\nLas hojas de Ifá fueron preparadas\npara que el lavara su cabeza (Ori),\npara que él lavara su Ifá.\nEl adivino le dijo:\n\"Opakẹrẹ nunca estará enfermo\".", "comentario": "Después del sacrificio preparar una medicina de Ifá para proteger al cliente y evitar una enfermedad inminente. Con la medicina se lava la cabeza de la persona y su Ifá.", "origen_id": "b2600a37f186fce09213d147"}, {"titulo": "Verso 3.2", "texto": "Gbẹgi jebete\nfue el que adivinó Ifá para Ode,\ncuando Awasa era su enemigo.\nLe aconsejó a él (Ode) que ofreciera:\nun garrote y una carga de ñames.\nOde hizo caso de la advertencia y sacrificó.\nEllos machacaron los ñames.\nEllos comieron los ñames machacados\npor la noche.\nEllos fueron a dormir,\ncuando cae la noche, viene Awasa.\nOde usó su garrote para matar a Awasa.\nAl siguiente día en la mañana,\nencontraron al cuerpo de Awasa afuera.", "comentario": "Ode consultó a Ifá para saber que debía hacer para deshacerse de su enemigo Awasa. El siguió el consejo del adivino y acrificó names y un garrote, el cual fue usado para matar a su enemigo.", "origen_id": "b1982e4717fb4b457eeef03e"}, {"titulo": "Verso 3.3", "texto": "Ögún-ribiti:\nadivinó Ifá para Iworiméji,\ncuando Iwöriméji iba a casarse con pè,\nla hija de Ọlofin\nLe aconsejaron hacer sacrificio,\npara que su esposa nunca fuera estéril.\nUna gallina debe ser el sacrificio.\nEl escuchó y sacrificó.\nEl adivino dijo:\n\"Ambos, los arboles de palma femeninos\ny masculinos nunca serán estériles\"", "comentario": "A causa de que lwòri Méjì hizo el sacrificio apropiado, las personas nacidas bajo este Odù nunca serán estériles o infértiles.\nEllos siempre serán bendecidos con hijos.", "origen_id": "e1cad4dae2b4ce9ff311411b"}, {"titulo": "Verso 3.4", "texto": "fue el que adivinó Ifá para Ode.\nLe dijo que él debía venir y sacrificar:\nuna piedra de amolar y una estera,\npara lograr que todos aquellos\nque habían venido a regocijarse con él\nsiempre permanecieran con él.\nOde rechazó y abandonó el sacrificio.\nEl dijo: \"que estaba satisfecho,\nsi él podía solamente deshacerse de Awasa\".", "comentario": "Las personas siempre vendrán a divertirse y celebrar con Ode, pero como Ode abandonó el sacrificio prescrito, nadie nunca se quedará con él. A causa de esto, las personas encarnadas por este Odù solo tienen éxito temporal, por corto tiempo, y nada parece durar mucho, sus riquezas, trabajos, negocios y alegría son siempre de corta duración.\nOde (Ìwòrì Méjì) no hizo sacrificio para la estabilidad y que las cosas buenas le perduraran.", "origen_id": "8f7e73a74ec082ac77ff82e7"}, {"titulo": "Versos complementarios 1", "texto": "Ifá dice que las buenas cosas que en el pasado, no\nllegaban a esta persona, están bien cerca, que no\nse lamente más de no tenerlas. Vivirá bastante en\nla tierra. Para lograr que la vida le sea plácida\ndeberá ofrendar.\n\n                Láàmbókò ìrè\n           Ệ pé kó mó ráhùn mó\n           Títí ale a móợ daláşợ\n         A dífá fún Òde gbànňsàsà\n        Èyí tí ń sunkún alái lénikan\n       Òún le nìíyàn láyé òún báyìí?\n            Wón ní ki Òde rúbợ\n                Òde dẹbợó lè\n                    Ó rúbợ\n          Bówó ba si ti kó Èşù lójú\n             Léyìín téèyán rúbợ\n                    Iré dé\n                  Ệbợ dà fun\n                   Ayé yẹ é\n     Ó ní béè làwợn babaláwo tòún wí\n                Láàmbókò ìrè\n           Ệ pé kó mó ráhùn mó\n           Títí ale a móợ daláşợ\n         A dífá fún Òde gbànňsàsà\n        Èyí tí ń sunkún alái lénikan\n              Ệbợ n wón ní ó şe\n               Òde gbébợ ńbè\n                    Ó rúbợ\n              Òràn Òde gbajó ò\n               Òràn Òde gbayò\n\n                Òde Gbànňsàsà\n                  Wá gbijó ò\n                Òde Gbànňsàsà\n\nLáàmbókò, el Grillo\nNo la dejes lamentarse más, antes que el\ncrepúsculo se vista.\nLanzó Ifá para Òde Gbànňsàsà, quien lloraba a\ncausa de no tener compañía alguna (compañera).\nSe le pidió sacrificar y así él lo hizo.\nUna vez realizado el sacrificio, Èşù le envió los\nbeneficios, de las fortunas, entre ellas la de la\ncompañía femenina, y la vida le fue plácida.\nÉl hizo lo que los babaláwos le dijeron que hiciese.\nLáàmbókò, el Grillo\nNo la dejes lamentarse más, antes que el\ncrepúsculo se vista.\nLanzó Ifá para Òde Gbànňsàsà, quien lloraba a\ncausa de no tener compañía alguna (compañera).\nSe le pidió sacrificar y así él lo hizo.\nSus éxitos merecían que se bailase para regocijar\nen lo máximo.\nÒde Gbànňsàsà\nVen y observa las funciones conformadas por Òde.\nÒde Gbànňsàsà\nVen y baila al ritmo del tambor\n\n         Òbámú bamù pirá pirá\n         Ợpợợki pợợki nirù Ệfòn\n          A dífá fún Òrúnmìlà\n     Níjó ti ń lợ rèé rààtá bolé ayé\n         Òún le tóbi láyé báyìí?\n Tóun ó bóri ilé ayé gbogbo bó ti tóbi tó\n       Wón ní kí Òrúnmìlá ó rúbợ\n            Òrúnmìlá bá rúbợ\n                O dẹbợó lè\n\n  Kò síbi wợn ò gbé mÒrúnmìlà láyé yìí\n   Gbogbo ibi wón tí ń şe nňkan tó dáa\n            Òrúnmìlà ń bẹ níbè\n  Kèrèkèrè lÒrúnmìlà gba gbogbo ilú lợ\n              Ijó ní Bàbá ń jó\n                 Ayò ní ń yò\n         Ní ń yin àwợn Babaláwo\n         Àwợn Babaláwo ń yin Ifá\n    Ó ní béè làwợn Babaláwo tòún wí\n          Òbámú bamù pirá pirá\n          Ợpợợki pợợki nirù Ệfòn\n           A dífá fún Òrúnmìlà\n      Níjó ti ń lợ rèé rààtá bolé ayé\n       Owó tewé alájàňgbàlúù mi\n                  Kèrèkèrè\n       La ó móợ gbàlú lówóợ wợn\n                  Kèrèkèrè\nÒbámú bamù pirá pirá\nLa cola del Búfalo es muy voluminosa.\nAdivinó para Òrúnmìlà, cuando decía que formaría\nuna sombra para cubrir la Tierra.\n¿Seré grande en la Tierra?, él preguntó.\n¿Podré superar al Mundo siendo este tan grande?,\nse decía.\nLe pidieron a Òrúnmìlà que sacrificara y así él lo\nhizo.\nNo hay un solo lugar en el Mundo donde él no sea\nconocido. Donde quiera que se emprendan buenas\nacciones, se identifica sus manos y sus enseñanzas.\nSu poder se extendió por las tierras, trayendo la paz\nfirme.\nÉl bailó sinceramente y alabó a sus babaláwos.\nLos babaláwos alabaron a Ifá.\nÒrúnmìlà hizo lo que ellos le dijeron que hiciese.\n\nÒbámú bamù pirá pirá\nLa cola del Búfalo es muy voluminosa.\nAdivinó para Òrúnmìlà, cuando decía que formaría\nuna sombra para cubrir la Tierra.\nYo he obtenido la hoja de alájàňgbàlúù.\nKèrèkèrè.\nTomaremos de ellos todas las ciudades.\nKèrèkèrè", "origen_id": "460fc343590586402ef554c8"}, {"titulo": "Relatos y ofrendas", "texto": "Iwori meji\n\n85\n\nEl motor -que -usamos -para -moler -el -ñhame, -no -es -usado -para -perforar -a -elu. -una -\ncazuela -envejecida -en -la -boca, consulta Ifá para Olu en el día que quería irse a lié Olókun\n(casa det Espíritu det Océano) y Ilé Olosa (casa del Espiritu de la Laguna). Ifá aconsejó a Olu\nhacer Ebo para que el viaje fuera bendecido con bondad. Olu hizo Ebo. Olu llego al hogar de\nOlókun y le ganó tres veces jugando ayo (un juego de suerte). Olókun prometió que le daría la\nmitad de su propiedad a cualquiera que te ganara a jugar ayo. Olu fue al hogar de Olosa y le ganó\ntres veces jugando ayo. Olosa prometió que le daría la mitad de su propiedad a cualquiera que le\nganara a jugar. Fue en ese día que Olu recibió la bendición de la abundancia. Olu estaba cantando\ny bailando en alabanza del awo, mientras el awo alabó a Ifá, mientras Ifá alabó a Olodumare.\nCuando Olu empezó a cantar, Esu lleno su boca con una canción.\nOlu canto:\nMo bolu t'ayo mo kan re o.\nMo bolu t'ayo mo kan re o.\nMo bolu t'ayo lóyinbo o.\nMo bolu t'ayo mo kan re o, o, o, o,\nJugué ayo con Olu, recibí una bendición.\nJugué ayo con Otu, recibí una bendición.\nJugué ayo con Olu en el hogar de un extranjero.\nJugué ayo con Olu, recibí una bendición.\n\nComentario:\n\nIfá dice que esta persona para las bendiciones que él busca. Ifá dice que esta persona debe\nvolverse experimentado en juegos de suerte. Ifá dice que esta persona debe ofrecer una oveja a\nEleda. Ifá dice que esta persona va a encontrar buena fortuna de un extranjero.\n\nEtutu (ofrecimiento): 1 eiyele (pichón), 1 abo adie (gallina), 1 plato blanco, eko (pastet de\nharina de maíz) y dinero determinado por el adivinador, ofrecido a Obàtálá.\n\n(Eta (Oferecendo): 1 eiyelé (pombo), 1 Abo adie (galinha), 1 prato branco, ekó (bolo de\nmilho) e uma quantia em dinheiro ser determinada pelo 4wo, que será oferecida a Óbatálá.)\n\nLo — que — a— ti— te — gusta, - a — mi— no — me — gusta, - quién — debe — de — estar — junto — a—\nnosotros, consulta ifá a Omimuti Iwori, hijos de esos que motan a caballo con arrogancia enfrente\nde Olu en el día que fueron preocupados de ser tratados como si estuvieran muertos. Ifá aconsejó\na los hijos hacer_ebo. Los hijos hicieron ebo. El adivinador dijo que la imagen de una persona\nmuerta nunca ha sido vista cavando el suelo. Desde ese día los hijos fueron conocidos como estar\nentre los vivos.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo para desviar la muerte y la enfermedad. Ifá dice que esta\npersona debe hacer ebo para que el mundo no lo trate como si estuviera, ya sea, muerto ó que no\nvale nada. Ifá dice que esta persona debe recibir dos juegos de Íbeji, un juego de Ibeji femenino,\ny un juego de Ibeji masculino, como parte de su lugar santo personal. Ifá dice que Ibeji proveerá\nprotección de los enemigos, muerte y enfermedad.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 abo adie (gallina), 1 plato blanco, 4 eko (hecho de\nfame cocido), eku (rata pequeña), 1 epo (botella de aceite de palma) y 50 nira (dinero), ofrecido a\nIbeji y Obàtálá. Eéwo (tabú): perro y fruta ori.\n\n(Ett (oferendas); 4 eiyele (pombo), 4 Abo adie (galinha), 1 prato branco, 4 eko. (feitos de\ninhame cozido), Eku (rato pequeno), 1 epo (garrafa de azeite de dendé) e 50 nira (dinheiro\nnigeriano), oferecidos a Ibeji e Óbatálá. Eewó (tabu): cachorro e fruta ori.)\n\n86\n\nI I\n\nTi Ti\nTi Ti\nI I", "origen_id": "2066470a36a507e10ac76b3c"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Iwori Meji habla de las personas que tienen dones con la\n      habilidad de ver cosas con una perspectiva verdadera. Ellos sueñan a\n     menudo, tienen claras visiones y crecen para convertirse en adivinos o\n      espiritistas. Los clientes de quienes este Odu es divinizado deben ser\n advertidos de adorar Ifá. Esto les traerá a ellos buenas perspectivas, larga\n          vida (ire aiku), salud (ire aje), una esposa (ire aya) e hijos (ire omo).\n             WO – El cliente está examinando cuidadosamente y volviendo a\n\nestimar tanto el sendero temporal como el espiritual emocional.\n   Odu Iwori Meji ocupa el tercer lugar en el orden de los Odu como un\n     Olodu, Iwori Meji consiste en Iwori en el lado derecho (el principio\n               masculino) y Iwori en el izquierdo (el principio femenino).\n    Ifá dice que si algo se ha perdido, el cliente tendrá asegurado que las\n cosas serán vistas o recuperadas. Oportunidades para una promoción de\n    trabajo, son buenas pero el cliente necesita ofrecer un sacrificio para\n                impedir a los detractores que puedan causar degradación.\n          Si el cliente desea viajar fuera de la ciudad donde él vive o va ir\n  afuera (ultramar) debe sacrificar para que sus ojos no vean nada malo.\n          Cuando el sacrificio correcto se realice, una persona enferma de\n                                                     seguro se pondrá bien.\n    Ifá confirma en Odu en Iwori Meyi que las 16 nueces de palma (Ikin\nIfá) son la represetación de Orumila y su objeto de adoración en la tierra.\n       Es por esto que el adivino de Ifá (Babalawo) lo usa para revelar los\n                                                       misterios de la vida.\n\n\n3.1 · Mujimuwa, Babalawo de Opakere Babalawo adivinó para él. Para\n            impedir que se enfermara, él fue advertido sacrificar. Ebo: 20\n        anzuelos de pescar y 20 palomas. El obedeció e hizo el sacrificio.\n           Las hojas de Ifá fueron preparadas para él, para ser usadas para\n       lavarle su cabeza (ori) y para ser usadas para lavar su Ifá. Opakere\n                                                nunca estará enfermo (☼).\n\n\n3.2 · Gbegi Jebete fue el que adivinó para Ode cuando Awasa era su\n             enemigo. Ellos le pidieron a él (Ode) que ofreciera 1 garrote y un\n             poco de ñames. Ode hizo caso de la advertencia y sacrificó. Ellos\n       machacaron los ñames. Ellos comieron los ñames machacados por la\n       noche. Ellos fueron a dormir cuando cayó la noche, vino Awasa, Ode\n             usó su garrote para matar a Awasa. Al siguiente día en la mañana,\n                              ellos encontraron el cuerpo de Awasa afuera (☼).\n\n\n3.3 · Ogún-ribiti adivinó para Iwori Meji cuando Iwori Meji iba a casarse\n             con Ope, la hija Olofin. Ellos pidieron hacer sacrificio. Su esposa\n           nunca será estéril. una gallina fue el sacrificio. Ellos dijeron que los\n                   árboles de palma, ambos femenino y masculino nunca, serán,\n                                                                    estériles (☼).\n\n\n3.4 · Tijotayo fue el que adivinó para Ode. Ellos dijeron que él debía venir\n       y sacrificar. Una piedra de amolar y una estera. Para hacer que todos\n       aquellos que habían venido a regocijar con él, siempre se mantengan\n                 con él. Ode rechazó y abandonó el sacrifico. El dijo que estaba\n                             satisfecho sólo si se podía deshacer de Awasa (☼).", "origen_id": "1d22963ff7d13f692b165980"}, {"titulo": "Relato en inglés 1", "texto": "“A hoe handle has a head, but it does not have brains”! was the one who cast\nIfa for “Two-Knots,? Eji Iwori,\" when he was going to Ọyọ. They said he should\nsacrifice two pigeons, two chicken eggs, and one shilling three pence. They said\nhe would not see evil where he was going; they said that a blessing was what he\nwould see. Ifa says he will not allow us to see evil in the matter for which we\nhave divined.\n\n“The diviner’s eye will not see evil, Eji Iwori;\n“The diviner’s eye will not see evil, Eji Iwori.\"?", "comentario": "1. The “head” of the hoe handle is the knot in the piece of wood into which\nthe blade is fastened. Though it looks like a head, it has no brains inside it. The\nreference here is to the marrow or meat inside the head, and not to intelligence\nor sense.\n\n2. “Two-Knots” is an alternative name of the figure, Iwori Meji or Eji Iwori.\nIt appears here as a character for whom a divination was performed. Koko is a\nknot in a piece of wood and the allusion here is to the “head” of the hoe-handle.\nThe word “koko” is onomatopoetic, and really refers to anything which makes the\nsound “koko” when tapped.\n\n3. This is used as a song, repeated by children when going home to expected\npunishment. It is believed that if it is repeated, their parents will not punish them.", "origen_id": "3e953b1930d59e75c55b29d1"}, {"titulo": "Relato en inglés 2", "texto": "-\"-\n\nQrunmila says we should cry \"Sssi.\"1: I say that whoever is in the way should\nduck. He says that we should look before we throw water into the street, lest we\nthrow water upon a visitor. I say, “What visitor?” He says, “A visitor who will\nbring money.”\n\nQrunmila says we should cry “Sssi.” I say that whoever is in the way should\nduck. He says that we should look before we throw water into the street, lest we\nthrow water upon a visitor, I say, “What visitor?” He says, “A visitor who will\nbring wives.”\n\nQrunmila says we should cry “Sssi.” I say that whoever is in the way should\nduck. He says that we should look before we throw water into the street, lest we\nthrow water upon a visitor. I say, “What visitor?” He says, “A visitor who will\nbring children.”\n\nQrunmila says we should cry “Sssi.” I say that whoever is in the way should\nduck. He says that we should look before we throw water into the street, lest we\nthrow water upon a visitor, I say, “What visitor?” He says, “A visitor who will\nbring a title.”\n\nIfa says that he sees the blessing of visitors, the blessing of money, the bless-\ning of wives, the blessing of children, and the blessing of a title. He says we\nshould sacrifice one pigeon and one hen.", "comentario": "1. Sssi is a warning cried at night before throwing water or refuse into the\nstreet.", "origen_id": "f5beb4ed517aecb6a585bdf9"}, {"titulo": "Relato en inglés 3", "texto": "“Qkan sprouts firm; it enters the forest; Qgan sprouts long and slender; it\nreaches the road,” and “In climbing a hill, one’s hips move biripe-yunyun'\"? were\nthe ones who cast Ifa for “Farm hut stands watch in the farm but does not catch\nthieves,” who was a child of “Patient One,” the diviner of “Hero of fish.” They\nsaid that that year his head would bring him to a place where he would achieve\nhis destiny. They said he should sacrifice two rats, two fish, and two chickens.\nHe heard and offered the sacrifice.\n\nAfter a while, the King of the people of Igbodo die@. They took a fish and put\nit in a covered calabash. They said that anyone who could recite Ifa verses which\ntouched upon the thing they had put inside the calabash, that is, who mentioned the\nword “fish,” would be made king of their town.\n\nAll the diviners of the town recited Ifa without mentioning the word “fish,”\nbecause they did not know enough about specific alternatives.3 Afterward as\n“Farm hut stands watch in the farm but does not catch thieves” was passing by,\nthey called him to come and recite Ifa, because they saw the beads of Ifa on his\nwrist. But he replied that he did not know Ifa, and he said:\n\n““Qkan sprout firm, they enter the forest; Qgan sprouts long and slender, it\nreaches the road’ and ‘When one climbs a hill, his hips move biripe-yunyun’ were\nthe ones who cast Ifa for me, ‘Farmhut stands watch in the farm but does not\ncatch thieves’ who am the child of ‘Patient One,’ diviner of Alapa, ‘Hero of Fish.”\n\nWhen the people of Igbodo heard this, they said he did know about specific\nalternatives because when he recited Ifa, he mentioned “fish”; so they took him\nand made him king of their town. “Farm hut stands watch in the farm but does\nnot catch thieves\" is what we call Spotted Hyena.\n\nAfter two years had passed, when Hyena had become a highly honored per-\nson, all the ewes and she-goats began to disappear from town, It was Eshu who\nwas taking and hiding them because “Farm hut stands watch in the farm but does\nnot catch thieves” had made only the sacrifice for a title, but had not sacrificed\nagainst a slanderer. Therefore Eshu was taking the ewes and she-goats in town\nand hiding them. Then Eshu went to the townspeople and said to them, “Don’t you\nknow that the person you have made king is the one who is killing\n\nyour ewes and she-goats and eating them?” The people of the town conferred to-\ngether, and they took Hyena from the throne.\n\nWhen Hyena saw they had removed him from his position, he went to the\ndiviners he had visited before, and he asked them what he could do to be able to\nreturn to his post. They said he should sacrifice six pieces of meat,‘ three\nshillings, and one pot of palm oil. They said he should take his sacrifice to the\nbank of the river at cock’s crow, before dawn, and sit down beside it and watch\nit. When day broke, and the women of Igbodo came to draw water at the place at\nthe river where Hyena had brought his sacrifice, Eshu took the pieces of meat\n\nand put one in each of their jars. As he put the meat into their jars, it turned\ninto front or hind legs of a she-goat, and the water that the women dipped into\ntheir pots became blood. Eshu told Hyena to follow them and arrest them, When\nthis affair came to court, Eshu said to the people of Igbodo, “Have you taken your\nking from the throne because he was killing your animals and eating them, while\nyou yourselves have been sending your wives to bring the same meat home?” He\nsaid, “Whether you like it or not, you must find a way to take him back and make\nhim king again.”\n\nIfa says that someone has lost something, but it will come back again; and\nthat if someone, or if the person for whom this figure was cast, should achieve a\nposition or a title, he should sacrifice that he will not encounter a slanderer who\nwill cause him to be removed from it.", "comentario": "1. Cf. nn, 5 and 6, verse 1-1.\n\n2. A phrase describing the motion of a person's hips when taking high steps\nin climbing.\n3. See Chapter V.\n4. Lumps of meat of the size that are served in Yoruba stews, each of which\nis about a mouthful, This part of the sacrifice is instrumental in restoring Hyena\nto the throne.", "origen_id": "5adb10d4cb0c179710a55395"}, {"titulo": "Relato en inglés 4", "texto": "“Eyelashes! do not gather dew; old beards do not have good color” was the\none who cast Ifa for Eye when he was going to Apere. Apere is what we call the\nearth. They said he should sacrifice two pigeons and six pence six oninis. They\nsaid he would not see evil.\n\nWhen Eye was coming to Apere, he went to the diviners. They said he should\nsacrifice so that his eyes should not see anything bad on earth; he should take one\npigeon and touch it to his left eye, and take the other and touch it to his right eye.\nWe will take one of these two pigeons and sacrifice it with ten of the cowries. We\nwill take the second pigeon home, or the diviner will take it home with him.\n\nIfa says that the person for whom this figure was cast wants to go out of town\nor on a journey. He should sacrifice that his eyes should not see evil where he is\ngoing.\n\n*", "comentario": "1. Ipenpe includes the eyelashes, the eyelid, the eyebrow.", "origen_id": "2bd33c167d3062d0c698da1b"}, {"titulo": "Relato en inglés 5", "texto": "“Not round, not round;! the back of Vulture’s head resembles an axe handle,\nbut it cannot split wood” was the one who cast Ifa for “Two-Knots, Eji Iwori\"?\nwhen he was coming to earth as the third® figure of Ifa,\n\nIfa says this is someone whose relatives are causing him trouble; they do\n\nnot allow him to find a house or a farm, But if he sacrifices, he will find peace\nof heart and will overcome all his enemies,\n\nWhen the sixteen Figures of Ifa were coming to the earth, “Two-Knots, Eji\nIwori” wanted to be third among them on earth; but the other Figures conspired\nagainst him. They told him that there was no room for him to live on earth.\nThen “Two-Knots, Eji Iwori” got ready and went to the diviners, that they might\nexamine his case and tell him how he might be able to find a place to live on\nearth. They said that one she-goat, a mortar, the tẹtẹ leaf, the gbegbe leaf,4\nand eleven shillings were required as sacrifice.\n\n“Two-Knots, Eji Iwori\" heard and he offered the sacrifice. They said he\nshould return to earth again. When he reached the earth he told the other fif-\nteen Figures that he had come. They said, hadn’t they told him that there wasn’t\nroom on earth for him to live? Then “Two-Knots, Eji Iwori\" replied as his di-\nviners had taught him:\n\n“The mortar will testify that I see room in which to settle,\n“The tẹtẹ leaf will testify that I see room in which to stretch out,\n“The gbegbe leaf will testify that I see room in which to dwell.”>\n\nWhen the other Figures heard this kind of a reply, they said, “Ah! ah! this isa\nvery powerful thing indeed, oh!” They said he should take his seat; then “Two-\n\nKnots, Eji Iwori” found his place to sit down in the third position among the other\nFigures.", "comentario": "1. Something flattened, or oval-shaped like a vulture’s head.\n\n2. See n. 2, verse 35-1. Here the allusion is to the knot into which the axe\nblade is inserted.\n\n3. In rank order. See Chapters IV and V.\n\n4, Tete is Amaranthus caudatus; gbegbe is Icacina trichantha.\n\nLa\n5. There is a play on words here, and the efficacy of the sacrifice depends\nin part on the sound of the names of the ingredients. The mortar (odo) insures\nroom in which to settle (do), the tẹtẹ leaf insures room in which to stretch out\n(te), and the gbegbe leaf insures room in which to dwell (gbe).", "origen_id": "55371aee5e9c51d7494ff6fe"}, {"titulo": "Relato en inglés 6", "texto": "“Horse awakes in the morning; it takes the bit! in its mouth,” “Sun enters the\nhouse through chinks in the wall,” “Sky God turns the moon high up above,” and\n“Rainbow, the foolish one, stays in the heavens, shining very brightly”? were the\nones who cast Ifa for Brass, beat palm nuts for Lead, and shared® it with Iron,\nthe last-born of these three children.\n\nIfa says that these are three children of the game mother. They should sac-\nrifice so that the last-born among them will not die, and so that the two others\nwill not have to weep for this small child in their midst. The tongue of the last-\nborn is sharper than the edge of a razor,* and he argues a great deal. Therefore\nthey should sacrifice a lump of shea butter, one he-goat, one pigeon, and three\nshillings.\n\nWhen. these three children of the same mother were told to sacrifice against\ndeath, Brass sacrificed and Lead made an atonement, but Iron said that the di-\nviners were telling lies. He said that as the Sky God has ordained things, so\nthey are destined to be forever. The sacrifice that Iron refused to make is what\nis eating him away. Since that time if Iron has been buried in the ground for as\nlong as four years,\" he begins to rust and to spoil. But the sacrifice that Brass\nand Lead made is what prevents them from spoiling even if they stay in the ground\nfor many years,", "comentario": "1. This is an onomatopoetic word which refers to anything that makes the\nsound “gbinringbinrin.”\n\n2. Cf, verse 24-1,\n3. See n. 4, verse 18-4,\n4. The reference here is to Iron.\n5. In the fifth year according to the Yoruba system of counting.", "origen_id": "a3955efcfeafdbfe51d884f2"}, {"titulo": "Relato en inglés 7", "texto": "“Horse-whip,” the diviner of the town of Itori, and “Something with a big\nbase,\"? the diviner of the town of Ilugun, were the ones who cast Ifa for the king\nat his palace, They said something round would fall #rom heaven and break into\nseven pieces on the ground. They said he should sacrifice so that he might keep\nit under control. They did not sacrifice, and they did not appease Eshu.\n\nHey! This is a compound which tears will enter. Ifa says there is a group\nof six people who should sacrifice so that they may not die one after another un-\ntil only the last-born among them remains; and so that when their family is\n\nmourning and does not heed promptly the pleas to stop weeping, Eshu and the\nFour Hundred Deities may not\n\nadd to their tears by causing the one remaining child to die like the others.\n\nWhen Qrunmila went on a journey, he left his six sons behind. When he had\ngone, an epidemic entered the town. Since Qrunmila was not at home to cast Ifa\nfor them, his sons went to the diviners that they might examine their case and\ntell them what to do so that this epidemic could not kill them before their father\nreturned, The diviners told Qrunmila’s children —\"Pouch of Poison,” “Pouch can\nfight,’* “Ejemgoluwonran,” “This one can be of assistance,” “Ateginnidekun,”® and\n“Look me in the eye” —that they should sacrifice one she-goat each, one thigh of\nbush goat each, two rats each, and three shillings apiece.\n\nWhen they had finished gathering all these things together, they insisted that\nthe diviners should kill the she-goats,® although they ought not to have killed them.\nIfa says this is someone who has been doing something important and who has al-\nready accomplished it, but that he should watch himself carefully, lest it be spoiled\nthrough a small detail.” The diviners killed the she-goats as they were told and\nput their heads on top of the sacrifice; but the last-born, “Look me in the eye,” told\nthe diviners that they should make\n\nhis sacrifice as it ought to be made. They did not kill his she-goat, but the oth-\ners they killed and put in broken pots and placed at the bottom of Eshu’s shrine.\nWhen they had taken them to the base of Eshu, flies gathered, covering the sac-\nrifice. The evil spirits saw this and rushed? into the house and killed the five\nchildren whose goats had been killed by the diviners, but they left the last-born\nalone,\n\nOn the night of that very day Qrunmila dreamed a dream, and his dream was\nnot good. He cast Ifa, and he cast Iwori Meji. They said he should return to his\nhome. He got ready and came home, but when he arrived at his house he did not\nfind the five other children; he met only the last-born. When he asked about the\nother five, they lied to him saying they had gone to farm. When four days had\npassed, the last-born child went to his father’s friends and asked them to come\nand comfort Qrunmila and let him begin to mourn for the elder brothers. When\nthey had told Qrunmila, he began to weep; they pleaded and pleaded with him,\nbut he would not listen. Qrunmila put his hands over his ears and began to cry:\n\n“Pouch of Poison, my child, oh,\n\n“When one’s child looks him in the eye,\n“One should see his child.\n\n“Pouch can fight, my child, oh,\n\n“When one’s child looks him in the eye,\n“One should see his child.\n“Ejemgoluwognran, my child; oh,\n\n“When one’s child looks him in the eye,\n“One should see his child.\n\n“This one can be of assistance, my child, oh,\n“When one’s child looks him in the eye,\n“One should see his child.\n“Ateginnidekun, my child, oh,\n\n“When one’s child looks him in the eye,\n“One should see his child.”\n\nWhile Qrunmila was weeping, refusing to listen to the pleading of his friends,\nEshu came to him and told him that if he did not keep quiet, he and all his com-\nrades would add to Qrunmila’s tears, by causing his last-born child who was still\nleft to die also.", "comentario": "1. A pun on atori, a bush from which switches [gpa-(a)tori] are made.\n2. Something “like a palm tree.”\n\n3. To give a part of a sacrifice when one cannot afford to give it all, as\nAriran and Esun did in verse 33-2.\n4. A pouch or sheath made from telescoping tubes of bamboo or leather in\nwhich poison is kept.\n\n5. The informant could not translate two of these names.\n\n6. It is implied here, that they did not trust the diviners, suspecting that they\nwould simply add them to their possessions. ki\n\n7. As Qrunmila's children brought an expensive sacrifice to naught, by quib-\nbling about a small point.\n8. Literally “gushed,” like water.", "origen_id": "4986dc139cf0c9da4cbc78c4"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Opakẹrẹ: veinte anzuelos y veinte palomas; lavado de cabeza y de Ifá con hojas de Ifá.", "Òde contra Awasa: un garrote y una carga de ñames, que se machacan y se comen en la noche.", "Ìwòrì Méjì: una gallina para que la esposa sea fértil.", "Òde (rechazado): una piedra de afilar y una estera para que la gente se quede.", "Olu: una paloma, una gallina, un plato blanco, ẹ̀kọ y dinero, a Ọbàtálá; una oveja a Ẹlẹ́dá.", "Contra la muerte y la enfermedad: 4 palomas, 4 gallinas, un plato blanco, 4 ẹ̀kọ de ñame, una rata pequeña, aceite de palma y dinero, a Ìbejì y Ọbàtálá; recibir dos juegos de Ìbejì, uno femenino y uno masculino. Prohibido: perro y fruta òrí."], "pasajes": [{"titulo": "Ofrenda en el verso 3.1", "texto": "Mujimuwa el adivino de Opakẹrẹ\nadivinó Ifá para Opakẹrẹ.\nÉl fue advertido sacrificar\na fin de impedir enfermarse:\nveinte anzuelos de pescar\ncon veinte palomas.\nEl escuchó e hizo el sacrificio.\nLas hojas de Ifá fueron preparadas\npara que el lavara su cabeza (Ori),\npara que él lavara su Ifá.\nEl adivino le dijo:\n\"Opakẹrẹ nunca estará enfermo\".", "origen_id": "a4617289f36a6c2027c7e220"}, {"titulo": "Ofrenda en el verso 3.2", "texto": "Gbẹgi jebete\nfue el que adivinó Ifá para Ode,\ncuando Awasa era su enemigo.\nLe aconsejó a él (Ode) que ofreciera:\nun garrote y una carga de ñames.\nOde hizo caso de la advertencia y sacrificó.\nEllos machacaron los ñames.\nEllos comieron los ñames machacados\npor la noche.\nEllos fueron a dormir,\ncuando cae la noche, viene Awasa.\nOde usó su garrote para matar a Awasa.\nAl siguiente día en la mañana,\nencontraron al cuerpo de Awasa afuera.", "origen_id": "8a9073a2cee274c9a959223a"}, {"titulo": "Ofrenda en el verso 3.3", "texto": "Ögún-ribiti:\nadivinó Ifá para Iworiméji,\ncuando Iwöriméji iba a casarse con pè,\nla hija de Ọlofin\nLe aconsejaron hacer sacrificio,\npara que su esposa nunca fuera estéril.\nUna gallina debe ser el sacrificio.\nEl escuchó y sacrificó.\nEl adivino dijo:\n\"Ambos, los arboles de palma femeninos\ny masculinos nunca serán estériles\"", "origen_id": "22bd3d133247837d8bfe53ad"}, {"titulo": "Ofrenda en el verso 3.4", "texto": "fue el que adivinó Ifá para Ode.\nLe dijo que él debía venir y sacrificar:\nuna piedra de amolar y una estera,\npara lograr que todos aquellos\nque habían venido a regocijarse con él\nsiempre permanecieran con él.\nOde rechazó y abandonó el sacrificio.\nEl dijo: \"que estaba satisfecho,\nsi él podía solamente deshacerse de Awasa\".", "origen_id": "9ac702af4cab13a608f21586"}, {"titulo": "Ofrenda complementaria 1", "texto": "4 eiyelé (pichón), 4 abo adie (gallina), 1 plato blanco, 4 eko (ñame cocido), 1 epo (botella de aceite de palma) y 50 nira (dinero)\n\nDestinatario: Ibeji y Obàtálá", "origen_id": "7d793f04c8c96858e38f4510"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà está representado por los dieciséis ikin. Èṣù envía la compañía a quien ofrece. Olókun y Ọlọ́sà son dueños del mar y de la laguna. Ọbàtálá, Ìbejì y Ẹlẹ́dá reciben ofrendas de protección.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Sango; Aganju", "origen_id": "92ffb5cb179403fbd7702ef0"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Anzuelos, ñame, garrote, piedra de afilar, hojas de Ifá para lavar la cabeza, hoja de alájàngbàlúù."}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 1", "texto": "cachorro; fruta orì", "origen_id": "7fb8b1b82bb1bf011e029607"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 3.1 (yorùbá): Mujimuwa awo Ọpakẹrẹ / li o dífá f'Opakẹrẹ. / Ó niki ó rúbọ / ki o ma baa ṣaisan: / Ógún Iwọ pẹlu ógún eyẹlé / Ó gbọ̀ ó rú. / Ó ṣe ewé Ifá fún un / ki o fi fọ Ori, / ki o si fi wẹ Ifá rẹ̀. / Ó ni: \"Opakẹrẹ ko maa ṣaisan\".", "Verso 3.2 (yorùbá): Gbẹgi jebete: / li o dífá fún Ode, / nigbi Awasa nbaa iṣo'tá. / Wọ̀n niki ó rú / Olugboro ati ẹru-iṣu. / Ode gbọ̀ ó rú. / Wọ̀n gun'yán / Wọ̀n jẹ yán tán ni alẹ / Wọ̀n sun / Nigbati o di oru / Awasa mbọ / Ode fi Olugboro owọ̀ rẹ paa / Nigbati o di owuro qjẹkeji / Wọ̀n ba okú Awasa ni òde.", "Verso 3.3 (yorùbá): Ogün-ribiti: / ll o difá fún Iwòriméji, / nigbi Iwòriméji mi la fẹ Ọpè / tiiṣe ọmọ Ọlọ́fin / Wọ̀n ni ki o wa rúbọ, / koni'id'àgán. / Abo-adiyẹ li ebọ / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Tako tabo opè kiid'ágàn\".", "Verso 3.4 (yorùbá): Tijótayọ̀: / li o difá f'Ode / Wọ̀n ni ki o wa rúbọ / ọlọ ati eni, / ki àwọn ti nwa yọ li ọ̀dọ̀ rẹ / le maa joko tii. / Ode kọ ko rúbọ / Ó ni: bi oun ba ti p'Awasa ṣa o to.", "REZO: IWORY MEYI YIGUI YIGUI MAYO MAYO ADIFAFUN KOKOLO YEBEIFA TIROKEYA LAMPE SHANGO ARONI YEO ELEREPIN ORUNLA LORUBO.", "REZO: OSHISHE KOLORI MILLEKAN OKONI FINIGONI HANDU ADIE ANI BABALAWO. LODIFAFUN ARERE ONI OLOKUN OMO AYA ARELELO ORONOPIN IWORY MEYI YIGUI YIGUI MAYO MAYO ADIFAFUN KOKOLO YEBEIFA TIROKEYA LAMPE SHANGO ARONI YEO ELEREPIN ORUNLA LORUBO.QUIOLORUN ABO AKORDIE EKU EPO ABEFA OWO.", "REZO: ASHESHE KODORA ALOSHIN KONI LLEGANARARENI PURU INA GUEGUI IBADU ADIE CUN BABALAWO LODIFAFUN ARERE ONI LORUN UBEALLARERE ARONIPIN EYA LONOBO KOLA ODENE NI MU ABATASHOSHIN OKUTA GUERA LODE EMBORUSHOLA NATA PERE BORO KARAIDEFAFUN AKATO AYARE NIBATI OLO RUN ENGUERE LEBO.", "REZO: OTICOGUE SHOMO NIDE MAGUELE ADAFUN BALE TINSHO MOIGUE ARUMBON AIDO DIE MELLE LEBO OWO LA MEYO MEYO ASHISHA OMO ALARA OTONISHA YEKAN ORONIPINI EYA LENU SHOLA EREBEN Y TINLA BORO BORO SOKO AYA OTAN ADIFA FUN OKOTE AYARE ARIMI BATIALOKUN GUERENGUERE LEBO.", "REZO: IFA ANULA BOBORO KOKO BOISHE BORE KARINKUNKU BORU SHOLA AIDAFUN OLOKUN KOKOTO AYARE.", "REZO: EBENEGU SHOLEN ORE BENINUN ABALU OKUTE BERE OMO NIMA OMO ITI KONIOGUE ANUMIN PANIUN OLDE OUKO BORU SHOLA INATA BOROBORO AYO, OTAN BORO, BORO KAMU ADIFAFUN YOKAFUN OKOTO AYARE OWUNKO AKORDIE EYELE OWO LA MEFA OKU EYA.", "REZO: YIGUI YIGUI MOYO ADAFUN UMBATOLO LOORBA LODA BOBO KEKE OMOLONGO ODAFUN YONLO ODE BALASA ODIYO ODERE ODE BALASA ODERE EBO EWE META GUAGUA BANETA EL LEÑA Y UN EKO.", "REZO: IFA O. ODIFAYOKO OKANIKO ENLE KOKORIOKO LELUN KOKORIOKO RUBO KINKO MELLA AKORDIE ADIE MELLI ADOFA ELBO FUN KORIKO YOMBA, LOIGODO OKON RESHEGUE ASECERO GRI GRI LONIO BABALAWO ADOFA YOKO FUN SHEKERE DIBAYU TANTO LOYE BABARE ARENI IGUS ARE NI ODI OFA SHEGUE ORONI MOLE OFE.", "REZO: OSHISHE OMO LARA ATISHE KONI YEKAN ARONI GUIN NIPONI IBA DUADIE UN BABALAWO LODIFAFUN ARERE ONI OLORUN AYAERELO ARONI GUIN EYA ABEMEBU SHOLA ARE BEUN MABADA SHO ESHUN EKUTA GUEREGUERE NI OMO ITIKOKO MOPE ORUN OSHUPA NI OMODE BARUN SHOLA BORO SOKO AYO OTA BORO KARUN ADIFAFUN KOTO EYELE.", "REZO: AKASO FARATILE LODAFUN KONISA, BOGO ODI AKUKO AKOFA EKU EYA EBETA AOGUO ADIFAYOKO AKORIDO KULE KONKO LELUN KORIKO ORUGBO ADIE MELLI ONLE OKOFA EKU EYA EBETA OWO.", "REZO: IWORY MEYI AKUSHERALA OTOSHE NI YEKU ALERE NI AJALDA OGOLDE DIESDE EYELE IBO. AWO SHEKE ESOKAN QUIERE GRIGRI OLOMA TOLO FALLE GUALE ALIAKA LODAFUN ORUNLA ORUBA AKORDIE AUKO IGUALE META ERU EYA EBETA OWO. DICE QUE LA PERSONA ESTA MUY MAL Y QUE EL COJO NO PUEDE CORRER; Y EL QUE TIENE UN SOLO MEDIO NO PUEDE SONARLO. DESPUES DE LA ROGACION USARA UN PAÑUELO TODOS LOS DIAS Y ASI VERA SU ADELANTO Y LO QUE DESEA.", "REZO: ASHIBE OLARA AWO ATOSHI KONIYEKAN OBINI LANLA NIBANI NIMU NI BANDU ADDIE ODAFUN ADERE OBINI AYA OLORUN LOMU OKAN IÑI KIROSHEKE ESEHAN GUIRI GUIRI LONA ADIFAFUN OBINI AYA SHEKERELUBA OYUPAN UNLE YIWI MAYO MAYOADI AFUN TOKOLUBA OBINI UNLEUN LODE EPEITI ASHISHELEOGODO NISHOYU KEK TOLOKUN ADAPA ALANLA KUTIFIKO GBOBO ARAISHE TOLOYU OBINI KARAWA LODAFUN OBANLA KAFEREFUN OGGUN, SHANGO ATI OZAIN.", "REZO: IWORY MEYI AWO OMO NIFA ENI IFA ELEGBARA AWO OMO NIFA UNSORO AWO OMO NIFA AFEKU ELEGBA AIBALE AIYA SHON SHON LOMA OYU OBATALA OFORANLE OBATALA ILE ORUNLA EGGUN BABA ELEGBA IBURA IFA SHANGO AGBORAN OSHE OMOLO OMA MOTUMBA O IWORY MEYI AWO OMO NIFA MAFEREFUN ELEGBA OBATALA SHANGO ATI EGGUN BABARE.", "REZO: ORI BAWA LORI IBE ONONIRE ILE IKU INTORI AWO ONIRE LORI ABERE ORI OKANA GALERE LERI INA BEKE LESE SHANGO ONI SHANGO KOGIELEKUN WA NI IRE AWO OSHE OBINI ARUN OBARI INTORI IRE ORUNLA.", "REZO: ASOPEMPE YARU ADIFAFUN SARUMI TIODOLORUN ABORI YUGU ADIFAFUN ODE LEIBO OGIRI SAPALA EGIRI SAPALO AJUBU LU KORIKO LODE OBODO ARUGBO.", "REZO: SHEGUE SHEGUE SHEGUERE GUIRI GUIRI KAN GUILONO UMBATI UMPON.", "REZO: BABA IWORY MEYI OBINI META TA OFI OFI OLO ORISIRE IGUERI ALELE IWORY IFA LOGUIFUN LORUBO EURE META ISHU ILU META ERUSHI META OWO.", "REZO: ATAKARA MATIKA AIRA UYO OMA ATANI KARA EYE OKOKO MORELENI ADIFA BABA AKAFILA ELENO APOSHI APOSHIRE AWO EWE IFA AKAKARA MATIKA AJARA JERI OMOLO IKI OPA SHORO SHORO OFOTA KOTA KORU."]}]$q$::jsonb),
(4,'596d8aa583708727ae3d68fe238d8562','39a623693e427ad44e7527f1295eb455',$q$[{"titulo": "Idea central", "texto": "Ìdí Méjì completa los cuatro puntos cardinales del universo y simboliza la maternidad: la unión de lo masculino y lo femenino que da a luz. Habla de enemigos ocultos, de hechizos y de pesadillas, y de una persona que no logra establecerse. Con la ofrenda llegan la buena fortuna, la larga vida y una posición elevada; lo que se hace paso a paso y con firmeza se vuelve grande.", "pasajes": [{"titulo": "Frase clave", "texto": "Odi crea el renacimiento.", "origen_id": "78908a4981919de9f7b63a87"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está presionado por problemas de dinero y emocionales, teme a enemigos ocultos o tiene pesadillas.", "No logra establecerse: cambia de casa o de lugar buscando dónde echar raíces.", "Está por alcanzar una posición importante y teme perderla después; el crecimiento puede ser lento pero seguro (relato de Àkèsán y el mercado).", "Desea formar familia o tener hijos (relato de Odidimadẹ).", "Se acerca un viaje con riesgos que se pueden superar (relato de Òrúnmìlà en el camino).", "Siente que la buena suerte ya llegó una vez y se le escapó, y espera que vuelva (relato de Onibode).", "Quiere ver hechas realidad sus ideas (relato de Itẹrẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que las ideas se materialicen.", "Larga vida y buena fortuna, para hombre o mujer.", "Una posición alta en la vida; lo que crece despacio pero seguro.", "Fama, paz mental, riqueza y sosiego.", "Una hija para la mujer que la desea, aplacando a Ọ̀rúnmìlà.", "Un viaje seguro si se ofrece a Ògún.", "Protección como la de una muralla alrededor de la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enemigos ocultos, hechizos y pesadillas.", "Cambiar de casa en casa sin echar raíces; puede ser necesario volver al lugar de nacimiento.", "Trabajar duro y perderlo todo al final si no se ofrece a los ancestros.", "Muerte súbita si no se adora a Ifá.", "Detractores al subir de posición."]}, {"titulo": "Enseñanza principal", "texto": "Hay que ser veraces, honestos y rectos en el trato con los demás, y tener los pies en la tierra. La red de pesca se teje con pequeñas vueltas de la mano y termina siendo enorme: así crece lo que se hace con constancia."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Ìdí Méjì habla de gente que tiene enemigos secretos que lo molestan lanzando hechizos sobre ellos, o de personas que tienen pesadillas la mayoría del tiempo. Ellos necesitan aplacar a Ifá para superar estos obstáculos mundanos.", "origen_id": "4dde55fdfa97e3aefbd7e1b4"}, {"titulo": "Características generales", "texto": "Otros nombres: Odi Moji / Ejiodi / Èjidí.\nÌdí Méjì es el 4to. Odù en el orden fijo de Ọ̀rúnmìlà. Este Odù es esencial ya que completa los 4 puntos cardinales del universo, Èjìogbè (este), Ọ̀yẹ̀kú Méjì (oeste), Ìwòrì Méjì (norte), Ìdí Méjì (sur). El Odù Ìdí Méjì simboliza la maternidad, la interacción entre la parte masculina Odi en el lado derecho, con la parte femenina en el lado izquierdo resulta en la reproducción, el nacimiento de un niño.\nSi una persona está encontrando dificultades para establecerse en la vida y está cambiando de casa en casa sin una residencia permanente, Ìdí Méjì dice que la persona debe regresar a la ciudad o lugar o país de su nacimiento. Con el sacrificio apropiado al Ori de la persona (cabeza) o Ẹlẹ́dá (creador), la vida puede ser retornada con facilidad a la normalidad.\nEn Ìdí Méjì, Ifá ve la buena fortuna y larga vida para un hombre o una mujer, pero el cliente necesita adorar a Ifá para evitar una muerte súbita.\nEl cliente puede elevarse a una buena posición en la vida pero debe ser cuidadoso con los detractores. Es posible trabajar duro temporalmente en la vida y perderlo todo al final. Para prosperar deben ser hechas constantes ofrendas a los ancestros del cliente.\nSi alguien está planeando viajar, debe ser hecho un sacrificio a Ogún para asegurar una jornada segura y feliz. Cuando una mujer está desesperada por tener un hijo, se le aconseja aplacar a Ọ̀rúnmìlà. Ifá dice que ella podrá tener un hijo y que este será una niña.\nPara tener éxito en la vida, las personas encarnadas por Odù Ìdí Méjì tendrán que ser veraces, honestos y rectos en sus tratos con otras personas. Ellos deben tener los pies en la tierra y ser prácticos en sus actitudes durante su vida.", "origen_id": "d247a8caf80208e96f3ea78f"}, {"titulo": "Interpretación tradicional", "texto": "Odi es la palabra Yoruba para los órganos reproductivos de las mujeres y el proceso de dar a luz. En Ifá cosmología de todos los nacimientos, después del momento inicial de la Creación, es renacimiento. En términos humanos, renacimiento se refiere a la reencarnación (atunwa), en términos prácticos, es la creación de nuevas formas de estructuras inadecuadas y obsoletas. En su manifestación negativa, Odi es un intento desesperado de aferrarse al pasado.", "origen_id": "2999859ee56fdd47d6bb1bc0"}, {"titulo": "Orientación complementaria", "texto": "Odi como el renacimiento se refiere al cambio dotal de mente, cuerpo y espíritu que ocurre en puntos significantes en el camino de la disciplina espiritual. El renacimiento ocurre en una iniciación ritual y en esos momentos iniciados en nuestras vidas diarias que transforman nuestra percepción de unos mismo del mundo. Ifá enseña que después, del momento original de la Creación de todo nacimiento es el renacimiento, luz renacida como estrellas, estrellas renacidas como planetas, agua renacida de la tierra y así sucesivamente. En su manifestación negativa, Odi es, ya sea, arbitraria al cambio en resistencia a la transformación real o es un aferro inapropiado al pasado.", "origen_id": "cb492e3bb6d73425b2b615c8"}]}, {"titulo": "Relatos reunidos", "puntos": ["Itẹrẹ y las ideas que se cumplen. Atẹlẹwọ́-abinutelu consultó para Itẹrẹ y le dijo que sus ideas siempre podrían hacerse realidad. Le marcaron clavos de cabeza, tres chivos y tres gallos, y medicina de Ifá para beber. Cumplió. Los clavos de cabeza significan que sus sueños e ideas llegarán a buen término.", "La cadena que la muerte no rompe. La muerte estaba matando a la gente de Ilé-Ifẹ̀. Opa-aro abidijegelege les marcó una cadena y un carnero. Ofrecieron, y el babaláwo dijo: 'El eslabón sencillo nunca se rompe; por eso las manos de la muerte ya no pueden tocarlos'. Así se detuvo la muerte fuera de tiempo.", "Odidimadẹ y su hijo. Odidi-afiditi le aconsejó a Odidimadẹ ofrecer dos cocos grandes, dos babosas y 3,200 cauríes. Se negó, y el babaláwo dijo: 'Tu hijo nunca hablará en esta vida'.", "La muralla que protege la ciudad. Durante una guerra entre pueblos, los adivinos consultaron para la muralla (Odi) y le dijeron que protegería la ciudad si ofrecía dos telas para abrigar. Cumplió. Esto vale para toda familia o persona que necesita protegerse de lo que amenaza su estabilidad.", "Àkèsán, el primer mercado. 'Con pequeñas vueltas de la mano se teje la red, y termina siendo tan ancha que se traga un mortero.' Así consultaron para Àkèsán, el primer mercado creado en la Tierra, gobernado por una mujer rey, para que tuviera mucha gente. Ofreció en cientos, y desde entonces el mundo entero acude a Àkèsán, el mercado que guió a todos los demás.", "Àjòjì gòdògbò en Benin. El caracol no hace la base del tinte, ni se espera que el pollo vuele. Así consultaron para Àjòjì gòdògbò, el extranjero que iba a ejercer la adivinación en Benin y preguntaba si le iría bien. Le dijeron que ahí encontraría su fortuna si ofrecía. Ofreció y se hizo riquísimo. Cantaban: 'Ayúdanos a reconstruir Benin, Àjòjì gòdògbò'.", "Onibode y la bondad dos veces al día. 'Las dos nalgas en que me siento me dan comodidad.' Así consultaron para Onibode Ejiejiemogun, que quería que la bondad lo recibiera dos veces al día. Ofreció, y desde ese día así fue. Esta persona cree que la buena fortuna ya pasó de largo y se le escapó entre los dedos; debe seguir optimista y rezar con constancia a su Òrìṣà para que sus sueños se cumplan.", "Ọ̀rúnmìlà y los tres lugares de la muerte. Ifá consultó para Ọ̀rúnmìlà el día que debía pasar, cargando al pato, por los tres lugares donde se reúne la muerte. Le pidieron ofrecer para que la muerte, la enfermedad y las piedras de los problemas no lo alcanzaran. Ofreció, y los dos pasaron sin daño."], "pasajes": [{"titulo": "Verso 4.1", "texto": "Atelẹwó-abinutelu:\nadivinó Ifá para Itẹrẹ.\nEllos dijeron\n\"sus ideas siempre podrían materializarse\",\nPor eso debe realizar sacrificio:\nclavos\"\n, tres chivos\ny tres gallos.\nIterẹ obedeció e hizo el sacrificio.\nEllos prepararon medicina de Ifá\npara que él las bebiera.", "comentario": "Entre los materiales prescritos para el sacrificio están los clavos con cabeza, que significan que ltere podrá tener sueños que se convertirán en realidad o permitirle que lleguen cabeza ideas su realizables que puedan ser materializadas.\n\nIṣó: clavo de metal. El significado más ancestral de Iṣó es: uña, pesuña, garra.\nPara elaborar la medicina de este Odù valorar el uso de garras, que también\ntienen la función mágica de \"fijar\" o \"agarrar\".", "origen_id": "0f12d455820706d1be147f00"}, {"titulo": "Verso 4.2", "texto": "Opa-aro abidijegelege:\nadivinó Ifá para las personas en lfè,\ncuando-todos gritaban que la muerte\nastaba matando a las personas allí.\nEllos deblan sacrificar:\nuna cadena y un carnero padre.\nEllos lo oyeron y sacrificaron.\nEl Babaláwo dijo:\nUn eslabón simple nunca se rompe,\npor eso las manos de la muerte\nno pueden tocarlos por más tiempo\".", "comentario": "La muerte estaba matando a todos en llé-lfẹ. Ifá fue consultado. El Babaláwo aconsejó a los residentes que hicieran un sacrificio que incluyera el eslabón de una cadena que nunca se pudiera romper. así fue como las intempestivas manos de la muerte fueron detenidas (la muerte fuera de tiempo).", "origen_id": "fffb5ecae71668de687419bd"}, {"titulo": "Verso 4.3", "texto": "Odidi-afiditi adivinó Ifá para Odidimadẹ.\nEl aconsejó que ofreciera un sacrificio:\ndos cocos grandes (agbon olodu),\ndos caracoles babosa\ny 3200 cowries.\nEl rehúso hacer el sacrificio.\nEl Babaláwo dijo: Ifá dice:\n\"su hijo nunca hablara en esta vida\".", "comentario": "Òdí Méjì adivinó para Odidimadẹ, pero el rehúso ofrecer el sacrificio. Por lo tanto, de acuerdo a Ifá, su hijo quedará mudo por toda la vida.", "origen_id": "bff2ab35efe2d536868a08a2"}, {"titulo": "Verso 4.4", "texto": "Yo soy èni-òdí,\nTú eres ẹ̀ni-òdí,\nDos eni-òdí:\nadivinaron para Odí (la muralla)\ndurante las hostilidades políticas.\nEllos dijeron: \"la muralla protegerá la ciudad\".\nPor lo tanto este debe ofrendar:\ndos ropas para abrigar.\nÉl escuchó e hizo la ofrenda.", "comentario": "Durante las hostilidades políticas entre dos pueblos, era obligatorio para los habitantes construir una muralla alrededor del pueblo para que los resguardara de los ataques enemigos. Esto se aplica a una comunidad, persona o familia que necesita protegerse de la amenaza de cualquier tipo de cosa que ponga en peligro su integridad o estabilidad.", "origen_id": "ed07f46f53eb24c94d018274"}, {"titulo": "Versos complementarios 1", "texto": "Esta persona será muy conocida, obteniendo paz\nmental, riquezas y buen sosiego. Todas las cosas\nque está haciendo paso a paso, pero con paso firme\ny seguro, se convertirán en cosas grandes.\n\n  Kóróbótó kóróbótó ni wóón pilè àwợn\n            Bó bá dókè a gbibú\n            A móợ gbợmợrí odó\n            A móợ gbợmợrí ợlợ\n             A dífá fún Àkèsán\n      Àkèsán tíí şe baálè ợjà olówó\n        Àkèsán lợjà àkódá ńlé ayé\n                Ợba ló si ni í\n          Obìnrin sí ni Ợba òhún\n              Wón ní kó rúbợ\n                 Ó bá rúbợ\n     Ó rú ohun gbogbo nígbà nígbà\n        Gbogbo ayé bá Àkèsán pé\n     Tée dòní ní wón ń nájà Àkèsán\n        Gbogbo ợjà tó kù ti wón dá\n      Àkèsán ní bàbá gbogboo wợn\n      Ifá pé ayé ó yẹ ẹni ó dá Ifá yìí\n           Ó tóbi tán ní ń yin Ifá\n         Ifá ń yin Olódùmarè Ợba\n    Ó ní béè làwợn Babaláwo tòún wí\n  Kóróbótó kóróbótó ni wóón pilè àwợn\n            Bó bá dókè a gbibú\n            A móợ gbợmợrí odó\n            A móợ gbợmợrí ợlợ\n   A dífá fún Àkèsán baálè Ợjà Olówó\n       Wón ní ó rúbợ kó lè baà tóbi\n\n          Kó lè baà dẹni ńlá láyé\n            Àkèsán gbébợ ńbè\n                  Ó rúbợ\n                  Írú ẹbợ\n               Èèrù àtùkèsù\n         Ệ wáá bá ni ní jèbútú ire\n    Jèbútú ire làá bá ni lésè Ợba Òrìşà\n            Àkèsán mòmò dé ò\n                 Báàlè ợjà\n             Báa bá rólórí rere\n                 À á dájà.\n\nEn pequeñas vueltas de mano, ellos empiezan a\ntejer la red de pesca, y así se va ensanchando\ncompletamente.\nPudiendo tragarse un mortero, pudiendo contener a\nun molino.\nLanzaron adivinación para Àkèsán, que era el más\nadelantado hombre rico del mercado, Àkèsán fue el\nprimer mercado creado en la Tierra.\nUn rey, poseyó el mercado y era una mujer, a quien\nse le dijo que ofrendase para poder tener una buena\nafluencia de personas.\nElla ofreció el sacrificio en múltiples de cientos.\nY el mundo entero se unió con Àkèsán hasta\nnuestros días.\nÀkèsán fue la cabeza guía del resto de los mercados\nformados en el mundo.\nIfá dice que la vida le será plácida a esta persona.\nElla se convirtió en grande y comenzó a invocar y\nalabar a Ifá.\nIfá está invocando a Olódùmarè.\nElla hizo todo como se lo dijeron que hiciera.\nEn pequeñas vueltas de mano, ellos empiezan a\ntejer la red de pesca, y así se va ensanchando\ncompletamente.\n\nPudiendo tragarse un mortero, pudiendo contener a\nun molino.\nLanzaron adivinación para Àkèsán, que era el más\nadelantado hombre rico del mercado, Àkèsán fue el\nprimer mercado creado en la Tierra.\nElla escuchó el consejo y ofrendó.\nPara poder ser famosa, conocida y poderosa.\nOfrecimiento de sacrificios y regalos libres a Èşù,\nhará que las buenas cosas lleguen a nosotros.\nNos encontraremos con las riquezas al pie del Òrìşà.\nAquí está Àkèsán, el mercado supremo y poderoso.\nSi tenemos un buen líder, formaremos un\nconmemorativo mercado.\n\n             Ìgbín ò pilè aró\n        Àfèè bòjò ni ò pilè àràn\n     A ò gbójúu fifò le adiẹ àágádá\n    Taa ló gbójúu yíjan lé Alágẹmợ\n                Mo dé rere\n                Mo rìn rere\nWón şèşè ń kóhun ợlà kalè ni mo wợlè dé\n             bí ợmợ Olóhun\n          Kèé síí sợmợ Olóhun\n       Ìrìn àrinkò ni mo mòó rìn\n        A dífá fún Àjòjì gòdògbò\n      Níjó tíí ń sawoó ròde Ìbínní\n           Níbi ti òún ń lợ yìí?\n               Ó dáa fóun?\n        Wón ní gégé ire ní ó şe\n             Wón ní kó rúbợ\n                Ó bá rúbợ\n                 Ló lówó\n              Ló şe gégé ire\n         N ní wá ń jó ní wá ń yò\n\n        Ní ń yin àwợn Babaláwo\n        Àwợn Babaláwo ń yin Ifá\n   Ó ní béè làwợn Babaláwo tòún wí\n             Ìgbín ò pilè aró\n        Àfèè bòjò ni ò pilè àràn\n     A ò gbójúu fifò le adiẹ àágádá\n    Taa ló gbójúu yíjan lé Alágẹmợ\n                Mo dé rere\n                Mo rìn rere\nWón şèşè ń kóhun ợlà kalè ni mo wợlè dé\n             bí ợmợ Olóhun\n          Kèé síí sợmợ Olóhun\n       Ìrìn àrinkò ni mo mòó rìn\n        A dífá fún Àjòjì gòdògbò\n      Níjó tíí ń sawoó ròde Ìbínní\n            Báni tún Binní şe\n              Àjòjì gòdògbò\n            Báni tún Binní şe\n              Àjòjì gòdògbò\n             Báni túnlè yí şe\n              Àjòjì gòdògbò\n             Báni túnlè yí şe\n              Àjòjì gòdògbò.\n\nEl Caracol (Babosa) no forma la base del tinte.\nÀfèè bòjò no forma la base del túnel.\nNo hay esperanzas de que un pollo àágádá, pueda\nvolar.\nTampoco guardamos esperanzas del arrogante\nandar del predicador que está orando.\nAndamos y llegamos de buena forma.\nEllos estaban llevando afuera los artículos de la\nriqueza, cuando yo entré como si fuese el hijo del\ndueño.\n\nY aún sin haber llegado el verdadero dueño, yo supe\ncaminar, haciendo que el tiempo coincidiese con su\nllegada a casa.\nFueron quienes lanzaron Ifá para Àjòjì gòdògbò, el\ndía que ejercía el sacerdocio y la adivinación en la\nciudad de Benin.\n¿Me será bueno el lugar a donde me dirijo? El\npreguntó a Ifá.\nEllos le dijeron que se encontraría con sus futuras\nfortunas, pero debía sacrificar.\nÉl sacrificó y así sucedió, como estaba predicho.\nSe encontró con las fortunas y devino en hombre\nriquísimo.\nSe regocijó y alabó a sus babaláwos.\nEllos alabaron a Ifá.\nSe hizo exactamente lo que los babaláwos dijeron\nque se hiciera.\nEl Caracol (Babosa) no forma la base del tinte.\nÀfèè bòjò no forma la base del túnel.\nNo hay esperanzas de que un pollo àágádá, pueda\nvolar.\nTampoco guardamos esperanzas del arrogante\nandar del predicador que está orando.\nAndamos y llegamos de buena forma.\nEllos estaban llevando afuera los artículos de la\nriqueza, cuando yo entré como si fuese el hijo del\ndueño.\nY aún sin haber llegado el verdadero dueño, yo supe\ncaminar, haciendo que el tiempo coincidiese con su\nllegada a casa.\nFueron quienes lanzaron Ifá para Àjòjì gòdògbò, el\ndía que ejercía el sacerdocio y la adivinación en la\nciudad de Benin.\n¡Ayúdanos a reconstruir Benin!\nÀjòjì gòdògbò.\n¡Ayúdanos a remodelar a Benin!\nÀjòjì gòdògbò.\n\n¡Ayúdanos a reconstruir esta tierra!\nÀjòjì gòdògbò.\n¡Ayúdanos a reconstruir esta tierra!\nÀjòjì gòdògbò.", "origen_id": "b1a3788769c49062a485a5d5"}, {"titulo": "Relatos y ofrendas", "texto": "IDI MEJI (ODI MEJI)\n\nDos — traseros — que — uso — para —sentarme — en — ellos, - me — dan — comodidad, consulta Ifá\npara Onibode Ejiejiemogun en el día que Onibode Ejiejiemogun quería ver que la bondad lo\nrecibiera dos veces al días, Ifá aconsejó a Onibode Ejiejiemogun hacer ebo para que la bondad no\nlo pasara. Onibode Ejiejiemogun hizo ebo. Desde ese día, la bondad recibió a Onibode\nEjiejimogun dos veces al día.\n\nComentario:\n\nIfá dice que esta persona recibirá bendiciones si se hace ebo. Ifá dice que esta persona cree que la\nbuena fortuna lo ha pasado. Ifá dice que cuando la buena fortuna haya venido a esta persona en el\npasado, se escapó a través de sus dedos. Ifá dice que esta persona se queda optimista acerca del\nfuturo y él debe ofrecer alabanzas al Orisa pidiendo apoyo en la manifestación de sus sueños, Ifá\ndice que el rezo constante traerá los sueños de esta persona a la realidad.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), todas las cosas comestibles (ofrecimiento de una\nvariedad de comidas preparadas), 4 eko (pastel de harina de maíz), 1 epo (botella de aceite de\npalma), 1 plato blanco y 40 nira (dinero), ofrecido a Esú.\n\n(Ett (oferendas); 4 eiyele (pombo), todas as coisas comestíveis (oferendas de uma\nvariedade de comidas), 4 ekó (bolos de milho), 1 epo (garrafa de azeite de dendé), 1 prato\nbranco e 40 nira (dinheiro nireriano), oferecidos a Esú)\n\nEatalewa — con — gbagbdegbagada — ojos consulta Ifá a Orunmila en el día que Orunmila estuvo\ncargado a lagede a los tres lugares de reunión de la muerte. Es pato al que llamamos sojiji, y es\nlagade quien fue cargado a los tres lugares de reunión de la muerte. Ifá aconsejó a Orunmila\nhacer ebo para que la muerte, enfermedad y la piedra del problema no lo recibiera en los tres\nlugares de reunión de la muerte. Orunmilá hizo ebo y pasó a través de los tres lugares de reunión\nde la muerte con lagede. Ambos hicieron un viaje sin ser dañados. Orunmilá empezó a bailar y\ncantar en alabanza al Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a Olodumare.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo para que las piedras aventadas por la muerte y la\nenfermedad no los alcancen.\n\nEtutu (ofrecimiento): 3 Ako okuta (piedras duras), 3 eiyelé (pichón), 1 eko (pastel de harina de\nmaíz), 1 àgbo (carnero), 1 plato blanco y dinero determinado por el adivinador, ofrecido a Esú.\nÉéwo (tabú): Si el ñame se rompe mientras está siendo removido de su contenedor, no debe ser\ncomido. No caves agujeros cerca de la entrada a la ciudad.\n\n(Ett (Oferecendo): 3 Ako òkúta (pedras duras), 3 eiyele (pombo), 1 eké (bolo de milho), 1\nagbó (carneiro), 1 prato branco e certa quantidade de dinheiro determinada pelo 4wo, a ser\noferecida a Ésa. Eéwó (tabu): Se um inhame quebra enquanto está sendo removido de seu\nrecipeiente náo deve ser comido. Náo cave buracos perto da entrada da ciade.)\n\nI I\nI I\n\n87\n\nTr Tr\nOH HO", "origen_id": "83dc774b0ab9975aad802bc4"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Idi Meji habla de gente que tienen enemigos ocultos o tratando\n            de hechizarlos o que tienen pesadillas la mayoría del tiempo. Ellos\n            necesitan aplacar a Ifá para superar estas obstrucciones mundanas.\n            WO – el cliente se siente crecientemente presionado en problemas\n                                              tanto temporales como emocionales.\n       Idi Meji es el cuarto Odu en el orden fijado de Orunmila. Este Odu es\n           esencial, ya que éste completa los 4 puntos cardinales del universo.\n        Eyiogbe (este), Oyeku (oeste), Iwori (norte) y Idi (sur). Odu Idi Meji\n     simboliza la maternidad, la interacción entre la parte masculina Idi en el\n           lado derecho con la parte femenina en el lado izquierdo resulta en la\n                                       reproducción, el nacimiento de un niño.\n           Si una persona está encontrando dificultades para establecerse en la\n vida y está cambiando de casa en casa sin una residencia permanente, Idi\n       Meji dice que la pesona debe regresar a la ciudad o lugar o país de su\n       nacimiento. Con el sacrificio apropiado a ori de la persona (cabeza) o\n Eleda (creador) la vida puede ser retornada con facilidad a la normalidad.\n               En el Odu Odi Meji, Ifá ve la buena fortuna y larga vida para un\n      hombre o una mujer, pero el cliente necesita adorar Ifá para evitar una\n     muerte súbita. El cliente puede elevarse a una buena posición en la vida\n       pero debe ser cuidadoso con los detractores . Es posible trabajar duro\ntemporalmente en la vida y perderlo todo al final. Para prosperar deben ser\n        hechas constantes ofrendas a los ancestros del cliente. Si alguien está\n\nplaneando viajar, debe ser hecho un sacrificio a Oggún para asegurar una\n       jornada segura y feliz. Cuando una mujer está desesperada por tener un\n        hijo, se le aconseja aplacar a Orunmila. Ifá dice que ella podrá tener un\n                                                   hijo y que éste será una niña.\n          Para tener éxito en la vida, las personas encarnadas por Odu Idi Meji\n  tendrán que ser veraces, honestos y rectos en sus tratos con otras personas.\n      Ellos deben estar con los pies en la tierra y ser prácticos durante su vida.\n\n\n4.1 · Atelewo-Abinutelu adivinó Ifá para Itere. Ellos dijeron que sus ideas\n         siempre podrían materializarse; por lo tanto él debía sacrificar clavos,\n                   3 chivos y 3 gallos. Itere obedeció e hizo el sacrificio. Ellos\n                           prepararon hojas de Ifá para que él las bebiera (☼).\n\n\n4.2 · Opa-Aro Abidijegelege adivinó Ifá para el pueblo de Ife. Ellos\n             dijeron desde que la muerte estaba asesinando personas allí. Ellos\n                  debían sacrificar una cadena y un carnero . Ellos lo oyeron y\n            sacrificaron. El Babalawo dijo: un eslabón simple nunca se rompe.\n            Por esto las manos de la muerte no podrán tocarlos por más tiempo\n                                                                            (☼).\n\n\n4.3 · Odidi-afiditi adivinó Ifá para Odidimade. Ellos dijeron que ofreciera un\n       sacrificio: 2 cocos grandes, caracoles de babosa, 3200 cowrie. Él rehusó\n  hacer el sacrificio. El Babalawo dijo: Ifá dice que su hijo nunca hablará en\n                                                                  esta vida (☼).\n\n\n4.4 · Yo soy Eni-Odi. Tú eres Eni-Odi. 2 Eni-Odi adivinaron para el Odi\n(fortaleza) durante las hostilidades políticas. Ellos dijeron: el odio abarcará\n el pueblo. Por lo tanto éste debe ofrendar (ebo) ropas de abrigar. Y éste lo\n                                                                      hizo (☼).", "origen_id": "7f6665268ffc745b451f9647"}, {"titulo": "Relato en inglés 1", "texto": "“The fractured surface of brass shines like fire,” ‘Buzzing One’! beats the\ngbedu drum with both hands,” and “Very tall whirlwind,” the diviner of “One who\nawakes and sits in royal splendor”? were the ones who cast Ifa for “One who awakes\n\nand sits in royal splendor” when he was coming from heaven to the dwelling places\non earth?\n\nIfa says that we will bear a son who comes from heaven carrying his “calabash\nof destiny.”* There is no one who will be able\n\nto oppose him or to stop him in anything he undertakes. His glory will be great\n\non earth; everyone will know him all around the world; and he will complete what-\never he undertakes. The mention of the name of this child will cause the ground\n\nto tremble® around the world. “One who awakes and sits in royal splendor” is\n\nwhat we call Sun.\" Two hundred needles, one ewe, one white cloth, palm oil, and\none shilling two pence is the sacrifice, “One who awakes and sits in royal splendor”\nheard and made the sacrifice.", "comentario": "1. A large beetle with a black shell and red under-wings, whose name refers\nto the buzzing (bgunbgun) he makes when flying.\n\n2. Notes 2-4 appear on page 313.\n2. A king is said to gunwa when his chairs, carpets, and cushions are set out\nfor him and he comes out in all his royal finery and sits with arms and legs spread\nout pompously. Possibly it is derived from gun-(i)wa, meaning to mount-destiny.\n\n3. Not only in Nigeria, but all over the world, wherever houses are built.\n\n4. Cf. n. 2, verse 4-1A.\n\n5. “Kijikiji” describes the way it vibrates at the mention of his name.\n\n6. As in verses 1-6 and 103-1, Day (9j9) was interpreted as meaning Sun\n(orun). This verse explains why the sun is known and respected the world over,\nand predicts great fame for the child that is to be born. The rising of the sun in\nall its glory is compared here with a king sitting in royal splendor. In both this\ncase and in verse 103-1 the rather unusual sacrifice of 200 needles is required;\n\nperhaps these symbolize the rays of the sun.", "origen_id": "1f88de8725a090fe024733a9"}, {"titulo": "Relato en inglés 2", "texto": "“Hollowing is the foundation of the aran drum;? it Tt goes up, it becomes huge;\nif it goes up, it becomes immense” was the one who cast Ifa for Ipesan, Chief of\nthe Market. Ipesan arrives, oh, Chief of the Market; he is going to take new land\non which to settle. Ipesan is what we call the Qdan tree.? A lucky person arrives\nat the market,’ oh!\n\nIfa says this is someone who will have a settlement‘ of his own and lots of\nroom, but he should sacrifice lest he encounter an enemy and a thing which will\ndecrease the size of his settlement.\n\nThey said that Qdan tree should sacrifice one he-goat, one cock, one cutlass,\nand one shilling seven pence eight oninis, so that he would not encounter a slanderer\nat his settlement.\n\nThey said he would find a large enough place in which to settle, and that he would\n\nstretch out his arms and stretch out his legs.> Qdan tree heard the sacrifice, and\n\nhe offered one he-goat and one shilling seven pence eight oninis for a place in\n\nwhich to settle, but*he did not offer the cock and the cutlass that he might be able\n\nto stay there for a long time. When Qdan tree reached his settlement, he stretched\n\nout his arms and he streched out his legs; but when he had finished stretching them\n\nout, people came and took a cutlass® and began to cut off his arms and legs.\nTherefore this person should sacrifice in order that what he has achieved in the\n\nmorning of his life shall not be destroyed by others in the evening of his life.", "comentario": "1. Kotokoto is said also to represent the scraping sound in hollowing out a\nlog to make a drum. Aran is one of the types of drums used in the worship of Ifa.\n\n2. The ọdan tree (Ficus spp.) is called Chief of the Market here because it\nis commonly planted in Yoruba market places as a shade tree.\n\n3. This phrase implies that he finds good fortune, that he “arrives at the mar-\nket of destiny” (cf. verse 256-1), and, more specifically, that he will have a large\nfamily (cf. verse 225-3).\n\n4. That is, a place to live. It is implied that he will also have a large num-\nber of people living with him.\n5. The branches and roots of the tree.\n\n6. This verse explains why the ọdan tree grows in the market, and why people\npass time by hacking at its roots and branches. It is understood that it met this\nfate through the cutlass which it refused to sacrifice.", "origen_id": "02408da4f5b222db0f1e80e7"}, {"titulo": "Relato en inglés 3", "texto": "“You arrive here excellently, you walk excellently; you know how to walk on\ntime! with both feet; no sooner are riches spread on the ground than you arrive\njust like the child of their owner,” was the one who cast Ifa for Stout Foreigner\nwhen he was going to Benin City. They said that someone’s head will bring him\nto a place where he will achieve his destiny; they said a blessing is certain to\nreach him. They said that Stout Foreigner, who was going to\n\nBenin, should sacrifice two rats, two fish, two snails, two chickens, and eleven\nshillings. He heard and he made the sacrifice.\n\nWhen he reached Benin, everything he turned his hand to became good. If a\nwoman who could not conceive came to him, she became pregnant; if they brought\nan ill child to him, it became well. Thus Stout Foreigner became a rich person\nand the owner of a house in Benin.\n\nIfa says this is someone who wants to go on a journey. He should sacrifice\nthat he may be able to gain money, glory, and honor where he is going, and that\nhis journey may be of great benefit? to him.", "comentario": "1, That.is, arriving punctually.\n2. Note the pun on san (cure or heal) and san (benefit).", "origen_id": "c207d9fd015b70c76451910b"}, {"titulo": "Relato en inglés 4", "texto": "“Come here, people in heaven do not refuse their relatives a home”! was the\none who cast Ifa for “My partner? does not refuse my requests,” an only child who\nwas about to inherit everything on earth. “My partner doesn’t refuse my requests”\nis what we call the Egungun.?\n\nIfa says we should sacrifice to an Egungun. He says the Egungun will open\nthe door of children for someone; a woman will bear many children.\n\nWe should sacrifice red steamed beans,‘ a basket of cornstarch porridge, a\nwhip, and a he-goat to the Egungun. Ifa says that the name of this person will not\ndie out, and he will not fail in the thing concerning which we have cast Ifa, but that\nhe should go to Egungun about the matter.", "comentario": "1, This translation is open to question. One informant interpreted it as\n“people in heaven do not refuse themselves a house,” but the diviner himself justi-\nfied the interpretation given by stating, “No one has ever heard of anyone being\nrefused admission to heaven.” \"\n\n2. Literally, “My Second,” with reference to the guardian spirit in heaven.\n\n3. Seen. 6, verse 7-5. The dead “inherit everything on earth” in the sense\nthat all living things must die,\n4, Word magic is implied here, as red steamed beans (ọlẹ) are sacrificed to\nproduce pregnancy, and ọlẹ is the word for embryo.\n\n52-5\"\n\n“How about today? broad foreleg of a dog beside the fire; how about tomorrow?\nbroad foreleg of a dog beside the fire; White Pin Tailed Whydah, its tail feather) is\nwhite” was the one who cast Ifa for Ogbegbe Ranyinranyin,” when he was bringing\nriches to whatever house he visited.\n\n“Idu,* bring riches and visit my house;\n“Ogbegbe ranyinranyin, bring riches and visit my house”\n\nIfa says he sees the blessing of a wife? whom someone will marry. At this very\nmoment she is kneeling beside his ancestral guardian soul in heaven. One cock, one\nhen, and nine pence six oninis is the sacrifice that Idu offered at that time, along\nwith four pigeons.\n\n1. The Olokoge (or Ologoge) bird is the Pin Tailed Whydah (Vidua macroura).\nMales of this species have tail feathers (irere) which are two to three times the\nlength of their bodies. See Fairburn (1933; 98), Abraham (1958: 796).\n\n2. The meaning of this name could not be explained, except for saying that\nRanyinranyin is the noise that Ogbegbe makes. In verse 54-7 ranyin means spin-\nning or oscillating.\n\n3. Idu, also unexplained, appears to be another name for Ogbegbe Ranyinranyin,\nfor whom this figure was cast, as Idu is later named as the one who made the sacri-\nfice.\n\n4. There is no relation here between the prediction of taking a wife and the\nprecedent case which refers to wealth.", "origen_id": "e13588e2e07dd9da148cddac"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Itẹrẹ: clavos de cabeza, tres chivos, tres gallos y medicina de Ifá para beber.", "Ilé-Ifẹ̀: una cadena y un carnero.", "Odidimadẹ (rechazado): dos cocos grandes, dos babosas y 3,200 cauríes.", "La muralla: dos telas para abrigar.", "Onibode: 4 palomas, comida variada, 4 ẹ̀kọ, aceite de palma, un plato blanco y dinero, a Èṣù.", "Contra la muerte y la enfermedad: 3 piedras duras, 3 palomas, ẹ̀kọ, un carnero, un plato blanco y dinero, a Èṣù. Prohibido comer el ñame que se rompa al sacarlo de su recipiente y cavar hoyos cerca de la entrada de la ciudad.", "Para la mujer que desea hijos: aplacar a Ọ̀rúnmìlà. Para viajar: ofrenda a Ògún. Ofrendas constantes a los ancestros."], "pasajes": [{"titulo": "Ofrenda en el verso 4.1", "texto": "Atelẹwó-abinutelu:\nadivinó Ifá para Itẹrẹ.\nEllos dijeron\n\"sus ideas siempre podrían materializarse\",\nPor eso debe realizar sacrificio:\nclavos\"\n, tres chivos\ny tres gallos.\nIterẹ obedeció e hizo el sacrificio.\nEllos prepararon medicina de Ifá\npara que él las bebiera.", "origen_id": "feebe159f967bea7f2fdc211"}, {"titulo": "Ofrenda en el verso 4.2", "texto": "Opa-aro abidijegelege:\nadivinó Ifá para las personas en lfè,\ncuando-todos gritaban que la muerte\nastaba matando a las personas allí.\nEllos deblan sacrificar:\nuna cadena y un carnero padre.\nEllos lo oyeron y sacrificaron.\nEl Babaláwo dijo:\nUn eslabón simple nunca se rompe,\npor eso las manos de la muerte\nno pueden tocarlos por más tiempo\".", "origen_id": "ba5d4e160b968d585d6149d4"}, {"titulo": "Ofrenda en el verso 4.3", "texto": "Odidi-afiditi adivinó Ifá para Odidimadẹ.\nEl aconsejó que ofreciera un sacrificio:\ndos cocos grandes (agbon olodu),\ndos caracoles babosa\ny 3200 cowries.\nEl rehúso hacer el sacrificio.\nEl Babaláwo dijo: Ifá dice:\n\"su hijo nunca hablara en esta vida\".", "origen_id": "7c1d71b016626b964faa3561"}, {"titulo": "Ofrenda en el verso 4.4", "texto": "Yo soy èni-òdí,\nTú eres ẹ̀ni-òdí,\nDos eni-òdí:\nadivinaron para Odí (la muralla)\ndurante las hostilidades políticas.\nEllos dijeron: \"la muralla protegerá la ciudad\".\nPor lo tanto este debe ofrendar:\ndos ropas para abrigar.\nÉl escuchó e hizo la ofrenda.", "origen_id": "6ccce0791ae2c08c4d23aba0"}, {"titulo": "Ofrenda complementaria 1", "texto": "3 Ako okuta (piedras duras), 3 eiyelé (pichón), 1 eko (pastel de harina de maíz), 1 àgbò (carnero), 1 plato blanco y cierta cantidad de dinero determinada por el Awo\n\nDestinatario: Èṣù", "origen_id": "530358b2d343774b0e544b0c"}]}, {"titulo": "Relaciones espirituales", "texto": "Orí y Ẹlẹ́dá, la cabeza y el creador, devuelven la normalidad a la vida. Ọ̀rúnmìlà da hijos a la mujer. Ògún protege los viajes. Los ancestros sostienen la prosperidad. Èṣù recibe las ofrendas de protección.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Yemoja", "origen_id": "30bfede48c374379c3d82640"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Clavos, cocos grandes, babosas, cadena, telas, piedras duras, ẹ̀kọ."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 4.1 (yorùbá): Atẹlẹwó-abinutelu / li o difá fún Itẹrẹ / Wọ̀n ni: / \"Ero ti'oni orí li oun mi a maa pa\" / Nitorinaa ki ó rú: / iṣó, òbúkọ méta / ati akuko-adiyẹ mẹta. / Itẹrẹ gbó ó rú. / Wọ̀n ṣe ewé Ifá fún un kio maa muu.", "Verso 4.2 (yorùbá): Ọpa-aro abidijẹgẹlẹgẹ: / lo difá fún'wọn lode lfẹ, / wọ̀n ni bi ikú ti npa wọn nibẹ yi. / Ki wọ̀n rú: / ewọn kan ati agbo kan. / Wọ̀n gbọ̀ wọ̀n rú. / Babaláwo ni: / \"Okanṣoṣo ẹwọn kiikẹ, / bẹẹ ni ọwọ̀ ikú ko ka wọn mọ\". / \" Iṣó: clavo de metal. El significado más ancestral de Iṣó es: uña, pesuña, garra. / Para elaborar la medicina de este Odù valorar el uso de garras, que también / tienen la función mágica de \"fijar\" o \"agarrar\".", "Verso 4.3 (yorùbá): Odidi-afiditi: / li o difá f'Odidimadẹ. / Wọ̀n ni ki ó rú: / agbon olodu móji. / lgbin méjl / ati pgbörindilógün owó / Ô gbọ̀ ó rú. / Babalâwo ni: Ifá wipe: / \"Ọmọ rọ̀ ko nii sọrọ loju rẹ̀.\"", "Verso 4.4 (yorùbá): Emi eni-òdí, / Iwọ èni-òdí, / ẹ̀ni-òdí Méjì: / li o dífá f'Òdi nigba otẹ. / Wọ̀n ni: \"Qwọ̀ Òdí a Kalu\" / Nitorinaa ki ó rú: / Qja Idimo Méjì / Ó gbọ̀ ó rú.", "REZO: ODI MEYI ASHAMA ARUMA KODIMA IKU, KODIMA SHUKURU KURU KIELE BITI BITI KOGOBALE NI ABITI ADIFAFUN AYO OMO OÑI YEGAN AIKORDIE LEBO.", "REZO: ACHAMA AD IMA ICA CODINA A NO CODINA CHACURU CUNU ONI QUERAN LLOMA COMAMA LLORIMA ACHERAN LIME MA MA LOMIMA ABITI BITI COTOBALE BITI ADIFANFUN ALLEOMO ONI LLEGUN.", "REZO: OLERE OR IRE UN ARA ONILESE ACHEO HOLA OTABA OFUALLO ACIFA FA LA OLLE ODIFE TALDO LLEGUA DOGUE LOS ILE AIKORDIE MEYI AKUKO MEYI EKU EYA EPO OMI OWO.", "REZO: AGUDE ADAFA ELEGUINE A COBEHE UN RIRE A CODIE AGUN UN DE EKU EYA OWO ABATEROBI.", "REZO: A CHAMU ADIMA DIMA CODINA CHURUCU CURU QUE ELEN ABATI BITI COTABALE NI BITI ADIFAFUN ALLEOMO ONELLIGUN.", "REZO: OLDERE ARUMA ORUPA ONI ASECO ONIOCHA CHETIN POLAN GUORI PERO ERINLAN CHACANA ARUMA A DIMA DIMA ICU CODINA ARO CODIMA OCHACURA QUELE ONI QUE ERAN COLLIMAN COMAMA LLOMIMA CHEREN ALLIMA MAMALLO MAMALLO OMIMA ABATI ABITI COTO BALE BOTI ADIFAFUN ALLEOMO ONI LLEGAN.", "SUYERE: ODI MODI IYE. ODI MODI IRE. MAMA YE KIO. MAMA YE KIO. OSOBO MONDABALE MONDABALE ASHIRI BABA. MONDABALE MONDABALE ASHIRI BABA.", "REZO: ODIMA ODIMA ODO ODIMA DIMAO OKE ODIMADIMA KUKURA BUELE OKO NAKOIMA KOMAYELIME ORUNELESE EWE GUNGUN ODARA OLOFIN ODI MEYI KATA.", "SUYERE: OYAMESE OSUN AREYERA ERIRONA KONINIRON EUROMA KONINIRON ERIRONA KONINIRON.", "REZO: ODERE ORURE OMO ONI ADADONACE OBUTI PONLA GUERE PERE ORUNMILA ACHAMA ARUMA ODINA DIMA IKU DIMA KODIMA", "ARUN KODIMA SHAKURUWELE ENIKE ERAN KODIMA KOYIMA KOMANA YORIMA SHIRA KEYIMA MAMA YORIMA OMENA ABITI BIRI KOTO KOBALE BOTI ADIFAFUN AYE ANOYEGUN.", "REZO: IFA NIRE TELENEYI IKU OPERE KORU EYELE MEYI EGBAN MELLO EWA ORUN ARAE TODARA OTI BATA ADIFAFUN PAJOGUE GO, GBOGBO EYUTALE WOLO WERE MEYO TOWON KUNRO OBA BEME AJOGUN GB BOGBO SAWE RODE OBINI LODA MEYI EBETA AJOYA DARA FUN SHUGBON KORU AGBA ORUGBO TALOBA KARI SOMA EGBI MEWO WON BAYO OBA YORU NA OYA BEMI BATO ORIN AWO TOBOSI LEMU EMENIKAN AWO EN MI ODAFUN ORUNMILA KAFEREFUN EGGUN.", "SUYERE: AWO ONU MORI OMIE NIKAN NI MORE ARI BORE.", "REZO: KELEY OSHUNNIFORI OMO, KESE NAMBO EGO OJALUONA, INSHE ABIKA, OMO OKAN OKERE, JUN BALE KOKOFA ERUKE MOSARE KOSE FADES, AGADA SOWO AWO ADIFAFUN EYEUMA KENI IYAMA ORUBO OSIN ORUBE TANI ARABA KERESERE OWAIN AWON A MORE OÑI PABABASE KUEYANI NI AWADO AWOME, OJODERUNE OBORO FUN OSINUN EWAYI NI WIN SOMBE BABA OBONI LORDAFUN.", "SUYERE: INSHE AKUO KEKORI TALAUSME LOSENDIE SEYEKE SEYENKE.", "REZO: AGUDE ADEFA EL EKENI AUN KASHE UNISERE EIYE, ABATALOSI UGUI EYU, OMI, ADIFAFUN ORUNMILA, ADIFAFUN ESHU.", "REZO: ADIFAFUN YEMAYA OROKO OMOLI IKI ORO MODO ONILE ERINLO ATI SHAKUANO LOPA ERINLO SEREANARIN LODAFUN ORUNMILA KAFEREFUN OSHUN, YEMAYA, SHANGO."]}]$q$::jsonb),
(5,'38b27b0784c50fdafa8ac93fb3ea3ab6','1e49544ba71aef2d50587b6d6750a874',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Méjì habla de una persona conocida y respetada, a la que saludan en la calle, pero que pasa por dificultades emocionales y de dinero. Las cosas avanzan despacio y piden más trabajo del normal. Ifá le pide cuidar su cabeza (Orí), honrar a sus ancestros, sobre todo al padre, tener paciencia y recordar que ninguna situación es para siempre. Trae la bendición de los hijos.", "pasajes": [{"titulo": "Frase clave", "texto": "Irosun crea satisfacción del potencial.", "origen_id": "85f830ad40ec3bb3658eef62"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que su vida o su negocio está estancado y que avanzar le cuesta el doble.", "Hay un cargo, una herencia o un puesto en juego dentro de la familia, y no todos se prepararon igual para recibirlo (relato de Iná, Eyin e Iko).", "Le recomendaron una ofrenda o una precaución y todavía no la ha hecho (Iko fue el único que cumplió).", "Espera un hijo, o le preocupa el futuro de sus hijos y que tengan con qué salir adelante (verso de Ìrosù).", "Le afectan los chismes o las críticas de otros (relato de Apeni).", "Necesita paciencia: le toca esperar su turno sin desesperarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos: la mujer que desea embarazarse lo logrará con la ofrenda; el niño puede ser babaláwo.", "Muchos hijos y las bendiciones que andaban rondando sin llegar.", "Regresar al lugar de origen y ahí encontrar la riqueza.", "Conservar por largo tiempo un cargo heredado.", "Protección contra lo que habla la gente."]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder el interés por lo que acaba de empezar o por el trabajo de siempre.", "Negarse a la ofrenda y dejar a los hijos una vida difícil.", "Querer dos coronas a la vez: nadie quita una corona sin derramar sangre.", "Enemigos que hablan para dañar."]}, {"titulo": "Enseñanza principal", "texto": "El que sabe esperar su turno conserva lo que recibe. Iko, la rafia, fue el único de tres hermanos que hizo su ofrenda y fue paciente; por eso la lluvia no lo destruyó y gobernó mucho tiempo. Se pide hacer cada año un ritual para toda la familia y mantener el respeto al padre, vivo o muerto."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ìrosùn Méjì habla de personas que son muy populares y andan por las calles entre el saludo de sus amigos, gozando de gran respeto. Ellos necesitan cuidar mucho su salud propiciando sacrificios a su cabeza (Ori) y apaciguando ocasionalmente a Osù (báculo de Ifá).\nCuando ellos sienten que pierden interés por algo recién comenzado o por las labores que normalmente realizan, deben consultar lfá y apaciguarlo para ellos.\nÌrosùn Méjì denota dificultades emocionales y financieras. Pero las cosas no son tan difíciles como parecen, el cliente puede evitar los problemas ofreciendo el sacrificio adecuado y rechazando los espíritus e ideas malignas que le puedan llegar, es importante que la persona evolucione hacia la búsqueda de un pensamiento más positivo.", "origen_id": "304ac6d47136de0e95451741"}, {"titulo": "Características generales", "texto": "Otros nombres: Ìrosùn Méjì; Ejirosùn / İrosüméji / Olosünmeji.\nÌrosùn Méjì es el quinto Odú en el orden inalterable de Ọ̀rúnmìlà.\nEste Odù nos llama a una cuidadosa reflexión sobre nuestro futuro.\nNosotros no debemos de fallar en realizar aquello de \"El hombre propone y Dios dispone\".\nIrosú Méjì llama a realizar anualmente un ritual para toda la familia. EI cliente debe practicar y mantener el honor y el respeto por sus ancestros, particularmente del padre, este vivo o muerto.\nAquellos que nacieron bajo este signo, deben hacer hincapié en el aprendizaje y la paciencia, esperar que los tiempos difíciles se vayan.\nEllos deben recordar que ninguna condición es permanente.\nSí se realiza el sacrificio apropiado una mujer ansiosa de tener un hijo lo logrará en su momento. Ìrosùn Méjì dice que ella saldrá en estado y que parirá un hijo. El niño será Babaláwo.", "origen_id": "b30017d4b0ba0f5740845bc9"}, {"titulo": "Interpretación tradicional", "texto": "Irosun es la palabra Yoruba para la sangre de la menstruación. Es en referencia al linaje ancestral. Ifá enseña que la reencarnación (atunwa) ocurre más frecuentemente adentro de la familia inmediata de un niño. Irosun en su manifestación positiva, representa el uso efectivo de herencia genética y guía familiar (satisfacción del potencial). La manifestación negativa de Irosun es, ya sea resistencia al soporte ancestral, o denigración propia (resistencia a desarrollar el potencial).", "origen_id": "a6ebcdb99a13ca2eefd3e38a"}, {"titulo": "Orientación complementaria", "texto": "Irosun es el potencial latente de nuestro destino más alto dado a nosotros a través de nuestro eslabón de nuestros ancestros. Ifá enseña que nuestro destino más alto existe en forma de espíritu en el reino invisible, y se refiere como el Iponri en referencia al eslabón entre conciencia personal y la conciencia colectiva de nuestros ancestros. La palabra Irosun significa la sangre menstrual y es usada para representar la herencia ancestral, ambas (DNA) físico y sabiduría cultural) espiritual. En su manifestación negativa, Irosun es el fracaso para actualizar las habilidades latentes.", "origen_id": "d027af8548ade339b64346eb"}]}, {"titulo": "Relatos reunidos", "puntos": ["Iná, Eyin e Iko. Oliyẹbẹ consultó para tres hermanos: Iná (el fuego), Eyin (el fruto de la palma) e Iko (la rafia). A cada uno le marcó una estera y una tela amarilla, y solo Iko cumplió. Cuando murió el padre, que era jefe, pusieron a Iná en su lugar; vino la lluvia y lo apagó. Pusieron a Eyin y la lluvia también acabó con él. Al final le tocó a Iko: cuando llovía se cubría con su estera y cuando escampaba se la quitaba, y así sobrevivió y conservó el título de su padre por mucho tiempo.", "Ìrosùn y su hijo. Le dijeron a Ìrosùn, que estaba por dar a luz, que su hijo varón tendría una vida difícil y batallaría para conseguir dinero y mantener a los suyos. Para cambiarlo debía ofrecer dos caracoles babosa. Se negó, y por eso los hijos varones de este signo tienen que trabajar mucho y ofrendar para llegar a la abundancia.", "El gallo y su cresta. Al gallo le pidieron su cresta roja y 2,200 cauríes. Por orgullo no quiso dar la cresta, y el adivino respondió que entonces el propio gallo sería la ofrenda. El gallo aceptó: prefirió morir antes que perder su honor.", "La cabeza y la corona. Adeiṣi consultó para Ataparí, la cabeza, cuando iba a recibir su corona del Òrìṣà, y le advirtió que nadie le quitaría esa corona sin derramar sangre y que es imposible llevar dos coronas al mismo tiempo. Por eso los hijos de Ìrosùn Méjì suelen encontrar tropiezos.", "Òní, el que lloraba por hijos. Èjì Ìrosùn consultó para Òní, del clan de Kólójo, que lloraba porque no tenía hijos. Le prometieron muchos hijos y las demás bendiciones que lo rondaban sin llegar, y le pidieron muchos caracoles babosa. Ofreció, tuvo hijos en cantidad y la gente lo llamaba 'padre de Mòjèşín', el que trajo multitud de jóvenes al mundo.", "Ìgbà regresa a Òyó. Ìgbà fue a trabajar como sacerdote a Òyó y luego se fue a vivir a las granjas, donde probó de todo para hacer fortuna sin que nada le resultara. Corrió con sus babaláwos, que le marcaron quimbombó y berenjena en abundancia. Ofreció, y poco después unos paisanos lo encontraron y le dijeron: 'Todos somos de Òyó; el que se va al campo algún día vuelve a casa'. Regresó a Òyó y ahí empezó a tener riqueza.", "Apeni y la boca de la gente. Ifá consultó para Apeni cuando la boca de las personas lo amenazaba con muerte y destrucción. Hizo su ofrenda y quedó protegido. Cantaba: 'Su boca, su boca no puede matar a Apeni'.", "Okansusu Irosu y los niños. Cuando Okansusu Irosu iba a venir del hogar de los ancestros a la tierra, le dijeron que ofrendara para que, cada vez que moliera ñame o hiciera sopa, viera a un niño comérselo. Cumplió y vio a los niños comer todo lo que cocinaba. Cantaba: 'Padre, no me hagas comer solo'."], "pasajes": [{"titulo": "Verso 5.1", "texto": "Oliyẹbẹ adivinó Ifá para Iná (fuego),\nOliyẹbẹ adivinó para Eyin (fruto de la Palma),\nOliyẹbẹ adivinó para Iko (rafia).\nCada uno de ellos debía sacrificar:\nuna estera (ẹni-ifi) y una ropa amarilla.\nSolo Iko hizo el sacrificio.\nCuando su padre (un jefe) murió,\nIná fue instalada como jefe.\nVino la lluvia y destruyó a Iná.\nEyin fue instalado como jefe.\nVino la lluvia y destruyó a Eyin también.\nIko entonces fue instalado como jefe.\nCuando Ilovió Iko se tapó con su estera,\ncuando ceso la lluvia, Iko se quitó la estera\ny como resultado no murió.", "comentario": "La lluvia no puede destruir a Iko (rafia'®) porque fue el único de los tres hermanos que ofreció la estera como sacrificio. Iko uso la estera como protección contra la lluvia. Iko hizo sacrificio y fue paciente al esperar su turno para gobernar, Iko fue por lo tanto capaz de retener el título de su padre por largo tiempo.\n'\" La rafia es una fibra altamente resistente y flexible que se saca de un género de palmera (Rafia), oriunda de África y América. La rafia se emplea en la confección da estoras, sombreros y artesanias.", "origen_id": "3b82a190338158363e0c69a1"}, {"titulo": "Verso 5.2", "texto": "Qkakaraka-afowótikú,\nIdaṣegberẹgbẹrẹw'akọ:\nadivinaron Ifá para İrosù,\ncuando Irosù iba a dar a luz un niño.\nEllos dijeron:\n\"a vida de su hijo varón podría ser difícil,\npodria tener dificultades para obtener dinero\ny mantener a su hijo\",\nPero si Irosú desea invertir esa situación,\npara que su hijo pueda encontrar riquezas,\ncon las que mantener a su hijo.\nIrosú debería sacrificar\"\ndos caracoles babosa.\nIrosù se negó a sacrificar.", "comentario": "El hijo de Ìrosùn Méjì siempre encontró dificultades en su vida porque Irosù en este verso rehusó hacer el sacrificio requerido para que sus hijos tuvieran una vida más fácil. Los varones hijos de este sacrificios para alcanzar la Odù deben trabajar mucho y hacer abundancia.", "origen_id": "55d426a27a5c67ec9402d4cf"}, {"titulo": "Verso 5.3", "texto": "Iṣẹṣerẹfogbeṣe'yẹ:\nadivino lfa para Akuko (el gallo).\nA él se le pidió que ofrendara:\nsu capucha roja (cresta del gallo)\ny 2200 cowries como sacrificio.\nÉl rehusó sacrificar su cresta roja.\nEl Babaláwo dijo: Ifá dice:\n\"el gallo debe ser sacrificado\"\nEl gallo dijo: \"que así se haga\".", "comentario": "El gallo rehusó a sacrificar su cresta roja por honor y aceptó el sacrificio de morir como una obligación de su vida.", "origen_id": "70c8739f0faac0e109892faa"}, {"titulo": "Verso 5.4", "texto": "Adeiṣi:\nadivinó Ifá para Ataparí (cabeza),\ncuando Ataparí fue a recibir\nun gorro (corona) de Oriṣà.\nEl adivino dijo:\n\"nadie podrá arrancarle su gorro\nsin un derramamiento de sangre\"\ny \"es imposible tener dos coronas puestas\"\nEs por esto que las personas\nnacidas mediante Ìrosùn Méjì\na menudo encuentran dificultades en la vida.", "origen_id": "c2fc85caafb29d11a3e42bf2"}, {"titulo": "Versos complementarios 1", "texto": "Ifá le desea la fortuna de los hijos, y las buenas\nbendiciones nunca le eludirán, para esto deberá\nofrecer muchas Babosas (Caracoles). Mujeres y\nhombres de este odù se convertirán en padres. Ifá\ndice que esta persona es un nativo de Òyó.\n\n           Èjì Ìrosùn ni ò gbààwè\n                 A dífá fún Òní\n          Ợmợ Onísin ikó ti Kólójo\n      Níjó ti ń fomi ojúú şògbérè ợmợ\n         Wón ni yóó bímợ lợpợlợpợ\n             Wón láyéé rè ó dáá\n     Wón ni ire gbogbo ní ó jókòó ti í\n               Şùgbón kó rúbợ\n                  Òní bá rúbợ\n                  Ayé yẹ Òní\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n           Èjì Ìrosùn ni ò gbààwè\n                 A dífá fún Òní\n          Ợmợ Onísin ikó ti Kólójo\n      Níjó ti ń fomi ojúú şògbérè ợmợ\n         Wón ni yóó bímợ lợpợlợpợ\n               Ệbợ ợmợ ní kó şe\n               Ệni ó fi Ìşín rúbợ\n                Ká ti móợ pè é?\n                 Ìyáa mòjèşín\n                 Bàbá mòjèşín\n      Mòjèşín ló kómợ délè yí bèèrè.\n\nÈjì Ìrosùn, no desayunó rápido.\nLanzó adivinación para Òní, el hijo del clan Onísin\nikó de Kólójo, cuando gemía a causa de la falta de\nhijos.\nLe dijeron que tendría muchos hijos, pero debía\nofrecer.\nY así le llegarían los hijos, además de las demás\ncosas que le estaban rondando, sin llegarle.\nÒní ofreció el sacrificio y la vida le fue placentera.\nÉl se regocijó y alabó a sus babaláwos.\nEllos alabaron a Ifá.\nÉl hizo lo que los babaláwos le dijeron que hiciese.\nÈjì Ìrosùn, no desayunó rápido.\nLanzó adivinación para Òní, el hijo del clan Onísin\nikó de Kólójo, cuando gemía a causa de la falta de\nhijos.\nLe dijeron que tendría muchos hijos, pero debía\nofrecer.\nQuien usó Ìşín (manzana Akee) como sacrificio.\n¿Qué llamamos a semejante persona?\nLa madre de Mòjèşín.\nEl padre de Mòjèşín.\nEs Mòjèşín quien trajo los hijos al mundo en\nmultitudes.\n\n           Ìta rúkú lawo Ìta rúkú\n           Ìta rùkù lawo Ìta rùkù\n              Rúkúrùkù tataata\n               A dífá fún Ìgbà\n          Níjó ti ń sawoó ròde Òyó\n         Ló bá şe tán ló bá kó looko\n            Ó wáá şe şee şe lóko\n                  Òkan ò lójú\n              Ó bá súré teteete\n\n              Ó gboko Aláwo lợ\n               Wón ní kó rú Ilá\n                    Ó rú ilá\n        Àwợn ti ón wáá ri Ìgbà lona\n            Àwợn bá ní ó kálợ ilé\n           Òyó nílée gbogboo wa\n               Bééyàn bá looko\n                 Yóó fàbò sílé\n          Ìgbà ba şẹrí wà òde Òyó\n               Ló bá bèrè síí lá\n           N ní wá ń jó ní wá ń yò\n          Ní ń yin àwợn Babaláwo\n          Àwợn Babaláwo ń yin Ifá\n     Ó ní béè làwợn Babaláwo tòún wí\n           Ìta rúkú lawo Ìta rúkú\n           Ìta rùkù lawo Ìta rùkù\n              Rúkúrùkù tataata\n                A dífá fún Ìgbà\n          Níjó ti ń sawoó ròde Òyó\n         Ó şe tán ó kó ìgbà lợ sóko\n       Wón ní kí ìgbà ó móợ bò wálé\n                   Òyó nílé ò\n           Ìgbà, emi lo wà dóko?\n                   Òyó nílé ò\n           Ìgbà, emi lo wà dóko?\n              Ìgbà ká ròyó ilè ò\n           Ìgbà, emi lo wà dóko?\n\nÌta rúkú es el sacerdote de Ìta rúkú.\nÌta rùkù es el sacerdote de Ìta rùkù.\nRúkúrùkù tataata\n\nFueron quienes lanzaron Ifá para Ìgbà, cuando se\naventuraba a ejercer el sacerdocio en la ciudad de\nÒyó.\nÉl decidió después seguir para las granjas del\npueblo y allí asentarse.\nÉl probó toda clase de cosas en la granja para hacer\nriquezas.\nTodas le fueron insolventes.\nÉl pensó en una solución rápidamente y corrió a ver\na sus babaláwos.\nEllos le dijeron que ofrendara con Okra\n(Quimbombó) y con Huevos de jardín (Berenjena)\nen grandes cantidades. Él ofreció.\nPoco después unas personas vieron a Ìgbà, y le\npidieron que regresara con ellos a casa.\nNosotros todos somos naturales de Òyó, y si alguien\nse va a las plantaciones, algún día debe regresar a\nla aldea.\nÌgbà decididamente regresó a su casa en Òyó.\nY comenzó a ver y tener riquezas.\nÉl se regocijó y alabó a sus babaláwos.\nEllos alabaron a Ifá.\nÉl hizo lo que los babaláwos le dijeron que hiciese.\nÌta rúkú es el sacerdote de Ìta rúkú.\nÌta rùkù es el sacerdote de Ìta rùkù.\nRúkúrùkù tataata\nFueron quienes lanzaron Ifá para Ìgbà, cuando se\naventuraba a ejercer el sacerdocio en la ciudad de\nÒyó.\nÉl decidió después seguir para las granjas del\npueblo y allí asentarse.\nEllos le pidieron a Ìgbà que regresara a casa.\nÒyó es tu casa.\n¿Ìgbà, por qué estás localizado en la aldea?\nÒyó es tu casa.\n¿Ìgbà, por qué estás localizado en la aldea?\nÌgbà, vamonos para la casa de Òyó.\n\nÒyó es tu casa.\n¿Ìgbà, por qué estás localizado en la aldea?", "origen_id": "5535f4e87db9bee6b122ef65"}, {"titulo": "Relatos y ofrendas", "texto": "IROSUN MEJI\n\nSu — boca — su - boca consulta Ifá para Apeni en el días que él fue amenazado por la boca de las\npersonas del mundo. Ifá aconsejó a Apeni hacer ebo para evitar la muerte y la destrucción de la\nboca de las personas del mundo. Apeni hizo ebo. Apeni fue protegido de la muerte y destrucción\ncausados por las personas del mundo. Apeni estuvo cantando y bailando y alabando al Awo,\nmientras el Awo alabó a Ifá, mientras Ifá alabó a Olodumare. Cuando Apeni empezó a cantar,\nEsú puso una canción en su boca. Apeni canto:\n\nEnu won, enu won é le pa Ápéni.\n\nEnu won, enu won é le pa Ápéni.\n\nSu boca, su boca no puede matar a Apeni.\n\nSu boca, su boca no puede matar a Apeni.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo para su protección, en contra de los enemigos. Ifá dice\nque los ofrecimientos deben ser hechos a la familia de Egúngún.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 abo adie (gallina), 1 epo (botella de aceite de palma),\nakara (pastel de frijol), mohin — mohin (bolas de almidón) y 16 nira (dinero), ofrecido a Ori y\nEgúngún.\n\n(Ett (oferendas); 4 eiyele (pombo), 4 Abo adie (galinha), 1 epo (garrafa de azeite de\ndendé), akara (bolinho de feijáo), Oólé (bolas de goma de amido) e 16 nira (dinheiro\nnigeriano), oferecidos ao Orí ea Egúngún)\n\nPorogun — de — igbodu — con — una — acción — inferior consulta Ifá para Okansansusu Irosu en el\ndía que Okansusu Irosu hizo el viaje de su hogar de los ancestros al hogar de las personas en la\ntierra. Ifá aconsejó a Okansusu Irosu hacer ebo para que cuando Okansusu Irosu muela ñame, él\nverá a un niño comérselo, cuando Okansusu Irosu prepare sopa, él verá a un niño comérsela.\nOkansusu Irosu hizo ebo y vio a los niños comerse todo lo que él cocinó. Okasusu Irosu empezó\na cantar y a bailar en alabanza del Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a\nOlodumare. Cuando Okansusu Irosu empezó a cantar, Esú puso una canción en su boca.\nOkansusu Irosu canto:\nBaba ma je nkan jé, iyán ti mo gún.\nBaba ma je nkan jé, Obe ti mo se.\nBaba ma je nkan jé.\nPadre no me hagas comer sólo, ñames que\nhe preparado.\nPadre no me hagas comer sólo, sopa que he preparado.\nPadre no me hagas comer solo.\nComentario:\nIfá dice que esta persona ó alguien cercano a él están buscando a los niños. Ifá dice que hacer ebo\ntraerá una bendición de niños.\nEtutu (ofrecimiento): iyan (ñame molido), eba (sopa), cosas dulces, eiyelé (pichón), 1 abo adie\n(gallina), 1 plato blanco, 1 epo (botella de aceite de palma) y 35 nira (dinero), ofrecido a Ori y a\nEgúngún. Eéwo (tabú): víbora, trapos rojos.\n\n88\n\n(Ett (oferendas); ¿yán (inhame pilado), éba (mandioca), coisas doces, 1 eiyele, 1 Abo adie\n(galinha), 1 prato branco, 1 epo (garrafa de azeite de dendé) e 35 nira (dinheiro nigeriano),\noferecidos ao Orí e a Egúngún. Eewó (tabu): cobra, roupa vermelha.)\n\nTr Tr\nTr Tr\nI I\nI I", "origen_id": "a2a34ef0797841cafeff9728"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Iroso Meji habla de aquella gente que son muy populares y\n     andan por las calles entre el saludo de sus amigos. Ellos necesitan tomar\n                               mucho cuidado con su salud y sus propiedades.\n             Ellos necesitan cuidar sus cabezas, apaciguarlo ocasionalmente el\n                                                         osu o el oficio de Ifá.\n             Si ellos sienten que comienzan a perder el interés en las cosas que\n        ellos están haciendo, Ifá debe ser consultado y apaciguado por ellos.\n             Irosu Meji denota dificultades emocionales y financieras. Pero las\n                                      cosas no son tan difíciles como parecen.\n                  El cliente puede evitar los problemas ofreciendo el sacrificio\nadecuado y rechazar de sus predios los espíritus y pensamientos malignos.\n             WO – Las cosas no están floreciendo fácilmente. Se requiere más\n                                    trabajo que el normal para lograr las cosas.\n\nIrosu Meji es el quinto Odu en el orden inalterable de Orunmila. El\n      cual nos llama a reflexionar sobre nuestro futuro. Nosotros no debemos de\n                   faltar a aquellos de que “el hombre propone y Dios dispone”.\n              En este Odu (Irosu Meji), Ifá llama a realizar anualmente un ritual\n          para toda la familia. El cliente debe practicar y mantener el honor y el\n          respeto de sus ancestros particularmente del padre esté vivo o muerto.\n              Aquellos que nacieron bajo este signo, deben hacer hincapié en el\n         aprendizaje y la paciencia y esperar que los tiempos difíciles se vayan.\n                     Ellos deben recordar que ninguna condición es permanente.\n           A su momento, se hará un sacrificio para una mujer que está ansiosa\n       de tener un hijo. Irosu Meji dice que ella saldrá en estado y que parirá un\n                                                      hijo. El niño será Babalawo.\n\n\n5.1 · Oliyebe adivinó Ifá para Ina (fuego), Oliyebe adivinó Ifá para Eyin (fruto\n           de la palma), Oliyebe adivinó Ifá para Iko (raffia). Cada uno de ellos\n         debían sacrificar: 1 estera (eni-ifi) y una ropa amarilla. Sólo Iko hizo el\n        sacrificio. Cuando su padre (un jefe) murió, Ina fue instalada como jefe.\n         Vino la lluvia y destruyó a Ina. Eyin entonces fue instalado como jefe,\n      vino la lluvia y destruyó a Eyin también. Cuando finalmente se instaló Iko\n      como jefe, cuando llovió, Iko se tapó con su estera. Cuando cesó la lluvia,\n                          Iko se quitó la estera y como resultado no murió (☼).\n\n\n5.2 · Okakataka-Afowotiku, Idasegberegberen Ako adivinó para Irosu, cuando\n      Irosu iba a entregar un niño. Ellos dijeron que la vida del niño sería difícil\n\ny podría tener dificultades para hacer dinero para mantener al niño. Pero si\n            Irosu deseaba revertir la situación. Irosu debería sacrificar. dos caracoles\n                                            de babosa. Irosu se negó a sacrificar (☼).\n\n\n5.3 · Iseserefogbere´ye adivinó Ifá para akuko (el gallo), a él se le pidió que\n                    ofrendara su capucha roja. La cresta del gallo y 2200 cowrie como\n               sacrificio. El rehusó sacrificar su cresta. El babalawo dijo que el gallo\n                                  debería ser matado. El gallo dijo: “que así sea“(☼).\n\n\n5.4 · Adeisi adivinó Ifá para Atapari (cabeza). Atapari fue a recibir una capucha\n       (gorro) de Orişa. Ellos dijeron que nadie podría arrebatar de él su capucha\n            sin derramamiento de sangre. Es imposible tener 2 capuchas. Es por esto\n       que las personas nacidas mediante Irosu Meji a menudo podrían encontrar\n                                                                dificultades en la vida.", "origen_id": "1e12d7a5b1201c012211daab"}, {"titulo": "Relato en inglés 1", "texto": "“The deadfall is sprung, it strikes the ground with its chest” was the one who\ncast Ifa for “Title has descendants” when she was weeping because she had not be-\ncome pregnant and when she\n\nwas fasting because she had no child to carry on her back, They said she should\nsacrifice; they said she would give birth to a child who would be known to all the\nworld and that the mention of his name would cause the whole world to tremble.\nShe offered 200 needles, one ewe, five shilling six pence, and a pot of palm oil.\nWhen “Title who has descendants” gave birth, she gave birth to Sun.\n\nIfa says that someone is weeping for a child, and that she will bear a child,\nand this child will be a boy.", "comentario": "1, Again this verse explains why the sun is known all over the world. Cf.\nverses 1-6 and 52-1, and n. 6, verse 52-1,", "origen_id": "1b5a82c2ebcfa5396f5ebf6c"}, {"titulo": "Relato en inglés 2", "texto": "“Igunnukun! looks here, Igunnukun looks there” was the one who cast Ifa for\nOrisha when he was going to marry Sword of Thunder. Ifa says that someone is\nwanting to take a wife. There will be much gossip about the woman and it will be\nsomewhat difficult, but we should go ahead; he says we shall succeed,? Orisha\nsacrificed one he-goat, one shilling seven pence eight oninis, and the black cloth\nhe was wearing, When Orisha had married thisewoman, he was afraid because\nthey said that someone else would take her away from him; so he built his house\nin the back yard, and whenever people passed by, he shrank with fear, lest some-\none should take her from him. Then they began to sing:\n\n“Shimmering® high noon,\n“One who asks for trouble* will find trouble.”", "comentario": "1. A Nupe deity (ẹbura Tapa) which, like the Egungun, is masked. It is de-\nscribed as a tall cylinder that can grow tall and grow short. See Nadel (1954:\n189-190). Its worship was introduced to Ife by a Nupe woman,\n\n2. This interpretation, given by informants, is somewhat different from the\nliteral translation, which is also uncertain, The whole verse, in fact, is obscure\nand apparently not understood by the diviner himself. Sword seems to have been\nthe former wife, or perhaps the daughter, of Thunder, but the relationship is not\nspecified in the text. Orisha here probably refers to Orisha of the Back Yard\n(Origa Agbala), one of the “white deities” (origa funfun), but it is not clear how\nhe happened to be wearing a black cloth. See n. 4, verse 249-1,\n3. “Werewere” was described as referring to the shimmering of heat waves\non a road during the heat of the day.\n4, That is, one who wants to do something that is forbidden,", "origen_id": "10e523d727524355bba48219"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Iko: una estera y una tela amarilla.", "Para los hijos: dos caracoles babosa; para Òní, muchos caracoles.", "Ìgbà: quimbombó y berenjena en abundancia.", "Apeni: cuatro palomas, cuatro gallinas, una botella de aceite de palma, akara, bolas de almidón y dinero, a Orí y a Egúngún.", "Okansusu Irosu: ñame molido, sopa, cosas dulces, una paloma, una gallina, un plato blanco, aceite de palma y dinero, a Orí y a Egúngún.", "Ofrendas ocasionales a Orí y a Osù, el báculo de Ifá; ritual anual para toda la familia.", "Tabú: víbora y trapos rojos."], "pasajes": [{"titulo": "Ofrenda en el verso 5.1", "texto": "Oliyẹbẹ adivinó Ifá para Iná (fuego),\nOliyẹbẹ adivinó para Eyin (fruto de la Palma),\nOliyẹbẹ adivinó para Iko (rafia).\nCada uno de ellos debía sacrificar:\nuna estera (ẹni-ifi) y una ropa amarilla.\nSolo Iko hizo el sacrificio.\nCuando su padre (un jefe) murió,\nIná fue instalada como jefe.\nVino la lluvia y destruyó a Iná.\nEyin fue instalado como jefe.\nVino la lluvia y destruyó a Eyin también.\nIko entonces fue instalado como jefe.\nCuando Ilovió Iko se tapó con su estera,\ncuando ceso la lluvia, Iko se quitó la estera\ny como resultado no murió.", "origen_id": "a2215b5a93444b6602e697d6"}, {"titulo": "Ofrenda en el verso 5.2", "texto": "Qkakaraka-afowótikú,\nIdaṣegberẹgbẹrẹw'akọ:\nadivinaron Ifá para İrosù,\ncuando Irosù iba a dar a luz un niño.\nEllos dijeron:\n\"a vida de su hijo varón podría ser difícil,\npodria tener dificultades para obtener dinero\ny mantener a su hijo\",\nPero si Irosú desea invertir esa situación,\npara que su hijo pueda encontrar riquezas,\ncon las que mantener a su hijo.\nIrosú debería sacrificar\"\ndos caracoles babosa.\nIrosù se negó a sacrificar.", "origen_id": "1360b0fcf36e8d55202bf98b"}, {"titulo": "Ofrenda en el verso 5.3", "texto": "Iṣẹṣerẹfogbeṣe'yẹ:\nadivino lfa para Akuko (el gallo).\nA él se le pidió que ofrendara:\nsu capucha roja (cresta del gallo)\ny 2200 cowries como sacrificio.\nÉl rehusó sacrificar su cresta roja.\nEl Babaláwo dijo: Ifá dice:\n\"el gallo debe ser sacrificado\"\nEl gallo dijo: \"que así se haga\".", "origen_id": "6e01441359ee368443d703f5"}, {"titulo": "Ofrenda complementaria 1", "texto": "iyan (ñame molido), eba (sopa), cosas dulces, eiyelé (pichón), 1 abo adie (gallina), 1 plato blanco, 1 epo (botella de aceite de palma) y 35 nira (dinero)\n\nDestinatario: Ori y Egúngún", "origen_id": "f52e5cbd9d0ff8cad52b33a9"}]}, {"titulo": "Relaciones espirituales", "texto": "Orí y Osù, el báculo de Ifá, piden atención frecuente. Egúngún y los ancestros, en especial el padre, reciben ofrendas y respeto. Èṣù pone en la boca del cliente el canto de agradecimiento.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Egun", "origen_id": "d8c8447f12a90c7e352731d2"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Caracoles babosa, estera, tela amarilla, quimbombó (okra), berenjena, ñame molido, sopa, akara, bolas de almidón, aceite de palma, plato blanco. Iyẹ̀-ìrosùn, el polvo sagrado de Ifá."}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 1", "texto": "víbora; trapos rojos", "origen_id": "3c2fad080cab1de428ac4b47"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 5.1 (yorùbá): Oliyẹbẹ li o dífá fún Iná, / Oliyẹbẹ li o difá fún Ṣyin, / Oliyẹbẹ li o dífá fún Iko. / A niki okookan wọ̀n wa rúbọ: / ẹni (agbafi) ifi ati aṣo ofeefee. / Iko nikan lio gbọ ebọ ti orú. / Nigbati baba wọn kú / (Oloye ni baba wọn) / Wọ̀n fi Iná le'ye / Ojo de o pa a / Wọ̀n fi Eyin le'ye / Ojo de o paa bakanna / Wọ̀n fi Iko le'ye / Nigbati ojo de / Iko fi eni rè bori / Ojo da O ka ẹni rẹ̀ kuro / Iko ko ku.", "Verso 5.2 (yorùbá): Qkakaraka-afowotikú, / Idaṣegbẹrẹgbẹrẹw'akọ: / li o difá fún Irosù, / nigbi Irosu mi la bimo. / Wọ̀n nỉ: / \"ako-omo li o ma bi yi, / nitori ko ni ri owó fi wo qmọ naa\". / \"Sùgbọ̀n bi o ba ni / ki oun (Ìrosù) ri owó, / fi wo ọmọ naa, / ki (Irosù) ó wa rúbo\": / igbin Méjì. / ò kọ, ko rubo.", "Verso 5.3 (yorùbá): Iṣeṣerẹfogbeṣe'yẹ: / li o difá f'Akuko-adiyẹ. / Wọ̀n ni ki o fi fila pupa / tiowa lorí rẹ̀ ṣẹbọ / ati ogbokànlá owó. / Ó kọ ko rú / I oun ko maa fi fila oun ṣẹbo. / Àwon Babaláwo ni: Ifá ni: / \"Pipa ni wọn maa paa\" / Akuko-adiyẹ ni: \"ko burú ṣa\".", "Verso 5.4 (yorùbá): Adeiṣi: / li o dífá f'Ataparí, / Ataparí mi la gba fila lọwọ Oriṣà. / Wọ̀n ni: / \"kosi ẹniti O maa le gbaa lową rẹ / ki ejẹ ko ma yii\" / ati \"pe ko maa ni fila Méjì\". / Nitorinaa Ojú a maa pón / eniti Ìrosùn Méjì ba bi.", "REZO: IROSO MEYI OYOROSO APANTARITA BEBE OYOROKO TO BEBE LOYEKUN. OLOKUN APANTARITA BEBE OYOROSO OYOROSO IROSO OLOKUNO OSHEBOGBO MO IYE TUTU ELEGURE NI MEYI KOKOLO LOSHE YEWI LOWA ORISA SHANGO DUPUE.", "REZO: ADIFAFUN OYU APON MASHASHA ADIFAFUN ARA ADIFAFUN EKO ADIFAFUN OLARA OKO IROSO MEYI KAFEREFUN OLOKUN KAFEREFUN OLOFIN.", "REZO: IROSO MEYI OYOROSO APANTARITA BEBE OYOROKO TO BEBE LOYEKUN. OLOKUN APANTARITA BEBE OYOROSO OYOROSO IROSO OLOKUNO OSHEBOGBO MO IYE TUTU ELEGURE NI MEYI KOKOLO LOSHE YEWI LOWA ORISA SHANGO DUPUE.", "REZO: APANTERILA TERI OBEBE QUINQUIN BABA AWO LASHE INA UNFO CUSIMORO OROMI CUSIMARA A BABA KORINI ANYO LODO ADIFAFUN INA ANYO LODO ADIFAFUN OLOKUN UNROKO TOALE AWO DIDA AWO DIDE KAFEREFUN YEGUA.", "REZO: APANDE AWO ASHA LUO DIDE APOSHE APAN MESARE ESPALO LA ADEA ADAPA ALEKODERE TIMPO OLORUN TALLE TALE TALO BOKAN LEBO IBAKO EYELE MEYI ONI LENO AWO APAN TARI TARIBU LEBEKUN GAN AGUA ANA AGUA LASHE INA UNFOKOMONO ARODIPADO KURI NADA BABA KORI INI UNYAR LOKO INA UNIYAN LODO ODAFUN ELERETONUN ROKO TALE AWO NINDAGUN NIDE KAFEREFUN YEGUA OLOKUN.", "REZO: IBORI SI TOSI ATAMATESI OSINI LASHA EUKU OFORISOLO OUNTO DEFISILE OUNTOYO IFA BEDE MAYI BAMEDE ATA EÑI ABA ABA TUTU LANU ASHEBA ADA OMA OLUN YO YOLO UN BELEWO OTUN IDELFUN BELEWO OSI.", "REZO: IROSO MEYI AKAUANTALOSHA ONDI ABBO QUE NIBE QUE UN GUALLO BAUN LAOSHE OSHE AGUANTALOSHE INLE AFOSHE AKUN AUN ASI KURUKA EPEA ARAÑA.", "REZO: AKUONDE AWO NIDEREA APOSHE AKUAN MESURE KAPOLE LENU ADAD AREKADERE TIMPO CLODAR TELE BA OU LEBO IKOKO EYELE ARO AUN SUN EYA ELENO AWO.", "REZO IYESA: IBORI SI TOSI ATAMATESI OSINI LASHA EUKU OFORISOLO OUNTODEFISILE OUNTOYO IF BEDE MAYI BAMEDE ATA EÑI ABA ASA TUTU LANU ASHEBA ADA OMA OLUN YO YOLO UN BELEWO OTUN IDELFUN BELEWO OSI. REZO: AWO KODERE ADAFUN OLODIRE PIOLORO TALE TELE ENU MUSURU KAFIKAFI KAPELENU. ADA ORO DOLE ALBOKO TALE TALE OBON AIKU OBON OTALA ALA DEBE MOFIERE OWO.", "REZO: ADIFAFUN OYU APON MASHASHA ADIFAFUN ARA ADIFAFUN EKO ADIFAFUN OLARA OKO IROSO MEYI KAFEREFUN OLOKUN KAFEREFUN OLOFIN.", "REZO: ADIFAFUN ORUNMILA, OKUNI ALAGBARA, LODAFUN GBOGBO ORISHA.", "REZO: ADIFAFUN SHANGO, OBAROSUN NILE AWO ODARA, LODAFUN OSHIN.", "REZO: ADIFAFUN OBATALA OBANILE MOWAYEN BELEGUN INLE OKEYABI OMO UNSORO ARAYE OBA ARUGBO SHONSHO UMBOWA ONIKA INLE SOKUN SOKUN LAYE BOGBO ARAYE AWOGBO ORUNMILA UMBOWA INLE OKEYABIANO UNSODE ADAFUN EBOTALONI EBOLASUDAYE TANIJUELEGO LOWA UMBOWA ONIKA KUMAROBO JORO JORO ENI AKASHO BELEGUN OBATALA BABA ABELELE UMBOWANI EBOADA OKEYABIANI INLE TALAKO MOFORIBALE OBATALA AMONA ORE ILUO FUN FUN LODAFUN ORUNLA, LODAFUN OBA ARUGBO.", "REZO: APUAN ALUOSHA ASHAWO APUANI ADIFA IRE SUN ILE OLOFIN."], "pasajes": [{"titulo": "Canto complementario 5", "texto_ritual": "Baba ma je nkan jé, iyán ti mo gún.\nBaba ma je nkan jé, Obé ti mo se.\nBaba ma je nkan jé.", "traduccion": "Padre, no me hagas comer solo el ñame que he preparado.\nPadre, no me hagas comer solo la sopa que he preparado.\nPadre, no me hagas comer solo.", "origen_id": "68f8bc29cabd2c82bde26d1e"}]}]$q$::jsonb),
(6,'bf45ca4a18f3d46fd660d5d110e1f6a8','1b7cfd5ccde70b38baf005f1317e5cd9',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Méjì pide moderación en todo y pensar con claridad para tener éxito. A quien está hundido en la pobreza le anuncia dos bendiciones juntas, dinero y pareja, si hace la ofrenda correcta. La ofrenda no es solo para alimentar a los Òrìṣà y a los ancestros: también debe dar de comer a mucha gente. Favorece la agricultura y el comercio.", "pasajes": [{"titulo": "Frase clave", "texto": "Owonrin crea cambios inesperados.", "origen_id": "d861e3444020518fe09ab6a9"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está por tomar una decisión con prisa y debe pensarla bien antes de actuar.", "Vende y se esfuerza, pero no gana (relato de Sièjidé en el mercado).", "Le falta dinero y también pareja, y espera que ambas cosas mejoren.", "Un trabajo ligado a la tierra o al campo puede darle prosperidad (relato de Okewu).", "Va a viajar o teme un lugar hostil, y puede regresar bien si se prepara (relato del gato Ologbo).", "Le ofrecen un cargo o una responsabilidad y debe recordar ayudar a los suyos (relato de Owon).", "Desea tener hijos (relato de Opẹkẹtẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero y pareja al mismo tiempo para quien está en la pobreza.", "Buenas cosechas que mejoran las finanzas.", "Ganancias en el comercio y vencer a los enemigos.", "Viaje seguro y regreso a salvo.", "Muchos hijos.", "Un título o un cargo de responsabilidad en la familia."]}, {"titulo": "Ibi y advertencias", "puntos": ["Comerciar mucho y no ganar.", "Ataques de brujería durante un viaje.", "Enemigos alrededor que quieren frenar su crecimiento."]}, {"titulo": "Enseñanza principal", "texto": "Para tener éxito hay que atender a Orí de vez en cuando, escuchar a los padres, respetar a los mayores y honrar a los ancestros (egúngún). La ofrenda se acepta cuando alimenta también a la gente."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Este Odù llama a tener moderación en todas las cosas. Ọ̀wọ́nrín Méjì predice dos grandes bendiciones para alguien que este hundido en la pobreza, siempre que haga el sacrificio correcto, será bendecido con dinero y esposa (o esposo) al mismo tiempo. Ifá insiste en la importancia del sacrificio. Cuando el sacrificio sea ofrendado no debe pensar solo en alimentar a los Oriṣàs y/o los ancestros, sino que debe usarse también para alimentar la boca de muchas personas. Esta es la manera de hacer que los sacrificios sean aceptables.", "origen_id": "c784b08af75dea3219a3bd7a"}, {"titulo": "Características generales", "texto": "Otros nombres: Ọ̀wọ́nrín Méjì; Èjiğwọ̀nrin / Ohenren Méjì / Èjiohenren / Èjiòwọ̀n.\nEn el orden inalterable de Ọ̀rúnmìlà, Ọ̀wọ́nrín Méjì es el 6to Odù.\nLa agricultura es una oportunidad beneficiosa para los hijos de Ọ̀wọ́nrín Méjì, conseguirán cosechas exitosas que aumentaran sus finanzas. Para alcanzar el éxito en sus vidas deben aprender a propiciar sus cabezas (Ori) de vez en cuando, escuchar los consejos de sus padres, respetar a sus mayores y reverenciar a sus ancestros (egúngún).\nSi una persona planea viajar bajo este Odù, Ifá dice que debe sacrificar para lograr un viaje seguro, exitoso y agradable. Para tener larga vida es necesario hacer sacrificios a Ifá y aplacar el Elédá (creador).", "origen_id": "3c55cd3f5a476663b3c68ddf"}, {"titulo": "Interpretación tradicional", "texto": "Owonrin es una referencia al principio del caos en el universo. La física enseña que todos los eventos que se ven ordenados, aparecen altamente caóticos cuando se ven de cerca. La física también enseña que efectos al azar muestran signos de orden cuando se ven desde una distancia. El aspecto negativo de Owonrin es la perturbación inesperada, destruyendo una fundación débil. El aspecto positivo de Owonrin es la habilidad de enfrentarse al cambio y ver cosas desde una nueva perspectiva.", "origen_id": "9f47ef0dc4f875794134cbc2"}, {"titulo": "Orientación complementaria", "texto": "Owonrin es la fuerza del caos en el universo.  El caos puede ser protegido a través de un entendimiento más profundo de los ciclos y patrones cósmicos. El cambio puede ser la fundación para ya sea, la buena fortuna o la tragedia dependiendo de la voluntad de la persona sujeta a ello. La existencia del caos crea diversidad en el universo. El caos en su manifestación negativa es perturbador sin la transformación y el crecimiento. El caos puede ser, ya sea para liberar o solidificar la percepción misma de una persona.", "origen_id": "ea4a253b16f7831bf7c8b4b4"}]}, {"titulo": "Relatos reunidos", "puntos": ["El gato en la ciudad de las brujas. Ifá consultó para Ologbo Ojigolo, el gato, cuando iba a trabajar como adivino a la ciudad de las àjẹ́, las brujas. Le dijeron que volvería a salvo si ofrecía una carnera, dos palomas y medicina de Ifá. Cumplió y le aplicaron la medicina.", "Los 165 animales y la tela negra. A 165 animales que salían de viaje les pidieron una tela negra. Ninguno la ofreció, solo el gato. Al llegar se toparon con las brujas, que se comieron a todos los que no habían ofrendado. El gato iba cubierto con la tela negra y tenía cuatro ojos como ellas, así que lo tomaron por uno de los suyos y lo dejaron. Fue el único que regresó a casa, sano y fortalecido.", "Ọpẹkẹtẹ y sus hijos. Ọpẹkẹtẹ fue a consultar porque no tenía hijos. Le pidieron doscientos alfileres, doscientas agujas, doscientas ratas y doscientos pescados. Ofreció y tuvo muchos hijos.", "Sièjidé, la princesa comerciante. Sièjidé, hija del rey de Òyó, vivía del comercio; vendía y vendía y no le quedaban ganancias. Juntó sus pocos cauríes y fue con Ọ̀rúnmìlà, que le pidió ofrendar. Lo hizo y empezó a ganar. 'Apóyate en mí para que yo me apoye en ti, como la ortiga se apoya en la hierba': así llegó la gente a comprarle a la hija del rey.", "Ìrókò Ògò rodeado de enemigos. Ìrókò Ògò preguntó si podría vencer a los enemigos que lo rodeaban donde vivía. Ofreció, creció por encima de todo el monte y los arbustos del bosque, y dominó a todos sus enemigos.", "Ọ̀wọ̀n y el poder del mar. Ifá consultó para Ọ̀wọ̀n, el follaje, que quería obtener el poder de un jefe del mar, y le pidió ofrendar para recibir fama. Ofreció, se hizo jefe y cantaba: 'Ọ̀wọ̀n baila, Ọ̀wọ̀n canta; ha traído el poder del jefe del mar'."], "pasajes": [{"titulo": "Verso 6.1", "texto": "Igi-ńlá ni ngba agogo-idẹ l'enú,\nAgbigbo-ńlá ni nfo ragajigi l'egan,\nOpẹ-ihaha ko'ran iwosi,\nI k'ẹnikẹni ma sợ'gba kẹrẹkẹrẹkẹrẹ lori oun:\nadivinaron Ifá para Ologbo Ojigolo (el gato),\ncuando iba en viaje de adivinación\na la ciudad de las hechiceras (àjé).\nLos adivinos dijeron:\n\"él retornará a salvo si sacrifica\":\nuna carnera, dos palomas y medicina de Ifá.\nÉl escuchó el consejo y sacrificó\nLa medicina de Ifá fue aplicada\ndespués de haber hecho el sacrificio.", "origen_id": "0aa1e73f0d30bcff779cced8"}, {"titulo": "Verso 6.2", "texto": "Gogromaafiyun, Gooromaafibą\nadivinaron Ifá para 165 animales,\ncuando ellos fueron a un viaje.\nA ellos se les pidió que sacrificaran:\nuna ropa negra (tela negra).\nEllos no sacrificaron.\nOlogbo (el gato) fue el único que ejecutó el sacrificio.\nAl llegar a su destino, se encontraron con las hechiceras (àjé)\nquienes devoraron a todos los animales\nque habían rehusado sacrificar la ropa negra.\nEl gato fue visto a distancia cubriéndose con la ropa negra.\nEl tenía 4 ojos como las hechiceras,\nquienes decidieron no matarlo porque él era uno de ellas.\nEl gato regresó a la casa cantando:\nGọoromaafiyun,\nGooromaafibo...", "comentario": "De los 165 animales que fueron al viaje, el gato fue el único que regresó a casa sano y fortalecido, porque él efectuó todos los sacrificios prescritos por Ifá.\n* werejéje: (Wérénjéjé) ABRUS PRECATORIUS L., Leguminosae Papilionoideae.", "origen_id": "dc692d4e9179a558c9205d3a"}, {"titulo": "Verso 6.3", "texto": "Oloirekoire,\nOloorunkoorun:\nadivinaron Ifá para Opẹkẹtẹ.\nCuando ella iba a la sala de parto\nElla fue aconsejada para que sacrificara:\ndoscientas Ikoti, doscientas agujas,\ndoscientas ratas y doscientas peces.\nỌpẹkẹtẹ obedeció y ejecutó el sacrificio.\nElla fue productiva como lo predijo Ifá.", "comentario": "Opẹkẹtẹ fue a consultar Ifá debido en la falta de hijos. A ella se le dijo que ejecutara un sacrificio. Ella ofrendó el sacrificio y tuvo muchos hijos como fue predicho por Ifá.\n''Igba Ikoti: doscientos alfileres.", "origen_id": "5e4518bf3956efcfe371d0c3"}, {"titulo": "Versos complementarios 1", "texto": "Él está comerciando y se queja de no hacer ganancias. Debe\nofrecer sacrificio y sus caminos estarán abiertos. Él eclipsará a\nsus enemigos.\n\n                          Síbà lé mi\n                        Kí n síbà lé ợ\n                  Bí Yèrèpé ti síbà lÉèşún\n                    Ká jợ síbà léraa wa\n                     A dífá fún Sièjidé\n             Sièjidé ti ó móợ sòwò Ợjà ń níná\n               Ợmợ Ợba ni Sièjidé lóde Òyó\n                        Ợjà ní móợ ná\n                       Ó wáá tajà tajà\n                         Ợjàa rè ò tà\n                   Ó bá mú eéji kún ẹéta\n                   Ló bá tợ Òrúnmìlà lợ\n        Ó ké si àwợn “Òwón Owó làá náwó mini”\n               Àwợn “Òwón omi làá pèsun”\n            Àwợn “N tó bá wón làá pè níyàn”\n       Ó ní kí àwợn métèèta ó yẹ òun lóókan ibò wò\n                     Wón níwợ Sièjidé\n        “Ó sòwò sòwò ợjàà rẹ ò tà lo dá Ifá yìí sí”\n                         Ệbợ ní kó rú\n                    Ợjàà ré ó sí móợ tà\n                       Sièjidé bá rúbợ\n                Ó rúbợ tán ó bá bèrè síí lá\n                   N ní wá ń jó n ní ń yò\n                 Ní ń yin àwợn Babaláwo\n                 Àwợn Babaláwo ń yin Ifá\n             Ó ní béè làwợn Babaláwo tòún wí\n                          Síbà lé mi\n                        Kí n síbà lé ợ\n\n                  Bí Yèrèpé ti síbà lÉèşún\n                    Ká jợ síbà léraa wa\n                     A dífá fún Sièjidé\n             Sièjidé ti ó móợ sòwò Ợjà ń níná\n                Èyí tíí sợmợ ợba lóde Òyó\n                     Ệbợ ń wón ní ó şe\n                  Ệ yáa wá rajà ợmợ ợba\n        Ệ pò sinsin wáá ẹ wáá rajà ohùn yìí ó wón!\n                  Ệ yáa wá rajà ợmợ ợba.\nApóyese en mí.\nPara que yo me pueda apoyarme en ti.\nAsí como las ortigas se apoyan en las salvajes hiervas.\nNosotros nos apoyamos unos a los otros.\nLanzaron adivinación para Sièjidé, que tomaría el comercio\ncomo su medio de sustentación.\nSièjidé era la hija del rey de Òyó.\nElla se había especializado en marketing, y aunque negociaba y\nnegociaba, no obtenía buenos dividendos.\nElla adicionó dos cowríes a tres y vino a ver a Òrúnmìlà.\nElla llamó a los sacerdotes:\n“Òwón Owó làá náwó mini”\n“Òwón omi làá pèsun”\n“N tó bá wón làá pè níyàn”\nQuienes lanzaron Ifá usando ibò para ella.\nLe dijeron que debía ofrendar para obtener buenas ganancias.\nElla sacrificó y empezó a ver buenas ganancias en su comercio.\nEntonces ella se regocijó y alabó a sus babaláwos.\nEllos se regocijaron y alabaron a Ifá.\nApóyese en mí.\nPara que yo me pueda apoyarme en ti.\nAsí como las ortigas se apoyan en las salvajes hiervas.\nNosotros nos apoyamos unos a los otros.\nLanzaron adivinación para Sièjidé, que tomaría el comercio\ncomo su medio de sustentación.\nY aquella que era también princesa del reino de Òyó, sacrificó\nen la forma en que ellos habían prescrito.\n\nPor consiguiente venga y compre de los artículos del niño del\nrey.\nUsted junte a toda la muchedumbre para comprar los escasos\nartículos.\nVenga y compre de los artículos del niño del rey.\n\n                   Akarasangba Òşùmàrè\n                Òşùmàrè náà Akarasangba\n                    A dífá fún Ìrókò Ògò\n               Níjó ti ń bẹ láàrin Òtá sáńgílítí\n                   Ààrin Òtá ti òún wà yí?\n                      Òun le şégun báyìí\n                        Wón ni kó rúbợ\n                          Ó bá rúbợ\n               Ló bá ga ju gbogbo pàňti igbó\n             Ló bá tẹ gbogbo àwợn òtá è mólè\n                    N ní wá ń jó n ní ń yò\n                  Ní ń yin àwợn Babaláwo\n                  Àwợn Babaláwo ń yin Ifá\n             Ó ní béè làwợn Babaláwo tòún wí\n                   Akarasangba Òşùmàrè\n                Òşùmàrè náà Akarasangba\n                    A dífá fún Ìrókò Ògò\n               Níjó ti ń bẹ láàrin Òtá sáńgílítí\n                      Ệbợ n wón ni ó şe\n                       Ó wáá gbébợ ńbè\n                            Ó rúbợ\n             Ìrókò Ògò nikàn ló yợrí jú wón lợ\n                          Ìrókò Ògò.\n\nAkarasangba Òşùmàrè\nÒşùmàrè náà Akarasangba\nLanzó adivinación para Ìrókò Ògò, cuando se encontraba\nrodeado de enemigos potenciales.\n\n¿Podré vencer a estos enemigos que están dónde yo moro? Él se\npreguntó. Ellos le dijeron que debía sacrificar. Así lo hizo.\nÉl creció por encima de todos los céspedes y arbustos del\nbosque.\nY controló a todos sus enemigos totalmente.\nEl bailó y alabó a sus babaláwos.\nEllos alabaron a Ifá.\nAkarasangba Òşùmàrè\nÒşùmàrè náà Akarasangba\nLanzó adivinación para Ìrókò Ògò, cuando se encontraba\nrodeado de enemigos potenciales.\nEl sacrificio fue la solución prescrita para él; cosa que escuchó\ny realizó.\nÌrókò Ògò, los ha eclipsado a todos.\nÌrókò Ògò.", "origen_id": "be9dab7cc2e45e5485eaf78a"}, {"titulo": "Relatos y ofrendas", "texto": "OHENREN MÉJÌ (OWÓNRÍN MÉJÌ)\n\nLadrón, - pero — no — un — ladrón — que — hizo — al — adivinador — tomar — nuestras — cosas — en —\nnuestra — presencia consulta Ifá para Owon follaje en el día que él quería traer el poder de un jefe\ndel mar. Ifá aconsejó a Owon follaje hacer ebo para que él recibiera una bendición de fama.\nOwon follaje hizo ebo y se hizo jefe Owon follaje empezó a cantar y bailar en alabanza del Awo,\nmientras el Awo alabó a Ifá, mientras que Ifá alabó a Olodumare. Cuando Owon follaje empezó a\ncantar, Esú puso una canción en su boca. Owon follaje canto:\nOwon mi jó, Owon mi jó.\nOwon ti mú, ota oye b'odo.\nOwon mi jó, Owon mi jó.\nOwon día baila, Owon día canta.\nOwon ha tarido el poder del jefe del mar.\nOwon día baila, Owon día canta.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo para que él pueda recibir un titulo ó posición importante.\nIfá dice que esta persona tiene la cabeza de un líder. Ifá dice que esta persona debe asumir una\nposición de responsabilidad dentro de su familia. Ifá dice que esta persona puede ayudar a su\nfamilia a resolver un problema.\n\nEtutu (ofrecimiento): 6 eiyelé (pichón), e abo adie (gallina), 6 eku (rata pequeña), 6 eja aro\n(bagre negro), 1 plato blanco y 25 nira (dienro), ofrecido a Obàtálá y a Esú.\n\n(Etútú (oferendas); 6 eiyele (pombo), 6 Abo adie (galinha), 6 Eku (rato pequeno), 6 Eja aro\n(bagre), 1 prato branco e 25 nira (dinheiro nigeriano), oferecidos a Óbatálá e a Ésù. )\n\nEs — un — árbol — grade — que — toma — una — campana — de — latón — de — la — boca — de — la —\npalma — pequeña, - dejando — a tras — el — insulto, - diciendo — que — nadie — debe — empujar — la\n— calabaza — gradualmente — al — lado — de — ellos consulta Ifá para Ologbo Jigolo (gato\nperezoso) en el día que Ologbo Jigolo se encontró en ataque por esos que avientan embrujos. Ifá\naconsejó a Ologbo Jigolo hacer ebo. Ologbo Jigolo hizo ebo. Desde ese día Ologbo Jigolo viajó\nsin que fuera lastimado. Ologbo Jigolo empezó a bailar y a cantar en alabanza del Awo, mientras\nel Awo alabó a Ifá, mientras Ifá alabó a Olodumare. Cuando Ologbo Jigolo empezó a cantar, Esú\npuso una canción en su boca. Ologbo Jigolo canto:\nOlógbo dúdú ese, gòòlò ma se lo, gòòlò ma se bo.\nGato nebro, perezosamente me iré, perezosamente volveré.\n\nComentario:\nIfá dice que si esta persona está planeando tomar un viaje debe hacer ebo en orden para evitar ser\n\ndañado por embrujos. Ifá dice que después de que el ebo sea hecho, esta persona debe usar Eyonu\nhierbas para atraer las cosas buenas mientras esté de viaje.\n\n89\n\nEtutu (ofrecimiento): 10 okete (rata grande), lepo (botella de aceite de palma), 1 plato blanco y\n50 nira (dinero), ofrecido a Obátálaá y a Esú.\n\n(Ett (oferendas); 10 Okete (rato grande), 1 epo (garrafa de azeite de dendé), 1 prato\nbranco e 50 nira (dinheiro nigeriano), oferecidos Óbatálá e a Esù.)\n\nI I\nTI TI\nTI TI\nTI TI", "origen_id": "1d9182f310d5179366cd8f58"}, {"titulo": "Versión complementaria de los relatos", "texto": "En el orden ajustado de Orunmila Ojuani Meji es el sexto Odu. Este\n                                    Odu llama para la moderación en todas las cosas.\n                        Ojuani Meji predice grandes bendiciones para alguien que esté\n\nafligido por la pobreza, mientras él o ella ofrezcan el sacrificio correcto.\n      La persona será bendecida con dinero y una esposa al mismo tiempo.\n          Ifá en Ojuani Meji hace hincapié en la importancia del sacrificio.\n  Cuando el sacrificio es ofrendado no debe pensarse sólo para los Orişas o\n      los ancestros, si no que debe usarse para alimentar la boca de muchas\n                 personas. Esta es la manera de hacer sacrificios aceptables.\n                WO – se requiere de un pensamiento claro para tener éxito.\n       La agricultura se presenta como la oportunidad más provechosa para\n    los hijos de Ojuani Meji. Cosechas exitosas le ayudarán a aumentar sus\n                                                                     finanzas.\n      Para lograr éxito en la vida los hijos de Ojuani Meji deben aprender a\n     propiciar sus cabezas (ori) de vez en cuando, escuchando a sus padres,\n      respetando a sus mayores y reverenciando a sus ancestros (egungun).\n             Si una persona planea viajar, Ifá dice que el sacrificio debe ser\n                       ejecutado para asegurar un viaje seguro y agradable.\n           Para una larga vida es necesario hacer sacrificios a Ifá y también\n                                                   aplacar el Eleda (creador).\n\n\n6.1 · Igi–nla ni ngba agogo–ide l´enu – Agbigbo-nla ni nfo ragajigi l´egan -\nOpe–Ihaha ko’ran, Iwosi – I k’énikeni ma so’gba kerekerekere lori oun. La\n  adivinación de Ifá fue ejecutada por Olegbo Oyihulo (el gato) quien fue a\n                                     visitar la ciudad de las hechiceras (aje).\n           A él le fue dicho que retornaría a salvo si él podría sacrificar una\n       oveja, dos palomas y hojas de Ifá (Afila algunos cobres e indique las\n\nlimallas con semillas de werejeje y frótelos sobre una incisión hecha\n                                                                   bajo las cejas).\n                                 Él hizo caso del consejo y ejecutó el sacrificio.\n               La medicina de Ifá fue aplicada como se indica arriba, después de\n                                                         haber hecho el sacrificio.\n\n\n6.2 · Gooromafiyun, Booromaafibo. Adivinó Ifá para 165 animales cuando ellos\n           fueron a un viaje. A ellos se les pidió que sacrificaran una ropa negra.\n           Ologbo (el gato) fue el único que ejecutó el sacrificio para llegar a su\n          destino. Al llegar, ellos se encontraron con las hechiceras (aje) quienes\n      devoraron todos los animales que habían rehusado sacrificar la ropa negra.\n                El gato fue visto a la distancia cubriéndose con la ropa negra. Él\n                  tenía 4 ojos como las hechiceras quienes decidieron no matarlo\n                    porque él era uno de ellas. El gato volvío a la casa cantando:\n                                            Gooromaafiyum, Gooromaafibo (☼).\n\n\n6.3 · Oloirekoire, Oloorunkoorun adivinó Ifá para Opakete. Cuando ella iba a la\n       sala de alumbramiento, ella fue aconsejada para que sacrificara 200 ikoti,\n                200 agujas, 200 ratas y 200 peces. Opakete obedeció y ejecutó el\n                          sacrificio. Ella fue productiva como lo predijo Ifá (☼).", "origen_id": "a1e7cd3a90847eade032b434"}, {"titulo": "Relato en inglés 1", "texto": "“Wealth stretches out its hand,” the diviner at Ido;! “Wealth stretches out its\nfoot,” the diviner at Qtun;? “Oto” and “Qya,” the diviners at Koro; “The leaf called\n‘Honor swaying’”;* “The evil that exists on the diviner’s head today will go away\nto the bottom of the water” were the ones who cast Ifa for Qrunmila when he was\ngoing to divine at Ọyọ. They said he should sacrifice two cocks, one pigeon, three\nkola nuts, and red palm oil so that his journey would be good. Qrunmila sacri-\nficed,? and he carried the sacrifice to the bank of a river.®\n\nIfa says that we should sacrifice because of a journey we are going to take,\nso that we may bring home the fruits of our labor.", "comentario": "1, A town about twenty-five miles southeast of Ila.\n\n2. A town about fifteen miles east of Ila.\n\n3. There are several towns by the name of Koro, but this was identified by\ninformants as one about four miles from Ime¢si, which is twenty miles northeast\nof Ilesha.\n\n4. Swaying like a supple plant upon which a bird has alighted.\n\n5. Since Qrunmila is noted for his success in divining, it is not necessary\nto state that the sacrifice accomplished its purpose.\n\n6. There seems to be some correlation between the names of the diviners\nand the instructions to the client. The last name describes evil leaving the head\nof the diviner and going to the bottom of the water, and Qrunmila carries his\nsacrifice to the edge of the river.", "origen_id": "dd4f4970bfe3be2065216a27"}, {"titulo": "Relato en inglés 2", "texto": "\"He arrives for his family to indulge,\" the diviner of \"He awakes to indulge\nhis family,\" \"He is cool when he arrives,” the diviner of “He awakes to give good\nadvice\" were the ones who cast Ifa for Qrunmila on the day he was going to \"He\nawakes to indulge his family” to divine. They told Qrunmila to sacrifice a she-\ngoat to his ancestral guardian soul so that his journey would be good. Qrunmila\ndid not sacrifice to his guardian soul until he had made the journey. When he ar-\nrived at the place where he was going\n\nto divine, no one came to him to divine; and when he saw that he would die of\nhunger, he returned to his house to make the sacrifice to his ancestral guardian\nsoul. When he killed the she~goat, he divided it with the elders of the town, and\nin return they each gave him six pence. Qrunmila became a rich man that day\nand he began to sing:\n\n“Where is money to be found, oh?\n“Money is to be found among one’s own followers,} oh;\n“Money is to be found among one’s own followers, oh.”\n\nIfa says that the person for whom this figure was cast will see someone who\nwill aid him in anything he turns his hand to, even if he has no money at hand.", "comentario": "1. “Ara” refers to both a person's friends and relatives; the latter are general-\nly distinguished as ara ile.", "origen_id": "048f258dc9cfccc90b67a195"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El gato: una carnera, dos palomas y medicina de Ifá.", "Para el viaje: una tela negra.", "Ọpẹkẹtẹ: doscientos alfileres, doscientas agujas, doscientas ratas y doscientos pescados.", "Para un cargo: seis palomas, seis gallinas, seis ratas, seis bagres, un plato blanco y dinero, a Ọbàtálá y a Èṣù.", "Para viajar protegido: diez ratas grandes, una botella de aceite de palma, un plato blanco y dinero, a Ọbàtálá y a Èṣù; luego hierbas para atraer lo bueno durante el viaje.", "Sacrificios a Ifá y al Elédá (el creador) para una vida larga."], "pasajes": [{"titulo": "Ofrenda en el verso 6.1", "texto": "Igi-ńlá ni ngba agogo-idẹ l'enú,\nAgbigbo-ńlá ni nfo ragajigi l'egan,\nOpẹ-ihaha ko'ran iwosi,\nI k'ẹnikẹni ma sợ'gba kẹrẹkẹrẹkẹrẹ lori oun:\nadivinaron Ifá para Ologbo Ojigolo (el gato),\ncuando iba en viaje de adivinación\na la ciudad de las hechiceras (àjé).\nLos adivinos dijeron:\n\"él retornará a salvo si sacrifica\":\nuna carnera, dos palomas y medicina de Ifá.\nÉl escuchó el consejo y sacrificó\nLa medicina de Ifá fue aplicada\ndespués de haber hecho el sacrificio.", "origen_id": "59b4fec75ee3a9fcaec7db0b"}, {"titulo": "Ofrenda en el verso 6.2", "texto": "Gogromaafiyun, Gooromaafibą\nadivinaron Ifá para 165 animales,\ncuando ellos fueron a un viaje.\nA ellos se les pidió que sacrificaran:\nuna ropa negra (tela negra).\nEllos no sacrificaron.\nOlogbo (el gato) fue el único que ejecutó el sacrificio.\nAl llegar a su destino, se encontraron con las hechiceras (àjé)\nquienes devoraron a todos los animales\nque habían rehusado sacrificar la ropa negra.\nEl gato fue visto a distancia cubriéndose con la ropa negra.\nEl tenía 4 ojos como las hechiceras,\nquienes decidieron no matarlo porque él era uno de ellas.\nEl gato regresó a la casa cantando:\nGọoromaafiyun,\nGooromaafibo...", "origen_id": "f59edf9edd8af4a030964f06"}, {"titulo": "Ofrenda en el verso 6.3", "texto": "Oloirekoire,\nOloorunkoorun:\nadivinaron Ifá para Opẹkẹtẹ.\nCuando ella iba a la sala de parto\nElla fue aconsejada para que sacrificara:\ndoscientas Ikoti, doscientas agujas,\ndoscientas ratas y doscientas peces.\nỌpẹkẹtẹ obedeció y ejecutó el sacrificio.\nElla fue productiva como lo predijo Ifá.", "origen_id": "d1799610d5ead6f3bc4cd0aa"}, {"titulo": "Ofrenda complementaria 1", "texto": "6 eiyelé (pichón), 6 abo adie (gallina), 6 eku (rata pequeña), 6 eja aro (bagre negro), 1 plato blanco y 25 nira (dinero)\n\nDestinatario: Obàtálá y Esú", "origen_id": "0d74a04ae50c6debfe95911d"}, {"titulo": "Ofrenda complementaria 2", "texto": "10 okete (rata grande), 1 epo (botella de aceite de palma), 1 plato blanco y 50 nira (dinero)\n\nDestinatario: Obàtálá y Esú", "origen_id": "64c8f2f478afce83b5c7399c"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá y Èṣù reciben las ofrendas de este signo. Las àjẹ́ (brujas) respetan al que ofrenda. Egúngún y los padres deben honrarse.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Esu", "origen_id": "df8aea74c9b0591fea710a6c"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Limaduras de bronce o latón y plomo molidas con semillas de wẹ́rẹ́njẹ́jẹ́ (Abrus precatorius), frotadas en una pequeña incisión bajo las cejas, como medicina del gato. Tela negra, alfileres, agujas, ratas, pescados, carnera, palomas, plato blanco."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 6.1", "texto": "Moler limalla de bronce o latón y plomo con semillas de werejéje , frotar el polvo sobre una incisión hecha bajo las cejas.", "origen_id": "d6c54c64a6fcaacea1812472"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 6.1 (yorùbá): Igi-nlá ni ngba agogo-idẹ l'enú, / Agbigbo-ñlă ni nfo ragajigi l'egan, / Ọpe-ihaha ko'ran iwosi, / I k'pnikoni ma sợ'gba / kẹrẹkẹrẹkerẹ lori oun: / a difá fún Ologbo Ojigolo / nṣawo re ilu àjẹ. / Wọ̀n ni: / A yọ bọ, bi o ba rúbọ: / agùtàn, ẹyẹlé Méjì ati ewé Ifá / Ó gbó ó rú. / Wọ̀n ṣe éwe Ifá fún un gẹgẹbi a ti wi / pe kioloo lẹhin ti o ti rúbọ.", "Verso 6.2 (yorùbá): Gogromaafiyun, / Gooromaafibo: / li o difá fún Arunlojẹ eranko, / nigbi wọn mi losájo. / A niki wọn rú: / aṣo dúdú. / Wọ̀n kọ wọ̀n ko rú. / Ologbo nikansosọ li ó rúbọ ninu wọn. / Nigbi wọ̀n d'ajo ti wọ̀n nre / Awọn Àjé ni wọn ba pade / Awọn omo eranko / ti wọn sọ pe àwọn ko jẹ fi aṣo-dúdú / wọn rúbọ li Ajẹ bẹrẹsiipa jẹ / Wọ̀n ri ologbo lokere / Ó f'aṣo-dúdú bòra bii ti won / Ojú rẹ̀ si jẹ mẹrin bii tiwon / Awọn Àjé ni àwọn ko niipa jẹ / nitoripe ara wọn niiṣẹ / Nigbati ologbo nbowa ilé o nkorin bayi: / Gooromaafiyun, / Gọoromaafibo...", "Verso 6.3 (yorùbá): Oloirẹkoirẹ, / Oloorunkoorun: / Ii o difá fün Ọpaketo, / nlç kan orile omobibi. / Wọ̀n ni ko rú: / Igba Ikotip\", igba abẹrẹ, igba èku ati igba ẹja. / Opekpte gbọ̀ ó rú. / Q rg, gegebi Ifá ti wi.", "REZO: OJUANI MEYI BABA OROGUN NI MOUN ORI YEKO ADIFAFUN AKITIFA, ADIFAFUN ARONI, MAMA FOROSILE AKITIFA, ADIE SINKENA ELEBO.", "REZO: FORORO FORORO SITE AQUITIPA. INFUAGUALICHE GUALEGUE OFI ONA A FACHE ADOS O ELLE AFI ERUNOCHO ARERE AIMBO FIO OFUN CHOMA NIBI SIGUA ELLE FUN OGO ACARERUM MALE EKU ELLAFUNI AGUA ARAGON NI MONI UN A GUON O OROG UA ALOCO ONI BABALAWO ADIFAFUN AQUITIPA AQUITIPA MAMA FIORORO MAMA FIORORO SILE AQUITIPA.", "REZO: OJUANI MEYI IOA FAFACHA NIE HELE QUELE EBE OMO ONA AFACHA DODE ALLE FORUN CHOSERE OIBO FORUN FUGAN ANI EBECUA ELLI AWO IBAOROGUN ENI MONI ALBA LLACA ADIFU A QUITIPA ADIFAFUN CHORINI AQUITIPA FORORO SILE AWO.", "REZO: IKU FABA NICHELEQUE LEBA MOUNA OFAN EHODODO ELLE PEREFUN OBERE IBO FOCUNOCHONA ONI ELEGUA ELLE FUN AGRIO IBA OROGUN NI MONI UN ABACHOCA ADIFAFUN AQUITIPA MAMA FOROSILE AQUITIPA.", "REZO: IFA CORI QUE ODAFUN OJUANI ADAFUN OSHOSI ODAFUN ECHA AGUAN ANCHA COTOCHE LLEONODOC HO ODOCHE ROCO INTIO CUON OCO NIMU OTOLE A OCUNA BO ORIBA RANI OCUANDIE CHUDE ANDALLE CANOLHUB ALA GUOMO ACU ADIE MELLI OLE ECHU GUOLEQUI FUN CACONI CANI CANI OCUN ELALLA CHETITU OPOLOPO OWO ECHU ENI LA ASHE AGUTAN UN BATON CHELITA ILLE OROTAN CALEL OTOLE.", "REZO: MOBORI EKU MOBORI EYA MOBORI COPI COCO TIMBELE AGUN OCONIEOCO LAPACHO CONILE UMPILESE ALLOLLI AWO LASOLLO COSA CO MEYI GRAGANDA LODAFUN GUALEO TIOCHEMO O OMI ORO A LESA OCO ALACAN MOBORI FAPA TA LLECUN POBA.", "REZO: ABA OROGUN MAMOUN LLOCO ADIFAFUN AQUITIPA ADIFAFUN ARONI MAMA FORO SILE AWO FORORO SILE AQUITIPA.", "REZO: EOUN ICUN FA BA NI SILE QUE LEBE OFO EHODO ADIFAFUN AGARARA TICHU ECNO OLODUMARE ONI LENO A OWO UMPABA NICHELE QUE LEBE OMUONA OPUCHODE ELLE RERE FUN CHARER IBO FOCUN ONI BEBE ELEDA ELLEFUN AWO IBI SILE OR PGUN NI MORO UN ABALLACO ADIFAFUN MAMA AQUITIPA MAMA PORO PORO SILE AQUITIPA MAMA FORO SILE AQUITIPA.", "REZO: IBA ORUGUN NIMORI A UN OBA LLAOA ADIFAFUN ARO ANI AQUITIPA MAMA ORO SILE AQUITIPA MAMA A QUITIPA ORUBO META ACODA IBARUTA.", "REZO: BABA OGGUN NIMONI OKO LABAYOKO ADIFAFUN AKITIKUA ARONI MAMA FOROSILE AWO FOROSILE ADUE AKITIKUN OTUFO TOLOSAMADO LOBO.", "REZO: OJUANI MEYI ODODO IGUI SOKUN SOKUN KARE LAWA SODENI LAYE OMO ABITA IGUI IYA LASHE EWE ABITA ODODO IGUGUN OMO LAYE ABITA LAWA KUAWO ADE LAYE IDA ABITA BABA OJUANI MEYI OMO ALASEN OMO ABITA IRE UMBO WUANI ENI SHANGO OZAIN OTOKUN ENI BAGURA AILA SHEKUE OBATALA IGUI IYA LASHE SOKUN SOKUN ISOLE UMBO NI AIYE IFA NI KAFEREFUN ORUNMILA OZAIN NI ABITA.", "REZO: BABA OJUANI MEYI AKUALI SHELI BEBLE OLOGBO KOLE SHELEBO OFI ONA OTA BURUKU BURUKU AFASHE ODDOEYO OFI", "EFUSHE MENYI ARERE OLOGBO AWO NI ORUN OLUWO OZAIN TOKU ABOFI OGU SHOMA BIBI SIWALE EYE FUN AWO KAFEREFUN EKU EKU EYE FUNI AWA ARA OGO MANANI AWO OLUWO OZAIN KORUKE AYOKO AWO BABALAWO ADIFAFUN AKITIFA MAMA FIORORO SILE AKITIFA IRUFARA EBA NI SHELI KELE BIBE OMO UN INSHE FORE AYE EGGUN OYIMBO OJU ARAKONISHE SEKE LABE ONA KOBELEFO OZAIN AWO OLOGBO FESHOKOSILE AYOYI AWO TIMBEBARAKUN OZAIN EGGUN BATUNDE OKONI KOKO LA FE SHOKO INLELEA KOYOOLUEKO MEYI BARADAN LODAFUN AWO LODEO EKOTI SHEMA KUNI EGUNGUN ORUN ALSA OKO ALKAN MOBOTI KUAKUATA YAFUN BOGBO IBA TI EGUNGUN ORUN ALSA OFOGUN OLOGBO NIMBUN YOKO IBA ARAWA OMO TINTUN OBADI MEYI EGUNGUN OZAIN NI MORIUN OBA YAKA ADIFAFUN ARON KOLEBA ADIFAFUN EGGUN AGARARA TINSHAWO BABA NI KUELE EKO OLODUMARE ONI LEMU AWO UMPABA NI SHILE KELEBE OMU AKUAN SHODO NILE ORUN UN ABAYOKO ADIFAFUN OZAIN ARONI KUIN ORUGBO AKUKO META ALO ASHE LODAFUN OZAIN Y ORUNMILA.", "REZO: OJUANI PAPEKUN IKU ELEGBA MATISHE IKU EGGUN ALAWANA MALOKUN ARUN IBASHE OLODUMARE OLOFIN MAFREN OFON APA OSI MAYERE EGGUN KAYIBI ORUN LAYE ME ERIN YEYE OLERI EGGUN MASAUN LELE BABA LODE LORUN ORUN LAYE OJUANI LAYE ASHE ORUN EGGUN OMO IKU SHAME LAYE ORUN KUAYERE OMO ODARA EGGUN AMEGO UNDEDE ORUN LELE EGGUN UNIEN OKO OTOKOMA NI OLORUN.", "SUYERE: BABA TERUN NILE EGGUN OBA YEKUN TONI MILE EGGUN OBA YEKUN.", "REZO: OJUANI KEREBE ESHUBA ESHUBA AUN FESHU LEKEDE AMARA GODO AWO AUN ORUGBO KEREKAN NAMELI AWO LASHE EDUN ESHEGONI AGUEMA EGONI IMBELE BABE KOTE KE IGBAN IGBA BARA KOTESU SHANGO KEKERE YIBE KEKERE YERI YERI KEKERE TEYULUN OSHI LOWA INITEN SHENI SHENI KEBAN NIBO IKUN MAGURE AGUEMA OKUA SHELE MOLE BERENE MENO EJUN SHUNDUDI EBE GUYANASHE RERE ADIFAFUN AUN BEE BATUN LESILE EYELIBE KAFEREFUN ORUNMILA.", "REZO: IBA OROGUN NI MARI YAKA AYAKO ADIFAFUN AROBO UMBATI ODI GAMU ADIFAFUN AKITIPA ORI ORUN SAYE FORUN", "SHOSHERE OBORE IBO KORIKO ADIFAFUN EGGUN OPA AYA LODAFUN ELEGBA.", "REZO: ARONI MAMAFOROSILE AWO FOROSILE AKITIFA DIFAFUN ORUNMILA KAFEREFUN OZAIN."]}]$q$::jsonb),
(7,'cd3a1e125b0bccd36b1116bf7413b052','17038a50e18c204635b88539c97fb81d',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Méjì habla de un estado de incertidumbre que paraliza a la persona para decidir y la llena de inseguridad; debe dominarlo con su fuerza interior y su voluntad. Sus hijos tienden a ser impulsivos y víctimas de su propio entusiasmo, y lamentan lo que deciden bajo presión o con los nervios alterados. Ifá le desea riqueza: su Orí está destinado a la prosperidad y su fortuna tiene raíz en Ọ̀ṣun.", "pasajes": [{"titulo": "Frase clave", "texto": "O'bara crea transformación interna.", "origen_id": "e1107eb712792994ec1cfe19"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está bajo presión, con incertidumbre o problemas de dinero, y le cuesta decidir con calma; quizá se arrepiente de una reacción impulsiva.", "Su negocio necesita clientes o mejores condiciones.", "Siente oposición a su alrededor; antes de culpar a alguien debe ver la causa real.", "Quiere empezar un proyecto, mudarse o iniciar una relación (relato del árbol Odán).", "Busca prosperidad o hijos (relatos de Awòn y de Ifákáyòdé).", "Necesita apoyo mutuo: una mano lava a la otra (relato de Awùn y Ondero).", "No siguió un consejo y ahora paga las consecuencias (relato de Èji-Ọ̀bàrà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un Orí próspero y la riqueza.", "Casa y negocio llenos de clientes y amigos si sigue a Ifá y ofrenda a Ọ̀rúnmìlà.", "Muchos hijos, más varones que mujeres.", "Vencer a los enemigos y descubrir quiénes son y qué causa sus problemas.", "Abundancia y buena relación de pareja al empezar algo nuevo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Decisiones impulsivas o tomadas bajo presión.", "Problemas de dinero y enemigos que preparan un ataque sorpresa a su vida o a su casa.", "Enfermedad en el pecho o el abdomen, como la de Èjì Ọ̀bàrà.", "Comer carne de oveja (es tabú)."]}, {"titulo": "Enseñanza principal", "texto": "Una mano lava a la otra: la derecha lava la izquierda y la izquierda la derecha. Para prosperar hay que atender a Orí de vez en cuando, vestirse de blanco y no despreciar lo que Ifá prohíbe."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ọ̀bàrà Méjì indica la existencia de un estado de incertidumbre o suspenso, que inutiliza a la persona para tomar decisiones, provocándole inseguridad y vacilación, él o ella deben dominar estos estados de ánimo por medio de su fuerza interior y la voluntad. El hijo de Ọ̀bàrà Méjì tiene tendencia a ser impulsivo, y por tanto se convierte en victima de su entusiasmo, de su ímpetu y de sus pensamientos violentos.\nEllos lamentaran la mayoría de las decisiones que tomen bajo presión o en un estado de depresión nerviosa. Para prosperar en la vida, el hijo de Ọ̀bàrà Méjì necesita propiciar su cabeza (Orí) de vez en cuando.", "origen_id": "07e87cc46a763ebce003ba37"}, {"titulo": "Características generales", "texto": "Otros nombres: Ọ̀bàrà Méjì; Èjiğbàrà.\nOdù Ọ̀bàrà Méjì ocupa el 7mo. lugar en el orden inalterable de Ọ̀rúnmìlà. Para el cliente que está en negocios, Ifá dice que para llenar su casa y el negocio de clientes y amigos, él o ella deberán hacer sacrificio a Ọ̀rúnmìlà y ser seguidores de Ifá.\nSi el Odù Ọ̀bàrà Méjì sale en adivinación para alguien, se dice que aparte de los problemas y dificultades financieras, el cliente está rodeado de enemigos que lo acechan o que quieren hacer un ataque sorpresa en su vida o a su casa. El problema financiero disminuirá y los enemigos serán derrotados si realiza todos los sacrificios prescritos por Ifá. Al final, la persona conocerá quiénes son sus enemigos y será capaz de identificar la causa de sus problemas.", "origen_id": "2fc0d5b3e9ab3f6ccb3919e3"}, {"titulo": "Interpretación tradicional", "texto": "O'bara significa fuerza o espíritu de fuerza. La manifestación negativa de fuerza es el deseo de forzar voluntad personal hacia otros. Ifá enseña que ésta manifestación inapropiada es la fundación del egoísmo. Como una regla de conciencia, el egoísmo está basado en un sentido propio inflado. Es lo contrario a la humildad, que está basada en la voluntad para considerar la opinión de otros. Todo egoísmo debe, en algún punto, enfrentarse con la realidad (el individuo no es el centro del universo). Ésta confrontación puede llevar, ya sea, al crecimiento o a la destrucción propia. La voluntad del humano nunca puede llegar a ser más fuerte que la Fuerza de la Naturaleza que creó la conciencia del humano. El entendimiento de éste principio es la fundación del concepto de buen carácter de Ifá.", "origen_id": "167398e377e464616c8bec52"}, {"titulo": "Orientación complementaria", "texto": "Obara es una transformación interna que ocurre como resultado del ego que es temperado por la humildad. El egoísmo no sano se radica usualmente en la emoción sin control centrada en la gratificación de uno mismo. En O`bara el balance entre la cabeza y el corazón ocurre como un acto de voluntad y el intelectual guia al individuo para transcender la repeticion de viejos patrones no efectivos del comportamiento de vencimiento de uno mismo y destrucción de uno mismo. Algunos de estos patrones tienen una base ancestral (disfunción familiar) y toman la forma de una maldición. En esta forma el individuo identifica a uno mismo con el comportamiento destructivo. Este patrón de comportamiento usualmente  requiere intervención comunal.", "origen_id": "9f17c6f091c06d02decc9cdb"}]}, {"titulo": "Relatos reunidos", "puntos": ["El árbol awùn lava la cabeza de Ondero. El adivino dijo al árbol awùn, que iba a lavar la cabeza de Ondero, que su Orí sería próspero si ofrecía una carnera, una paloma y cuentas de coral; después debía atar las cuentas a la esponja de su baño. A Ondero le pidieron tela blanca, suficiente para hacerse una ropa, y una paloma, para que una buena persona le lavara la cabeza. Por eso a quien le sale este signo se le aconseja vestir de blanco.", "La carnera de Ifẹ. Le dijeron a Èjì Ọ̀bàrà, que bajaba a Ifẹ, que ofreciera una carnera para no enfermar. No lo hizo. Al llegar lo agasajaron con carne de carnera; comió y le vino una enfermedad que le hizo crecer el pecho hasta el final de sus días. Desde entonces los hijos de este signo tienen el pecho grande y no deben comer carne de oveja.", "Atapẹrẹ y sus hijos. Ifá consultó para Atapẹrẹ, hija de Ọwá Ọlófin, y le pidió manteca de cacao, mucho algodón y una carnera. Ofreció y le aseguraron muchos hijos; después de comer la medicina de Ifá cocinada en una olla, tuvo hijos en gran cantidad.", "Awòn lava su Orí en el río. Ọ̀ṣọ́ló, el sacerdote de Awòn, consultó para él el día que iba al río a lavar su Orí de riqueza, y le dijo que le sería fácil, pero que ofrendara a Ọ̀ṣun. Ofreció, empezó a tener hijos y se los llevó a todos a Ọ̀ṣun para que la muerte no los tocara. Ọ̀ṣun cuidó de él y de sus hijos.", "Ifákáyọ̀dé. Ifá consultó para Ifákáyọ̀dé, hijo de Àgbọnnìrègún, y le pidió ofrendar. Si la persona tiene un hijo varón debe llamarlo Ifákáyọ̀dé, 'Ifá ha traído la alegría'; los devotos de Ifá no morirán jóvenes.", "Odán se establece. Abarere consultó para Odán, que quería establecerse, para que el lugar tuviera sombra. Ofreció, el lugar se llenó de sombra y Odán cantaba: 'Odán nació, Odán sobrevivió, Odán ya se estableció'."], "pasajes": [{"titulo": "Verso 7.1", "texto": "Otúnwẹsin?\nÖsinwẹtun\nuna mano lava la otra:\nadivinaron Ifá para el árbol awùn,\ncuando Awun fue a lavar la cabeza de Ondero.\nEllos dijeron:\n\"su Ori será un Ori bueno (próspero)\",\npara eso debe sacrificar:\ncarnera, una paloma y cuentas de coral.\nÉl obedeció e hizo el sacrificio.\nDespués del sacrificio se le aconsejó\namarrar las cuentas de coral en la esponja\nque él debía usar para bañarse.", "comentario": "awùn: ALSTONIA BOONEI De Wild., Apocynaceae.", "origen_id": "6ad4b98e133dd26ada36b90b"}, {"titulo": "Verso 7.2", "texto": "Otunwẹsin\nOsinwetun\nuna mano lava la otra:\nadivinaron Ifá para Ondero,\ncuando el árbol awùn\nestaba yendo a lavar su cabeza (Ori).\nÉI (Ondero) fue aconsejado que sacrificara,\npara que una buena persona lavara su cabeza.\nOndero dijo: \"¿Cuál es el sacrificio?\"\nEl Babaláwo dijo que él debía sacrificar:\ntela blanca y una paloma.\nÉl escuchó e hizo el sacrificio.\nPor eso cualquiera que reciba este Odù\nserá aconsejado para que use ropas blancas.\nOtünwẹsin: significa: \"la mano derecha lava la mano izquierda\".\nOsinwẹtun: significa: \"la mano izquierda lava la mano derecha\".", "comentario": "La cantidad de tela blanca para el sacrificio debe ser suficiente como para confeccionar una ropa.", "origen_id": "fee9375b70067ad470b91e96"}, {"titulo": "Verso 7.3", "texto": "Ojikutukutu\nBaragendengendẹn-bi-igbá-elepo:\nfue el que adivinó Ifá para Èji-Ọ̀bàrà,\ncuando este bajó a lfẹ.\nÉl fue aconsejado a sacrificar:\nuna carnera para evitar la enfermedad.\nEl escuchó y no sacrificó.\nCuando Èji-Ọ̀bàrà llegó a lfè\nél fue agasajado con la carne de una carnera.\nEl comió y le comenzó una terrible enfermedad\nque provocó que su pecho\ncreciera anormalmente\nhasta el final de sus días.\nDesde entonces aquellos nacidos\ncon este Odú de Ifá\nsiempre tendrán un pecho insólitamente grande.\nTabú: Aquellos nacidos en el Odù Ọ̀bàrà Méjì no comerán carne de\noveja (carnera).", "comentario": "La persona con este Odù debe cuidarse de un padecimiento o enfermedad en la región del pecho y abdomen. A Éji- Ọ̀bàrà la enfermedad se le alojó en el pecho, afligiéndose con dolores en el mismo hasta el final de sus días.", "origen_id": "ded490022868edb086d4be2b"}, {"titulo": "Verso 7.4", "texto": "Ogigif'ojú-iran-wọ'lẹ:\nadivinó Ifá para Atapẹrẹ,\nla hija de Qwá-Ọlófin.\nElla fue aconsejada a hacer sacrificio:\nmanteca de cacao,\nmucho algodón (motas de algodón)\ny una carnera (àgútàn)\nElla obedeció y sacrificó.\nA alla se le aseguro tener muchos hijos.\nElla tuvo 900 hijos diarios\ndespuós que comió la medicina de Ifá\ncocinada para olla.", "comentario": "De la misma forma esta medicina para clientes los cuales hayan elegido este Odù y hayan realizado el sacrificio prescrito por Ifá.\nbiyenmẹ: planta no identificada.\nIrugba: PARKIA BIGLOBOSA (Jacq.) Benth., Leguminosad Mimosoideae.", "origen_id": "146761f55aa5961778bdb099"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pe ire fún eléyìun. Orí' olà' lórí' è. Yóó là, yóó sì tobi láyé.' Òsún\n                                                                         '     kán´´n be\n                                                                                      ' ní ìdílè' è,\n  bí ò bá sí' Òsún,\n              '      kó bèèrè níbi wón\n                                     '     gbé dá Ifá yìí fún un: kó sì 'lòó\n                                                                           ' bo\n                                                                             ' ' Òsún\n                                                                                 '    ' òhún toríi\n  lodo\n ' ' '' Òsún    ni gbogbo ire ó nìí láyé   ó ti wá. Omo\n                                                  ' ' ' ' Òsún  ni òun  pàápàá.\n\nÒsòló awo Awòn      '\nLó díá fún Awón    '\nNíjó    ´´\n  ' ti n 'lo rèé werí   ' ' Olà lodo\nArá 'ro Òun báyìí?\nWón\n ' lára ó 'rò' ó\nWón\n ' ní' sùgbón    ' kó rúbo     ' fún' Òsún\n                                        '\nÓ bá rúbo    '\nArá bá 'dè' é\nNí bá´´n bímo  '\nLó bá kó' omo    ' ' è lo fún ' Òsún\n                                 '\nWón\n ' níkú ò gbodò     ' ' pa' omo    ' Awòn '\nAyé ye' ´´'é\nOshun n 'tójú' è\nNí´´n gè\n      ' '´´é\nN ní wá n jó n ní´´n yò    '\nNí´´n yin àwon ' Babaláwo\nÀwon                    ´´\n   ' Babaláwo n yin Ifá\nÓ ní béè\n      ' ' làwon  '      Babaláwo tòún wí\nÒsòló Awo Awòn        '\nLó díá fún Awón    '\nNíjó    ´´\n  ' ti n lo rèé werí    ' ' Olà lodo\nÒsòló mòmò  ' ' dé ò\nAwo Awòn     '\nE ò mò       pÓrí  rere lÀwòn     ´´n wè?\n      '                      '        '\n\n' Òbàrà Méjì A\n  Ifá desea bien a esta persona. Su Orí se destina para ser adinerado y él sería rico en la\n  vida. Ifá dice allí existe una sitio de Òsun en su linaje. Si por otra parte, él debe\n  preguntar que de dónde un sitio pudiera encontrarse para él para ofrecer sacrificio\n  inmediatamente. Esto es porque todas sus fortunas están arraigadas en Òsun.\n\nÒsòló el sacerdote de Awón\nAdivinación lanzada para Awòn\nEn el día él iba a lavar su Orí de riqueza en el río\n'Habría ser más fácil para mí'? Él preguntó\nEllos le dijeron que sería fácil para él\nPero le aconsejaron que realizara sacrificio a Òsun\nÉl ofreció el sacrificio\nLa vida lo agradó entonces\nÉl empezó teniendo niños\nÉl tomó a todos sus niños después a Òsun\n'La muerte no debe matar al niño de Awòn, ellos instruyeron\nLa vida los agradó tanto\nÒsun tuvo cuidado bueno de él y sus niños\nY también acarició a todos\n\n Él estaba bailando y estaba regocijando\n Él estaba alabando su Babaláwo\n Su Babaláwo estaba alabando Ifá\n Él dijo que era como su Babaláwo había dicho\n Òsòló los sacerdotes de Awòn\n Adivinación lanzada para Awòn\n En el día él iba a lavar su Orí de riqueza en el río\n Òsòló realmente está aquí\n Él es el sacerdote de Awòn\n ¿No haga usted saber todo que Orí es que Awòn lavo en el río?", "origen_id": "0d3a54da8f00cc35f2c7f30f"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé ire fún eléyìun. Bí eléyìun bá bí' omo\n                                              ' ' Okùnrin, Ifákáyòde\n                                                                 '   ni kí wón\n                                                                            ' ó so\n                                                                                 ' 'ó.\n' Okùnrin ó 'pò nínú' omo\n                        ' ' è.\n\n' Òkùn gìdìgbà níí rìn bí' ení jó, bí' ení jó\n  A díá fún Ifákáyòdé'\n  Èyí tíí 'somo\n              '  bíbí  inú Àgbonnìrègún\n                             '\n  Ebo\n' '    n  wón   ní\n            ' ´´ ' ó  se\n  Ó sì gbèbo ' nbè\n                 '\n  Ó rúbo\n       '\n  Èrò Ìpo\n  Èrò' Òfà\n  Àrìnjó Ifá ò níí kú léwe\n\n' Òbàrà Méjì B\n  Ifá desea bien a esta persona. Si él tiene un niño masculino, el niño debe nombrarse\n  Ifákáyòdé. Él tendría muchos niños más masculinos que hembras.\n\n Es el gusano de tierra grande que mueve como si bailando\n Adivinación lanzada para Ifákáyòdé\n El niño de Àgbonnìrègún\n Le habían pedido que realizara sacrificio\n Él había oído hablar del sacrificio\n Y lo realizó\n Las personas de la ciudad de viajeros de Ìpo de la ciudad de Òfà\n Àrinjó Ifá nunca se morirían prematuramente", "origen_id": "3882c3798c083907dba3d459"}, {"titulo": "Versos complementarios 3", "texto": "'         bobòó: El nombre de un Babaláwo esculpido fuera de Òbàràbogbè.\n   2. Bòó bòó bòó: El sonido producido por la manera resbaladiza de gusanos\n       cuando ellos escapan en sus madrigueras.\n   3. Ikú yò ó, àrùn yò ó: Los nombres de Babaláwos. (Lt) 'la Muerte y enfermedad\n       lo habían exonerado'\n   4. Òtòntò  ` Ìròkò: Un Babaláwo.\n   5. Ìdó: Un pueblo en Nigeria.\n   6. Òwìrìwìrì: La manera por que las olas de fuego cuando las perturba por el\n       viento fuerte.", "origen_id": "3198158c5d3df8b0cc84af75"}, {"titulo": "Relatos y ofrendas", "texto": "Ò'BÀRÀ MÉJÌ\n\nLavando — la — mano — derecha — con — la — mano — izquierda — y — lavando — la — mano —\nizquierda — con — la — mano — derecha consulta Ifá para Awun (madera blanca) en el día en él\nquería tener su cabeza limpiada. Ifá aconsejó a Awun hacer ebo. Awun hico ebo. Fue en ese día\nque Awun recibió una buena cabeza. Awun cantó y bailó en alabanza del Awo, mientras el Awo\nalabó a Ifá, mientras Ifá alabó a Olodumare. Cuando Awun empezó a cantar, Esú puso una\ncanción en su boca. Awun canto:\nAwún de na, Awún dero. Orí ire I'Awún nwe.\nAwún de na, Awún dero. Orí ire I\"'Awún nwe.\nAwun ha venido, Awun facilidad. Es buena suerte que\nAwun tome un baño.\nAwun ha venido, Awun facilidad. Es buena suerte que\nAwun tome un baño.\nComentario:\nIfá dice que esta persona debe tener su cabeza limpiada para que la mano del Awo apacigie su\ncarga. Ifá dice que esta persona debe adorar a Ifá para que su carga pueda continuar a ser\nlevantada.\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 abo adie (gallina, 1 epo (botella de aceite de palma), 6\niyan funfun (fame blanco), eko (pastel de harina de maíz) y 50 nira (dinero), ofrecido a Esú.\n(Ett (oferendas); 4 eiyele (pombo), 4 Abo adie (galinha), 1 epo (garrafa de azeite de\ndendé), 6 iyán funfun (inhame branco), 6 eké (bolos de milho) e 50 nira (dinheiro\nnigeriano), oferecidos a Ésn.)\n\nAbarere Awo Odán consulta Ifa a Odán en el día que estaba preparándose para restablecerse a si\nmismo. Ifá aconsejó a Odán hacer ebo para que el área tuviera sombra. Odán hizo ebo. El área\nempezó a tener sombra. Odán empezó a cantar y a bailar en alabanza del Awo, mientras el Awo\nalabó a Ifá, mientras Ifá alabó a Olodumare. Cuando Odán empezó a cantar Esú puso una canción\nen su boca. Odán canto:\nOdán nbi, Odán nre. Odán ti múle Ibudo o.\nOdán nbi, Odán nre. Odán ti múle Ibudo o.\nOdán nació, Odán sobrevivió. Odán se ha etablecido\na si mismo.\nOdán nació, Odán sobrevivió. Odán se ha etablecido\na si mismo.\n\nComentario:\n\nIfá dice que es un buen tiempo para que esta persona, empiece u nuevo proyecto, ifá dice que si\nesta persona quiere mover el tiempo, es correcto. Ifá dice que si esta persona está a punto de\nentrar en una relación, la relación será buena. Ifá dice que esta persona va a recibir una bendición\n\n90\n\nde abundancia y una bendición de una buena relación.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 abo adie (gallina), 1 epo (botella de aceite de palma),\n1 plato blanco, 4 eko (pastel de harina de maíz), 100 nira (dinero) ofrecido a Esú. Eéwo (tabú):\ncazar pájaros pequeños.\n\n(Ett (oferendas); 4 eiyele (pombo), 4 Abo adie (galinha), 1 epo (garrafa de azeite de\ndendé), 1 prato branco, 4 ekó (bolos de milho) e 100 nira (dinheiro nigeriano) oferecidos a\nÉsù. Eéwó (tabu): cacar passarinhos.)\n\nn n\nn n\nn n\nI I", "origen_id": "5af9986d2558e1a482cd919d"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Obara meji denota un estado de incertidumbre o suspenso. Está\ninhabilitado para tomar decisiones. El hijo de Obara Meji tendrá tendencia\n        a ser impulsivo, será víctima de sus pensamientos violentos. Ellos les\n pesará su decisiones tomadas bajo una depresión nerviosa. Para prosperar\n     en la vida, el hijo de Obara Meji necesita propiciarle a su cabeza (ori) de\n                                                                  vez en cuando.\n                     WO - Temporal y espiritual, bloqueado emocionalmente o\n                                              dificultades que deben ser resultas.\n                Odu Obara Meji ocupa el séptimo. Lugar en el orden fijado por\n Orunmila, para el cliente que está en negocios, Ifá dice que debe llenar su\n            casa de consumidores y amigos. Él o ella deberán hacer sacrificos a\n                                                                      Orunmila.\n                Si Odu Obara Meji habla para aquel que estará en dificultades y\ndeberá vencer a sus enemigos quienes lo vigilan en el camino para tomarlo\npor sorpresa a él o a su casa. Las dificultades financieras se mitigarán y se\n     vencerán a los enemigos cuando el cliente consienta en realizar todos los\nsacrificios prescritos por Ifá. Al final, la persona conocerá quienes son sus\n                enemigos y será capaz de identificar la causa de sus problemas.\n\n\n7.1 · Otunwesin (la mano derecha lava la izquierda). Osinwetun (la mano\n\nizquierda lava la derecha). Quienes lavan las manos, ellos hicieron\n      adivinación de Ifá para el árbol awun. Cuando awun fue a lavar la cabeza\n        de ondero (ori), ellos dijeron que él prosperaría. Por eso Él ofreció una\n             carnera, una paloma y una cuenta de coral. Él obedeció he hizo el\n        sacrificio. El habló de amarrar la cuenta en la esponja que él usara para\n                                                                       bañarse.\n\n\n7.2 · Otunwesin-osinwetum, quienes lavaron sus manos. Ellos hicieron\n           adivinación de Ifá para Ondero. Cuando el árbol awun fue a lavar la\n  cabeza de Ondero, éste dijo: ¿cuál es el sacrificio? El babalawo dijo que él\n                       ofreciera ropas blancas y 1 paloma. Él hizo el sacrificio.\n               Por eso el que reciba este Odu será avisado de usar ropa blanca.\n\n\n7.3 · Ojikutukutu Baragendengenden bi igba elepo, hizo la adivinación de Ifá\n  para Eji Obara quien vino del bajo Ife. Él mandó a sacrificar 1 carnera para\n       evitar la enfermedad. Él rechazó el sacrificio. Cuando Eyi Obara llegó a\n  Ife, él se entretuvo con la carne de una carnera. Él lo comió y así la terrible\n       enfermedad que vivía en su pecho llegó al fin. Desde entonces aquellos\n         que son nacidos en Ifá siempre tendrán un inusual aquejamiento en el\n                                                                     pecho (☼).\n\n\n7.4 · Ogigi f´oju iran wo´le, adivinó Ifá para Atapere la hija de Owa-Olofin.\n          Ella habló de hacer un sacrificio de manteca de cacao, opolopo ou, 1\n         carnera. Ella obedeció y sacrificó. Ella fue asegurada de tener muchos\n\nhijos. Ella tuvo 600 hijos diarios después que ella cocinó y comió\n     medicina de Ifá cocinada para ella. Hierbas de Ifá cocinar hojas ogio-ori\n      con biyenme, claveles y irugna, muélalas, juntas con otros ingredientes\n                         para hacer una sopa para que sea comida por ella (☼).", "origen_id": "2743683b59a48755f29f4030"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Awùn: una carnera, una paloma y cuentas de coral atadas a la esponja de baño.", "Ondero: tela blanca suficiente para una ropa y una paloma.", "Atapẹrẹ: manteca de cacao, mucho algodón y una carnera.", "Para lavar la cabeza: cuatro palomas, cuatro gallinas, aceite de palma, seis ñames blancos, ẹ̀kọ y dinero, a Èṣù.", "Odán: cuatro palomas, cuatro gallinas, aceite de palma, un plato blanco, cuatro ẹ̀kọ y dinero, a Èṣù; tabú: cazar pájaros pequeños.", "Ofrenda a Ọ̀ṣun en el río; ofrenda a Ọ̀rúnmìlà para llenar el negocio."], "pasajes": [{"titulo": "Ofrenda en el verso 7.1", "texto": "Otúnwẹsin?\nÖsinwẹtun\nuna mano lava la otra:\nadivinaron Ifá para el árbol awùn,\ncuando Awun fue a lavar la cabeza de Ondero.\nEllos dijeron:\n\"su Ori será un Ori bueno (próspero)\",\npara eso debe sacrificar:\ncarnera, una paloma y cuentas de coral.\nÉl obedeció e hizo el sacrificio.\nDespués del sacrificio se le aconsejó\namarrar las cuentas de coral en la esponja\nque él debía usar para bañarse.", "origen_id": "43c4333ab290b2e21d144e79"}, {"titulo": "Ofrenda en el verso 7.2", "texto": "Otunwẹsin\nOsinwetun\nuna mano lava la otra:\nadivinaron Ifá para Ondero,\ncuando el árbol awùn\nestaba yendo a lavar su cabeza (Ori).\nÉI (Ondero) fue aconsejado que sacrificara,\npara que una buena persona lavara su cabeza.\nOndero dijo: \"¿Cuál es el sacrificio?\"\nEl Babaláwo dijo que él debía sacrificar:\ntela blanca y una paloma.\nÉl escuchó e hizo el sacrificio.\nPor eso cualquiera que reciba este Odù\nserá aconsejado para que use ropas blancas.\nOtünwẹsin: significa: \"la mano derecha lava la mano izquierda\".\nOsinwẹtun: significa: \"la mano izquierda lava la mano derecha\".", "origen_id": "f6d0f0b3f932ac3f5a7faad5"}, {"titulo": "Ofrenda en el verso 7.3", "texto": "Ojikutukutu\nBaragendengendẹn-bi-igbá-elepo:\nfue el que adivinó Ifá para Èji-Ọ̀bàrà,\ncuando este bajó a lfẹ.\nÉl fue aconsejado a sacrificar:\nuna carnera para evitar la enfermedad.\nEl escuchó y no sacrificó.\nCuando Èji-Ọ̀bàrà llegó a lfè\nél fue agasajado con la carne de una carnera.\nEl comió y le comenzó una terrible enfermedad\nque provocó que su pecho\ncreciera anormalmente\nhasta el final de sus días.\nDesde entonces aquellos nacidos\ncon este Odú de Ifá\nsiempre tendrán un pecho insólitamente grande.\nTabú: Aquellos nacidos en el Odù Ọ̀bàrà Méjì no comerán carne de\noveja (carnera).", "origen_id": "b5fbb45e113fd616e78a76f7"}, {"titulo": "Ofrenda en el verso 7.4", "texto": "Ogigif'ojú-iran-wọ'lẹ:\nadivinó Ifá para Atapẹrẹ,\nla hija de Qwá-Ọlófin.\nElla fue aconsejada a hacer sacrificio:\nmanteca de cacao,\nmucho algodón (motas de algodón)\ny una carnera (àgútàn)\nElla obedeció y sacrificó.\nA alla se le aseguro tener muchos hijos.\nElla tuvo 900 hijos diarios\ndespuós que comió la medicina de Ifá\ncocinada para olla.", "origen_id": "96a032b6b0aacbe034af0c15"}, {"titulo": "Ofrenda complementaria 1", "texto": "4 eiyelé, 4 abo adie, 1 epo, 1 plato blanco, 4 eko y 100 nira\n\nDestinatario: Esú", "origen_id": "be56b374e03dbb532a026177"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀ṣun es la raíz de la fortuna de este signo y cuida a los hijos. Ọ̀rúnmìlà llena la casa y el negocio. Èṣù recibe las ofrendas de limpieza de cabeza.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Sango", "origen_id": "bbbe8cd01945a4a909ecf024"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Awùn (Alstonia boonei), cuentas de coral, tela blanca, algodón, manteca de cacao. Medicina para tener hijos: manteca de cacao molida con hojas de biyẹnmẹ, clavo y semillas de iru (Parkia biglobosa), se puede añadir ajo, en sopa para comer. Tabú: carne de oveja. Ante dolores en el pecho o el abdomen, conviene ir al médico."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 7.4", "texto": "Moler juntos: Ogi-òri (manteca de cacao), hojas de biygnmp\", clavos (especia) e irugba\", también le puede adicionar ajo.\nuna sopa. El cliente Agregue estos ingredientes a elementos para hacer debe comer esta sopa como medicina.\npuede ser cocinada", "origen_id": "bb2c48e859bbda007635c328"}]}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 1", "texto": "cazar pájaros pequeños", "origen_id": "0877fa9b4fa51aa700f63f41"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 7.1 (yorùbá): \"Ọ̀túnwẹsin, / Ösinwẹtún ni qwọ̀ ṣe nmọ\": / li o difá fún igi awùn, / nigbi awùn nlọ wẹ Ori Ondero. / Wọ̀n ni: / \"Orí rẹ a d'orí rere\" / nitorinaa ki ó rú: / àgùtàn, ẹyẹlé ati iyun. / Ó gbó ó rú. / Wọ̀n niki o so iyun na mọ kanrinkan / ti oun yo maa lo fún wiwe ara re.", "Verso 7.2 (yorùbá): \"Ọtúnwẹsin, / Ösinwẹtún ni owọ̀ ṣe nmọ\": / Il o difá fún Ondero, / nigbati igi awùn mbowa wẹ Orí rẹ. / Wọ̀n niki ó rúbọ, / kio baa le ri ẹnirere wa wẹ orí fún un / Ondero ni: kini ebo? / Babaláwo niki ó rú: / agp funfun ati eyẹlé kan. / Ô gbọ̀ ô rú. / Nitorinaa gnikçni ti Ifá yi ba bi / a o so fún un pe ki o maa la aṣo funfun.", "Verso 7.3 (yorùbá): Ojikutukutu / Baragendẹngenden-bi-igbá-elepo: / li o difá f'Èji-Ọ̀bàrà mi bowa, / S'alẹ lfẹ. / Wọ̀n niki ó rú: / àgùtàn ki o ma baa ṣaisan. / Ó gbọ̀ ko rúbọ. / Eji-Ọ̀bàrà lọ s'alẹ Ifẹ, / wọ̀n fi obẹ-ẹran àgùtàn ṣee ni àlejò. / O jẹẹ Ó bẹrẹsi ṣaisan titi o fipo si oke-aya, / lati ojẹ naa wa titi fi di òni-olóni yi. / Àwọn ti Ifá yi ba bi, / wọ̀n a maa po si oke aya.", "Verso 7.4 (yorùbá): Ogigif'ojú-iran-wọ'lẹ: / li o difá fún Atapẹrẹ, / tliṣe ọmọ Qwá-Ọlọ̀fin. / A niki ó rú: / ogi-òrí, ojo-òwú ati àgùtàn kan. / Ô gbọ̀ ó rú. / Wọ̀n ni a bimọ titi inú rẹ a bo / Egbẹta omọ ni oun maa nbi lojoojumo / Içhin ti wọn ti ṣe ewé Ifá fún un / tio si ti jẹẹ. / Beegẹgẹ niki a ṣe fún èniti a dá'fá / fún tio si ti rú ẹbọ ti Ifá yan.", "REZO: OBARA MEYI ONIBARA OLABARA EYEBARA KIKATE AWO KOMAKATO ARAYE KOMAKATE ARA ORUN ADAFUN BOGBE EYEOKO OROFO LORUBO BOGBO TENUYEN KOKORO.", "REZO: OBARA MEYI ONIBARA OLOBARA ELLEBARA QUICATE AWO ADIFAFUN OROPO TONCHE ILEOLALLA ESHU.", "REZO: ONIBARA ALA BARA ELLEBARA QUIOSTE ADIFAGO CANFU OROFO TINOCHE PROLLA ONIBARA ELLE AFIGLU OLLO QUIO ATE. OBARA MEYI IFA ONI LARA ALA BARA ELLE BARA QUICATE AWO FOLOFODE. TINCHE CHECHE LLELE ESHU ORUNLA LORUGO AGUERE AIKORDIE EYELE ELEGBA DE MEDILOGUN EKU EYA EPO. OBASA ONI GEGER ONI GEGER ONI CHACUALUMA LAPEROBE OBUDU LLALLA LA PEOTI.", "REZO: ONIBARA OLABARA ELLEBARA QUICATE ADAFORO TINSHE LOYA EYE ALONA PAFILLO EYE QUICATE ABEBOADIE MEYI LEBO SHILENO OWO.", "REZO: OBARA MEYI IFA ONI LARA EYE ARA QUICATE AWOFALOFODE TINSHE EYEYE ASHA ORUNLA LORUBO EURE AIKORDIE EYELE ELEWEDE MEDILOGUN AWO MEDILOGUN EKU ELLA EPO.", "SUYERE A OZAIN: OZAIN POWO MEYO TOWO DUN DUN OZAIN ATAWO ODE OZAIN MEWO FOWONIRE AWO", "LLAMADA DE EGGUN DE ESTE SIGNO: EGGUN MATARIN MAWA IKU. ORIN MATARIN AEA IKU EGGUN LODO EGGUN AWA OLUBEKAN MAWA BAÑIRE EGGUN MORAKUN AGUN MOYORE EGGUN.", "SUYERE: OROFOFUGO DE ESE EYE ORUNDARE AFE AYE OYA EQUICATA.", "REZO: TOYO TOYO TENU APALAPO OKANA MANI ADAFUNTETE LODAFUN OLOFIN KAFEREFUN ESHU LORDAFUN ORUNLA OBARA NIREGUN IFA LORDAFUN OLOKUN", "REZO: OBARA NI AWO OBARA BARA NI IFA ONI BARA NI REGUN AWO OBASHE ORIBAWE ORUNLA AKUALO IÑA AMAWADE DE ODUDUNA ONI BARA NIREGUN ORUNMALE ISOTA ERI NIBARI TRIBUTE ARIKATO ONI BABALAWO LODAFUN OLOFIN OBARA OBARA NI BARA ABAYE NI IFA ONI BABALAWO ONI BARA NIREGUN OBARA EYI ONI BARA KUNA LE OLOOZAIN OBARA ABA YINIFA ONI BABALAWO ORI OBA AWARE AWO AWO LARA ENI ORO OLOFIN OBARA NIREGUN EGGUN NANIRE AWO IFA KAFEREFUN SHANGO.", "REZO: OBARA MEYI ONI BARA OLOBARA OYEBARA KIKATE AWO ADIFAFUN OROPO TOSHE ILE FAYA ESHU ERIN OKE OMO OBA ARUN ESHINSHIN AWO ODARA IFA KAFEREFUN SHANGO.", "REZO: ONIBARA BABARA EYEBARA KIKATE ADIFAFUN KAFU ARO OFO TINSHE EROYA EYE AFINYU OBE KIKATE."], "pasajes": [{"titulo": "suyere", "texto_ritual": "A OZAIN: OZAIN POWO MEYO TOWO DUN DUN OZAIN ATAWO ODE OZAIN MEWO FOWONIRE AWO", "origen_id": "f2aca5dbb5f5884fbf21b563"}]}]$q$::jsonb),
(8,'db2e29447637227ce0696687b5427003','cb5906beef97eeb4ecd7ecb1f0764dd3',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Méjì habla de sufrimiento, malas vibraciones, problemas y pleitos judiciales. Sus hijos dan en el clavo cuando hacen y dicen lo correcto en el momento justo; la gente los cree agresivos porque luchan contra todo pronóstico, y a veces se rebelan contra las costumbres y eso les trae problemas. Son propensos a infecciones y deben cuidar su salud. Es momento de ceder, arreglar y cerrar los problemas.", "pasajes": [{"titulo": "Frase clave", "texto": "okanran crea nuevas direcciones y nuevas posibilidades.", "origen_id": "8047564ba82fae92d9ed2bb8"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Atraviesa una disputa o contrariedades y necesita negociar o cerrar un asunto pendiente.", "Busca dinero o hijos que no llegan y se pregunta si podrá lograrlo con sus propias manos (relato de Jìngbìnní).", "Va a viajar esperando reconocimiento o recursos (relato de Ṣàkótó en Ọwá).", "Un cambio de casa o de entorno le cambia los planes de regreso (relato de Ilé Ètilè).", "Compite con otro por algo y solo uno se preparó (relato de Olú-igbó y Olú-òdan).", "Tiene un solo hijo y desea otro (relato de Oló).", "Debe elegir entre reaccionar con el enojo o dar un paso pensado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que se resuelvan la falta de hijos, de dinero y de otras cosas buenas si cree en Ọ̀rúnmìlà.", "Llegar como extranjero y ser hecho rey.", "Un hijo adicional.", "Riqueza que llega a las manos.", "Fama y abundancia en un viaje."]}, {"titulo": "Ibi y advertencias", "puntos": ["Problemas judiciales y malas vibraciones.", "Rebelarse sin medida contra las normas.", "Infecciones y enfermedades que se vuelven crónicas.", "Reducir la ofrenda que pide Ifá."]}, {"titulo": "Enseñanza principal", "texto": "Para vencer a los enemigos y controlar las dificultades, se ofrenda a Ṣàngó y a Èṣù. No se recorta lo que Ifá pide: la ofrenda completa es la que abre la mano a la riqueza."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ọ̀kànràn Méjì significa sufrimiento, malas vibraciones, problemas, casos judiciales. Los hijos de Ọ̀kànràn Méjì siempre darán en el clavo por hacer y decir lo correcto en el momento.\nLas personas a menudo piensan que los hijos de Ọ̀kànràn Méjì son agresivos y dominantes porque ellos tratan de prevalecer a pesar de lo que se esperaba por tener todas las probabilidades en su contra. En muchas situaciones ellos se rebelarán contra las convenciones de la sociedad y como consecuencia esto le traerá problemas para ellos mismos. Ọ̀kànràn Méjì es un propenso a las infecciones, los nacidos con este Odù deben cuidar mucho su salud para evitar convertirse en enfermos crónicos.", "origen_id": "65952c8c29075ae5ef257674"}, {"titulo": "Características generales", "texto": "Otros nombres: Ọ̀kànràn Méjì; Èjiọ̀kànràn / Olokànrànméji.\nỌ̀kànràn Méjì es el 8vo. Odù en el orden inalterable de Ifá. Ọ̀kànràn Méjì en adivinación, le dice al cliente que está sufriendo por falta de hijos, dinero y otras cosas buenas de la vida, pero si el cliente cree en Ọ̀rúnmìlà y en los trabajos de Ifá, todos sus problemas serán resueltos. Para superar a sus enemigos y tener el control sobre todas las dificultades, el cliente deberá ofrecer sacrificios a Ṣàngó y a Èṣú.", "origen_id": "c53b56d7e90d6340a3f7d19f"}, {"titulo": "Interpretación tradicional", "texto": "Okanran significa venir del corazón. Ifá enseña que el crecimiento espiritual ocurre como resultado del balance entre la cabeza y el corazón, conocido como ori tutu (armonía entre pensamiento y emoción). El antídoto del egoísmo que puede ocurrir en O'bara es humildad, que puede ser creada en Okanran. Cuando la experiencia nos enseña que nuestra percepción del mundo está en error, la conciencia empieza una búsqueda de la verdad de la materia. Esto es el ciclo de la muerte y el renacimiento que es la fundación de toda iniciación. En términos sociales, éste ciclo es representado a menudo por la voz del profeta. En términos negativos, Okanran representa cambio constante basado en las respuestas emocionales que no están firmes en la reflexión conciente.", "origen_id": "ce5e2f59d8ad9370d1121d7e"}, {"titulo": "Orientación complementaria", "texto": "Okanran representa el primer paso que ocurre como resultado de un nivel nuevo de entendimiento de uno mismo. Cualquier cambio en la percepción de uno mismo y el mundo altera la visión de la persona del futuro y como pueden ellos proceder en el mundo. Cualquier que rehusa a tomar el primer paso , corre el riesgo de que ellos se aíslen y cerrando la puerta de un crecimiento mas adelante.", "origen_id": "b06ca2ebad8f065afff97a27"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ṣakótó, el extranjero empapado. Los babaláwo le dijeron a la gente de Ọwá que ofrendara para que un extranjero fuera nombrado rey, y anunciaron que el próximo rey llegaría empapado por la lluvia. A Ṣakótó, que iba de viaje a Ọwá, le pidieron una paloma, una carnera y tres tortas de frijol, y le dijeron que en el camino no les diera las tortas a Èṣù, sino que se las comiera frente a él. Al primer Èṣù le dijo: 'Si te doy esta torta, ¿detendrás la lluvia hasta que llegue a Ọwá?', y se la comió. Hizo lo mismo con el segundo y con el tercero. El tercer Èṣù, enojado, mandó un aguacero. Ṣakótó llegó a Ọwá completamente mojado, y el pueblo lo hizo su rey.", "Ṣakótó trae la lluvia. Ifá también cuenta que Ṣakótó, camino a Ọwá, sí le dio sus tortas a Èṣù, que se le apareció como mujer, como niño y como caminante. Èṣù le contó que en Ọwá llevaban mucho tiempo sin lluvia y le mostró un sembradío de calabacitas: debía escoger una de las que no hablaban, cortarle la tapa, alzarla sobre su cabeza en la entrada del pueblo y anunciar que traía la lluvia. Lo hizo y empezó a llover. El rey de Ọwá lo mandó llamar y le dio la mitad de todo lo que tenía. Cantaba: 'Ṣakótó es belleza; la buena adivinación es dulce de alabar'.", "El rey del bosque y el rey de la sabana. El rey del bosque y el rey de la sabana fueron a seducir a Ẹwu, esposa de Iná, el fuego. Les pidieron un manojo de escobas, medicina de Ifá, una gallina y una tela negra. El de la sabana se negó; el del bosque cumplió. Un día Ẹwu dejó a Iná y se fue con el rey de la sabana. Iná llegó gritando su nombre y quemó todo lo que tenía el rey de la sabana. Ẹwu corrió con el rey del bosque, e Iná no pudo con él. Así el bosque se quedó con Ẹwu, su vestido de hojas.", "Oló y su único hijo. Oló tenía un solo hijo. Le pidieron una carnera blanca sin manchas, una chiva joven y un chivo joven, y le dijeron que ese hijo se volvería dos. Ofreció y poco después tuvo dos. Desde entonces el signo se llama Ọ̀kànràn Méjì, y a quien le sale tendrá un hijo más.", "Jìngbìnní y la mano llena. Jìngbìnní preguntó si su mano llegaría a tocar la riqueza. Ofreció sin recortar nada, y su mano, que había estado vacía y fría, se llenó de fortuna.", "Èjì Ọ̀kànràn en Ètilè. Le pidieron a Èjì Ọ̀kànràn ofrendar para volver pronto a casa de su viaje a Ètilè. Allá le fue tan bien y comió tan bien que ya no quiso regresar."], "pasajes": [{"titulo": "Verso 8.1", "texto": "Qṣunṣun-igbó-yi-koṣ'oje,\nOburokoṣ'ẹjẹ:\nfue quien por primera vez adivinó Ifá\npara el pueblo de la ciudad de Qwá.\nEllos fueron aconsejados a hacer sacrificios,\npara que un extranjero pudiera ser nombrado Rey\nCualquier cosa (todo) lo que el Babaláwo pida será el sacrificio.\nEllos escucharon y ofrecieron el sacrificio.", "origen_id": "d432e52b050e4b7006afeaff"}, {"titulo": "Verso 8.2", "texto": "Ọpunṣun-igbó-yi-koṣ'oje,\nOburokoṣ'eje:\ntueron los que adivinaron Ifá para Ṣakótó,\ncuando él iba de viaje para la ciudad de Owá\nA él se le aconsejó que sacrificara:\nuna paloma, ago-ala\n, una carnera,\ntres tortas de frijol.\nEl oyó el consejo y efectúo el sacrificio.", "comentario": "Después de realizar el sacrificio, los Babaláwos le aconsejaron a Ṣàkótó que guardara las tortas y que en su viaje no debía darle las tortas a Èṣù, que se las comiera delante de él. Cuando Ṣàkótó salió de viaje, se llevó las tortas. Él se encontró con el primer Èṣù en el camino y con la torta en la mano le dijo: “Èṣù si te doy esta torta tú pudieras detener que caiga la lluvia hasta que yo llegue al pueblo de Ọwá”, seguidamente él se comió la torta y se fue. Cuando Ṣàkótó llegó al segundo Èṣù en el camino, estiró su mano con una torta de judía a Èṣù y le repitió lo que le había dicho al primero, inmediatamente él se comió la torta de frijol. Él hizo lo mismo con el tercer Èṣù. Encolerizado el tercer Èṣù, causó una torrencial lluvia para eliminar a Ṣàkótó antes de que él arribara al pueblo de Ọwá.\nEn el pueblo de Ọwá, los Babaláwo habían predicho que la próxima persona a ser instalada como Rey en el pueblo de Ọwá llegaría fuertemente empapada por la lluvia. Los habitantes del pueblo de Ọwá hicieron al extranjero empapado su Rey.\n26 ago-ala: investigar qué ingrediente o elemento es este.", "origen_id": "026666a31c2b52915ab1f269"}, {"titulo": "Verso 8.3", "texto": "Mo daa pẹrẹ o ṣẹ pẹrẹ:\nadivinó Ifá para Olú-igbó (Rey del Bosque).\nMo daa perẹ o ṣẹ pẹrẹ:\nadivinó Ifá para Olú-odan (Rey de la sabana),\ncuando ellos fueron a seducir a Ewu, la esposa de Iná (fuego).\nLes fue aconsejado sacrificar:\nun manojo de escobas, medicina de Ifá,\nuna gallina junto con una tela negra.\nOlú-òdan rehúso ejecutar el sacrificio,\n', en presencia de su Esusu oni'gba ofon,\nél dijo: \"No\"\nde Wariwa oni'gba ida y lyọrẹ oni'gba itẹrẹ (varita mágica).\nOlú-igbó fue el único que realizó el sacrificio.", "comentario": "Un día Ewu, la esposa de Iná, dejó la casa de su marido por la casa de Olú-ọ̀dan. Iná salió para la casa de Olú-pdan a recuperar a su esposa. Cuando él llegó, grito el nombre de su esposa: \"Ẹwu, Ewu, Ewu\" Iná encendió a Esusu oni'gba ofon, Wariwa oni'gba ida, e lyorẹ oni'gba itẹrẹ. Ewu entonces corrió a Olú-igbó quien había hecho el sacrificio. Iná fue allí y grito: \"Ewu, Ewu, Ewu\", na de Ifa sobre Iná como fue ltes Veoeg Ewu estuvo disponible para Olú-igbó.\ntupido) se mantiene la oscuridad de la\nEwu: vestidura, ropaje. En estos versos, Ewu es el ropaje que hacen las hojas de los árboles y la vegetación para el bosque (igbó), que fue ganado por Olú-igbó (Rey del Bosque) para el bosque en esta historia al obtener a Ewu como esposa.\nrenren: rinrin: PEPEROMIA PELLUCIDA (L.) Kunth, Piperaceae.", "origen_id": "2ac3912890e826e015f3132e"}, {"titulo": "Verso 8.4", "texto": "[Nombre del adivino pendiente de lectura en el original]:\nadivinó Ifá para Oló,\ncuando él tenía solamente un hijo.\nLe fue aconsejado para que sacrificara:\nuna carnera blanca sin ninguna mancha negra,\nuna chiva joven (señorita),\ny un chivo joven.\nIfá dijo:\n“ese solo hijo se convertiría en dos”.\nÉl oyó y sacrificó.\nDespués de poco tiempo, fueron dos sus hijos.\nDesde ese momento\neste Odù se llama Ọkànrànméjì.\nIfá dice:\n“Cualquier persona a quien se adivine este Ifá\ntendrá un hijo adicional”.", "origen_id": "817b65b86c842ded13b2145d"}, {"titulo": "Versos complementarios 1", "texto": "´´` A\n    Ifá pé' owó\n             ' eléyìun ó ba ire.' Owóo\n                                   ' ' 'rè ó tòó nnkan ti n lé ti ò bá,' sùgbón\n                                                                            '   kó rúbo.\n                                                                                     '\n    Gbogbo' ebo\n              ' ò gbodò\n                   ' ' ' tàsé.\n\n' Òkànràn kan níhìín\n' Òkànràn kan' lóhùún\n' Òkànràn di Méjì o' se ìdí jàwàlá\n  A díá fún Jìngbìnní\n  Èyí ti´´`\n         n lo rèé 'fowo\n                      ' araa' rèé\n                               ' bèso\n' Owó\n    ' òun le 'te ire?\n  Wón\n   ' ní kó´´`  rúbo'\n  Ó sì gbébo\n         ' '    nbè\n                 '\n  Ó rúbo\n       '\n' Owóo\n    ' ' 'rè tó tutù\n' Owóo\n    ' ' 'rè tó ajé\n' Òkànràn     kan níhìín\n' Òkànràn kan' lóhùún\n' Òkànràn di Méjì o' se ìdí jàwàlá\n  A díá fún Jìngbìnní\n  Èyí ti´´`\n         n 'lo rèé 'fowo\n                      ' araa' rèé bèso\n  Jìngbìnní mòmò\n               ' '    dé o awoo re\n' Owó\n    ' mi tó tutù 'jé ó bàjé\n  Jìngbìnní dé ò awoo re\n' Owó\n    ' tó tutù 'jé ó bajé", "origen_id": "96fd4efe7fc6bca268d96c64"}, {"titulo": "Versos complementarios 2 · A", "texto": "Ifá dice que esta persona obtendría todas las fortunas que él había estado siguiendo.\n    Pero le aconsejan que realice sacrificio. Él no debe reducir su sacrificio.\n\n    Un Òkànràn localizó aquí\n    Otro Òkànràn localizó allí\n    Òkànràn se vuelve dos, mientras teniendo la base lánguida\n    Adivinación lanzada para Jìngbìnní\n    El que iba a cosechar las fortunas con sus manos\n    'Mi mano conseguiría a las fortunas? Ella preguntó\n    Ellos le dijeron que realizara sacrificio\n    Ella oyó hablar del sacrificio\n    Y lo realizó\n    La mano que no había estado lleno de riqueza\n    Ella se hizo inmensamente rica\n    Ella dijo que Un Òkànràn localizó aquí\n    Otro Òkànràn localizó allí\n    Òkànràn se vuelve dos y con la base lánguida\n    Adivinación lanzada para Jìngbìnní\n    El que iba a segar las fortunas con sus manos\n    Jìngbìnní esta realmente aquí el sacerdote bueno\n    Permita mi mano que está fría tocar fortunas\n    Jìngbìnní está aquí el sacerdote bueno\n    Permita la mano que está fría tocar fortunas.", "origen_id": "7ce148f1d6b7f77ead1c8ee0"}, {"titulo": "Versos complementarios 3 · B", "texto": "Bélébo\n  ' ' ' ò bá peni\n Àsèfín\n  '        won\n            ' ò yeni'\n Òrò\n' '    temí   ò se wò\n Kolombo ni n ó sojú\n A díá fún Èjì' Òkànràn\n Níjo    ´´`\n     ' ti n re ilé Ètilè'\n Wón' ní ó rúbo  '\n Kó lè baà tètè 'sérí wálé\n Ó wáá gbébo      ´´\n             ' ' nbè\n Ó rúbo'\n Ó dÉtilè' lo 'domo   '\n Ìgbà tóó dÉdtilè   ' loò' féléé wá mó\n                                    '\n O dÉtilè ' lo 'domo  '\n\n' Òkànràn Méjì B\n Si uno que requiere sacrificio no hace llamado en uno\n El problema de tener que realizar un sacrificio competente no es necesario\n El caso en que yo no compartí\n Mi cara no traicionaría ninguna ansiedad\n Adivinación lanzada para Èjì Òkànràn\n En el día él iba a Ilé Ètilè\n Le pidieron que realizara sacrificio\n Tal que él devolvería rápidamente a casa\n Él oyó hablar del sacrificio\n Y lo realizó\n Usted llegó Ètilè y se vuelve un niño que vale la pena\n Era cuando usted llegó Ètilè que usted no quiso devolver casa de nuevo\n Usted llegó Ètilè y se vuelve un niño que vale la pena.", "origen_id": "f4c26b001da6e06490d71cd4"}, {"titulo": "Relatos y ofrendas", "texto": "ÒKÀNRÀN MÉ JÌ\n\nLa — madera — dura — del — bosque — usada — para — hacer — Osunsun — báculo — no — da — jugo —\nmientras — un — árbol — usado — para — hacer Atori — báculo, - sacará — sangre, consulta Ifá para\nSakoto en el día que él estaba haciendo un viaje al pueblo de Owa. Ifá aconsejó a Sakoto hacer\nebo. Sakoto hizo ebo. Mientras Sakoto estaba viajando a Owa, él conoció a Esú y le dio un pastel\nde fríjol. Esú tomó el paste y se cambio a si mismo en una mujer. Esú, posando como una mujer,\nle preguntó a Sakoto por cualquier cosa que le pudiera dar. Sakoto le dio a la mujer un pastel de\nfríjol. Esú tomó el pastel y se cambio a si mismo en un niño pequeño. Esú, posando como un\nniño, le pregunto a Sakoto por cualquier cosa que le pudiera dar. Sakoto le dio al niño un pastel\nde fríjol. En su viaje, Sakoto dio tres pasteles de fríjol. Esú le pregunto a Sakoto a donde iba.\nSakoto le dijo que estaba haciendo el viaje a Owa. Esú le dijo a Sakoto que las personas de Owa\nestaban sufriendo, por un largo tiempo, por falta de lluvia. Esú apuntó a una siembra de aso\n(pequeñas calabazas usadas para cargar medicinas) y le dijo a Sakoto que fuera junto al ado. Esú\ndijo que alguna ado debe decir “Arráncame,” y otras se quedarían calladas. Sakoto fue mandado a\ntomar uno las ado que se quedaron calladas y le cortaría la parte de arriba. Esú dijo que cuando se\naproximara a la entrada a Owa, debería levantar la ado sobre su cabeza y anunciar que él estaba\ntrayendo la lluvia. Sakoto hizo lo que le fue mandado y entró al pueblo diciendo “Personas de\nOwa traigo lluvia.” Inmediatamente empezó a llover. El siguiente día el Oba de Owa mandó al\npueblo a pregonero para decirles a la personas de Owa que quería conocer al extranjero que dijo\nque había triado la lluvia. Sakoto fue traído al Oba y el Oba dividió todas sus propiedades y\npertenencias, dándole la mitad a Sakoto. Fue en ese día que Sakoto recibió las bendiciones que él\nhabía estado buscando. Sakoto empezó a bailar y cantar en alabanza al Awo, mientras el Awo\nalabó a Ifá, mientras Ifá alabó a Olodumare. Cuando Sakoto empezó a cantar, Esú puso una\ncanción en su boca. Sakoto canto:\nSakotó mo léwa, awo ire dun bo n'ife.\nSakotó mo léwa, awo ire dun bo n'ife.\nSakotó es belleza, la buena adivinación es dulce para alabar.\nSakotó es belleza, la buena adivinación es dulce para alabar.\n\nComentario:\n\nIfá dice que esta persona está a punto de irse en un viaje. Ifá dice que esta persona debe hacer ebo\npara que el viaje le traiga fama y abundancia. Ifá dice que cuando esta persona llegue a su\ndestino, el podrá resolver un problema que traerá buena fortuna. Ifá dice que esta persona debe\nofrecerle pasteles de fríjol a Esú antes de hacer el viaje. Ifá dice que cuando esta persona llegue a\nsu destino, tendrá muchos beneficios.\n\n91\n\nEtutu ofrecimiento: 4 eiyelé (pichón), 4 adie (ave), 1 epo (botella de aceite de palma), 1 plato\nblanco, 4 eko (pastel de harina de maíz) y 20 nira (dinero), ofrecido a Ogún y Esú.\n\n(Étùtù (oferendas); 4 eiyele (pombo), 4 adiye (ave), 1 epo (garrafa de zeite de dendé), 1 prato\nbranco, 4 ekó (bolos de milho) e 20 nira (dinheiro nigeriano) oferecidos a Ògún ea Ésù. )\n\nHay — maneras — diferentes — para — encontrar — la — tierra — de — los — ancestros consulta Ifá para\nIgbegbe (rata) en el día que él iba a vender la rata en el mercado. Ifá aconsejó a Igbegbe hacer\nebo para que él viera las cosas claramente. Igbegbe hizo ebo y tuvo una visión clara.\n\nComentario:\n\nIfá dice que esta persona está viendo las cosas claramente. Ifá dice que esta persona debe hacer\nebo para aclarar las confusiones.\n\nEtutu (ofrecimiento): 2 eiyelé (pichón), 3 adie (ave), 1 epo (botella de aceite de palma) mariwo\n(hojas secas de palma) 1 plato blanco y 25 nira (dinero), ofrecido a Ògún y Esú.\n\n(Ett (oferendas); 2 eiyele (pombo), 3 adie (ave), 1 epo (garrafa azeite de dendé), mariwo\n(folhas secas de palmeira), 1 prato branco e 25 nira (dinheiro nigeriano), oferecidos a Ogún\nea Esu.)\n\nI I\nI I\nI I\nTI TI", "origen_id": "73c5485ef5ec2928d212878e"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Okana Meji significa que habrán porblemas, casos en la corte,\n             sufrimiento y malas vibraciones. Los hijos de Okana Meji siempre\n      pondrán un dedo sobre su cabeza y dirán que es correcto. Su gente con\n        frecuencia piensan que los hijos de Okana Meji son agresivos porque\n            tratan de prevalecer sobre los demás. En muchas situaciones ellos se\n       rebelarán contra las convenciones de la sociedad. Los niños de Okana\n        Meji deben tener mucho cuidado con su salud para que no se vuelvan\n                                                             enfermos crónicos.\n                    WO – Es tiempo de establecer el compromiso de mitigar los\n                                                                     problemas.\n        Okana Meji es el octavo en el orden inalterable de Ifá. Okana Meji es\n un llamado al cliente. Ifá dice que el cliente está sufriendo por falta de un\n        niño, dinero y otras buenas cosas de la vida, pero si el cliente cree en\n     Orunmila todos sus problemas serán resueltos, vencerá a sus enemigos y\n\ntendrá el control sobre todas las dificultades, el cliente deberá ofrecer\n                                                   sacrificios a Şangó y Eşu.\n\n\n8.1 · Osunsun igbo yi kos´oje Oburokos´eje, fueron los que adivinaron Ifá\n             para el pueblo de la ciudad de Owa. Ellos fueron advertidos de\n       sacrificar para que un extranjero pudiera ser nombrado rey. De todas\n          maneras, todo lo que el Babalawo quisiera pudiera ser sacrificado\n                  como ebo. Ellos oyeron el aviso y ofrecieron el sacrificio.\n\n\n8.2 · Osunsun igbo yi kos´oje Oburokos´eje, fueron los que adivinaron Ifá\n       para Sakoto cuando él iba a ir al pueblo de Owa. A él se le aconsejó\n         que sacrificara una paloma, una carnera y tres tortas de judía (ago-\n                                                                         ala).\n        Él oyó el consejo y efectuó el sacrificio. Los babalawos también le\n       advirtieron a él que se comiera las tortas y que no se los diera a Eşu.\n       Como él se fue de viaje, llevó las tortas con él. Él se encontró con el\n       primer Eşu y dijo “si te doy esta torta tú podrías causar la lluvia para\n          eliminarme antes de que llegue al pueblo de Owa. Él entonces se\n        comió la torta y se fue. Él llegó al segundo Eşu, estiró su mano con\n          una torta judía a Eşu y le repitió lo que le había dicho al primero.\n      Entonces él se comió la segunda torta de judía. Él hizo lo mismo con\n      el tercer Eşu. Encolerizado el tercer Eşu, causó la lluvia para eliminar\n        a Sakoto antes de que él arribara al pueblo de Owa. Los babalawos\n       habían predicho que la próxima persona a ser instalada como rey en\n\nel pueblo de Owa llegaría fuertemente empapado por la lluvia. Los\n  habitantes del pueblo de Owa hicieron al extranjero empapado su rey.\n\n\n8.3 · Mo Daa Pere o Se Pere adivinó Ifá para Olu-igbo (rey del bosque)\n        Mo Daa Pere Ode Pere adivinó Ifá para Olu-Odan cuando ellos\n   fueron a seducir a Ewu, la esposa de Ina (fuego) se les aconsejó que\n      sacrificaran un paquete de escobas y hojas de Ifá (machacar hojas\n        renren en agua), una gallina y una ropa negra. Olu-Odan rehusó\n                                                   ejecutar el sacrificio.\n  El dijo: no en presencia de su Esusu oni´gba–Ofon, Wariwa Oni´gba-\n     ida e Iyore Oni´gba–itere (vara mágica). Olu-igbo fue el único que\n   realizó el sacrificio. Un día Ewu, la esposa de Ina, dejó la casa de su\n      marido por la casa de Olu–Odan, Ina se preparó y fue a la casa de\n     Olu-Odan para recuperar a su esposa. Cuando él llego allí, gritó el\n   nombre de su esposa: Ewu, Ewu, Ewu, Ina encendió Esusu Oni´gba-\n  ofon, Wariwa Ori´gba-ida e Iyore Oni´gba-itere Ewu entonces corrió\n   a Olu-igbo, quien había hecho el sacrificio. Ina fue allí y grito: Ewu,\n       Ewu, Ewu, Olu–igbo entonces roció la medicina de Ifá sobre Ina\n  como fue instruído por el Babalawo. Él recitó 3 veces: Mo Daa Pere\n       O Se Pere. Mo Daa Pere O Se Pere, Mo Daa Pere O Se Pere. El\n     fuego (Ina) murió, entonces Ewu estuvo disponible para Olu-Igbo,\n    Olu Igbo el bosque tupido aún mantiene la oscuridad que sacrificó.\n\n\n8.4 · Okitibirikiti fue quien adivinó Ifá para Olu cuando él tenía sólo un\n\nhijo. Él fue advertido para sacrificar una oveja blanca sin ninguna\n              mancha, una chiva joven y un chivo. Él fue asegurado que su hijo\n              único, se convertiría en dos. Él escuchó la advertencia y realizó el\n                 sacrificio. No pasó mucho tiempo, sus hijos fueron dos. Desde\n         entonces, este Odu ha sido llamado Okanranmeji. Persona a quien le\n                                      salga este Ifá siempre tendrá un hijo más.", "origen_id": "bdc51f26e55da7620b1f5993"}, {"titulo": "Relato en inglés 1", "texto": "“Thunder does not crash during the harmattan;! lightning does not flash se-\ncretly; male and female partridges do not have upright combs on their heads” was\nthe one who cast Ifa for black Ereje, mother of Ram, she who gave birth to Ele-\nphant and Buffalo, and whose third child was Ram, These three children planted\nochra, and the God of Thunder came from the sky to steal it; when their mother\nsaw that ochra was being stolen, she said she did not know what was picking it.\nElephant began to watch the field, and one day the God of Thunder came back to\npick ochra; when he saw Elephant, he roared at him, and Elephant fled into the\nforest. Buffalo also went to watch the farm; when the God of Thunder saw Buf-\nfalo, he roared at him, and he, too, fled into the forest. When it came Ram's\nturn, he took She- goat along with him because Me was his servant; and when the\nGod of Thunder was coming, he brought Dog along. When the God of Thunder\nreached the Farm and saw Ram, he roared at him, but Ram\n\nroared back; and when he began stabbing Ram with his knife, Ram began butting\nhim. When they had been fighting a while, the God of Thunder’s knife broke, and\nRam’s horn broke also, The God of Thunder sent Dog to bring him another knife,\nbut when Dog reached the road, he found a bone and lay down to eat it. Ram like-\nwise sent She-goat to bring him another horn; and when humans held out yam rinds\nto her, She- goat replied, “Today is no day for rinds, ‘bekeke bekekerike.”? So\nShe-goat brought another horn to Ram; and when Ram had fastened the horn to his\nhead, he chased the God of Thunder away. Since that time the God of Thunder has\nremained in the sky, and when thunder crashes and lightning flashes,? Ram paws\nthe ground with his feet, saying, “Our fight is not yet finished.”*\n\nIfa says we should sacrifice, lest something evil come from the farm and\nlest three children of the same mother should perish, and their mother should\nalso become affected by the evil. One he-goat, one shilling three pence, and six\nyams is the sacrifice; we should take it to the farm road,", "comentario": "1. During the dry season, from about December through February, the dry,\ndust-laden harmattan wind blows down from the Sahara. Thunderstorms are\nassociated with the rainy season, particularly during June and July.\n2. The sound that a goat makes when it bleats.\n\n3. Note the relationship here between the tale and the names of the diviners.\n\n4. This verse explains why the God of Thunder lives in the sky, and explains\nthe behavior of rams during thunderstorms. It differs somewhat from the explana-\ntion sometimes offered that the sound of thunder is caused by the God of Thunder’s\nram pawing the ground in the heavens. Rams are the main sacrificial animals for\nthe God of Thunder, ochra is another of his favorite foods, and dogs, though not\nused as sacrifices, are sacred to him. Compare the versions of this tale recorded\nby Parkinson (1909: 166-169) and Itayemi and Gurry (1953; 53-55) and the variant\nrecorded by Frobenius (1926: 247-248),", "origen_id": "2a3eb00705535c7d09cb9120"}, {"titulo": "Relato en inglés 2", "texto": "“An old cow does not speak; look at the gorgeous decoration on the neck of\nthe horse” was the one who cast Ifa for Bilgp¢, the child of Ọrunmila. They said\n\nhe should sacrifice two rats, two fish, two hens, and twenty cowries! in addition\nto one shilling, because he should not go to farm.\n\nInstructions for making the sacrifice: One chicken will be killed and split\nopen at the breast, and palm oil will be dipped inside it; we will take it to Eshu.\nWe will give the other chicken to the person for whom this figure was cast, so\nhe may take it to sacrifice to Ifa.\n\nIfa says that this is someone who should not go to farm, and who must not\ntouch the dew with his feet? And we say Ifa is thinking of someone; he should be\nsacrificing to Ifa.", "comentario": "1. This is another example of punning and word magic. Twenty cowries\n(oko) are added to the sacrifice of someone who must not go to farm (oko).\n\n2, As one does when he goes to the farm early in the morning. The client\nhere is instructed to give up farm work and to devote himself to the worship of\nIfa. Cf. verse 6-3,", "origen_id": "9ceab780e6a8a777afdbade4"}, {"titulo": "Relato en inglés 3", "texto": "\"One 'winrin,' one 'winrin'\"1 was the one wgo cast Ifa for Benniseed when\nshe was going to the farm of ritual? to take land to settle so that she might bear\nchildren. They said that she would bear children if she sacrificed two rats, two\nfish, and twenty cowries? in addition to one shilling. Ifa says someone is men-\nstruating at this moment; if she is able to make the sacrifice, she will bear a\nchild. Benniseed sacrificed.*\n\n_ 1. Winrin winrin was explained as a tinkling sound such as is made by rat-\ntling a small chain.", "comentario": "2. Because benniseed is the principal tabu of the God of Smallpox, it is pro-\nhibited to plant benniseed near Yoruba towns. It is also used in “medicine” to\ncause an enemy to have smallpox.\n\n3. Cf. n. 2, verse 86-2,\n\n4. The implication of this verse is that it is because Benniseed or Sesame\n(Sesamum indicum) made the sacrifice that she bears so many “children,” or seeds.", "origen_id": "be8a3ca209d5907702b27f7e"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ṣakótó: una paloma, una carnera y tres tortas de frijol (àkàrà); cuatro palomas, cuatro aves, aceite de palma, un plato blanco, cuatro ẹ̀kọ y dinero, a Ògún y a Èṣù.", "El rey del bosque: un manojo de escobas, medicina de Ifá, una gallina y una tela negra.", "Oló: una carnera blanca sin manchas, una chiva joven y un chivo joven.", "Para ver claro: dos palomas, tres aves, aceite de palma, màrìwò, un plato blanco y dinero, a Ògún y a Èṣù.", "Ofrendas a Ṣàngó y a Èṣù para vencer a los enemigos."], "pasajes": [{"titulo": "Ofrenda en el verso 8.1", "texto": "Qṣunṣun-igbó-yi-koṣ'oje,\nOburokoṣ'ẹjẹ:\nfue quien por primera vez adivinó Ifá\npara el pueblo de la ciudad de Qwá.\nEllos fueron aconsejados a hacer sacrificios,\npara que un extranjero pudiera ser nombrado Rey\nCualquier cosa (todo) lo que el Babaláwo pida será el sacrificio.\nEllos escucharon y ofrecieron el sacrificio.", "origen_id": "ed3de88f5999fb8fe019ba74"}, {"titulo": "Ofrenda en el verso 8.2", "texto": "Ọpunṣun-igbó-yi-koṣ'oje,\nOburokoṣ'eje:\ntueron los que adivinaron Ifá para Ṣakótó,\ncuando él iba de viaje para la ciudad de Owá\nA él se le aconsejó que sacrificara:\nuna paloma, ago-ala\n, una carnera,\ntres tortas de frijol.\nEl oyó el consejo y efectúo el sacrificio.", "origen_id": "c9655e10984a6cd5eb2203c1"}, {"titulo": "Ofrenda en el verso 8.3", "texto": "Mo daa pẹrẹ o ṣẹ pẹrẹ:\nadivinó Ifá para Olú-igbó (Rey del Bosque).\nMo daa perẹ o ṣẹ pẹrẹ:\nadivinó Ifá para Olú-odan (Rey de la sabana),\ncuando ellos fueron a seducir a Ewu, la esposa de Iná (fuego).\nLes fue aconsejado sacrificar:\nun manojo de escobas, medicina de Ifá,\nuna gallina junto con una tela negra.\nOlú-òdan rehúso ejecutar el sacrificio,\n', en presencia de su Esusu oni'gba ofon,\nél dijo: \"No\"\nde Wariwa oni'gba ida y lyọrẹ oni'gba itẹrẹ (varita mágica).\nOlú-igbó fue el único que realizó el sacrificio.", "origen_id": "fb26479163307038b3e7b050"}, {"titulo": "Ofrenda en el verso 8.4", "texto": "[Nombre del adivino pendiente de lectura en el original]:\nadivinó Ifá para Oló,\ncuando él tenía solamente un hijo.\nLe fue aconsejado para que sacrificara:\nuna carnera blanca sin ninguna mancha negra,\nuna chiva joven (señorita),\ny un chivo joven.\nIfá dijo:\n“ese solo hijo se convertiría en dos”.\nÉl oyó y sacrificó.\nDespués de poco tiempo, fueron dos sus hijos.\nDesde ese momento\neste Odù se llama Ọkànrànméjì.\nIfá dice:\n“Cualquier persona a quien se adivine este Ifá\ntendrá un hijo adicional”.", "origen_id": "bdcb1a9e8737c651fe33780e"}, {"titulo": "Ofrenda complementaria 1", "texto": "2 eiyelé, 3 adie, 1 epo, mariwo (hojas secas de palma), 1 plato blanco y 25 nira\n\nDestinatario: Ògún y Esú", "origen_id": "8ef57d5ab09e72434906600a"}]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó y Èṣù vencen a los enemigos de este signo. Ògún recibe las ofrendas de viaje. Iná, el fuego, persigue a quien se lleva a su esposa.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Ossosi", "origen_id": "ed71c6ad0127b59744051df0"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortas de frijol, escobas, tela negra, hojas de rinrin (Peperomia pellucida) machacadas en agua, màrìwò, calabacitas. Si hay infecciones repetidas, conviene la atención médica."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 8.3", "texto": "machacar hojas renrẹn? en agua.", "origen_id": "3d79d390ec3247497fee73c0"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 8.1 (yorùbá): Qṣunṣun-igbó-yi-koṣ'oje, / Oburokoṣ'ẹjẹ: / li o difá fún wọn l'aláde Qwá. / A niki wọ̀n rúbọ, / ki wọ̀n le ri àlejò wa le'ye. / Ohunkohun ti Babaláwo ba fẹ ni ebo. / Wọ̀n gbọ̀ wọ̀n rú.", "Verso 8.2 (yorùbá): Oṣunṣun-igbó-yi-koṣ'oje, / Oburokoṣ'ẹjẹ: / Il o difá fún Ṣàkótó / nigbi oun mi lo silu Qwá. / Wọ̀n niki ó rú / Ẹyẹlé, aṣọ-ala, àgùtàn / atl akara mẹta / Ô gbó ó rú.", "Verso 8.3 (yorùbá): Mo daa pẹrẹ o ṣẹ pẹrẹ: / li o dífá f'Olú-igbó. / Mo daa perẹ o ṣẹ pẹrẹ: / li o dífá f'Olú-odan, / nigbi wọn mi lọ gba Ewu tiiṣe Obirin Iná. / A niki wọn rú: / Iṣu-owo ati ewé Ifá, / abo-adiyẹ pẹlu aṣo dúdú. / Olú-ọ̀dàn kọ ko rú, / ó ni Loju Esusu oni'gba ofon, / loju Wariwa / oni'gba ida, loju lyọrẹ oni'gba itẹrẹ? / Olú-igbó nikinṣoṣo li o rúbo", "Verso 8.4 (yorùbá): u umo ro lp okangogo. / auilân kon ti ko ni dúdú rara, ti o jẹ fúnfün, / 1ewure / lan obükọ. / \"Omo rọ̀ kangogo yi a di mój\". / G ghọ̀ b rü. / Hẹ̀ ptợ raa đi Méjì / trọ DiĐ đi móii ni a ti npe. / Bẩu yt nE Okanrormeji / Apiva Ha yt nиpe / Hà naâ fun pmọ rọ̀ yoo di móji\".", "REZO: OKANA MEYI OÑI KANE OKANA NI OKUTE OKAPA MEYI NI ESHU BI EBOADA ESHU BI ADIE PAKIKO, ADIE ONADERE OKANA MEYI.", "REZO (DONDE BAJO OLOFIN): SE TOCA EL PECHO Y SE DICE: OLOFINA. SE TOCA EL SUELO Y SE DICE: NOFIN KABE MOFIN KABA GODO GODO DA IFA MOFIN KABA GODO IBAE ALAFI KISIEKO BEKE LORIE OÑA KAN ORI MI AFARE MAKO OWANI MOYUBA ABE IBA MI OMATUN OMO ASE ABA MISHE FUN NI OMO OMI NI MI.", "REZO (DILOGUN IYESA): OKANA SODE AYA LODE ARO GULE GUYE.", "REZO: OKANA MEYI OÑI KANE OKANA NI OKUTE OKAPA MEYI NI ESHU BI EBOADA ESHU BI ADIE PAKIKO, ADIE ONADERE OKANA MEYI.", "REZO: OKANA IRE IFA OKANA IRE AWO. OKANA IRE SHANGO. OKANA IRE ESHU BI OKAN NI OÑI KANA UNBATI OSODDE BOTALOKUN UNLO.", "REZO: OKANA MEYI SHAKUTE MAYAGUA GUARA AYETA AKUSE LODINE A SHULU ADA OSHURE ANI LADA BADUDU ONIFUNFAN ABAÑERE BEÑISO BARA TETICARUN.", "REZO: SHAKUTA MAYAWALA OLIAPA AWO AKIKO IRE DODI ASHUBI OIDA ASHURE LODAFUN AKUKO UMBATI LOSORDE OLUO IKUEYI DE OLOWA AKARA META LEBO AIKORDIE MEYI ONILEMO OWO.", "REZO: OKANA MEYI SHAKUTE MAYAWALA OYO PAKARO AWO DODI ENI ASHUMBI ADA SHURE ODUDUWA ONI FUN FUN OLA NIREBARA PETAN KARULO.", "REZO: SHACUTE MAYAWALA EYO PAKICO AWODA SHURE AWO KIKO DODI OSU ASHUBIDA SHURE ONI DUDU BABADU INI FUN FUN OU FUNFUN ALAÑIRI BARALAQUETU CARUNLO.", "REZO: SHACUTE MAYAWALA AYAPA KIO O AWO AKIKO DORI ENI ACHURI EBALESHELE ONIARAWO ORUBE AIKORDIE OSINCHE AWADO UNA RAJA DE LEÑA.", "REZO: SHAKUTE MAYAWALA EYO KUA KIO O AWO AWO AKIKO DODI ACHIBI ADA ACHUREONI ARA AWO.", "REZO: OKANA MEYI ESHAKUMAWALA OYO, AKIKO AREALERO DA ACHUBE ODA ADUIBO EBO AKUKO EKU EYA EPO AWADO OWO LA META.", "REZO: OLUFIRAN UMBOWAIYE AKUKO KIE OWUNKO KIO UMBOSA DENI- FAILE AFEKE AWO OLUFINA GODO GODO BAO KABI YESI OKANLE LOGURON OTA LEBO AKUKO LEBO OWUNKO EYELE OKAN APO LEBO OKAN GURO LEBO LODAFUN APA KAFEREFUN OLORUN", "SUYERE: OLOFIN MOFIN KARE OLOFINA MOFIKARE OKANA MEYI EDA IFA MEFIN KARE KAWO KABIYESILE.", "REZO: BABA OKANA MEYI ADA ASHUREO ELEGBA AWO AKUKO ADIE PAKUKO SHUKUTU MAYAKUALA ADIE ONADORE OKANA IRE BELELE OYOURO INLE MOGBA OKANA IRE ELEGBA SHEPE ELEGBA ISOKUN OSODE OLORE BO ASHE ELEGBA AWO AKUKO IBA FUNFUN LODAFUN ELEGBA IFA NI KAFEREFUN ORUNMILA."]}]$q$::jsonb),
(9,'136770840d85cb4db7fb79cf50516b71','d417085bc9ec2b42e743d3b348541e4e',$q$[{"titulo": "Idea central", "texto": "Ògúndá Méjì advierte sobre peleas, disputas y una hostilidad cercana: la persona debe vigilar a su alrededor, cuidarse de traidores y amistades falsas, y no confiar sus secretos a quien no lo merece. Si enfrenta problemas de dinero y enemigos, debe ofrendar a Ògún y luego a su Orí para tener éxito. Está cargando demasiado trabajo y los problemas de otros. Es el signo de Ògún: sus hijos son fuertes, creativos, abren puertas para los demás y tienen muchos hijos.", "pasajes": [{"titulo": "Frase clave", "texto": "Ogunda crea la eliminación de obstáculos.", "origen_id": "e7b788c805907ac2dbc46662"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga demasiado trabajo y también los problemas de otros; debe ver qué le toca a él.", "Hay tensiones o desconfianza; conviene guardar confidencias y ver los hechos antes de acusar.", "Trabaja, pero no logra conservar lo que gana (relato del tigre).", "Necesita abrir camino en el trabajo, para sí y para otros (relato de Ògún y el machete).", "Espera una mejoría que parece cerca pero no termina de llegar (relato de Idena-Magbon).", "Pregunta por hijos o por el crecimiento de la familia (verso de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Abrir caminos y conseguir trabajo y bendiciones para otros.", "Muchos hijos.", "Dinero, pareja, casa o un título nuevos con la ofrenda.", "Llegar a viejo, con el pelo blanco como la tiza.", "Vencer a los enemigos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Traiciones y amistades mentirosas.", "Confiar secretos a quien no debe.", "Cargar los problemas de todos.", "Enfermedad o muerte repentina si no ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "El que reparte con justicia evita la pelea: Ògún partió el pescado en dos para que los hombres no se pelearan, y por eso abrió caminos y recibió riquezas. Un solo eslabón de la cadena nunca se rompe."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Ògúndá Méjì advierte a las personas sobre peleas, disputas y de una hostilidad inminente. Durante una sesión de adivinación, sí este signo aparece para alguna persona él o ella serán advertidos de vigilar y observar bien a su alrededor para prevenirse de los traidores o amistades mentirosas. Ifá le dice a esta persona que debe tener cuidado de depositar sus confidencias y secretos en alguien indigno de su confianza.\nIfá dice que si el cliente está enfrentando una lucha por problemas financieros y la oposición de enemigos, Ògúndá Méjì le dice que él o ella deben ofrecer un sacrificio a Ogún y después propiciar a su cabeza (Ori) para obtener el éxito y la prosperidad.", "origen_id": "80394540badbfb9ec2ab2fdf"}, {"titulo": "Características generales", "texto": "Otros nombres: Ògúndá Méjì; ÈjiÒgúndá / Èjìoko; Ògúndá Méjì advierte a las personas sobre peleas, disputas y de una; hostilidad inminente. Durante una sesión de adivinación, sí este signo; aparece para alguna persona él o ella; serán advertidos de vigilar y; observar bien a su alrededor para prevenirse de los traidores o amistades; mentirosas. Ifá le dice a esta persona que debe tener cuidado de depositar; sus confidencias y secretos en alguien indigno de su confianza.; Ifá dice que si el cliente está enfrentando una lucha por problemas; financieros y la oposición de enemigos, Ògúndá Méjì le dice que él o ella; deben ofrecer un sacrificio a Ogún y después propiciar a su cabeza (Ori); para obtener el éxito y la prosperidad.; WO: El cliente está sobrecargado de trabajo, de preocupaciones y de; problemas personales de otras personas.; En el orden de Ọ̀rúnmìlà, el Odù Ògúndá Méjì ocupa el 9no lugar..\nEn el orden de Ọ̀rúnmìlà, el Odù Ògúndá Méjì ocupa el 9no lugar.\nEste Odù es la encarnación de Ogún; el dios del hierro y la guerra. La mayoría de los hijos de Ògúndá Méjì son adoradores de Ogún, quien es reconocido por su fuerza, coraje, poder transformador y talento creativo.\nLas persona encarnadas por Ògúndá Méjì con una inusual imaginación creativa son capaces de abrir disímiles puertas y de conseguir bendiciones y oportunidades de empleos para los demás. Ellos siempre serán bendecidos con muchos hijos.", "origen_id": "5a0702c9477ab7313c30e6b9"}, {"titulo": "Interpretación tradicional", "texto": "Ogunda es una omisión de Ogun significando que el Espíritu del Hierro crea. Ogunda es simbolizada por la idea de limpiar un camino o abrir una carretera. Históricamente es asociada con el proceso de organizar estructuras sociales dentro de ciudades o pueblos. En el nivel personal, es asociada con el progreso dirigido a la satisfacción del destino. La manifestación negativa de Ogunda es, destrucción sin intención.", "origen_id": "6744e7587dda61015b48e259"}, {"titulo": "Orientación complementaria", "texto": "Ogunda es la eliminación de obstáculos que bloquean a una persona en el movimiento hacia su destino más alto y la satisfacción de su potencial más alto. Los obstáculos  pueden  ser ya sea internos o externos y es importante identificarlos correctamente. Un problema nunca puede ser resuelto si el origen del problema no es identificado. La negatividad en Ogunda ocurre cuando una persona cree que los obstáculos no pueden ser vencidos. Esto crea enojo y conflicto innecesario.", "origen_id": "d7056cddbd216c17ec4334da"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ògún parte el pescado. Ifá le pidió a Ògún un machete, un gallo y ñame asado, y le dijo que el machete sería la llave de su éxito y que siempre lo llevara consigo. Comió el ñame asado y, cuando tuvo sed, fue a beber al río. Ahí vio a dos hombres peleando por un pescado que habían atrapado. Les pidió paciencia y que lo compartieran, pero ninguno cedió: uno decía que venía del este y el otro del oeste. Ògún sacó su machete y partió el pescado en dos. El primero le agradeció y le pidió que abriera un camino desde ahí hasta su pueblo, prometiendo enriquecerlo; el segundo le pidió lo mismo. Ògún aceptó. Desde entonces lo llaman 'el que partió el pescado en dos para que los hombres no pelearan'.", "Ògún, enviado a abrir el mundo. Ọlọ́fin Àjàlọ́run iba a enviar a su hijo Ògún a abrir el camino de la vida en el mundo. El adivino dijo que encontraría mucha oposición y no podría terminar solo el trabajo, y que ofreciera un carnero y un eslabón de cadena para tener salud y no morir de repente. Lo hizo. 'Un solo eslabón nunca se quiebra.'", "Ògún, el que arregla la vida de los demás. Le dijeron a Ògún que si ofrendaba nunca moriría, y que todos lo llamarían para que les arreglara la vida y les abriera el camino, aunque ninguno se detendría a ver sus propios problemas. Ofreció chivas y jícaras con tapa, que se pusieron en las cuatro esquinas del mundo.", "Los hijos de Ọ̀rúnmìlà. Le dijeron a Ọ̀rúnmìlà que su esposa le daría tantos hijos que no llegaría a conocerlos a todos. Ofreció una gallina de guinea y 2,000 cauríes. Alarẹ es el nombre del primogénito de Ọ̀rúnmìlà, y a los hijos de este signo se les llama 'hijos de Alarẹ'.", "Lo nuevo que llega fresco. 'Jala suavecito; está muy fresco. ¿Como qué? Como el dinero nuevo que vamos a tener.' Así sigue el verso con la esposa nueva, el hijo nuevo, la casa nueva y el título nuevo, cada uno con su ofrenda. 'El pẹrẹgún nunca usa la ropa del año pasado': cada año le crece corteza nueva. 'Mi cabeza se pondrá blanca como la tiza de Benin; vengan todos a alegrarse por mi cabeza.'", "Ọ̀rúnmìlà ante sus enemigos. 'Al azadón se le golpea plano, al machete de un modo y a la campana de bronce dando vueltas; si se juntan, se vuelven uno solo.' Ọ̀rúnmìlà iba a enfrentar a sus enemigos y le dijeron que los vencería si ofrecía tres gallos, 6,600 cauríes y una bolsa de tela ẹtù. Las bocas de los que usan iru y de los que usan sal quedarían cerradas.", "Ẹ̀là, el niño del elefante. Un día los tres cazadores de Ọlọ́fin hirieron a un elefante que no murió; llegó hasta la plaza del palacio y apoyó la trompa en la pared. Llamaron a los adivinos, abrieron al elefante y en sus entrañas hallaron un bulto envuelto en tela blanca; dentro había una jícara tapada y en ella un recién nacido con barba y cabello blanco, con ocho nueces de palma en cada puño. Ọlọ́fin mandó llamar a Ọ̀rúnmìlà, que cantó: '¿Cómo llamamos al recién nacido? Es Ẹ̀là, hijo de Origi'."], "pasajes": [{"titulo": "Verso 9.1", "texto": "Alagbára ni nsọkun Ade:\nfue la persona que adivinó Ifá para Ògún.\nA él se le mandó sacrificar\nun alfanje (machete), gallo, ñame asado.\nIfá dijo:\n“el alfanje será la llave para el éxito de Ògún”,\n“él debe caminar siempre con el alfanje”.\nLe fue aconsejado que comiera ñame asado.\nÉl lo comió, cuando él tuvo sed,\ny fue a beber agua del río.\nDespués de beber el agua del río,\nél vio dos personas peleando por un pescado que habían capturado.\nÒgún les dijo que fueran pacientes,\nque fueran para sus casas y compartieran el pescado.\nEllos lo rechazaron.\nEl primer hombre le dijo que él venía del Este\ny el otro le dijo que él venía del Oeste.\nDespués de oír sus excusas,\nÒgún tomó el alfanje que le habían aconsejado llevar siempre\ny picó en dos el pescado para ellos.\nEl primer hombre le agradeció el gesto\ny le invitó a abrir un sendero desde allí\nhasta a su casa natal.\nEste hombre le prometió enriquecerlo si cumplía sus deseos.\nTambién le dijo que él lograría valiosas cosas en la vida\npor su buen consejo para que no pelearan,\nlo cual estimulaba la confianza en él.\nEl segundo hombre sabiamente agradeció a Ogún,\ny le hizo igual petición,\nOgún acordó hacer lo que ambos le solicitaron.\nDesde aquel día, Ogún es llamado por \"Ògúndaméji\"\nel que dividió el pez en dos para que los hombres no pelearan.", "origen_id": "2dba75d5d5b13867e47c540f"}, {"titulo": "Verso 9.2", "texto": "Agogo-owó-koṣeif'apokosi:\nadivinó Ifá para Ọlófin,\ncuando Ọlófin Àjälọ̀run\nse propuso enviar su hijo, Ogún,\npara abrir el camino de la vida hacia el Mundo.\nEl adivino dijo:\n\"Ogún no podrá completar el trabajo asignado,\npor la fuerte oposición que recibirá en el Mundo\".\nPero él debía hacer un sacrificio\npara mantenerse saludable (contra la enfermedad)\ny para evitar la muerte súbita (repentina):\nun carnero y el eslabón de una cadena.\nEl hizo el sacrificio.\nEllos le dijeron: \"Un solo eslabón nunca se quiebra\"", "comentario": "aralile: cuerpo sano, estar saludable, sentirse bien, tener salud física y mental.\n30 aitètèkú: (ai+tètè+kú) evitar la muerte repentina, la muerte súbita, no morir antes de tiempo. ai: negación; tètè: en tiempo, puntual, en el momento oportuno: kú: morir.", "origen_id": "a30d9fe869a86884a00b7406"}, {"titulo": "Verso 9.3", "texto": "Okelegbongbo-ap'Òfún-kilo:\nhiso la adivinación de Ifá para Ogún.\nEl ailivino dijo: \"Si hace sacrificio, nunca morirá.\nTodo el mundo lo llamará a él siempre\nparn que les ayude arreglar sus vidas\n(para que les ayude a corregir el carácter)\ny abrirte el camino\nPero ninguno de ellos se iba a detener\nsue propios problemas\",\nrilVarle\ntro chivas,\nu (gbiras con tapao),\nen sacrificio.\nrifgie,\naerifico\nỌlonn si\n• cuatro esquinas del mundo.", "origen_id": "ded61d3b32a09517259759dd"}, {"titulo": "Verso 9.4", "texto": "Ikoko-Ìdí-ṣ'akun-bẹrẹ\nadivinó Ifá para Ọ̀rúnmìlà.\nLe dijo: adivinó\n\"su esposa dará tantos hijos\nque él no llegará a conocerlos a todos\"\nPor eso, le dijo que sacrificara:\nuna gallina de guinea y 2000 cowries.\nỌ̀rúnmìlà escuchó e hizo el sacrificio.\nAlarẹ es el nombre con que nosotros\nllamamos al primogénito de Ọ̀rúnmìlà.\nTodavía hoy, nosotros oímos llamar a la gente:\n\"omọ Alarẹ\" (el hijo de Alarẹ) al hijo de Ogúndáméji\nPara cualquiera que este signo sea adivinado\nsu esposa tendrá muchos hijos.", "origen_id": "f67a9884ac5f04f5e84163eb"}, {"titulo": "Relatos y ofrendas", "texto": "OGÚNDA MÉ JÌ\n\nHojas — secas — de — la — palma consulta Ifá para el tigre en el día que el tigre iba a cazar. Ifá\naconsejó al tigre hacer ebo para que él pudiera cosechar los frutos de sus esfuerzos. El tigre\nestuvo poco dispuesto hacer ebo. El tigre se fue a cazar y capturo un venado y lo puso debajo de\nun árbol de palma. Cuando estaba dispuesto a comerse el venado, hojas secas de palma cayeron\ndel árbol y lo espantaron. El tigre continuo la caza y capturo a un antílope, éste se cubrió de\nhormigas. El tigre regresó al Awo y le preguntó que debe hacer en orden para cosechar los frutos\nde sus esfuerzos. Ifá aconsejó al tigre hacer ebo. El tigre hizo ebo. Desde ese día, el tigre come\ntodo el juego que capturo en la caza.\n\nComentario:\n\nIfá dice que la persona debe hacer ebo para quedarse con el fruto de su labor.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 adie (ave), 1 pieza de cuero, 1 epo (botella de aceite\nde palma), 1 palo blanco y 55 nira (dinero), ofrecido a Ogún e Ifá\n\n(Ett (oferendas); 4 eiyele (pigeon), 4 adiye (ave), 1 pedaco de couro, 1 epo (garrafa de\nazeite ded dendé), 1 prato branco e 55 nira (dinheiro nigeriano), oferecidos a Ogún e Ifá.)\n\nEluku — no — tiene — Oro, - mientras — que — Oro — no — tiene — una — campana — de — metal,\nconsulta Ifá para las personas de Idena — Magbon en el día que el pueblo entero estaba llorando\npor buena fortuna. Ifá aconsejó a las personas de Idena — Magbon hacer ebo para que recibieran\nla buena fortuna que pondría final a su llorar. Las personas de Idena — Magbon hicieron ebo. Fue\nen ese día que las personas de Idena — Magbon recibieron la bendición de la buena fortuna.\n\nComentario:\nIfá dice que esta persona debe hacer ebo para asegurar que la buena fortuna venga a su camino.\n\n92\n\nIfá dice que muchas bendiciones están cerca, pero hay un riesgo de que se pierdan si no se hace\nebo.\n\nEtutu (ofrecimiento): 2 agogo (campana de metal), 2 eiyelé (pichón. 2 adie (ave), 2 Osunsun\n(una vara de madera dura usada para golpear las campanas) y dinero determinado por el\nadivinador. Ambas campanas tienen que ser marcadas con iyerosun. Una campana es para el\nadivinador y la otras campanas es para la persona que ha recibido el Odu. Eéwo (tabú): carga\ndinero en un monedero o billetera bendecida para protección.\n\n(Ett (oferendas); 2 agogo (sino de metal), 2 eiyele (pigeon), 2 adiye (ave), 2 Osunsun (vara\nde madeira dura usada para tocar o sino) e uma quantidade de dinheiro determinada pelo\nAwo. Ambos os sinos seráo marcados com iyerosun. Um sino é para o Awo e o outro sino é\npara o pessoa que recebeu o Odú. Eéwó (tabu): carregar dinheiro abencoado para protecáo\nem uma bolsa ou carteira.)\n\nTI TI\nI I\nI I\nI I", "origen_id": "a7ff81f46749dafff5bb46a3"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ogunda Meji advierte a la gente de peleas, disputas y de\n     hostilidades inminentes. Durante una sesión de adivinación, si este signo\n             aparece para alguna persona, él o ella serán advertidos de vigilar y\n        sus confidencias en alguien indigno de su confianza. Si el cliente está\n            batallando contra problemas financieros y oposiciones de enemigos,\n      Ogunda Meji le dice que él o ella deben ofrecer un sacrificio a Oggún y\ndespués propiciarlo a su cabeza (ori) para obtener el éxito y la prosperidad.\n               WO - El cliente está sobrecargado de trabajo y cargando con los\n                En el orden de Orunmila, el Odu Ogunda Meji ocupa el noveno\n  lugar. Este Odu es la encarnación de Oggún; el Dios de la ira y la guerra.\n La mayoría de los hijos de Ogunda Meji son adoradores de Oggún, quien\n\nes reconocido por su poder, coraje y talento creativo. Con su inusual\n imaginación usan sus increíbles hechizos, abre las más disímiles puertas\n    consiguiendo oportunidades de empleos para los demás. Ellos fueron\nencarnados por Ogunda Meji y son siempre bendecidos con muchos hijos.\n\n\n9.1 · Alagbara ni nsokun Ade fue quien hizo la adivinación Ifá para\n                                                                   Oggún.\n     A él se le mandó sacrificar un machete, un gallo, un ñame asado. Ifá\n    dijo que el machete sería la llave del éxito de Oggún. Él siempre debe\n     pasear con el machete, Él fue preguntado para comer ñame asado. Él\n                                                                 lo comió.\n       Cuando él tuvo sed, fue a beber agua del río. Después de beber el\n    agua del río, él vio dos personas peleando por un pescado que habían\n      capturado. Oggún les dijo que fueran pacientes, que fueran para sus\n                    casas y compartieran el pescado. Ellos lo rechazaron.\n     El primer hombre le dijo que él venía del este y el otro le dijo que él\n           venía del oeste. Después de oírles sus excusas, Oggún tomó el\n        machete y picó en dos el pescado para ellos. El primer hombre le\n             agradeció el gesto y le invitó a su casa. El hombre, prometió\n      enriquecer a Oggún de por vida si el cargaba sus deseos. El hombre\n     aseguró a Oggún que él recibiría muchas cosas buenas en la vida por\n                                                          su buen consejo.\n          El segundo hombre sabiamente agradeció a Ogúun he hizo una\n          promesa semejante, Oggún convino con ellos. Desde aquel día,\n\nOggún es llamado por Ogunda Meji: “el que dividió el pez en dos\n                                            para que los hombres no pelearan”.\n\n\n9.2 · Agogo-owo-koseif´apokosi adivinó Ifá para Olofin. Cuando Olofin\n         Ajalorun le propuso enviarle su hijo, Oggún, le abriría los caminos\n          del mundo y de la vida. Oggún advirtió que él sería poco hábil en\n       llevar a cabo lo asignado por lo difícil que le sería el mundo. Pero él\n       debía hacer un sacrificio contra la enfermedad y la muerte súbita. un\n           carnero y un eslabón de una cadena. Él hizo el sacrificio. Ellos le\n                                   dijeron: un eslabón solo nunca se quiebra.\n\n\n9.3 · Okelegbongbo-as´ofun-kilo hizo la adivinación de Ifá para Oggún. A\n      él se le aseguró que si él hacía un sacrificio, él nunca moriría. Todo el\n       mundo lo llamaría a él siempre para que les ayudara por los caminos\n         de la vida. Pero ninguno de ellos podría resolverle a él sus propios\n           problemas. 4 carneros, 4 chivos, 4 cazuelitas cubiertas, deben ser\n       ofrecidas en sacrificio. Él realizo el sacrificio, en las cuatro esquinas\n                                                                    del mundo.\n\n\n9.4 · Ikoko-idi-s´akun-bere hizo la adivinación de Ifá para Orunmila. Le\n       dijo que su esposa le daría muchos hijos pero que no los conocería a\n      todos ellos. Por eso, él le dijo que hiciera sacrificio con una gallina de\n      guinea y 2000 cowrie. Orunmila hizo el sacrificio. Alare es el nombre\n          con que nosotros conocemos al primer hijo de Orunmila. Todavía\n\nhoy, nosotros oímos decir a la gente. Omo alare. El hijo de alare –\n              dueño, alguien para quien sea hecho este signo de Ifá, debe tener\n                                                                     muchos hijos.", "origen_id": "f6868aff4cb869527df98027"}, {"titulo": "Relato en inglés 1", "texto": "He says, “It is pulling gently.” I say, “It is very cool.” He says, “Like what?”\nI say, “Like new money that we are going to have.” I say, “What is the sacrifice?”\nTwo pigeons and seven pence two oninis.\n\nHe says, “It is pulling gently.” I say, “It is very cool.” He says, “Like what?”\nI say, “Like a new wife that we are going to have.” I say, “What is the sacrifice?”\nHe says, “Two hens and seven pence two oninis.”\n\nHe says, “It is pulling gently.” I say, “It is very cool.” He says, “Like what?”\nI say, “Like a new child that we are going to bear.” He says, “Three cocks and one\nshilling seven pence eight oninis.” He says, “To bear child after child is what the\n\nshesheki plant does.”? He says children will not decrease in number behind his\nwife.\n\nHe says, “It is pulling gently.” I say, “It is very cool.” He says, “Like what?”\nI say, “Like a new house that we are going to build.” He says, “To grow against\nhimself, to grow against himself is how Peregun tree grows his cloth”; he says,\n“Peregun tree never uses last year’s clothes.” He says, “One she-goat and eleven\nshillings is the sacrifice.” They say, “The whole world will be sitting down there\nwith him.”\n\nHe says, “It is pulling gently.” I say, “It is very cool.” He says, “Like what?”\nI say, “Like a new title that we are going to take.” He says we should name the\nsacrifice that will enable him to take the title and remain long in office. One ewe,\na bunch of white cloths, a calabash of chalk, and five shillings six pence.\n\n“My head becomes as white as chalk from Benin;\n“Everybody, come and rejoice with me because of my head.”\n\nIfa says we will reach the end of our row.*", "comentario": "1. This refers to the abundance of seeds or fruit of this unidentified plant.\nCf. verse 249-3, i\n\n2. This refers to the fact that the peregungtree (Dracaena spp.), which is\nused to mark boundaries, gets a new layer of bark each year.\n3. I will become so old my hair will be white as chalk,\n\n4.. That is, find a solution to our problem. The prediction is that the client\nwill get money, a wife, a child, a new house, or a title, depending on which he\ncame to inquire about, if he makes the specified sacrifice.", "origen_id": "b0d240d1a5f3b46f6752c16e"}, {"titulo": "Relato en inglés 2", "texto": "“When we forge a hoe, we beat it out flat; when we forge a cutlass, we beat\n‘gbgnrandan-gbgnrandan’;! when we forge a brass gong, we turn it over and over\nand over; if we bring them together, they become only one alone” was the one who\ncast Ifa for Qrunmila when he was going to attack his enemies. They said he would\ndefeat them. They said he should sacrifice three cocks, one shilling seven pence\nand eight oninis, and one bag made of etu cloth?\n\nBoth those who use locust beans and those who use salt, their mouths will be\nclosed ‘sunin-sunin,* they say he will defeat them. Ifa says he will help someone\ndefeat the people of the world in this thing for which this figure was cast. He says\nwe want to do something; he says he will not allow us to find the evil of enemies\nin it.\n\n,", "comentario": "1, The sound made when beating iron on an anvil.\n\n2, Etu is a popular pattern of cotton cloth woven in blue and white on the men’s\nloom.\n\n3. The sound of a person closing his mouth, meaning that no one will be able\nto say anything against him. It was explained that since everyone uses locust beans\nor salt in seasoning food, Qrunmila will defeat everyone.", "origen_id": "dd81fa08b51865f73c488863"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ògún: un machete, un gallo y ñame asado; andar siempre con el machete.", "Ògún: un carnero y un eslabón de cadena.", "Ọ̀rúnmìlà: una gallina de guinea y 2,000 cauríes.", "Para dinero: dos palomas; para pareja: dos gallinas; para hijos: tres gallos; para casa: una chiva; para un título: una carnera, tela blanca y una jícara de ẹfun; cada uno con su cantidad de cauríes.", "Contra enemigos: tres gallos, 6,600 cauríes y una bolsa de tela ẹtù.", "Ofrenda a Ògún y luego a Orí; para conservar el fruto del trabajo: cuatro palomas, cuatro aves, un pedazo de cuero, aceite de palma, un plato blanco y dinero, a Ògún y a Ifá."], "pasajes": [{"titulo": "Ofrenda en el verso 9.1", "texto": "Alagbára ni nsọkun Ade:\nfue la persona que adivinó Ifá para Ògún.\nA él se le mandó sacrificar\nun alfanje (machete), gallo, ñame asado.\nIfá dijo:\n“el alfanje será la llave para el éxito de Ògún”,\n“él debe caminar siempre con el alfanje”.\nLe fue aconsejado que comiera ñame asado.\nÉl lo comió, cuando él tuvo sed,\ny fue a beber agua del río.\nDespués de beber el agua del río,\nél vio dos personas peleando por un pescado que habían capturado.\nÒgún les dijo que fueran pacientes,\nque fueran para sus casas y compartieran el pescado.\nEllos lo rechazaron.\nEl primer hombre le dijo que él venía del Este\ny el otro le dijo que él venía del Oeste.\nDespués de oír sus excusas,\nÒgún tomó el alfanje que le habían aconsejado llevar siempre\ny picó en dos el pescado para ellos.\nEl primer hombre le agradeció el gesto\ny le invitó a abrir un sendero desde allí\nhasta a su casa natal.\nEste hombre le prometió enriquecerlo si cumplía sus deseos.\nTambién le dijo que él lograría valiosas cosas en la vida\npor su buen consejo para que no pelearan,\nlo cual estimulaba la confianza en él.\nEl segundo hombre sabiamente agradeció a Ogún,\ny le hizo igual petición,\nOgún acordó hacer lo que ambos le solicitaron.\nDesde aquel día, Ogún es llamado por \"Ògúndaméji\"\nel que dividió el pez en dos para que los hombres no pelearan.", "origen_id": "8ea8a0560cb6133ac26a3471"}, {"titulo": "Ofrenda en el verso 9.2", "texto": "Agogo-owó-koṣeif'apokosi:\nadivinó Ifá para Ọlófin,\ncuando Ọlófin Àjälọ̀run\nse propuso enviar su hijo, Ogún,\npara abrir el camino de la vida hacia el Mundo.\nEl adivino dijo:\n\"Ogún no podrá completar el trabajo asignado,\npor la fuerte oposición que recibirá en el Mundo\".\nPero él debía hacer un sacrificio\npara mantenerse saludable (contra la enfermedad)\ny para evitar la muerte súbita (repentina):\nun carnero y el eslabón de una cadena.\nEl hizo el sacrificio.\nEllos le dijeron: \"Un solo eslabón nunca se quiebra\"", "origen_id": "33deabedaf94713d8fe26b85"}, {"titulo": "Ofrenda en el verso 9.3", "texto": "Okelegbongbo-ap'Òfún-kilo:\nhiso la adivinación de Ifá para Ogún.\nEl ailivino dijo: \"Si hace sacrificio, nunca morirá.\nTodo el mundo lo llamará a él siempre\nparn que les ayude arreglar sus vidas\n(para que les ayude a corregir el carácter)\ny abrirte el camino\nPero ninguno de ellos se iba a detener\nsue propios problemas\",\nrilVarle\ntro chivas,\nu (gbiras con tapao),\nen sacrificio.\nrifgie,\naerifico\nỌlonn si\n• cuatro esquinas del mundo.", "origen_id": "7cbf37230d50209ae7804a00"}, {"titulo": "Ofrenda en el verso 9.4", "texto": "Ikoko-Ìdí-ṣ'akun-bẹrẹ\nadivinó Ifá para Ọ̀rúnmìlà.\nLe dijo: adivinó\n\"su esposa dará tantos hijos\nque él no llegará a conocerlos a todos\"\nPor eso, le dijo que sacrificara:\nuna gallina de guinea y 2000 cowries.\nỌ̀rúnmìlà escuchó e hizo el sacrificio.\nAlarẹ es el nombre con que nosotros\nllamamos al primogénito de Ọ̀rúnmìlà.\nTodavía hoy, nosotros oímos llamar a la gente:\n\"omọ Alarẹ\" (el hijo de Alarẹ) al hijo de Ogúndáméji\nPara cualquiera que este signo sea adivinado\nsu esposa tendrá muchos hijos.", "origen_id": "f0b701703eccd0cf3625573b"}, {"titulo": "Ofrenda complementaria 1", "texto": "4 eiyelé, 4 adie, 1 pieza de cuero, 1 epo, 1 palo blanco y 55 nira\n\nDestinatario: Ògún e Ifá", "origen_id": "815c39cbc55f429eb7d0f0d2"}, {"titulo": "Ofrenda complementaria 2", "texto": "2 agogo (campanas de metal), 2 eiyelé, 2 adie, 2 Osunsun (varas de madera dura), iyerosun para marcar ambas campanas y dinero determinado por el Awo", "origen_id": "c106081ee12ee72fbdb34441"}]}, {"titulo": "Relaciones espirituales", "texto": "Ògún, dios del hierro y de la guerra, es el dueño de este signo. Orí recibe ofrenda después de Ògún. Ẹ̀là es hijo de Ọ̀rúnmìlà según este relato.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Ogun", "origen_id": "92450003573b334ec81ec7d5"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Machete, ñame asado, eslabón de cadena, ẹfun (tiza), tela blanca, pẹrẹgún (Dracaena), planta ṣẹ̀ṣẹ̀ki de muchas semillas. Para recibir buena fortuna: dos campanas de metal marcadas con iyẹ̀-ìrosùn, una para el babaláwo y otra para la persona."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 9.1 (yorùbá): Alagbára ni nsokun Ade: / li o difá fOgún. / A niki ó rú: / agbada, akuko-adiyẹ ati ẹsun-iṣu. / Ifá ni: / \"Agàdá yẹn ni Ògún maa fiṣe / Iṣẹ Ọrọ, ki o maa muu l'owọ̀ Kaakiri\". / A ni ki o jẹ ẹsun-iṣu naa, o jẹẹ. / Orungbẹ si ngbẹẹ, / o lọ si odó lọ mu omi. / Bi o ti mu omi tan, / O ri àwọn Méjì / Kan ti nja nitori ẹja kan ti wọ̀n pa. / aa тu suuru / in нi H6 / ni aun ti wa / 1uwa / 19 Tan un / I WOn % / a Hi qwọ rọ da pja / woh / gwo re. / à fiagádà qwọ rọ̀ / ld oun, o ni oun a / A MHR / Quoro, o ni pwo re yoo / te opolopo in kan ti ojú ko niifi / Bọ̀n gn kio too đe ọ̀dọ̀ oun. / Enikeji tun dupp, o bẹç ki o maṣai / ta qná wa de ilü oun bakanna / Ôgùn ni oun gbọ̀ / Niẹ̀ giọ ti Ôgún tí da gja si Méjì / Tun gwọn máji ti nja li a tin pee / 1t Ogündamejl:", "Verso 9.2 (yorùbá): Agogo-owó-koṣeif'apokosi: / li o dífá f'Ọlófin, / nigbi Ọlọ̀fin Àjàlọ̀run / mi a ran ọmọ rẹ̀ ti njẹ / Ögún wa s'ode Ayé / lati wa la ònà Iwa. / Wọ̀n ni: / Ogún konilaa tan ki ayé toṣe orí kogo / Sùgbọ̀n ki ó rúbọ / Nitori aralíle ati àitètèkú3o / Agbo kan ati ẹwọn koniko kan / Ó gbọ̀ ó rú. / Wọ̀n ni: \"Ewọn kan kiikẹ\".", "Verso 9.3 (yorùbá): as'Òfún-kilo: / rabý, a ko nigbọ ikú rè laelae. / a mlaman bpe pe: / a wọn tan iwa wọn pe\", / Leni kan / Hye B / tra ro\" / Hofin, sware morin ati igbá-ademu mérin ni ebọ. / We / y пaд. / Qiofin lọ rì qbọ na si igun mèrin ayé.", "Verso 9.4 (yorùbá): Ìdí-p'akun-bere: / fi o difá f'Ọ̀rúnmìlà. / Wọ̀n nì: / \"Obirin to ni yi a bimo titi / Ọ̀rúnmìlà koniimo iye qmọ rẹ̀\". / Nitorinaa ki ó rú: / oyẹ-awo ati ẹgbẹwa owó / Ọ̀rúnmìlà gbọ̀ ó rú / Alarẹ oruko ti ape Akobi Ọ̀rúnmìlà. / Ayani a ngbọ \"omọ Alarẹ\" (Olúwa rẹ, Olódùmarè). / Eniti a dá Ifá yi fún, / Obirin (aya) rẹ̀ a (bimọ pupọ) rẹ. / tún iwa wọn ṣe: (tún ... ṣe) arregiar o corregir el carácter de ellos.", "REZO: OGUNDA MEYI OGUNDA SIRO OWAYOLOKUN ASHANLA BIRINIWA OBATALA OBATAISA JEKUA OBA IGBO ODOBALENI OGGUN ORIRE YOLORUN. OCHOSI OGUNDA MEYI EYENI EYE ORARUMA OKUALORUN OBARALAYUNA TIWA ELEGBARA AWALAWA OLOWU SHIWOSI ORUNMILA KAYE WARIO ORUN MAFEREFUN ODUDUWA ORUGBO.", "SUYERE: OROSI BABA KERERE, BABA KERERE, BABA KERERE.", "REZO: OGUNDA EJI ERA TETEYI UNSHE EJA OGGUN KAFEREFUN OBATALA ATI ORUNMILA PIT Y GUIN ELEBBO. OGUNDA EJI TETEYI FARA LERI LOSUO EYO ALANIBAWA ADIFAFUN AYOROKE BI OPA OTORUN BOYE, ADIFAFUN IYAREWA OMONIWA ODUDUWA OKETE KEKE BI OMO ASHO KUENI ADIFAFUN AGBANI. OGUNDA EJI TETE SIRO OBINI ADIFAFUN ALAGUEDE, MAFEREFUN ASHANLA, IBORU, IBOYA, IBOSHESHE.", "REZO: OGUNDA EJI ABELONA FOLOYA IGI LEGAN ADIFAFUN TOLO INSHO OGUNDA TETEYI INLE IGBE AWELI OTOLOYO OTOLOYO FESE FESE MOSHOGUN ODO AWOLI NI EMIKE OKUA EURE MEYI IFA ODARA. OGUNDA EJI IYENI ODODO EKUNDAYO ILEKE OBINI AROKUNAYO.", "REZO: OGUNDA NI AYO OGUNDA BABERI IYA, OGUNDA KOKUN EYENI IYA OBUKUA MORA OMA SHEPE SHERO EKUN EKUE NIYIWE EYE IYA OPUERUN OBONI.", "REZO: OGGUN ORIBIAYE ORUN OGUNDA SIRO OMO WAYOKUN MANA DEDE OWO OMO ORUN MOYAYE WARILOYE ABONI KEFEREFUN BABA SHANGO.", "REZO: AMINGO ADIFAFUN AMELOGUN OMO OLUGBON ESE NOFANO A INI LODO BARABANI FEREFUN NO BATI UNLO SODE IFA OBINI ORISHA YEMAYA OKUTI OBI IYAESHU AKUGBO IGBO OMODE META BELEFUN ADE ALAMBO OMO LA MERIN TONTI MERIN SUTIRO SIRO AWO SUTIRO INLE ADIFAFUN OGGUN BOMALE OZAIN BELE BELE SOKUN LALE AWO ODARA, KEFEREFUN YEMAYA LODAFUN OGGUN.", "REZO: OGUNDA MEYI BABA SIRO SIROYE OWALOYOKUN OSHANLA JEKUA OBAIBO ADIFAFUN OMO BABA INU ORAYELUMA ODUDUWA OMOBONU INLE BABA FUN FUN OSHAYABI OGUNDA OSHANLA ADIFAFUN OLUWO SHIWOSHI IFA NI KEFEREFUN ORUNMILA Y OSHOSI LODAFUN OLOFIN.", "REZO: OGUNDA MEYI IDAWIRI ODO KIPODO IDAWIRI OLOKIPO ILE ADIFAFUNIYI ADIFAFUN ADIAUN UYI TINSHOMO AJALORUN OFO LORUBO KEFEREFUN OLOKUN AKARO.", "REZO: TOQUE DE LA PUERTA DE IGBODUN OGUNDA MEYI. —- OGUNDA MEYI BABA FARAYE OBATALA SHEWERE LOYE OGGUN TETE EJI EBORU, EBOYA, EBOSHESHE.", "REZO: OGUNDA TETEYI FARA LEYI LOSUO EYO ALANIBAWA ADIFAFUN AYAKORE BI OPA OTORUN BOYE, ADIFAFUN AYAREWA OMINIWA ADUDUWA OKETE KETE BI ORUN OMO ASHO KUENI KUENIA ADIFAFUN AGBANI.", "SUYERE: ORISI BABA KERERE, BABA KERERE, BABA KERERE. OGUEGUE OGUEGUE ORISHA ANANO OGUEGUE EWA ORISHA MANIEE. IBORU IBOYA IBOSHESHE ORISHA LANA IBORO IBOYA IBOSHESHE ORISHA LANA.", "OGUNDA TANI OSHA OKA IWONA AYAYA OKE IWOBA AYAYA TANI LOGUN AYAYA OKE IWONA TANO MALOWA", "AYAYA KUELEDE OKE IWONA TANI MALONOA AYAYA KOLENFU", "OROPALO OLOKUN OPA OKUN OLOHIPO ODE OROPALO OLOKUN OPA OKUN OLOHIPO ODE.", "IFA OUNKO ORUMILA LAKA LAKA LABOSI IFA OUNKO ORUMILA LAKA LAKA LABOSI AWO. OSHEMINIE.", "REZO: TETE AYE IYA OGGUN LORUN ARIBUN MOROBON ERU OKO, ERU OZAIN OKO ELEYA EJA OKAN NI OGUNDA NI OBATALA DENI OGGUN ONI OUN OBAYINU OBATALA ONI OUN OTUNSHE NI OGUNDA MEYI LODAFUN OBATALA KAFEREFUN ORUNMILA.", "REZO: AMIDIGO ADIFAFUN AMELEGUN OMO LUGBON ESE MORANO ADEI LODO BARANIREGUN NI BATI UNLO SODE IFA OBINI ORISHA YEMAYA OKUTE OBI IYA ESHU AKOKO IGBO OMODE BELEKUN ADE OLAMBO OMO LA MERIN TONTI MERIN SUTIRO SIRO AWO SUTIRO INLE ADIFAYOKO OGGUN BOMALE OZAIN BELE SOKUN LALE AWO ODARA MAFEREFUN YEMEYA LODAFUN OGGUN.", "REZO: ABENBOLA FOLAYA IGI LEGAN EIYENLA FOBAKE ABOGBO NIWALA FOLAKA IGI LEGAN IGI LEGAN ADIFAFUN TOLO INSWO OGUNDA TETEYI INLE IGBE AWELU OTOLOYO OYOLOYO OTOLO FESE FESE MOSHOGUN ODO AWOLI NI EMIKE FUN MEYI IFA ODARA.", "REZO: OGUNDA NI EYE OGUNDA BELERI IYA AGUEDA KEKUN EYENI IYE ABOKUE NORA OMA SHEPE ABORO ABORO EKUN EKUE NITIWE EYERI EYE IYA KAFEREFUN EBONI.", "REZO: BABA SIRO SIROYE OWALOYOKUN OSHANLA OBATAISA JEKUA OBAIBO ADIFAFU OMO BABA INU ORAYELUWA. ODUDUWA OMOBONU INLE. BABA FUN FUN OSHAYANI OGUNDA OSHANLA ADIFAFUN OLUWO SHIWOSHI. IFA NI KEFEREFUN ORUNMILA Y OSHOSI. LODAFUN OLOFIN.", "REZO: OGUNDA EYI AWAPARI AWA TEMATASHE AUN MOSHODE OLOFIN AGBANI BABALAWO ADIFA SHIGUN SHINLOKO IDI OBA OSUN UMBATI ILE OLOFIN LORUBO ORUNMILA META MOMO OKOYA EISE IRABO BENO OLOFIN EPO ORA ADIFA AGUSE TINSODA AWO NIDE OGUNDA MEYI ORUBO.", "REZO: IDAWIRI ODO KIPODO, IDAWIDI OLOKIPO ILE ADIFAFUN IYI ADIFAFUN UYI TINSHOMO AJALORUN OFO IYI LORUBO AKUKO ADIE MEYI EKU EJA MEYI EBO DILOGUN OWO IYI ROBO APA IROKO ARABA IRA OBARA MOFIJE SOFARERE OLODUMARE MOGUAYE EYO KOYO AYE OKAN AYILOWA OPEWE OPAN OKUN WUDA ORASI ERA ODA OFERESE IYE EJA SOPUN LODO KAFEREFUN OLOKUN KAFEREFUN OLOKUN AKARO.", "SUYERE: AROPALO OLOKUN OPA OKUN OLOHIPO ODE.", "REZO: ADIFAFUN OMOMIRIN ERU DOTA BERE ARAIKA LORDAFUN ESHU ARIBO ABANI ADE AIYEMI AGUTAN ODO ODONI ORUNMILA UMBO ORUN ATIENI IFE UMBO BASSYE GBOGBO ORISHA ADESHE IBORU IBOYA IBOSHISHE."], "pasajes": [{"titulo": "suyere", "texto_ritual": "IROFA ABENIKOTO BATI ORUNMILA TOSHEGUN ETA META.", "origen_id": "70a185a077e07a2122c3b768"}, {"titulo": "suyere", "texto_ritual": "BABA YOMI WAWAO - BABA YOMI WAWAO ODDUN-AREMU WAWAO - BABA YOMI WAWAO", "origen_id": "fc83d9851d2153b30669e712"}]}]$q$::jsonb),
(10,'d1b73a8e9aabcf4c95e01b991878d5c8','127bdfc55e56b49156b7aaebdc69f256',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Méjì habla de falta de valor y de confianza para enfrentar un conflicto, que se expresa huyendo o esquivando cualquier oposición. Sus hijos viajan mucho, por trabajo o por gusto, y son buenos administrando negocios ajenos; como se asustan fácil, rara vez arriesgan. Les cuesta concentrarse y se distraen con facilidad. Pide ayuda espiritual contra pesadillas y brujas que interfieren en el sueño, y ofrenda a Ṣàngó para vencer a los enemigos que planean hacerle daño.", "pasajes": [{"titulo": "Frase clave", "texto": "Osa crea cambio radical en circunstancias.", "origen_id": "a412d7935a3be1e01d73b6bc"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le llega un cambio repentino en el trabajo o en una relación y lo rechaza por miedo a perder estabilidad.", "Enfrenta oposición o una pelea y necesita prevalecer (relato de Òlúkòso y Ṣàngó).", "Busca prosperidad material (relato de Òwú, hijo de Ògòdò).", "Va a viajar o trabajar con desconocidos que podrían querer perjudicarlo (relato de Ọ̀rúnmìlà).", "Un susto o un imprevisto puede frenar su proyecto (relato de los dos Òsá).", "Busca pareja, hijos o reconocimiento (relatos del matrimonio de Ọ̀rúnmìlà y de Ejipabileseigi).", "Está cansado o descuida una necesidad propia (relato de Ajá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ganar fuerza hasta vencer a los enemigos con Ṣàngó.", "Encontrar pareja y tener muchos hijos.", "Gran riqueza si se casa con una sola mujer.", "Que los enemigos cambien de corazón.", "Fama por hacer el bien."]}, {"titulo": "Ibi y advertencias", "puntos": ["Huir de los problemas en lugar de enfrentarlos.", "Pesadillas y ataques de brujas.", "Debilidad, cansancio, boca seca y estreñimiento.", "Pelear y que la enfermedad caiga sobre la familia."]}, {"titulo": "Enseñanza principal", "texto": "El que no ofrenda huye: los dos Ọ̀sá corrieron ante el fuego de Ifẹ, y de ahí su nombre. Hay que seguir haciendo el bien aunque algunos no lo agradezcan; el buen trabajo trae la fortuna."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Oiá Mojl significa falta de coraje (falta de confianza en sí mismo para vsigerarae en un conflicto), que se expresa huyendo, evadiendo, banitamando las batallas, conflictos o cualquier oposición. Los hijos de Méjì hacen una gran cantidad de viajes en su vida, ya sean por los o placer. Ellos se desarrollan y convierten en buenos gerentes si ailninistran o manejan los negocios de otras personas. Como ellos se asustan con facilidad, raramente correrán riesgos que hagan peligrar un (igocio", "origen_id": "aa3a3fe1897495d57a44f47a"}, {"titulo": "Características generales", "texto": "Otros nombres: Kionã / Ọ̀sá kan.\nOná Méjì es el décimo Odù en el orden inalterable de Ọ̀rúnmìlà. Este Odú enfatiza en la necesidad de ayuda espiritual contra pesadillas y hechiceras que se manifiestan interfiriendo en el sueño de la persona. Los sacrificios apropiados deben ser efectuados para apaciguar a las brujas (ajẹ̀) y asegurar la protección necesaria. Si Ọ̀sá Méjì sale en adivinación para un cliente, Ifá dice que el cliente tiene enemigos que están planeando hacerle daño. Si el cliente realiza un sacrificio a Ṣàngó, él o ella irán ganando en fuerza hasta que finalmente triunfen sobre sus enemigos.\nAquellos encarnados por este Odù tienden a desentenderse y escapar de cualquier mando, control, dirección, gobierno o situación que los limite y refrene. Mucho esfuerzo se requiere para que ellos se concentren a realizar cualquier tarea o trabajo, y para que ellos, por si mismos, se dediquen atentamente a su trabajo. Estas personas se disocian con facilidad.", "origen_id": "600a347512b686694de4b843"}, {"titulo": "Interpretación tradicional", "texto": "Osa es la manifestación de un repentino cambio inesperado. Owonrin es el caos construido adentro de la estructura de una forma i.e. edad vieja y enfermedades latentes. Osa es la influencia de factores de afuera que perturban o destruyen una forma particular. Simbólicamente Osa está asociada con tormentas, huracanes, volcanes y esas fuerzas destructivas de la Naturaleza que transforman todo a su paso. Como una Fuerza en la Naturaleza, Osa tiene un efecto transformador y limpiador. En términos personales, Osa puede representar un cambio drástico que lleva a la abundancia. En términos negativos, Osa representa a alguien que está huyendo constantemente de sus responsabilidades que pueden llevar a varias formas de enfermedades mentales.", "origen_id": "fb2c9e49268d612af1788930"}, {"titulo": "Orientación complementaria", "texto": "Osa es cambio externo inesperado usualmente de orígenes externos. Una persona puede usar cambio para crear la aabundancia o dejar que el cambio cause confusión y depresión llevando a la inestabilidad mental y emociónal. Cuando este Odù aparece una persona debe de ser avisada contra de pretender ser inestable mentalmente, porque pretenderlo se volvera en una forma de invocación o embrujamiento propio.", "origen_id": "f25dd1052caab6ce97fcd04c"}]}, {"titulo": "Relatos reunidos", "puntos": ["Los dos que huyeron. Kasá consultó para los dos Ọ̀sá que iban a Ifẹ a adivinar, y les dijo que algo podía asustarlos e impedir sus planes; debían ofrecer un carnero y una piedra de rayo. No quisieron. Al llegar a Ifẹ estalló un fuego, una pelea; trataron de combatirlo, no pudieron y salieron corriendo. Desde entonces a los dos que huyeron se les llama Ọ̀sá Méjì.", "La pata solitaria. Ọ̀sá andaba sola y errante por el mundo. Le dijeron que encontraría buena pareja si ofrecía dos palomas, dos caracoles y medicina de Ifá. Ofreció. A quien le sale este signo tendrá muchos hijos.", "Ọ̀rúnmìlà y Olúyemi. Ọ̀rúnmìlà quería casarse con Olúyemi, hija de Ọlọ́fin. Le dijeron que si se casaba solo con ella su riqueza sería muy grande, y le pidieron dos gallinas, dos chivas y 3,200 cauríes. A quien le sale este signo se le aconseja tener una sola esposa.", "El perro y la sed. Al perro le pidieron dos caracoles y medicina de Ifá para bañarse, porque una sed excesiva lo tenía débil y agotado. Se negó: dijo que la saliva de su boca bastaba para calmarle la sed.", "Ṣàngó y las cien balas. Ifá consultó para Olúkòso Làlú, Ṣàngó, el que encuentra cien balas para vencer, y le pidió ofrendar. Ofreció. '¿Con qué venció Àrìrà? Con cien balas.'", "El algodón. Ifá consultó para Òwú, el algodón, hijo de Ògòdò, y le pidió ofrendar. Ofreció, y frente al campesino dio su fruto y se abrió: así se hizo rico.", "Ọ̀rúnmìlà y la ginebra. Ọ̀rúnmìlà iba a viajar lejos con unos compañeros que querían hacerle daño. Ofrendó y les ofreció ginebra. Cuando terminaron de beber se miraron y dijeron: 'El hombre al que queríamos dañar nos dio de beber'. Desistieron, y nunca le hicieron daño.", "El Desdichado azota a sus vecinos. Al que llamaban 'el Desdichado' le dijeron que no azotara a Ìjẹgbẹ y a Ẹjẹgbo. Dijo que sí lo haría, y lo hizo. Al volver a casa encontró a toda su familia enferma en el suelo. Los adivinos le dijeron que sin ofrenda no podría con ellos; ofreció dos palomas, nueve kolas, una gallina y un gallo, y le rezaron: 'Echamos a la muerte del pueblo; echamos a la enfermedad'."], "pasajes": [{"titulo": "Verso 10.1", "texto": "Kasá kaja-katetesa:\nadivinó Ifá para los dos Ọ̀sá.\ncuando los dos Ọ̀sá iban a Ifè para adivinar.\nEl adivino dijo:\n\"algo puede espantarlos (asustarlos)\ne impedir que sus proyectos sean llevados a cabo,\npor esta razón debían sacrificar:\ncarnero padre y una piedra de rayo.\nEllos rehusaron hacer el sacrificio.\nCuando ellos llegaron a Ifẹ, surgía un fuego (una lucha).\nEllos trataron de combatirlo pero no pudieron\ny tuvieron que huir corriendo.\nDesde ese día, los dos que huyeron corriendo\nhan sido llamados Osáméji.", "origen_id": "b75760054c278e4ad0838913"}, {"titulo": "Verso 10.2", "texto": "İgbín ko ya palaka ẹsẹ:\nadivinó Ifá para un Ọ̀sá (una pata Ọ̀sá),\ncuando vagaba errante solo por el mundo.\nEl adivino dijo:\n\"puede encontrar su pareja (buena pareja)\nsi efectúa un sacrificio\":\ndos palomas, dos caracoles de babosa y medicina de Ifá.\nỌ̀sá escuchó y efectúo el sacrificio.\nCualquiera para quien este Ifá sea adivinado\ntendrá muchos hijos.\n\" ljà: lucha, pelea, guerra. Iná: fuego.\n3' N.T.: Vencer los obstáculos y dificultades en su camino.\n\"' rin kiri: s. viajar errante, vagabundear, andar errante de un lugar a otro sin\nestabilidad.", "origen_id": "67e713d42ad6b21cb410b42f"}, {"titulo": "Verso 10.3", "texto": "Ọkan-atẹgun-kose-irode’lẹ:\nadivinó Ifá para Ọ̀rúnmìlà,\ncuando él quería en matrimonio a Olúyemi,\nquien era hija de Ọlọ́fin.\nEl adivino dijo:\n“si solo se casa con Olúyemi,\nsu riqueza (abundancia) será muy grande”.\nDos gallinas, dos chivas y 3200 cowries son el sacrificio.", "comentario": "Es aconsejable para cualquiera a quien este Ifá sea adivinado casarse solamente con una mujer.", "origen_id": "c147eae040143f1dfad420fd"}, {"titulo": "Verso 10.4", "texto": "adivinó Ifá para Ajá.\nél fue aconsejado sacrificar:\ndos caracoles de babosa y medicina de Ifá,\npara bañarse con la medicina\nporque una sed excesiva estaba extenuado su cuerpo\n(le traía debilidad y cansancio)\nAjá rehúso hacer el sacrificio.\nEl dijo:\n\"que la saliva de su boca\nera suficiente para calmar su sed\".", "comentario": "biyenmẹ: planta no identificada.", "origen_id": "26f291beb4017f49ddcf3b3a"}, {"titulo": "Versos complementarios 1 · A", "texto": "' Ebo\n   ' 'Íségun\n       '     Nikí eléyìun ó rú. Ifá pé kó ' lòó\n                                             ' bo\n                                                ' ' Sàngó. Yóó rìí' èyìn odì.\n\n' Ò sáá méjì lákòjà\n  Ó bú 'yekeyékè\n           ' ' ' lójú' opón '\n  A díá fún Òlúkòso làlú\n  Bámbí' Omo ' a rígba' ota' 'ségun\n  Èyí tí ó gòkè àlàpà ' Ségun   ' òtá' è\n  Ebo´ n wón ní ó se '\n' '       ' ´ '\n  Ó sì gbébo\n         ' ' n bé\n  Ó rúbo\n       '\n` Njé kín  lÀrìrá e' 'sétè?\n   '                    '\n  Igba' ota\n  N lÀrìrá e' 'sétè\n                 '\n  Igba' ota\n\n Òsá Méjì A\n Ifá manda a esta persona para realizar sacrificio que lo haría prevalecer. Él debe\n consagrarse a Sàngó. Él vería el fin de sus enemigos.\n\n Ò sáá méjì lákòjà\n Ó bú yekeyékè lójú opón\n La adivinación del lanzamiento para el Òlúkòso làlú\n Bámbí Omo a rígba ota ségun\n El que subiría una pared de barro ruinosa para ganar a sus enemigos\n Era el sacrificio que ellos le pidieron que ofreciera\n Él oyó hablar del sacrificio\n Y lo realizó\n ¿Qué Àrìrá había usado ganando, la guerra fría?\n Cientos de balas\n Qué Àrìrá había usado ganando la guerra fría\n Cientos de balas", "origen_id": "9286c2384bff92da2b4abe8f"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé ire fun eléyìun. Yóó là.\n\nÒgboronko ló soja gbendekú\n                     ' '   gbendekú\n                            ' '\nA díá fún Òwú\nÈyí tíí 'somo\n           ' Ògòdò\nWón\n '    ní kí Òwú ó rúbo\n                    '\nÒwú rú o\nÒwú tù\nLójú olóko\nÒwú là\n\nÒsá Méjì B\nIfá desea bien a esta persona. Él se haría rico.\n\nÒgboronko ló soja gbendekú gbendekú\nAdivinación lanzada para Òwú\nÒwú el niño de Ògòdò\nEllos le dijeron a Òwú que realizara sacrificio\nÒwú ofreció el sacrificio\nÒwú dio las ganancias\nEn la presencia del granjero\nÒwú là", "origen_id": "0dc194994990a6a38b7ca7ad"}, {"titulo": "Relatos y ofrendas", "texto": "ÒSÁMEJÌ\n\nLa - rueda - de — enfrente - guarda - dinero, - mientras - la - rueda - de — atrás - guarda - cuentas, -\nmientras - Ógedegédé - sigue - brillando - sobre - el - río, consulta Ifá para Órummilá en el día\nque él estaba preparándose a ir a lugares lejanos Ifá aconsejó a Orúnmilá hacer ebo antes que\nempezara su viaje. Órúnmllá hizo ebo. Órúnmllá ofreció ginebra a esos que estaban viajando con\nél. Cuando ellos terminaron de beber, se vieron a la cara de cada uno de ellos y dijeron, el\nhombre que queríamos dañar nos ofreció ginebra. Todos dijeron que ya no querían dañar a\nÓrúnmilla. Desde ese día Órúnmllá no fue dañado.\n\nComentario:\n\nIfá dice que esta persona va a trabajar con un extraño y debe aceptar el trabajo. Irá dice que esta\npersona viajará a la laguna donde habrá una brisa. (Esta es una referencia a algún tipo de\nperturbación en la iniciación). Ifá dice que esta persona tiene muchos enemigos. Ifá dice que si\nesta persona hace ebo, sus enemigos tendrán un cambio de corazón. Ifá dice que esta persona\ndebe ofrecer dos botellas de ginebra, una debe darse a los enemigos de esta persona y la otra debe\ndarse al adivinador. Ifá dice que antes de que la ginebra sea dada a los enemigos de esta persona,\ndebe tomar un trago de la botella en la presencia de los enemigos.\n\nEturu (ofrecimiento): 4 eiyelé (pichón), 4 adie (ave), 1 epo (botella de aceite de palma), 4 bolsas\nde harina de maiz, 1 plato blanco, 2 oti (botella de ginebra seca), y 100 nira (dinero) ofrecido a\nIyáámi.\n\n(Étùtù (oferendas); 4 eiyele (pigeon), 4 adiye (ave), 1 epo (garrafa de azeite de dendó), 4\npacotes de milho, 1 prato branco, 2 ofi (garrafas de gim seco), e 100 nira (dinheiro\nnigeriano) oferecido a lyami.)\n\nMientras — estamos — haciendo — el —bien — nadie — puede — decir — nada, - cuando — hacemos —\nun — error — las — personas — malas — empiezan — a — esparcir — la — palabra, consulta Ifá para\nEjipabileseigi en el día que él estaba buscando fama y fortuna. Ifá aconsejó a Ejipabileseigi hacer\nebo. Ejipabileseigi hizo ebo. Desde ese día, Ejipabileseigi fue conocido como un hombre\ngrandioso.\n\n93\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo a favor de los ancianos. Ifá dice que si esta persona hace\nebo, no perderán lo que ya tiene. Ifá dice que esta persona ha ayudado a muchas personas y\nalgunas de ellas no aprecian la ayuda. Irá dice que debe ignorar a esos que no aprecian el trabajo\ny continúe haciendo cosas buenas en el mundo. Ifá dice que el buen trabajo pronto traerá buena\nfortuna.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 adie (ave), obi (nueces de origen Africano), orogbo\n(nuez amarga), 1 plato blanco, 1 epo (botella de aceite de palma) y 25 nira (dinero).\n\nEéwo (tabú): sopa, comida de la cazuela.\n\n(Ett (oferendas); 4 eiyele (pombo), 4 adiye (ave), obi (noz de Cola), orógbó (Cola amarga),\n1 prato branco, 1 epo (garrafa de azeite de dendé) e 25 nira (dinheiro nigeriano).\n\nEéwó (tabu): sopa comida da panela.)\n\nTI TI\nI I\nTI TI\nTI TI", "origen_id": "5cd4143e5a5dc3c289f3992a"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Osa Meji habla de la falta de coraje y huir de una batalla o de\n una oposición. Los hijos de Osa Meji hacen un gran acuerdo de viajes, ya\n           sean por negocios o por placer. Ellos llegan a convertirse en buenos\n     administradores si realizan el negocio de otras personas. Como ellos se\n                                  asustan fácilmente, ellos no correrán riesgos.\n            WO – La cara del cliente cambia o se transforma súbitamente tanto\n                                              en el trabajo como en sus relaciones.\n       Osa Meji es el décimo Odu en el orden fijado de Orunmila, Odu Osa\n             Meji hace hincapié en la necesidad para la ayuda espiritual contra\n     pesadillas y hechiceras que interfieran con el sueño de uno. Sacrificios\n       apropiados deben ser efectuados para aplacar a las hechiceras (aje) y\n  asegurar la protección necesaria. Además, si Osa Meji es elegido para un\n cliente, Ifá dice que el cliente tiene enemigos que están planeando hacerle\ndaño. Si el cliente realiza un sacrificio a Şangó, el cliente recobrará fuerzas\n     y se irá incrementando hasta que eventualmente pase por encima de sus\n                                                                        enemigos.\n\nAquellos encarnados por este Odu tienden a perder el control o ha\ntener falta de moderación, mucho esfuerzo es requerido para permitirle a\n     ellos concentrarse en lo que están haciendo o para aplicar su propia\n                                                   diligencia a sus trabajos.\n\n\n10.1 · Kasa kaja-katetesa adivinó Ifá para Eyi-Osa. Eyi-Osa Iba a Ife\n         para un proyecto. Se les dijo que podrían ser amenazados por algo\n   que podría obstaculizar el proyecto; por esta razón deberían sacrificar\n               1 carnero padre y 1 piedra de rayo. Ellos rehusaron hacer el\n   sacrificio. Cuando ellos llegaron a Ife, resultó un fuego. Ellos trataron\n   de combatirlo pero no pudieron y tuvieron que huir. Desde ese día las\n                    dos personas que huyeron han sido llamadas Osa Meji.\n\n\n10.2 · Igbin ko ya palaka ese adivinó Ifá para una Osa cuando ella\n   vagaba errante sola por el mundo. Se le dijo que podría encontrar una\n            pareja, si efectuaba un sacrificio con 2 palomas, 2 caracoles de\n           babosa y hojas de Ifá (moler hojas de biyenme y cocinarlas con\n    huevos de gallina para que ella las comiera). Ella obedeció y efectuó\n           el sacrificio. Cualquiera para quien este Ifá sea adivinado tendrá\n                                                              muchos hijos.\n\n\n10.3 · Okan-ategun-kose-irode´le adivinó Ifá para Orunmila cuando\n           éste se estaba proponiendo casar con Oluyemi, la hija de Olofin.\n\nEllos dijeron que si él solo se casaba con Oluyemi su honor sería\n        grande. Ebo: 2 gallinas, 2 chivas y 3200 cowrie. Es aconsejable para\n              cualquiera para quien este Ifá sea adivinado casarse sólo con una\n                                                                           mujer.\n\n\n10.4 · Oliyenmeyenme adivinó Ifá para Aja. Se le aconsejó sacrificar\n       2 caracoles de babosa y hojas de Ifá. (machacar hojas de teteregun en\n      agua entonces romper la punta de la coraza del caracol y permitir que\n             el fluído se mezcle dentro del preparado). Él debía bañarse con la\n           medicina para calmar su abatimiento. Aja rehusó hacer el sacrificio.\n             Él dijo que su saliva era suficiente para calmar su sed. Ifá dijo: el\n       cliente para quien este Ifá es elegido no está gozando de buena salud.", "origen_id": "40cb6becaffc2e40b7ee4494"}, {"titulo": "Relato en inglés 1", "texto": "“Knot reaches the knee and ends;! road reaches the top of a rock and is lost’?\nwas the one who cast Ifa for Worthless when he was whipping Ijẹgbẹ and Ejegbo.>\n\nThey said he should not whip them, but he said he would whip them, and he did\nwhip them. When he returned to his home, he found all his family lying ill upon\n\nthe ground. He went to the diviners and they asked with whom Worthless was\nfighting. They said that unless he made a sacrifice he\n\nwould not be able to conquer them. He offered two pigeons, nine kola nuts, one\nhen, and one cock.. They came and recited Ifa for him as follows:\n\n“We chase Death out of town;\n\n“Worthless, you are the one who is whipping Ijẹgbẹ and also his\nEjegbo.\n\n“We chase Disease out of town today;\n\n“Worthless, you are the one who is whipping Ijẹgbẹ and also his\nEjegbo, Worthless.”\n\nIfa says someone should be careful not to fight, because if he should get into\na fight, disease and illness will afflict his family; and someone should sacrifice\nso that those who are ill in his house may be able to get up from where they are\nlying down because they have offended a deity.", "comentario": "1. The knee cap is the only “knot” to be found on the human body.\n\n2, A path may be difficult to follow where it crosses a'rock.\n\n3, The meaning of these two names is obscure. Informants suggested that\nthe latter may mean “face of sore” (oju egbo), and the former may refer to a group\nwhich formerly collected tribute from the people of Ifẹ for the king.", "origen_id": "1d5748c8c5bc326a65fc49ec"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Los dos Ọ̀sá: un carnero y una piedra de rayo.", "Para hallar pareja: dos palomas, dos caracoles y medicina de Ifá.", "Ọ̀rúnmìlà: dos gallinas, dos chivas y 3,200 cauríes.", "Contra la sed y la debilidad: dos caracoles y medicina de Ifá para baño.", "Contra los enemigos de viaje: cuatro palomas, cuatro aves, aceite de palma, cuatro bolsas de harina de maíz, un plato blanco, dos botellas de ginebra y dinero, a las Ìyàmi; antes de dar la ginebra a los enemigos, la persona bebe un trago frente a ellos.", "Para fama: cuatro palomas, cuatro aves, kola, orógbó, un plato blanco, aceite de palma y dinero; tabú: comer sopa directo de la olla.", "Contra la enfermedad en la familia: dos palomas, nueve kolas, una gallina y un gallo.", "Ofrenda a Ṣàngó y a las brujas (àjẹ́) para dormir tranquilo."], "pasajes": [{"titulo": "Ofrenda en el verso 10.1", "texto": "Kasá kaja-katetesa:\nadivinó Ifá para los dos Ọ̀sá.\ncuando los dos Ọ̀sá iban a Ifè para adivinar.\nEl adivino dijo:\n\"algo puede espantarlos (asustarlos)\ne impedir que sus proyectos sean llevados a cabo,\npor esta razón debían sacrificar:\ncarnero padre y una piedra de rayo.\nEllos rehusaron hacer el sacrificio.\nCuando ellos llegaron a Ifẹ, surgía un fuego (una lucha).\nEllos trataron de combatirlo pero no pudieron\ny tuvieron que huir corriendo.\nDesde ese día, los dos que huyeron corriendo\nhan sido llamados Osáméji.", "origen_id": "adf028731c39f7ca4b0ff22f"}, {"titulo": "Ofrenda en el verso 10.2", "texto": "İgbín ko ya palaka ẹsẹ:\nadivinó Ifá para un Ọ̀sá (una pata Ọ̀sá),\ncuando vagaba errante solo por el mundo.\nEl adivino dijo:\n\"puede encontrar su pareja (buena pareja)\nsi efectúa un sacrificio\":\ndos palomas, dos caracoles de babosa y medicina de Ifá.\nỌ̀sá escuchó y efectúo el sacrificio.\nCualquiera para quien este Ifá sea adivinado\ntendrá muchos hijos.\n\" ljà: lucha, pelea, guerra. Iná: fuego.\n3' N.T.: Vencer los obstáculos y dificultades en su camino.\n\"' rin kiri: s. viajar errante, vagabundear, andar errante de un lugar a otro sin\nestabilidad.", "origen_id": "0b8e5bcf40d50acd7990c322"}, {"titulo": "Ofrenda en el verso 10.3", "texto": "Ọkan-atẹgun-kose-irode’lẹ:\nadivinó Ifá para Ọ̀rúnmìlà,\ncuando él quería en matrimonio a Olúyemi,\nquien era hija de Ọlọ́fin.\nEl adivino dijo:\n“si solo se casa con Olúyemi,\nsu riqueza (abundancia) será muy grande”.\nDos gallinas, dos chivas y 3200 cowries son el sacrificio.", "origen_id": "0e4525c4fbc88e0e25104782"}, {"titulo": "Ofrenda en el verso 10.4", "texto": "adivinó Ifá para Ajá.\nél fue aconsejado sacrificar:\ndos caracoles de babosa y medicina de Ifá,\npara bañarse con la medicina\nporque una sed excesiva estaba extenuado su cuerpo\n(le traía debilidad y cansancio)\nAjá rehúso hacer el sacrificio.\nEl dijo:\n\"que la saliva de su boca\nera suficiente para calmar su sed\".", "origen_id": "a3f81600e5acceca6e49f694"}, {"titulo": "Ofrenda complementaria 1", "texto": "4 eiyelé (pichón), 4 adie (ave), 1 epo (botella de aceite de palma), 4 bolsas de harina de maíz, 1 plato blanco, 2 oti (botella de ginebra seca) y 100 nira (dinero)\n\nDestinatario: Iyàmi", "origen_id": "f10b74b3ae870229c08ab0db"}, {"titulo": "Ofrenda complementaria 2", "texto": "4 eiyelé (pichón), 4 adie (ave), obi (nueces de origen africano), orogbo (nuez amarga), 1 plato blanco, 1 epo (botella de aceite de palma) y 25 nira (dinero)", "origen_id": "b552e3c82f3e763a4182f636"}]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó (Olúkòso, Àrìrà) da la victoria. Las Ìyàmi o àjẹ́ reciben la ofrenda para no perturbar el sueño. Ọlọ́fin da a su hija a Ọ̀rúnmìlà.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Oyà", "origen_id": "d7d95d94118a4faf73c3d683"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de biyẹnmẹ cocinadas con huevos, para que coma la mujer que busca pareja. Contra la sed y la debilidad: hojas de tẹ̀tẹ̀rẹ̀gún (Costus afer) machacadas en agua con el líquido de un caracol, para bañarse. Piedra de rayo, algodón, ginebra. Ante debilidad, sed excesiva o estreñimiento persistentes, conviene ir al médico."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 10.2", "texto": "moler las hojas de bíyẹnmẹ , cocinarlas con huevos pallins. Medicina para que la coma la persona (ella).", "origen_id": "b1a1429a7146b64ea00cfb60"}, {"titulo": "Verso 10.4", "texto": "machacar hojas de tẹ̀tẹ̀règún en agua, romper la punta de la concha del caracol babosa, mezclar el fluido del caracol en el agua de tẹ̀terègún. Esta medicina es para bañarse el cliente.\nDice Ifá: El cliente para quien este Ifá es adivinado no está gozando de buena salud. Los síntomas de una enfermedad en el cuerpo son: debilidad, cansancio, extenuación, estreñimiento, sequedad en la boca.\n3° tẹ̀tẹ̀règún: CosTUS AFEr Ker Gawl., Costaceae.", "origen_id": "0bca764a644930f10f27d449"}]}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 2", "texto": "sopa; comida de la cazuela", "origen_id": "5debfd86559824c69fc396d0"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 10.1 (yorùbá): Kasá kaja-katetesa: / li o dífá f'Èji-Ọ̀sá, / Eji-Ọ̀sá nsawo lọs'alẹ lfè / Wọ̀n ni: / \"Inkan kan a maa wa dèrùbaa / koni jẹki o duro ṣe iṣẹ awo rẹ̀\", / nitorinaa kio wa rú: / agbo ati ẹdùn-ààrá. / Ó kọ ko rú. / Nigbati wọ̀n de alẹ-Ifẹ, lja de wọ̀n / ja wọ̀n ko le ja, wón sá. / Nje ojọ ti eniméji sá, / kia maa pee ni Osáméji.", "Verso 10.2 (yorùbá): İgbín ko ya palaka ẹsẹ: / li o difá f'Ọ̀sá kan, / nigbi oun nikan rin kiri ayé. / Wọ̀n ni: / \"a pe Méjì, biobarúbo\": / ẹyẹlé Méjì, igbin Méjì ati ewé Ifá. / Ó gbọ̀ ó rú. / Eniti a dá'fá yi fún yio o bimo pupo.", "Verso 10.3 (yorùbá): Pkan-atogun-kose-irode'lẹ: / 1o difa fOrúnmilà, / Hgbi oun mi lọ fẹ Olúyemi, / Họn qmọ Ọlọ̀fin / Wọ̀n nì: / biobani oun nikansoso, glà rẹ̀ a ga\". / Abo-adiẹ Méjì, ewúré Méjì / atl egberindilógún owó li ebọ.", "Verso 10.4 (yorùbá): onvermeyenme / Ннeнa гA / Wọ̀n niki ô rú: / Igbin Méjì ati ewé Há, / kiofi wẹ nitori ohaha, / Ki ara baa le rọọ. / Ajá kọ ko rúbọ. / O ni: / \"ito enú oun ti to lati pa oungbẹ\". / Oliyẹnmẹyenmẹ:", "REZO: OSA MEYI ORUNMILA DIFAYOKO ORDOFUN OLGUEN DIROYUN KODE AKAFARA TOFIKO DIGUON KALE IFA (BURO, BARAYA ADIFAFUN OGUE).", "REZO: BABA BURU BURU BABA FOSHE EFAN ABRAGAN OMO ODE AMI INU ADIE OPACARA ENU ORUN COLLO MASILE ONI ADIFAFUN OQUE NIBA OFERO SOFO LOGUO ONIANA LOGUO ELEBO EYELE MENI ASHO TIMBELARA UCO EPO.", "REZO: BABA BURU BURU BABACOCHE CHOCO EFAN ABA ABRAGAN OMO AMI INU ARDIE OBAPA CACARA ORUN COLLIMA SILE ANIBANA ADIFAFUN OQUE NIBATE OLOFAROSOFA LOGUO ONIBANA.", "REZO: KOKO DE OJU OROKUN O PINONA DE ORI APATA PORURU YEWERE NOJOTI O MAWA IJEGBE ATI EJEGBO NWON NI KI O MAWA NWON ONI ON YIO NAWON OSI NAWON.", "REZO: ADA OSHE ADIFAFUN ORUNMILA, LORDAFUN TALABI OMODE OSHAYAN ASHEGUN AYE UMBO WASIYE ORUNMILA PINADO IYASI MIMO KAFEREFUN OGGUN.", "SUYERE: “IFA ODARA, EMI ODARA MOYUKAYO MAMA WANKEREPO, MODUKAY MANNEREPO”.", "REZO: OSA BERE LERI OSA BERE LERI BAYEKUN IKU EWA NI SHANGO ERAN ABO MAMARA UNYEN EUKU IKU KI ABEREMI WARA LA LELI ABEYI LODA OLU BERU BERUN OLOKUN UNYEN OWUNKO WARA WARA YENI OSA BERE OSA OSA EGUEDE OBI EWE BABA EGGUN, EYA TUTO YEYE YEKUN IKU BABA ORISHA ORUNMILA EYENI LAYE, OSHA UNYEN EYA TUTO DE AGUA WAYE IKU FUMI ABEREMI LAYE, EYA ORUN SHANGO KEREKE LE ABEYE OSA BIOSA, OSA MEYI OSA EYA."], "pasajes": [{"titulo": "suyere", "texto_ritual": "PIRITI PIRITI OMODE ALARA. PIRITI PIRITI OMODE ALARA. PIRITI PIRITI OMODE ALARA, LAMINAGADDA.", "origen_id": "20a61693405fc22fa315173d"}, {"titulo": "suyere", "texto_ritual": "OFALODE ONI SHANGO OBARA LAYENI GRIYELU INLE ILE BAYE.", "origen_id": "41baab353e3386cfd54087d2"}, {"titulo": "suyere", "texto_ritual": "ORONIKI BAKULADO OSALOBEYO MAYAGARA IRKI IKUE LA SHEREWA.", "origen_id": "6c076a02b01f5d3aaa4d27ad"}]}]$q$::jsonb),
(11,'b61217170c33bce706ce9bb38beae4e3','97f717154d2d5f3ea755620b3cbf5849',$q$[{"titulo": "Idea central", "texto": "Ìká Méjì es el Odù de las preocupaciones, las inquietudes y la gente que goza con el dolor ajeno. Pide vivir con moderación, cuidar la cabeza (Orí) para decidir bien y no confiar a ciegas ni en parientes ni en amigos. Quien cumple con Ifá y con Ògún vence la muerte, la enfermedad y la pérdida; es además un buen momento para el embarazo.", "pasajes": [{"titulo": "Frase clave", "texto": "Ika crea desarrollo del poder de la palabra.", "origen_id": "ae4fdaefa5659cf3642792a2"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Junta preocupaciones de dinero, familia o salud y necesita decidir sin prisa.", "Desea un embarazo o hijos (relato de Bara Àgbọnnìrègún y el maíz).", "Teme que la envidia o los celos de otros le quiten una oportunidad.", "Hay un viaje o un trabajo con extranjeros que puede traer abundancia (relato de Erelu del Océano).", "Debe cuidar lo que dice y cómo habla de los demás: la palabra construye o destruye.", "Se confía demasiado en su posición y desoye un aviso (relato de Eyin), o actúa con fuerza sin prepararse (relato de Ògún).", "Hay una disputa de pareja (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser librado de las garras de la muerte, de la enfermedad y de la pérdida.", "Vida larga y firme, como la montaña que no muere.", "Muchos hijos y fecundidad en el mundo.", "Abrirse camino propio, como el fuego que avanza quemando lo que tiene delante.", "Protección de la esposa y del hogar frente a quienes quieren quitarlos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Problemas grandes que aparecen de golpe, sin aviso.", "Enemigos que por envidia bloquean las buenas oportunidades.", "Hijos poco confiables y apuros de dinero.", "Dejarse llevar a un lugar con promesas de grandeza y caer en una trampa.", "Despreciar la ofrenda por creerse ya coronado."]}, {"titulo": "Enseñanza principal", "texto": "Cada quien recoge lo que siembra. La corona que uno lleva encima no lo exime de ofrendar: el que se cree demasiado grande para pedir consejo es el primero en caer en el foso. Quien da a tiempo recibe las armas para defenderse, como el gato recibió sus garras."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odú Ìká Méjì significa muchas preocupaciones, inquietudes y angustias, por tanto llama a vivir y actuar con moderación. Con el sacrificio correcto es posible llegar a ejercer el control sobre esos problemas.\nLos hijos de Ìká Méjì están siempre rodeados de personas que están dispuestas a ocasionar daños y dolor a otros o que sienten placer con el sufrimiento ajeno.\nEllos constantemente deben estar alertas, porque no pueden contar con la ayuda de su familia, ni de sus amigos. Carecen de personas que los ayuden.", "origen_id": "ed3916e4dabf4ea4454ba763"}, {"titulo": "Características generales", "texto": "Otros nombres: Ìká Méjì; Ejiká.\nEl Odu Ìká Méjì ocupa el onceno lugar en orden inalterable de Ọ̀rúnmìlà Una persona de Odù Ìká Méjì siempre recogerá el fruto de lo que fue capaz de sembrar. Ellos necesitan propiciar sus cabezas (Orí) a menudo para tomar buenas decisiones y saber elegir correctamente.\nÌká Méjì en adivinación, dice que el cliente enfrenta dificultades, él o ella tienen enemigos que por celos o envidia están tratando de bloquear y obstruir sus buenas oportunidades. El cliente también esta sufriendo a causa de la carencia de hijos dignos de confianza y por problemas financieros. Sin embargo, si el cliente ejecuta los sacrificios apropiados a Ifá y a Ögún, él o ella tendrán ilimitadas oportunidades para convertirse en productivos y fructíferos.", "origen_id": "87efedc28e3d91a4eccd5bc3"}, {"titulo": "Interpretación tradicional", "texto": "Ika significa atraer o juntarse. En términos espirituales, se refiere a una asamblea de poder personal (ase). El poder personal se pone de manifiesto a través del uso de invocación ó a través del uso del poder de la palabra. Ika en una manifestación positiva, puede ser el origen de poder personal usado para protección como sanar, transformación y la creación de abundancia. Es el elemento fundamental en el proceso de afirmación de uno mismo. La manifestación negativa de Ika, es el origen de embrujos propios, chismes y denigración injusta del otro.", "origen_id": "ee6614935242cb0d55244bef"}, {"titulo": "Orientación complementaria", "texto": "Ika significa juntar. Una persona junta sus recursos cuando son a punto de ya sea bendecir algo o embrujar algo. El juntar es parte del proceso de acceso del poder de la palabra (ofo ase). Ifá enseña que las palabras tienen la habilidad de transformar la realidad física. En su manifestacion negativa, e comportamiento impropio de Ika es el uso no ético del poder de la palabra embrujar, chismear y la expresión de denigración.", "origen_id": "840ca07a7206b82e7982a7b9"}]}, {"titulo": "Relatos reunidos", "puntos": ["Oníkàámògún y el pangolín. Oníkàámògún, hijo del pueblo que aparta la mano de la muerte, fue a consultar porque la enfermedad y la muerte rondaban su casa. Le pidieron ofrendar y le advirtieron que debía añadir un pangolín (àkàká) a la ofrenda. Lo hizo tal como le dijeron. Desde entonces no volvió a enfermar ni a ver la muerte de cerca. Por eso se canta que el pangolín, que se enrolla dentro de sus escamas, hace rodar lejos todas las desgracias.", "Òràmolè, la montaña que no muere. Òràmolè, la montaña, preguntó cómo podría pasar por la tierra sin morir. Le pidieron ofrendar completo, sin dejar nada a medias, y lo hizo. Pasaron veinte años y la montaña seguía allí; pasaron treinta y seguía en pie, firme y pesada en su sitio. Por eso quien recibe este Odù pide que lo encuentren fuerte, vivo y sin muerte, como la montaña.", "Eyin y la corona. Eyin fue advertido de que un gran problema iba a caerle de repente, y que debía ofrecer un gallo y lo que el sacerdote escogiera. Respondió que con la corona tan hermosa que tenía sobre la cabeza no necesitaba ir a ningún adivino. No ofreció, y el problema llegó de golpe, cargado de angustia.", "Bara Àgbọ̀nnìrègún y las dos mazorcas. Ọ̀rúnmìlà iba a Ifẹ̀ a buscar la bendición de los partos. Le mandaron sembrar dos granos de maíz y ofrecer dos gallinas. Sembró, cuidó la siembra y, cuando el maíz dio espigas, cortó dos mazorcas para agasajar su cabeza. Entonces se dijo que quien corta dos mazorcas para su Orí se llama Ìká Méjì, y que tendrá muchos hijos en el mundo.", "La esposa de Ọ̀rúnmìlà y los vientos secos. Ọ̀pẹ̀, la esposa de Ọ̀rúnmìlà, estaba a punto de ser seducida. Ọyẹ, el viento seco y polvoriento, y Ọwọrẹ, la temporada más seca del año, querían treparse a ella y arrebatársela. A Ọ̀rúnmìlà le pidieron ofrecer dos cabezas de cobra y una soga de las que se usan para subir a las palmas. Cumplió, y ni Ọyẹ ni Ọwọrẹ pudieron trepar a la palma: se quedaron sin fuerza ante ella.", "Ògún y el ñame asado. Ògún salía a atacar la ciudad de sus enemigos. Le pidieron ofrecer una calabaza de vino de palma, un ñame asado y aceite de palma, y no quiso. Peleó y ganó la batalla, pero de regreso uno de sus hombres le dio un pedazo de ñame asado; se le pegó en la garganta, no pudo tragarlo y se quedó sin habla. Desde ese día, cuando le hablan, Ògún responde con la cabeza y con las manos.", "La tortuga, el elefante y el foso de Ilabẹsan. La gente de Ilabẹsan necesitaba un elefante para un sacrificio, y la tortuga se ofreció a traerlo. Fue a buscarlo y le dijo que lo querían hacer rey. El elefante, halagado, la siguió. Antes de llegar habían cavado un foso grande y lo habían tapado con hojas y tierra. La tortuga entró delante, ligera; el elefante pisó detrás, la tierra cedió y cayó al fondo. Allí lo mataron para la ofrenda. Quien se deja llevar por promesas de grandeza sin consultar termina en el pozo.", "El gato y las seis agujas. El gato no lograba atrapar lo que perseguía: todo se le escapaba. Le pidieron ofrecer seis agujas. Las ofreció, y las agujas se le volvieron garras. Desde entonces lo que el gato agarra ya no se le escapa.", "El fuego que abre su camino. El fuego preguntó cómo abrirse paso por el monte. Le pidieron tres gallos y aceite de palma. Ofreció, y desde entonces el fuego avanza consumiendo lo que tiene delante y se hace el camino solo.", "Erelu del Océano y el bote. Erelu del Océano, hija del bote y del lugar santo que está sobre el mar, buscaba abundancia. Le pidieron ofrendar y cumplió. Desde ese día recibió todas las bendiciones que pidió, y cuando se puso a bailar en alabanza, Èṣù le puso una canción en la boca: ven, bote mío, tiembla, bote mío; es buen mar por donde navega mi bote. Este Odù protege a quien sale de viaje, a quien vive del agua y a quien se hace rico trabajando con un extranjero.", "Agbadu, la víbora que espantaba a todos. Agbadu, la víbora de panza suave, iba a ser nombrada jefa. Le pidieron ofrendar y se negó. Desde ese día, todo el que ve a Agbadu sale corriendo. Así le pasa a quien, por ansiedad y desconfianza, ahuyenta a la gente que quiere ayudarlo; necesita valor para dejarse ayudar. El hijo de Ìká Méjì no come mono gris."], "pasajes": [{"titulo": "Verso 11.1", "texto": "Qdan-gejẹ awo Ata-nde:\nadivinó Ifá para Eyin\nEl adivino dijo:\n\"debe sacrificar a causa de un\ngran problema que aparecerá de inmediato\"\nUn gallo y lo que el Babaláwo\nseleccione como sacrificio.\nEyin dijo:\n\"con la maravillosa corona que esta sobre mi cabeza,\n¿por qué tendría que considerar\nir a ningún Babaláwo para sacrificar?\"\nÉl francamente se negó a sacrificar.\nDice Ifá: grandes problemas, conflictos o dificultades no previstas (que\naparecen al momento), surgirán para cualquier persona a quien se le\nadivine este Ifá, trayéndole preocupaciones, angustia e inquietud.", "comentario": "3 Se refiere a hijos con posibilidades de sobrevivir o hijos saludatts pran igbonagbooru: gran problema que aparece de inmediato, anomen mto, de repente, de forma imprevista.", "origen_id": "c3bd5fe6ca25265a164b1afb"}, {"titulo": "Verso 11.2", "texto": "Etuṣẹṣefi'nu-igboṣe'le,\nOniwakawakafi'nu-isaṣe budo:\nadivinaron Ifá para Bara Àgbọnnìrègún,\ncuando iba a lfè para lograr un bien de nacimientos (partos)\nSe le aconsejó sacrificar:\ndos granos de maíz (Qkà Méjì) y dos gallinas.\nEl ejecutó el sacrificio, plantó el maíz,\ny lo cortó cuando estuvo maduró (tuvo espigas)\npara propiciar su cabeza (Ori).\nEllos dijeron:\n\"quien corte dos espigas de maíz para agasajar su cabeza\ndeberá ser llamado ikáméji\"\nCualquiera para quien este Odù sea adivinado\ntendrá muchos hijos, o se convertirá en muy fructífero en el mundo.", "origen_id": "fb1e6e43a1d5e78c5e4d7f5e"}, {"titulo": "Verso 11.3", "texto": "Ojojoṣe-idiberẹ:\nadivinó Ifá para Çrúnmilà,\ncuando su esposa estaba a punto de cometer adulterio.\nA él le fue aconsejado sacrificar:\ndos cabezas de cobra y una soga de escalar palmas,\npara evitar que la gente seduzca a su esposa.\nEl escuchó el consejo y realizó el sacrificio.\nQyẹ y Oworẹ que eran rivales de Ọ̀rúnmìlà\npara arrebatarle la mujer (trepar a su mujer),\nse incapacitaron para seducir a la mujer de Ọ̀rúnmìlà,\nporque Ọ̀rúnmìlà había sacrificado.\nLa esposa de Ọ̀rúnmìlà se llama Ọ̀pẹ̀.\n1\" Qyẹ: Viento polvoriento extremadamente seco que sopla en el desierto del\nSáhara hacia la costa occidental de África, generalmente entre noviembre y\nmarzo.\n* Oworẹ: La etapa más seca de la estación de sequía.", "origen_id": "796f3a5ea5033a128dad61f0"}, {"titulo": "Verso 11.4", "texto": "Omipẹnṣen-akodun-koro:\nadivinó Ifá para Ogún,\ncuando iba a atacar la ciudad de sus enemigos.\nLe aconsejaron sacrificar:\nun agbe\nde vino de palma, un ñame asado y aceite de palma.\nOgún rechazó sacrificar.\nLos Babaláwos dijeron: Dice Ifá:\n\"antes de regresar a su casa\nél será envenenado,\nporque rechazó realizar el sacrificio prescrito\".", "comentario": "Ogún fue a la lucha sin realizar los sacrificios prescritos, combatió y ganó la batalla. Sin embargo en el camino de regreso a casa, uno de sus hombres le ofreció un pedazo de ñame asado, cuando él se lo comió, el ñame se pegó a su garganta y no pudo tragárselo, al extremo de quedarse sin poder hablar. Desde ese día cuando se le habla, él utiliza su cabeza y manos para articular sus respuestas.\n42 Agbe: Recipiente hecho de una calabaza gigante (parecida a la güira de Cuba, pero de una planta rastrera), a la que se hace un agujero en la parte superior para guardar líquidos. En Cuba se emplea el güiro amargo. Agbe-ẹmu: Calabaza de vino de palma.\n* agbe: recipiente tradicional yoruba usado para tomar líquidos. Se fabrica abriendo un agujero en la parte superior de una calabaza africana, se vacía su contenido y se limpia para que sirva como jarra para beber. En Cuba se puede construir con un güiro amargo de tamaño mediano.", "origen_id": "ab82cd9a652282a8ff3c1bc1"}, {"titulo": "Versos complementarios 1 · A", "texto": "Ifá pé ire fún eléyìn. Ifá pé òun ó gbà á kalè' 'lówó ' ikú,' lówó\n                                                                 ' àrùn, òfò àti gbogbo\n ajogun. Ifá pé ká fi aaka kún' ebo\n                                 '  rú. Ifá pé  ire ó to  lówó.\n                                                         ' '\n  Káwó' fún mi\n  Kí n kásè\n          ' fún' o\n  A díá fún Oníkàámògún\n' Omo' Aláaka káwó  ' ikú\n  Wón\n   '    ní ó sá káálè\n                   ' ' ebo\n                        ' ní ó' se\n  Wón\n   '    ní ó fi aaka kún' ebo\n                           ' ' è rú\n  Kò kú\n  Kò rùn\n  Kà sàì kábi kúò\n  Akika\n  Akika kà sàì kábi kúò\n  Akika\n\n Ìká Méjì A\n Ifá desea bien a esta persona. Ifá dice que él lo salvaría de las garras de la muerte,\n enfermedad y pérdida. Él debe agregar Aaka a su sacrificio.\n\n Káwó fún mi\n Kí n kásè fún o\n Adivinación lanzada para Oníkàámògún\n El niño de Aláaka káwó ikú\n Le pidieron que cuidara de la tierra y ofreciera sacrificio\n Le pidieron que agregara Aaka a sus objetos de sacrificio\n Él no se murió de nuevo\n Ni él no se cayó enfermo\n ¿Qué rodarían todas las malas fortunas lejos?\n Akika\n Akika rodarían todas las malas fortunas lejos\n Akika", "origen_id": "dd858d5790023c30e11721bb"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé kó síkú mó\n                ' , kò sí àrùn mó\n                               ' fún eleyiun. Ebo\n                                               ' ni kó rú.\n  Agbáágbá Orí' etu\n  A díá fún' Òràmolè  ' '\n  Èyí ti´´n rayé ìlaì níí kú\n' Ebo\n   ' n wón   ' ´´ní ó' se\n  Ó sì gbébo\n          ' ' nbè  '\n  Ó rúbo\n       '\n  Ògún' odún òní´´nkó    ' o?\n  Òkè´´n be '   láìkú\n  Gbonhingbonhin\n   '             '        n tòkè\n  Òkè gbonhingbonhin\n          '          ' ´´\n  Ogbón\n' '´´ '       odún  òní  nkó\n                          ' o?\n  Òkè n be  '   láìkú\n\n  Gbonhingonhin\n    '     '       n tòkè\n  Òkè gbonhingbonhin\n        '       '\n  Kèè pé\n      ' o\n  Kèè jìnnà\n' E wáá bá ni láìkú kangiri\n  Àìkú kangiri làwá wà\n\nÌká Méjì B\nIfá dice no hay ni muerte ni enfermedad para esta persona. Él debe ofrecer sin\nembargo por completo su sacrificio.\n\nAgbáágbá Orí etu\nAdivinación lanzada para Òràmolè\nEl que sobreviviría la muerte en la tierra\nEllos le pidieron que realizara sacrificio\nÉl oyó hablar del sacrificio\nY lo realizó\n¿Veinte años de hoy?\nEl Montañés todavía exista sin morir\nGbonhingonhin es para la Montaña\nLa Montaña es el gbonhingonhin existente\nTreinta años de hoy\nLa Montaña existe sin morir\nGbonhingonhin es para la Montaña\nLa montaña existe sin morir\nAntes de mucho tiempo\nEn el futuro más cercano\nVenga y encuéntresenos fuerte sin morir\nNosotros estamos viviendo sin la muerte y en la vitalidad", "origen_id": "552ede517f0d84fe3c3be640"}, {"titulo": "Relatos y ofrendas", "texto": "ÌKÁ MÉJÌ\n\nEl - pájaro, - vuela, - en - el - cielo, - mientras - el - extranjero - viaja - por — el - océano, -\nmientras — el - perro - viene - a - tomar - un - nombre, consulta Ifá para Erelu del Océano, el hijo\ndel bote del océano, el lugar santo encima del océano, en el día que estaba buscando abundancia.\nIfá aconsejó a Erelu del Océano hacer ebo. Erelu del Océano hizo ebo. . Desde ese día Erelu del\nOcéano recibió todas las bendiciones que pidió. Erelu del Océano empezó a cantar y bailar en\nalabanza del Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó a O/odumare. Cuando Erelu\ndel Océano empezó a cantar, Esú puso una canción en su boca. Erelu del Océano canto:\nOkò mi si, okò mi gbo, oko mi si, okò mi gbo\nEbute ire l oko mi lo. Ebuté ire I oko mi lo,\nBote del océano ven, bote del océano tiembla. Bote del\nOcéano ven, bote del océano tiembla.\nEs buen océano donde el bote esta navegando. Es bun\nOcéano donde el bote esta navegando.\nComentario:\nIfá dice que esta persona debe hacer ebo si van a un viaje. Ifá dice que esta persona debe hacer\nebo si se ganan la vida con un bote. /fá dice que esta persona se volverá rica si trabajan con un\nextranjero.\nEtutu (ofrecimiento): un bote pequeño de madera (para ser puesto en el plato blanco). Ògedẹ̀\nwéere (plátano), eyin (huevo), 1 epo (botella de aceite de palma), 1 adie (ave) y dinero\ndeterminado por el adivinador, ofrecido a Esú.\n(Étùtù (oferendas); barco pequeno de madeira (a ser colocado no prato branco), ógedé\nweére (banana), ein (ovo), 1 epo (garrafa de azeite de dendé), 1 adiye (ave) e uma quantidade\nde dinheiro determinado pelo 4wo, oferecido a Ésú.)\n\nEres - malvado, - soy — malvado, consulta Ifá a Agbadu (víbora) que estaba suave de la panza en\nel día que Agbadu iba a ser jefe. Ifá aconsejó a Agbadu hacer ebo. Agbadu rehusó hacer ebo.\nDesde ese día, cuando cualquiera veía a Agbadu, corrían lejos.\n\nComentario:\n\n94\n\nIfá dice que esta persona esta teniendo un tiempo difícil en una relación personal. Ifá dice que si\nesta persona está casada, tiene problemas en su matrimonio. Ifá dijo que esta persona es\nextremadamente ansiosa y ésta condición está haciendo sus problemas peores. Ifá dice qué hay\npersonas que quieren ayudarla, pero los esta ahuyentando. Ifá dice que esta persona necesita\ncoraje.\n\nEtutu (ofrecimiento): 1 ori agbadu (cabeza de una víbora), 1 eiyelé (pichón). 1 adie (ave). 1 epo\n(botella de aceite de palma) y dinero que será determinado por el adivinador ofrecido a Ésú.\nEéwo (tabú): un mono gris.\n\n(Ett (oferendas); 1 orí agbadu (cabeca de serpente), 1 eiyele (pombo), 1 adiye (ave), 1 epo\n(garrafa de azeite de dendé) e uma quantidade de dinheiro a ser determinada pelo 4wo,\noferecidos à Esú. Eéwó (tabu): macaco cinza.)\n\nInu\nn  n\nI I\nInu", "origen_id": "fd30921476c38e5834426098"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ika Meji significa muchas preocupaciones y por lo tanto para\n     evitar restricciones, con el sacrificio correcto es posible ejercer control.\n           Los hijos de Ika Meji están siempre rodeados de personas que están\n       dispuestas a castigar con dolor a otros o disfrutar de los sufrimientos\n     ajenos. Ellos constantemente deben estar en guardia y alerta porque no\n\npueden contar con su familia ni con amigos para que los ayuden.\n                        WO - Este es un buen tiempo para una concepción.\n          El Odu Ika Meji ocupa el decimoprimer lugar en el orden fijo de\nOrunmila, ellos siempre recogerán lo que él o ella siembre, los hijos de Ika\nMeji necesitan atender sus cabezas (ori) a menudo con el objetivo de hacer\n                                                       selecciones correctas.\n           Si Ika Meji es marcado para un cliente, Ifá dice que el cliente se\n  enfrenta con dificultades. El cliente tiene celos de sus enemigos quienes\n      están tratando de bloquear sus oportunidades, él o ella están también\n      sufriendo de la falta de la independencia de sus hijos y de calamidad\n      financiera. Pero si el cliente ejecuta los sacrificios apropiados a Ifá y\n         Oggún, él o ella tendrán ilimitadas oportunidades para convertirse\n                                                    productivos y fructíferos.\n\n\n11.1 · Odan-geje awo Ata-nde, adivinó Ifá para Eyin (fruto de la\n      palma), le fue aconsejado ejecutar sacrificio por las preocupaciones.\n              Ebo: 1 gallo y lo que el Babalawo le seleccionaría tener como\n       sacrificio. Eyin dijo, que con la maravillosa corona sobre su cabeza,\n              él nunca consideraría ir a ningún Babalawo para sacrificar. Él\n     obtusamente negó sacrificar. Ifá dice que cualquiera por quien Ifá sea\n                                                adivinado está en problemas.\n\n\n11.2 · Etusesefi´un-igboge´le, Oniwakawakafi´un-isase´budo, son los\n          que adivinaron Ifá para Bara Agbonniregun, quien iba a Ife para\n\ncomenzar el parto. Le fue dicho que tenía que sacrificar 2 granos de\n         maíz y 2 gallinas. Él ejecutó el sacrificio, él plantó el maíz el cual\n  cortó cuando se maduró para propiciar su cabeza (ori), ellos dijeron el\n    que corte dos mazorcas de maíz para deidificar su cabeza deberá ser\n         llamado Ika Meji. Cualquiera para quien este Odun sea adivinado\n              tendrá muchos hijos o se convertirá en fecundo en el mundo.\n\n\n11.3 · Ojojose-idibere, Adivinó Ifá para Orunmila cuando su esposa\n   estaba por cometer adulterio. Le fue preguntado sacrificar 2 cabezas\n             de cobra y 1 soga para escalar. Para prevenir que las personas\n    seducieran a su esposa. Él atendió el consejo y ejecutó el sacrificio.\n           Oye y Owore fueron los rivales de Orunmila, ellos no pudieron\n    seducir a la esposa de Orunmila porque Orunmila había ejecutado el\n                sacrificio. La esposa de Orunmila es llamada Ope (palma).\n\n\n11.4 · Omipensen-akodun-koro profetizó para Oggún cuando él iba\n           atacar a sus enemigos del pueblo, le fue aconsejado sacrificar 1\n   cuñete de vino de palma, ñame asado y manteca de corojo. Oggún se\n                                                            negó a sacrificar.\n    Los Babalawos dijeron: Ifá dice que él será envenenado allí antes de\n   regresar a casa, porque él se negó a ejecutar el sacrificio prescrito. Él\n    llegó allí, luchó y ganó la batalla, en su camino hacia la casa uno de\n   sus hombres le ofreció un pedazo de ñame asado, el cual él se comió,\n         el ñame se le atragantó en su garganta, el estaba incapacitado para\n\ntragárselo. Al final no podía hablar, si tú le hablas a él, él usa su\n cabeza y sus manos para articular sus respuestas hasta este día.", "origen_id": "c2665d0244c1a1c2bdeda01b"}, {"titulo": "Relato en inglés 1", "texto": "“Three streets of the house in Ila, roads of Ojomo odo;? three reach home,\nthree don't reach home” and “Very small palm tree of the house of Irojo yields\nvery good palm wine” were the ones who cast Ifa for the people of Ilabesan on the\nday their king died.? They said they should bring an elephant with which to make:\na sacrifice. All the hunters of the town tried to catch an elephant, but failed;\nTortoise said that he would do it. He took all the things that the mouth eats and\ncarried them out to Elephant. When Elephant had tasted them, Tortoise said,\n“These are the things that you, Elephant, will be eating if you come home so that\nthey can make you king, because the king of the town of Ilabesan has died, and you\nare the one they want to make king.” When Elephant heard this, he was happy, and\nhe followed Tortoise, and Tortoise sang:\n\n“We will take Elephant and make him king, Shẹkurẹbẹlẹ;?\n“We will take Elephant and make him Ming, Shekurebele.”\n\nThus Tortoise sang until these two\n\nreached home. When they entered into town, the townspeople saw Elephant and\nbegan to cheer, “Ye!” Elephant was frightened, but Tortoise encouraged him, say-\ning, “Don’t you see how happy the townspeople are to see you?” But before Ele-\nphant and Tortoise entered the town, the townspeople had dug a pitfall for them,\njust as Tortoise had instructed before he went into the forest to get Elephant.\nWhen Elephant entered the town, the townspeople had spread a mat on top of the\npitfall. And they said that Elephant should come and sit upon it, because the mat\nwas to be the throne on which he was to sit, When Elephant tried to sit down on\nthe mat, the mat fell into the pitfall, and Elephant fell into the pitfall with it.\nWhen the townspeople saw that Elephant had fallen into the pitfall, they took sticks\nand killed him. Thus the people of the town of Ilabesan were able to sacrifice an\nelephant for the good of their town, with the help of Tortoise, and their town be-\ngan to run smoothly again.\"\n\nIfa says there is someone whose head? will place him in an important posi-\ntion, but the person who will help him will come to his aid suddenly, and someone\nhe does not expect will be his helper.", "comentario": "1. Ojomo odo is an unidentified town; Ila is a town about forty-five miles\nnortheast of Ifẹ.\n\n2. The euphemism used here is “entered the house of rain.” Ilabẹsan is an\nunidentified town.\n\n3. Shẹkurẹbẹlẹ has no meaning but is added as the refrain “to make the song\nsound sweet.”\n4. Cf, the versions of this folk tale recorded by Frobenius (1926: 289-292);\nOgumefu (1929: 65-68; n.d. 7-9); Jacobs (1933: 9-11); and Walker and Walker\n(1961: 61-63),\n\n5. That is, his luck or destiny; an important position or office is in store for\nthis person.", "origen_id": "ff881792ec688c994d493577"}, {"titulo": "Relato en inglés 2", "texto": "“Pouncing,” the diviner of Cat, was the one who cast Ifa for Cat when he was\ntrading every day, but having his profits slip from his grasp. They said he\nshould sacrifice six needles, six pigeons, and three shillings.1 He made the\nsacrifice. From that time on, Cat has never again had things slip from his\ngrasp.”\n\nIfa says there is someone who is having everything slip from his grasp; he\nshould sacrifice so that things will never slip from his grasp again.", "comentario": "1. Since cowries are counted by units of 2000, there are six units of cow-\nries here, as there are six needles and six pigeons.\n\n2. It is understood that the needles became Cat’s claws, with which he keeps\nthings from escaping from his grasp. This verse thus explains how cats came to\nhave claws, and why they can hold things tightly.", "origen_id": "f54820a84e8f8fe6563fe03b"}, {"titulo": "Relato en inglés 3", "texto": "“To pay homage from afar”? the diviner of Fire, was the one who cast Ifa for\nFire. They said wherever Fire should turn, there would be a way for him; they\nsaid his head would open the way for him.? They said he should sacrifice three\ncocks, one shilling seven pence eight oninis, and plenty of palm oil? Fire made\nthe sacrifice.\n\nIfa says someone wants to do something; he should make a sacrifice, so that\nthe way will be clear for him, because if he should sacrifice, he will be able to do\nwhatever he wants—whether it is work or an important thing that he wants to do.", "comentario": "1. The imagery here compares the way one rubs his hands to warm them\nbefore the fire with the way in which one “rubs his hands” in paying homage to a\nruler. Cf. n. 5, verse 111-1 and n. 2, verse 2-2,\n\n2, The meaning is that Fire will burn its own path wherever it goes.\n\n3. Cf. verse 245-1, where it is specifically stated that the palm oil is\npoured on Fire to keep him alive.", "origen_id": "6d62047f630caf850d720a3d"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la enfermedad y la muerte: la ofrenda marcada más un pangolín (àkàká).", "Para la vida larga: la ofrenda completa, sin dejar nada a medias.", "Contra el problema repentino: un gallo y lo que escoja el sacerdote.", "Para hijos: dos granos de maíz y dos gallinas; sembrar el maíz y ofrecer dos mazorcas a la cabeza (Orí).", "Para cuidar a la esposa: dos cabezas de cobra y una soga de subir palmas.", "Para Ògún: una calabaza de vino de palma, ñame asado y aceite de palma.", "Para que nada se escape: seis agujas.", "Para abrir camino: tres gallos y aceite de palma.", "Para el viaje y el trabajo en el agua: un bote pequeño de madera sobre un plato blanco, plátanos, huevos, una botella de aceite de palma, un ave y dinero para Èṣù.", "Para los problemas de pareja y el miedo: una cabeza de víbora, una paloma, un ave, aceite de palma y dinero para Èṣù."], "pasajes": [{"titulo": "Ofrenda en el verso 11.1", "texto": "Qdan-gejẹ awo Ata-nde:\nadivinó Ifá para Eyin\nEl adivino dijo:\n\"debe sacrificar a causa de un\ngran problema que aparecerá de inmediato\"\nUn gallo y lo que el Babaláwo\nseleccione como sacrificio.\nEyin dijo:\n\"con la maravillosa corona que esta sobre mi cabeza,\n¿por qué tendría que considerar\nir a ningún Babaláwo para sacrificar?\"\nÉl francamente se negó a sacrificar.\nDice Ifá: grandes problemas, conflictos o dificultades no previstas (que\naparecen al momento), surgirán para cualquier persona a quien se le\nadivine este Ifá, trayéndole preocupaciones, angustia e inquietud.", "origen_id": "82c766903b3d6244a2fbc019"}, {"titulo": "Ofrenda en el verso 11.2", "texto": "Etuṣẹṣefi'nu-igboṣe'le,\nOniwakawakafi'nu-isaṣe budo:\nadivinaron Ifá para Bara Àgbọnnìrègún,\ncuando iba a lfè para lograr un bien de nacimientos (partos)\nSe le aconsejó sacrificar:\ndos granos de maíz (Qkà Méjì) y dos gallinas.\nEl ejecutó el sacrificio, plantó el maíz,\ny lo cortó cuando estuvo maduró (tuvo espigas)\npara propiciar su cabeza (Ori).\nEllos dijeron:\n\"quien corte dos espigas de maíz para agasajar su cabeza\ndeberá ser llamado ikáméji\"\nCualquiera para quien este Odù sea adivinado\ntendrá muchos hijos, o se convertirá en muy fructífero en el mundo.", "origen_id": "f81d6ba2b67c865806cb1395"}, {"titulo": "Ofrenda en el verso 11.3", "texto": "Ojojoṣe-idiberẹ:\nadivinó Ifá para Çrúnmilà,\ncuando su esposa estaba a punto de cometer adulterio.\nA él le fue aconsejado sacrificar:\ndos cabezas de cobra y una soga de escalar palmas,\npara evitar que la gente seduzca a su esposa.\nEl escuchó el consejo y realizó el sacrificio.\nQyẹ y Oworẹ que eran rivales de Ọ̀rúnmìlà\npara arrebatarle la mujer (trepar a su mujer),\nse incapacitaron para seducir a la mujer de Ọ̀rúnmìlà,\nporque Ọ̀rúnmìlà había sacrificado.\nLa esposa de Ọ̀rúnmìlà se llama Ọ̀pẹ̀.\n1\" Qyẹ: Viento polvoriento extremadamente seco que sopla en el desierto del\nSáhara hacia la costa occidental de África, generalmente entre noviembre y\nmarzo.\n* Oworẹ: La etapa más seca de la estación de sequía.", "origen_id": "a48c9443dc78b936f689d13f"}, {"titulo": "Ofrenda en el verso 11.4", "texto": "Omipẹnṣen-akodun-koro:\nadivinó Ifá para Ogún,\ncuando iba a atacar la ciudad de sus enemigos.\nLe aconsejaron sacrificar:\nun agbe\nde vino de palma, un ñame asado y aceite de palma.\nOgún rechazó sacrificar.\nLos Babaláwos dijeron: Dice Ifá:\n\"antes de regresar a su casa\nél será envenenado,\nporque rechazó realizar el sacrificio prescrito\".", "origen_id": "c21f002c7e3f81f41222af81"}, {"titulo": "Ofrenda complementaria 1", "texto": "Un bote pequeño de madera (para poner en plato blanco), ogedé wééré (plátano), eyin (huevo), 1 epo, 1 adie y dinero determinado por el adivinador\n\nDestinatario: Esú", "origen_id": "454e3c30928b0fcd6d2e8872"}, {"titulo": "Ofrenda complementaria 2", "texto": "1 ori agbadu (cabeza de víbora), 1 eiyelé, 1 adie, 1 epo y dinero determinado por el adivinador\n\nDestinatario: Esú", "origen_id": "a9fab49413c78f46d72d8364"}]}, {"titulo": "Relaciones espirituales", "texto": "Ògún pide su parte antes de cualquier pelea. Orí debe ser atendido a menudo para elegir bien. Ọ̀rúnmìlà protege a la esposa del consultante. Tabú: no comer mono gris.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Ori; Oro", "origen_id": "06eb7378b0ec073b14925ede"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz (dos mazorcas), ñame asado, vino de palma, aceite de palma, cabezas de cobra, soga de palmero, agujas, pangolín. Bote pequeño de madera, plátano, huevos, cabeza de víbora."}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 2", "texto": "un mono gris", "origen_id": "22dbc27ffdf1ae09f8da8375"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 11.1 (yorùbá): Qdan-gejẹ awo Ata-nde: / li o dífá f'Eyin. / Wón ni: / \"ki ó ṣẹbọ nitori oran igbonagbooru\". / Akuką kan ati ohunkohun / ti babaláwo ba fẹ ni ebọ. / \"Ẹyin I t'oun ti Ade Orí oun yẹpẹtẹ yi / lio maa losódą Babaláwo kan lati ṣẹbọ?\" / O kọ ko rú.", "Verso 11.2 (yorùbá): Etuṣeṣefi'nu-igboṣe'le, / Qniwakawakafi'nu-isaṣe'budo: / wọ̀n difá fün Bara Àgbọnnìrègún, / nlos'ode Ifẹ lọ ṣe ire omobibi. / Qkà Méjì / ati abo-adiyẹ Méjì ni ebọ. / Ó gbọ̀ ó rú. / O gbin okà, qkà gbo tan, o ṣẹ Méjì / Ninu rẹ, / O fi bọ Oluṣupẹn rè. / Wọ̀n ni: / \"Eyiti o ṣẹ okà Méjì / ti ofi bọ Oluṣupen rẹ̀, / Kiamaapee ni İkáméji\". / Eniti a dá Ifá yi fún yoo bimo pupo / tabi oun yoo rẹ pupo ninu ayé. / 39 Eyin: fruto de la palma, se usa para obtener el aceite de palma mediante su / cocción al fuego.", "Verso 11.3 (yorùbá): Ojojoṣe-idibẹrg: / li o difá f'Ọ̀rúnmìlà, / nigbi Obirin rọ̀ maa ṣ'àgbéré. / Wọ̀n niki ó rù: / Ori ejó oká móji ati igba opẹ, / ki wọn ma le gba obirin naa li qwọ̀ rẹ / Ở gbọ̀ ô rù. / Pypio ati Oworẹ / Il o nba Ọ̀rúnmìlà du obirin wọ̀n ko le gba obirin naa / nigbati Ọ̀rúnmìlà ti rúbọ. / Obirin Prúnmilà orukọ ti aipe pẹ̀.", "Verso 11.4 (yorùbá): Omipenṣen-akodun-koro: / li o difá fOgún / mi a gbe ogun lọ ja ilu ọ̀tá rẹ̀. / Wọ̀n niki ó rú: / Agbe-ẹmu, ẹsun iṣu ati epo. / Ôgún kó ko rú. / Awọn Babaláwo ni: Ifá wipe: / \"Lati ghun bowale ni wọn ti maagbe / inkan burúkú fún un jẹ / nitori airubo re\".", "REZO: IKA MEYI IGUE IYIOKOOWO ENÑONGO OCUAGUO EDE MEYI OBEDE MEYI OKUNKE YEBRE ELBE EYE AFEKU SHUORERE ADA FUN GUALAMI ALAFUN AROKOKO ARAGUAMERICORUGO ELEGUTE ORUBE O. VEKU SHUGUI AFIYERE SHOUNARO.", "REZO: IKA MEYI IGUE IYIOKOOWO ENÑONGO OCUAGUO EDE MEYI OBEDE MEYI OKUNKE YEBRE ELBE EYE AFEKU SHUORERE ADDIFAFUN GUALAMI ALAFUN AROKOKO ARAGUAMERICORUGO ELEGUTE ORUBE O. VEKU SHUGUI AFIYERE SHOUNARO.", "REZO: EGUAYOKO OWO OÑI OKUO AWO ODE MEYI OBEBE MEYI OKUNI QUELLI AFUFU SHORERE ADAFUN GUALAMI ALAFUN OROKO ORUO GUANAMI CORUE ELEBI ORUE ORUNMILA OWUNKO EYELE MEYI AUE LA MENI IGUAYU KAFEREFUN BUTAE.", "REZO: IKA MEYI IGUO ILLIOCO AGUAGUO EDE MEYI OBEDE MEYI OKUNI QUE ILEBRE EBBO ELLE AFUCU CHERERE ADAFUN GUADAMI ADAFUN ALACOCO ORUBO GUADAMI MEYI CORUBO ELEBUTE ORUBO ORUNMILA. FECU CHUGUI AFILLIERE CHOAN ARUN.", "REZO: IKA MEYI ARO IKA IJOJA OLOFIN IKA KIJAGBO EJENU IKA KI JURUKU ELERI IKA MEYI EGBEDE LERI AJA NIGBAKINO OWALE ENI KAMOGUN OKAWO OFA OFI OMI EBANLE IWA IKU DENDE KINWOKA KERIN DILOGUN NOWA BA ONI KAMOGUN OKAWO EFA OFI LERI OFASHO AYA BARA POKA META LEJEKO ONI KIMOGUN MO AKA META OSA NIRITA OSORDE IGBA AKA META MO IDI AKA META KAFEREFUN ORUNMILA.", "SUYERE: ATORI ATORE ATOWAO AFARINA LERI O (2 VECES) ADEDERE MONI ADEDERE MONI ADEDERE ELEGBA ELEGBA FUMI LERI OUNKO ADEDERE MONI ADEDERE.", "SUYERE: TENTE LERI OBA FOBAO, TENTE LERI OBA FUMI."]}]$q$::jsonb),
(12,'d92397b6aec3e6724f45bd577ac5b580','88241c89203468d85bc7a7a1cce7c78d',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Méjì, también llamado Ọlọgbọ́n Méjì, simboliza la maternidad y el parto. Sus hijos son resistentes, firmes y tercos: aguantan el trato duro y no se rinden, pero se confunden fácilmente si no tienen buena orientación. Para tener hijos sanos y bien formados pide ofrendar a los antepasados (Egúngún) y a Òrìṣànlá, escuchar a los padres y a los mayores, y atender la cabeza (Orí) con frecuencia.", "pasajes": [{"titulo": "Frase clave", "texto": "Oturupón crea el mantenimiento de la salud.", "origen_id": "46e1d13d84eb46907a09dd77"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pregunta por hijos, un embarazo o el bienestar de su familia.", "Es firme y resistente, pero puede volverse terco si no escucha a los mayores.", "Se va a casar o quiere saber el futuro de una unión (relato de Ọlọ́fin y Pupayẹmi).", "Busca una casa estable o va a cambiarse de vivienda (relato de Yaya y Yayá).", "Le preocupa la salud de un niño o su propia vulnerabilidad (relato de Ikusigbade).", "Llegó a un lugar nuevo y quiere hacerse un sitio (relato de los dos Ogẹ).", "Su valentía puede ponerlo en peligro (relato de Odo, el mortero)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos sanos, bien formados y que crecen.", "Éxito al llegar a un lugar nuevo.", "Vida larga; que la muerte se olvide de uno.", "Una casa propia que dura toda la vida.", "Estar cómodo y asentado dondequiera que vaya."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que el bebé se vaya pronto, el niño que promete regresar (àbíkú).", "Que la audacia lo lleve a la muerte.", "Construir sin ofrendar y ver caer la casa.", "Falta de prudencia y vigilancia."]}, {"titulo": "Enseñanza principal", "texto": "La fuerza sin orientación se vuelve contra uno. El que escucha a sus padres decide bien. Como la raíz del gbégi, que es profunda, quien aparta la maldad se asienta feliz en cualquier lugar."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Las características más importantes de las personas nacidas con el Odù Òtúrúpọ̀n Méjì son su resistencia y firmeza. Ellos son toscos, rudos y obstinados, y mostrarán una determinación tenaz a pesar de recibir un tratamiento duro (severo, rudo, grosero, etc.).", "origen_id": "11f109d4bc6406777d7db76c"}, {"titulo": "Características generales", "texto": "Otros nombres: EjiÒtúrúpọ̀n / Ọlọgbọnméjì.\nÒtúrúpọ̀n Méjì también llamado Ọlọgbọn Méjì es el decimosegundo Odù en el orden inalterable de Ọ̀rúnmìlà. Este Odù simboliza la maternidad y el parto. Òtúrúpọ̀n Méjì dice que es necesario ofrecer sacrificios a Egúngún (ancestros) y a Òrìṣànlá para tener hijos sanos y bien formados. Los hijos de Òtúrúpọ̀n Méjì tienden a convertirse en personas complacientes, sin embargo para tomar decisiones sabias y prudentes, tienen que escuchar y respetar las opiniones de sus padres y los puntos de vista de las personas mayores en general.\nLos hijos de Òtúrúpọ̀n Méjì tienen la fuerza de tolerar y sobreponerse al sufrimiento, dolor, pena, peligro, desgracia, etc. Por tanto ellos suelen ser excesivamente audaces, valientes y tercos, pero se confunden con facilidad cuando no están orientados positivamente en la vida, empleando negativamente estas facultades. Si ellos quieren mantenerse orientados en la vida, y no perder sus fuerzas (resistencia y tenacidad), tienen que hacer un esfuerzo persistente para propiciar a sus cabezas (Orí) y hacer sacrificios a Ifá de forma regular.", "origen_id": "40bd2c5fa29d2c52ec438c9a"}, {"titulo": "Interpretación tradicional", "texto": "Oturupon es la manifestación de enfermedades infecciosas. El sistema inmune del humano usa la enfermedad como un proceso de purificación. Sí el sistema inmune es débil, la enfermedad puede llevar a la incapacidad y muerte. Enfermedades infecciosas pueden también ser un síntoma de una relación que no es sana con la Naturaleza y el medio ambiente inmediato. Entender el origen de la enfermedad es el primer paso en determinar una cura. La manifestación positiva de Oturupon ofrece la información necesaria para mantener un sistema inmune sano. La manifestación negativa de Oturupón, es el esparcimiento de enfermedad pasando su función sana de purificar el cuerpo.", "origen_id": "58194d1974045a938c5db697"}, {"titulo": "Orientación complementaria", "texto": "Oturupon es la necesidad de la enfermedad como una manera de la naturaleza de rectificar el desequilibrio. Ifá enseña que la prevención de la enfermedad viene de vivir una vida de buen carácter en alineación con el desarrollo personal y el concepto de vivir en armonía en el mundo. En su manifestación negativa. Oturupon es una enfermedad prolongada que se arriesga en convertirse en incapacidad o fatal.", "origen_id": "ba868d6261ce3bccbbcfef6a"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ikúsìgbàdé, a quien la muerte olvidó. La muerte andaba buscando a Ikúsìgbàdé, cuyo nombre quiere decir que la muerte se olvide de mí. Le pidieron ofrendar con la cabeza tierna de la palma, cumplió, y recibió la bendición de una vida larga. Si hay un bebé en camino, este Odù pide ofrecer a los Ìbejì para que el niño cambie su promesa de volver pronto con los antepasados y se quede a crecer. Durante el embarazo conviene llevar el control médico.", "Yaya y Yayá construyen su casa. Yaya y Yayá querían construir cada uno su casa. A los dos les pidieron ofrendar. Yaya no quiso, y su casa se cayó. Yayá ofreció, y su casa duró el resto de su vida; vivió cómodo desde ese día. Quien busca un lugar nuevo para vivir debe ofrendar para encontrarlo confortable.", "Los dos Ògẹ̀ en Ifẹ̀. Ọlọ́fin iba a casarse con Pupayẹmi, una joven del Este, y le pidieron dos chivas. Cumplió, y le dijeron que de ese matrimonio tendría solo dos hijos, pero que los dos serían mimados porque llegarían a ser grandes. A esos dos los llamaron Ògẹ̀ Méjì. Antes de bajar a Ifẹ̀ consultaron, y les dijeron que los dos triunfarían allí si ofrecían caracoles, tortugas, piedras de rayo y medicina de Ifá. Así fue.", "El mortero y la raíz del gbégi. Al mortero (odó) le dijeron que apartara la maldad para estar siempre cómodo donde fuera, y que su audacia no lo llevara a la muerte. Le marcaron un caracol, una vaina de pimienta de caimán, dinero y medicina de Ifá. Escuchó y ofreció. Le cocinaron la medicina, y como la raíz del gbégi es profunda, el mortero siempre se sienta feliz en cualquier lugar.", "Ògẹ̀, el mortero que no quiso vigilar. A Ògẹ̀, que es otro nombre del mortero, le pidieron manteca de cacao y aceite de palma para ser prudente y precavido. No quiso. Si lo hubiera hecho, le habrían preparado la medicina, porque a mediodía el aceite de palma está alerta y eso da vida larga, y a mediodía la manteca de cacao está vigilante y eso lleva a la vejez."], "pasajes": [{"titulo": "Verso 12.1", "texto": "Qkaragba:\nadivinó Ifá para los dos Ogẹ,\ncuando estaban a punto de descender a Ifè,\nEl adivino dijo:\n\"ambos serán exitosos en lfè\".\nA ellos se les aconsejó sacrificar:\ndieciséis caracoles babosa, dieciséis tortugas,\ndieciséis piedras de rayo y medicina de Ifá,\n(Dos de cada ingrediente son suficientes para el sacrificio)\nDespués de comer la medicina\nel cliente debe poner las piedras de rayo en su Ifá.", "comentario": "ẹdùn-ààrá: piedra de rayo. En la traducción al inglés aparece como \"thunderboit\".", "origen_id": "44a0dd5405cf5b90ab53ea9d"}, {"titulo": "Verso 12.2", "texto": "Ṣluluṣe'dibẹrẹ:\nadivinó Ifá para Ọlọ̀fin,\nquien iba a casarse con Pupayẹmi, una muchacha joven del Este.\nSe le aconsejó sacrificar: dos chivas.\nEl efectúo el sacrificio.\nEl adivino dijo:\n\"podrá tener solo dos hijos del matrimonio,\npero los dos serán mimados porque serán grandes en la vida\".\nTambién se estableció\nque los dos niños que fueron mimados en Ifẹ\ndeberían ser llamados \"Ogẹ-Méjì\".\n45 okunpale: planta no identificada.\n*° abo-igbo: planta no identificada.\n4 agbosáwa: planta no identificada.", "origen_id": "26fc609b924d867c1f3f1a1e"}, {"titulo": "Verso 12.3", "texto": "Agba igbin-f'idijelü:\nadivino Ifá para Odo (ol mortero),\nEl adivino dijo\n\"ieno que apartar la maldad\npara que siempre estés cómodo\ndonda qulera que vayas,\nM para que tu intrepidez\n(audacia, valor) no vaya a matarte\".\nSacrificio: un caracol babosa,\nuna vaina de pimienta de caimán (ataare),\n3200 cowries y medicina de Ifá.\nOdo escuchó el consejo y sacrificó.\nLa medicina de Ifá fue cocinada para él,\npara que pudiera asentarse cómodamente.\nTal como la raíz del gbégi es profunda,\nOdo siempre estará sentado felizmente\nen cualquier lugar.", "origen_id": "3c3ab6a3c607ffc652c9d9c8"}, {"titulo": "Verso 12.4", "texto": "Kasakaja Katetesa:\nadivinó Ifá para Ogẹ.\nle fue aconsejado sacrificar:\npara que fuera prudente y precavido\n(para estar alerta, vigilante).\nSacrificio: Orí y epo.\nEl rehúso hacer el sacrificio.\nSi él hubiera realizado el sacrificio,\nse le hubiera preparado la medicina de Ifá,\nporque:\n\"Al medio día el aceite de palma esta alerta,\nesto beneficia para lograr una larga vida.\nAl medio día la manteca de cacao esta vigilante,\nesto beneficia para llegar a la vejez\".\nOge es el nombre de Odo (mortero).", "origen_id": "45c23931d86cbbe3bfb2fb72"}, {"titulo": "Relatos y ofrendas", "texto": "ÒTÚRÚPÒN MÉJÌ\n\nCabeza — de — la — palma - tierna, consulta Ifá para Ikusigbade (muerte olvídame) en el día que la\nmuerte la estaba buscando. Ifá aconsejó a Ikusigbade hacer ebo, Ikusigbade hizo ebo y recibió\nuna bendición de larga vida.\n\nComentario:\n\nIfá dice que si esta persona está esperando un bebé, debe de hacer ebo para prevenir abiku. Ifá\ndice que el bebé ha prometido a los inmortales, que regresará pronto a la tierra de los ancestros.\nIfá dice que el ebo debe ser hecho para que el bebé cambie su promesa para regresar a los\nancestros antes de que crezca totalmente.\n\nEtutu (ofrecimiento): 1 Mariwo (fronda de palma), 1 eiyelé (pichón), 1 adie (ave), 1 epo (botella\nde aceite de palma), 1 plato blanco y 50 nira (dinero), ofrecido a Ibeji.\n\n(Ett (oferendas); Mariwo (folhagens de palma), 1 eiyele (pombo), 1 adiye (ave), 1 epo\n(garrafa de azeite de dendé), 1 prato branco e 50 nira (dinheiro nigeriano), oferecidos a\nIbeji.)\n\nCuero - delgado - que - cubrió - la - cara - de — Egúngún, consulta Ifá para Yaya y a Yayá en el\ndía que ambos quisieron construir una casa. Ifá aconsejó a Yaya y a Yayá hacer ebo. Yaya\nrehusó hacer ebo, Yayá hizo ebo. La casa hecha por Yaya se calló, La casa construida por Yáyá\nduró el resto de su vida y vivió confortablemente desde ese día.\n\nComentario:\n\nIfá dice que esta persona esta buscando un lugar nuevo adonde vivir. Ifá dice que debe hacer ebo\npara encontrar un lugar confortable para vivir.\n\nEtutu (ofrecimiento): adimu a los ancestros, ofrecido a Egúngún a Ibeji. Eéwo (tabú): Una nuez\nde tres lados.\n\n(Étùtù (oferendas); Adimú para os antepassados, oferecida a Egúngún e Ibeji. Eewó (tabu):\nObi de trés gomos.)\n\nTr Tr\n95\n\nI I\nA I I ki", "origen_id": "ab267cb64b29f041f2653b59"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Otrupon Meji habla que la más importante característica de la\ngente nacida en este Odu es su sufrimiento. Ellos son ásperos y resistentes\n     y mostrarán una tozuda determinación a pesar de un rudo tratamiento.\n                       WO – Éxitos relacionados a niños están sobre la mesa.\n          Otrupon Meji también llamado Ologbon Meji es el decimosegundo\n     Odu en el orden inalterable de Orunmila. Este Odu simboliza el parto,\n       Otrupon Meji dice lo que es necesario para ofrecer como sacrificio a\n egungun (ancestros) y Orişa Nlá para la salud y el buen desenvolvimiento\n     de la criatura. Los hijos de Oturupon Meji tienden a ser complacientes.\nPara tomar sabias decisiones, ellos deben escuchar y respetar las opiniones\n               de sus padres y los puntos de vistas de los mayores en general.\n             Niños de Otrupon Meji tienen la fuerza de sobreponerse sobre la\n       pena y el dolor. Consecuentemente ellos suelen ser audaces, tercos y\n fácilmente confundidos. Si ellos han permanecido enfocados y no pierden\nsu apoyo en la vida, se esfuerzan persitentemente deben hacer y propiciar a\n                    sus cabezas y hacer sacrificios a Ifá sobre bases regulares.\n\n\n12.1 · Okaragba adivinó Ifá para Eji-Oge cuando él estaba a punto de\n\n          descender a Ife. Fue predecido que ambos podrían sobresalir en Ife,\n          se les pidió que sacrificaran 16 caracoles de babosa, 16 tortugas, 16\n\npiedra de rayo (2 de cada uno son suficientes) y hojas de Ifá (hojas de\n            okunpale y abo-igbo o agbosawa y otros condimentos para ser\n   molidos y cocinados como sopa y dada al cliente para que se la coma,\n         cualquiera que desee usar la medicina para la prosperidad también\n   pueden comerla. Después de comer la medicina el cliente debe poner\n                                    la piedra de rayo (edun-aara) en su Ifá.\n\n\n12.2 · Eluluse´dibere adivinó Ifá para Olofin quien iba a casarse con\n      Pujameyi, una muchacha joven del este. Se le aconsejó sacrificar 2\n  chivas. Él efectuó el sacrificio. Se le dijo que podría tener sólo 2 hijos\n          del matrimonio pero que los 2 debían ser mimados porque serían\n           grandiosos en la vida. También se estableció que los 2 hijos que\n                  fueron mimados en Ife deberían ser llamados Oge Meji.\n\n\n12.3 · Agba igbin-f´idiyelu adivinó Ifá para Odo, se le dijo que él siempre\n\n             podría encontrar un asiento donde quiera que él fuera, pero su\n         imprudencia podría matarlo. Ebo: 1 caracol de babosa, 1 vaina de\n   pimienta de cocodrilo, 3200 cowrie y hojas de Ifá. (moler hojas gbegi\n              con la pimienta hervir el caracol y cocinarlo todo junto) esta\n     medicina debe ser dada a comer al cliente o a cualquiera que quiera\n         usarla. Odo escuchó el consejo y sacrificó. La medicina de Ifá fue\n           cocinada para él como se indica arriba para que él pudiera estar\n         sentado seguro. A partir de que la raíz del gbegi es profunda, Odo\n                    siempre estará sentado firmemente en cualquier lugar.\n\n\n12.4 · Kasakaja Katetesa adivinó Ifá para Oge. Se le pidió sacrificar\n                para que fuera prudente. manteca de cacao y manteca de corojo\n            deberían ser sacrificados. Él rehusó hacer el sacrificio. Si él hubiera\n             realizado el sacrificio, la medicina de Ifá (mezcla 4 de cacao y 4 de\n        corojo) podría haber sido preparados para él para que se la frotara en\n        su cuerpo porque “al medio día el aceite de palma está alerta. Esto le\n            beneficia para una larga vida. Al medio día la manteca de cacao está\n                  vigilante. Esto le beneficiari para llegar a la vejez”. Oge es el\n                                                       nombre de Odo (mortero).", "origen_id": "5013970798f9145449ebb3e0"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la partida del bebé: una fronda de palma (màrìwò), una paloma, un ave, aceite de palma, un plato blanco y dinero para los Ìbejì.", "Para la casa: ofrenda de comida (àdìmú) a los antepasados, a Egúngún y a los Ìbejì.", "Para el éxito: caracoles, tortugas, piedras de rayo (dos de cada uno bastan) y medicina de Ifá; luego poner las piedras de rayo junto al Ifá del consultante.", "Medicina de prosperidad: hojas de okunpale y abo-igbo o agbosáwa molidas y cocidas en sopa.", "Para el matrimonio: dos chivas.", "Para asentarse: un caracol, pimienta de caimán, dinero; hojas de gbégi molidas con la pimienta y cocidas con el caracol para comer.", "Para la vigilancia: manteca de cacao y aceite de palma mezclados con iyẹ̀ ìròsùn del Odù para frotar el cuerpo."], "pasajes": [{"titulo": "Ofrenda en el verso 12.1", "texto": "Qkaragba:\nadivinó Ifá para los dos Ogẹ,\ncuando estaban a punto de descender a Ifè,\nEl adivino dijo:\n\"ambos serán exitosos en lfè\".\nA ellos se les aconsejó sacrificar:\ndieciséis caracoles babosa, dieciséis tortugas,\ndieciséis piedras de rayo y medicina de Ifá,\n(Dos de cada ingrediente son suficientes para el sacrificio)\nDespués de comer la medicina\nel cliente debe poner las piedras de rayo en su Ifá.", "origen_id": "f4f014d997e70cd29f697a3b"}, {"titulo": "Ofrenda en el verso 12.2", "texto": "Ṣluluṣe'dibẹrẹ:\nadivinó Ifá para Ọlọ̀fin,\nquien iba a casarse con Pupayẹmi, una muchacha joven del Este.\nSe le aconsejó sacrificar: dos chivas.\nEl efectúo el sacrificio.\nEl adivino dijo:\n\"podrá tener solo dos hijos del matrimonio,\npero los dos serán mimados porque serán grandes en la vida\".\nTambién se estableció\nque los dos niños que fueron mimados en Ifẹ\ndeberían ser llamados \"Ogẹ-Méjì\".\n45 okunpale: planta no identificada.\n*° abo-igbo: planta no identificada.\n4 agbosáwa: planta no identificada.", "origen_id": "b1e5813a2a68f9e97325864a"}, {"titulo": "Ofrenda en el verso 12.3", "texto": "Agba igbin-f'idijelü:\nadivino Ifá para Odo (ol mortero),\nEl adivino dijo\n\"ieno que apartar la maldad\npara que siempre estés cómodo\ndonda qulera que vayas,\nM para que tu intrepidez\n(audacia, valor) no vaya a matarte\".\nSacrificio: un caracol babosa,\nuna vaina de pimienta de caimán (ataare),\n3200 cowries y medicina de Ifá.\nOdo escuchó el consejo y sacrificó.\nLa medicina de Ifá fue cocinada para él,\npara que pudiera asentarse cómodamente.\nTal como la raíz del gbégi es profunda,\nOdo siempre estará sentado felizmente\nen cualquier lugar.", "origen_id": "c32335eb6740c69ddecd5350"}, {"titulo": "Ofrenda en el verso 12.4", "texto": "Kasakaja Katetesa:\nadivinó Ifá para Ogẹ.\nle fue aconsejado sacrificar:\npara que fuera prudente y precavido\n(para estar alerta, vigilante).\nSacrificio: Orí y epo.\nEl rehúso hacer el sacrificio.\nSi él hubiera realizado el sacrificio,\nse le hubiera preparado la medicina de Ifá,\nporque:\n\"Al medio día el aceite de palma esta alerta,\nesto beneficia para lograr una larga vida.\nAl medio día la manteca de cacao esta vigilante,\nesto beneficia para llegar a la vejez\".\nOge es el nombre de Odo (mortero).", "origen_id": "8cbdb24791597ae37e5f18e8"}, {"titulo": "Ofrenda complementaria 1", "texto": "Adimú para los ancestros\n\nDestinatario: Egúngún e Ibeji", "origen_id": "3073b4d903caf54757f1ef4b"}]}, {"titulo": "Relaciones espirituales", "texto": "Egúngún (los antepasados) y Òrìṣànlá dan hijos sanos. Los Ìbejì retienen al bebé. Orí debe ser atendido con regularidad. Tabú: la nuez de kola de tres gajos.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Onilé; nana Buruku", "origen_id": "6b76118dcd5a083e45a14e92"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Fronda de palma (màrìwò), gbégi (Eleusine indica), pimienta de caimán, manteca de cacao, aceite de palma, okunpale, abo-igbo, agbosáwa, tortugas, caracoles, piedra de rayo."}, {"titulo": "Preparaciones tradicionales", "pasajes": [{"titulo": "Verso 12.1", "texto": "Moler hojas de okunpale\"s y abo-igbo\" ó agbosáwa* ', junto con otros condimentos para ser cocinados como sopa.\nEsta medicina es para que la coma el cliente a quien se le adivinó este Odù o para cualquiera que desee usar esta medicina para la prosperidad.", "origen_id": "a1551fa96b5b01f080021182"}, {"titulo": "Verso 12.3", "texto": "Moler las hojas de gbégif® con la pimienta (ataare).\nhervir el caracol y cocinarlo todo junto. Esta medicina debe ser dada a comer al cliente para quien se adivinó este Ifá o a cualquiera que quiera usarla.\n''' gbégi: ELEUSINE INDICA (L.) Gaertn., Gramineae.", "origen_id": "61b0716071fcb046973150a0"}, {"titulo": "Verso 12.4", "texto": "mezclar la manteca de cacao y el aceite de palma, con Iyẹ̀-Ìrosùn del Odù, usar la mezcla para frotar en el cuerpo.", "origen_id": "ff9ac84c3167eb222f05c892"}]}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 1", "texto": "una nuez de tres lados", "origen_id": "76736c5cb43451f3b728895c"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 12.1 (yorùbá): Qkaragba: / li o dífá f'Èji Ọgẹ, / nlọ s'ọlẹ n'lfẹ. / Wọ̀n nì: / Awon Méjì naa ni o maa han n'lfẹ. / A niki wọ̀n rú: / igbin mérindilógún, ijapá mérindilógún / ẹdùn-ààrá mẹrindilógún (méjiméji ti too lo) ati ewé Ifá. / Bio bajẹẹ tan ki ẹniti o jẹẹ naa fi / edùn-àirá le orí Ifá rè.", "Verso 12.2 (yorùbá): Ṣluluṣe'dibẹrẹ: / li o dífá f'Ọlófin, / nlọ fẹ Pupayẹmi, tii ṣe pmọ wọn ni Wonran. / Wọ̀n niki ó rú: ewúrẹ Méjì. / Ó gbọ̀ ó rú. / Wọ̀n ni: / Ọmo Méjì saa li a maa bi / sùgbọ̀n gigẹ niki o ma gẹ wọn / nitoripe àwọn Méjì naa a dijidaira. / Njẹ àwọn Méjì ti a ngẹ n'lfẹ ki / o maa pe wọ̀n ni: \"Ọgẹ-Méjì\".", "Verso 12.3 (yorùbá): Agba igbín-f'idijẹlú: / Il o dífá f'Odo. / Wọ̀n nì: / \"kosi ibi ti o naa wa ti ko niini ibujoko, / gugbọ̀n aya nini li o maa paa\" / lgbin kan, odimdi ataare kan, / ogbokànlá owó ati ewé Ifá. / Ó gbọ̀ ó rú. / A ṣe ewé Ifá fún jẹ gegẹbi / ati wi loke yi nitoripe / Kiobaa le ni ibujoko. / Ajatirinmole niti Gbọ̀gi, / nitorinaa kosi ibiti Odo yoo de / ti ko niini abujoko.", "Verso 12.4 (yorùbá): Kasakaja Katetesa: / li o'dífa f'Ogẹ. / A niki o wa rúbẹ, / ki aya rẹ le maa ja diẹdiẹ. / Orí ati epo ni ẹbọ. / Ko rú bọ. / Biobarúbo a base ewé Ifá fún. / Nitoripe: / \"Bi osan ba pon ominu a kọ epo, / oun lo maa m'epo pẹ. / Bi osan ba pọn aya a pa òrí, / oun lo maa m'ori dagba.\" / Pgẹ oruko Odo.", "REZO: OBORO NI SHORO OLOGUON NIFEDERE NISHORO OWO ONI FEDERE AUN BABALAWO LODIFAFUN TOCUTU KUTU NISHORO OGGUN.", "REZO: OLORO TOROSHE ENI LAY SHORO", "REZO: ODI OLEKERU KURU ODI ELEKURE KURU EÑI EÑI LAWO ADENI LAWO EÑI EÑI LAWO ADONI LAWO, EKU MENI KI EKUN MAPAREWE", "REZO: OTRUPO MEYI OGORO NICHORO LEGUON NIFADERE NI CHODO OCU ONI FADERE BABALAWO TEDINFUNTECUTUTO CUTU ACHORO EKU.", "REZO: OLORO TOROCHE ADIFAFUN EKUO. OTORO TOROCHE EÑI LAY CHORO ISI OLOLAN NINCHORO OLOBAN IFA DERE NINCHORO EGGUN AQUILIPIDE AWO EÑI BANA LOTE IFA DERE NI IFA OLUWO GUAMI OYUGBONA GUAMI.", "REZO: OLDOGAN NICHORO ALOGUAN IFA DIRE CHOCHOLOGUO ONI BABALAWO ADAFUN TECUTU CUTU DIGUE LACHORO SECUN IGUILA ABERE MOCAN DUDUN TUNTUN AIKORDIE OCU EYA EBETA AWO.", "REZO: OLORO TOROCHE EÑI LAICHERO ISIA LOBAN NINCHORO ECUN OGUILIPELE OWO EÑI LONA IFA DERE NIFA OLUO BAMI OLLUBONA BANI.", "REZO: QUERECHETE OWO LADAFUN NIPA PO ADIFAFUN INLE NIPAPO KERE KERE NIPAPO KERE KERE NIPAO KITILLO ARO.", "REZO: BABA OTRUPON MEYI OLOROTO ROCHE EÑI LACHORO RIOLEBAN NICHORO OLOBAN IFA DEREGUN CHORO OCUN OQUI LIPELE AWO EBANA LOTE IFA DERENIFA LON OLUE BAMI OYUGBONA BAMI ORUNMILA ONI OSADIO MACHABA LOGUO OKU LOGUO OKU LOGUO ERIN", "IBABA LODAFUN AGUN GUN OCOCO LODAFUN ORU CHAORDE BAMBA LODAFUN BARA LOMIREGUN ONI BAMBA LODAFUN BARA LODAFUN BARA LOMIREGUN ONI BAMBA LODAFUN BATRA LOMIREGUN ONI BAMBA LOGUEREGUEN CHAGUE BAMBA LEGUEREGUEN CHAGUO.", "SUYERE: OÑIÑI LAISHORO OÑIO OÑIÑI LAISHORO OÑIO OÑI FEKUN LAISHORO EKUN OÑIÑI LAISHORO OÑIO.", "REZO: BABA ADIFAFUN EGGUN, ONIQUE EGGUN ORUBO ABOLERO AJERE ABAKO NILE ADIFAFUN IDADERE BATINLOBA IKU SHORE ABERE MESAN AWO EFUN EURE ADIE MERI OKITI KUELE AWO EBANLA LOTE IGADERE ILE OBATALA NIFA OIN NI OLORO TOROSEINALE AKUKO EYELE AYAPA LEBO.", "REZO: META AGBA OLOFIN ORUNMILA OBATE IYA KAYE OMO ELEGBA ORI OBAIN KOKO INA KALETE SIYA ADIFANFUN OLOGBO IYAFA ELEGBA TUNWA ARAMISHE ADIFAFUN OTRUPON MEYI NANA AGBA ORI ADIFAFUN OKEEY OMO SHOWO EGGUN OSHA KALE AYE EGGUN MODUN NAINA OMO TUTO LORDAFUN IYAFA KAFEREFUN OLOFIN."]}]$q$::jsonb),
(13,'56ac9f3398e38644ac9f1ccbcbf3d4ab','55fb52c3109c3b3d58951b60e977ec34',$q$[{"titulo": "Idea central", "texto": "Òtúrá Méjì es paz mental y libertad de la ansiedad. Sus hijos son apacibles, moderados y de carácter suave, y tienen mucho éxito en el comercio, sobre todo comprando y vendiendo. Deben aprender a descansar para no agotarse en cuerpo y mente, y atender a Èṣù con frecuencia para que nadie revele sus secretos ni los separe de su familia. Con ofrendas a Ògún, a Yemọja y a Ifá superan a los enemigos, ganan dinero y tienen pareja e hijos.", "pasajes": [{"titulo": "Frase clave", "texto": "Otura crea la visión mística.", "origen_id": "c96bc7e41b9f6ab7b82365e9"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una oportunidad de comprar, vender o empezar una relación, pero necesita organizarse para sostenerla.", "Trabaja sin descanso y está a punto de agotarse.", "Tendrá que viajar o estar lejos más tiempo del planeado (relato de Òtú en Ifẹ).", "Quiere vender algo y busca el mejor lugar para hacerlo (relato de Òtú y las tortugas).", "Le toca fundar, dirigir o poner orden en un grupo, con justicia (relatos de Ọ̀rúnmìlà).", "Pierde dinero o armonía en casa y culpa a alguien cercano; antes debe revisar los hechos.", "Busca calma y sentido espiritual."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Paz mental y tranquilidad.", "Éxito en los negocios y en las relaciones.", "Riqueza vendiendo al mejor precio.", "Fundar un lugar que se vuelve mercado.", "Gente de todas partes que viene a honrarlo.", "Que las cosas salgan con calma, por una vida de devoción."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desgaste físico y mental por no descansar.", "Traición: alguien que revela sus confidencias y planes.", "Parientes o cercanos que lo vuelven atolondrado hasta dejarlo pobre y solo.", "Antepasados o colegas envidiosos que roban la abundancia."]}, {"titulo": "Enseñanza principal", "texto": "El agua corre por el camino y el camino cruza el río: cada cosa sigue su curso con calma. No se vende al primer precio; Èṣù avisa cuándo aceptar. Quien ofrenda a tiempo recibe honra sobre la estera."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Òtúrá Méjì significa paz mental y libertad de toda ansiedad.\nLos hijos de Òtúrá Méjì son apacibles, moderados y de carácter suave.", "origen_id": "814004d4d08c70ac9b4c6b4e"}, {"titulo": "Características generales", "texto": "Otros nombres: Òtúrá Méjì; ÈjiÒtúrá / Etúrá Méjì / Èjietúrá.\nÒtúrá Méjì es el decimotercer Odù en el orden fijo de Ọ̀rúnmìlà. La gente nacida bajo este signo tendrá muchos éxitos en los negocios, particularmente para comprar y para vender. Es importante apaciguar a Eṣú frecuentemente, sino habrá persona dispuestas a traicionarlo revelando sus confidencias, secretos y planes para separarlo de su familia. Los hijos de Òtúrá Méjì deben aprender a descansar y no malgastar sus energías para evitar el \"colapso físico y mental\".\nSi el Odù Òtúrá Méjì aparece para un cliente, Ifá dice que el cliente tiene enemigos o personas cercanas (parientes) que lo han convertido en un ser atolondrado (inconsiderado, descuidado, irreflexivo), al punto de verse en la pobreza, sin relación de pareja, ni buenas relaciones familiares. Él o ella deben, tan rápido como sea posible, ofrecer sacrificios.\nÒtúrá Méjì dice que debe hacer ofrendas a Ogún, Yemoja y a Ifá, solo así, podrá estar capacitado para superar a sus enemigos, hacer algún dinero y finalmente tener esposa e hijos.", "origen_id": "fd71b133da5c50ea8e9f921b"}, {"titulo": "Interpretación tradicional", "texto": "Otura es el origen de la visión mística. La visión mística pone al ori (conciencia) en alineación justo con el Origen (Olodumare). Otura es la fundación del sentido del destino del individuo y propósito en la tierra. En su manifestación negativa, puede ser el origen de un sentido inflado de importancia propia. Otura puede también manifestarse como identificación con otra cosa que no sea el Origen. Las formas más comunes de identificación falsa son avaricia, nacionalismo, racismo y superioridad moral.", "origen_id": "399386d0ada3fcfb5de2519c"}, {"titulo": "Orientación complementaria", "texto": "Otura es la experiencia de conexión con el Origen. Cualquier persona que hace errores de identificar deseos personales con el Origen esta sufriendo la decepción de uno mismo. La manifestación negativa de Otura, es la creencia que la voluntad personal es lo mismo que la voluntad divina.", "origen_id": "ef3e5dd4f17bff79aff6c14e"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀tú y las dos tortugas. A Ọ̀tú le pidieron ofrecer dos tortugas para volverse muy rico, pero le advirtieron que no las matara sino que las vendiera, y que él decidiría dónde venderlas al mejor precio. Llegó a un pueblo y le ofrecieron ochenta sacos de dinero por ellas. Èṣù, que siempre está del lado de quien ofrenda, le avisó que no aceptara. La oferta fue subiendo, y cuando llegó a cientos de sacos de dinero, Èṣù le dijo que aceptara. Así Ọ̀tú se hizo muy rico, y los sacerdotes dijeron: el día que Ọ̀tú compró dos tortugas debe llamarse Òtúrá Méjì.", "Ọ̀rúnmìlà funda un pueblo con el odán. Ọ̀rúnmìlà salía a descubrir y fundar un pueblo. Le pidieron un grupo de hormigas guerreras, jabón negro, cuarenta caracoles ensartados en una cuerda en la oscuridad, tela blanca y un retoño de odán. Cumplió. Le dijeron que sembrara el odán en una arboleda y le atara la sarta de caracoles, que se bañara con el jabón negro mezclado con las hormigas y hojas de odán, y que se cubriera con la tela blanca. Y le aseguraron: el lugar donde se sembró el odán se convertirá en mercado.", "La estera de Ọ̀rúnmìlà. A Ọ̀rúnmìlà le pidieron seis esteras, seis plumas de loro, seis chivas y dinero para gobernar con justicia a su pueblo, y le dijeron que gente de todo el mundo vendría a honrarlo sobre su estera. Ofreció lo más rápido que pudo, y la gente vino de todas partes a honrarlo como se había dicho. Desde ese día los sacerdotes de Ifá se sientan sobre una estera para adivinar.", "Ọ̀tú en Ifẹ̀. Ọ̀tú iba a Ifẹ̀ a hacer su trabajo de adivinación. Le pidieron dos bastones de caminante y dos carneras, y le dijeron que no volvería pronto. Ofreció y se quedó mucho tiempo en Ifẹ̀.", "El devoto de túnica larga. Como el agua corre por el camino y el camino cruza el río, así adivinaron para el musulmán de túnica larga que quería seguir el camino de los inmortales. Le pidieron ofrendar, cumplió, y desde ese día las cosas le salieron con tranquilidad. A quien recibe este Odù le corresponde una vida devota, y así le llegan las bendiciones.", "La Tierra en el mercado. La Tierra quería vender en el mercado y le pidieron ofrendar para que los poderes destructivos que viven en ella no la dañaran. Ofreció, y desde ese día todas las ganancias se quedaron con la Tierra. Este Odù pide ofrendar para que los antepasados destructivos de la familia no roben la abundancia, y ser amable con los colegas para que no se vuelvan envidiosos."], "pasajes": [{"titulo": "Verso 13.1", "texto": "Arugbó-ńlá niiṣe orí fegunfegun:\nadivinó Ifá para Òtú,\ncuando él estaba yendo a lfẹ\npara hacer su trabajo de adivinación.\nSe le aconsejó ofrecer un sacrificio:\nDos báculos de caminante\ny dos carneras.\nA él se le dijo que no retornaría pronto.\nÒtú escuchó y sacrificó\nÉl permaneció por largo tiempo en Ifè.", "comentario": "\"Opa: Báculo, vara larga que usan los caminantes para apoyarse mientras caminan y revisar donde pisan, puede ser de bambú o cualquier otro tipo de madera.", "origen_id": "b5fbed29ddee8ef8f716f536"}, {"titulo": "Verso 13.2", "texto": "Arugbó-Oba ni-nsọ'gbodi'le,\nÌdí-agbani-nṣe jẹkujẹkẹ:\nadivinaron Ifá para Çrúnmilà,\ncuando él estaba yendo en una misión\npara descubrir y establecer un pueblo.\nA él se le aconsejó que sacrificara:\nGrupo de hormigas guerreras (ową ijamja), jabón negro,\ncuarenta cowries que hayan sido ensartados\ncon una cuerda en la oscuridad,\ntela blanca (para hacer una ropa) y una postura de odán.\nỌ̀rúnmìlà escuchó y sacrificó.\nDespués del sacrificio\nlos Babaláwos aconsejaron a Ọ̀rúnmìlà\nque sembrara el odán en una arboleda (manigua)\ny que amarrara la cadena de caracoles a este.\nEl debía lavar su cuerpo con el jabón negro\npreparado con hojas de odán y las hormigas.\nEl usó la tela blanca para cubrir su cuerpo.\nSi este Ifá encarna en alguien,\nel debe ser aconsejado hacer lo mismo.\nLos Babaláwos le dirán con seguridad:\n\"el lugar donde se plantó el árbol de odán\nse convertirá en un mercado\".", "origen_id": "d24ae802f1281fabedb853b8"}, {"titulo": "Verso 13.3", "texto": "Ökiti-ogán-af'idij'ago:\nadivinó Ifá para Otú.\nLe aconsejó sacrificar: dos tortugas,\npara convertirse en excesivamente rico.\nOtú oyó y sacrificó.\nEl Babaláwo advirtió a Otú de no matar las tortugas,\nsino que las vendiera.\nLa suerte estaba echada\npara que él decidiera dónde ir a venderlas\nal mejor precio.\nCuando él llegó al pueblo,\nle ofrecieron ochenta sacos de dinero por las tortugas.\nÈṣú avisó a Otú de no aceptar el precio.\nEṣú siempre está a favor de quien sacrifica.\nLa oferta fue aumentando,\ncuando el precio aumento\na cientos de sacos de dinero,\nEṣú avisó a Otú de que aceptara el precio.\nAsí fue como Otú se hizo muy rico.\nLos Babaláwos dijeron:\n\"El día que Otú compró dos tortugas, debe ser llamado Òtúrá Méjì\".", "origen_id": "6a9824b711d1046c2f502317"}, {"titulo": "Verso 13.4", "texto": "Oluṣpse áwon ni Awo inú-igbó,\n#lu-odàn-afidij'Odù:\nadivinaron Ifá para Ọ̀rúnmìlà.\nA él le fue aconsejado sacrificar\npara que gobernara justamente a su pueblo.\nỌ̀rúnmìlà preguntó: ¿Cuál es el sacrificio?\nLos Babaláwos dijeron:\nmois esteras, seis plumas de loro,\nseis chivas y 1200 cowries.\nLe fue dicho que gentes\nde todas partes del mundo\nvendrían a rendirle honor en su estera.\nỌ̀rúnmìlà hizo el sacrificio tan rápida\ncomo le fue posible,\ny las personas de todas partes del mundo\nvinieron a brindarle honor\nsobre la estera como fue predicho.\nDesde ese día, los Babaláwos\nse sientan sobre una estera\npara hacer sus predicciones.", "origen_id": "ab000fef09a563f375bdd821"}, {"titulo": "Relatos y ofrendas", "texto": "OTURÁ MÉ JÌ\n\nComo - el - agua - corre - por — el - camino, - el- camino - pasa - a través - del - Eri - río, consulta\nIfá para el Muslim con trapos largos en el día que el Muslim con trapos largos estaba tratando de\nseguir el camino de los inmortales. Ifá aconsejó al Muslim con trapos largos hacer ebo. El\nMuslim con trapos largos hizo ebo. Desde ese día, las cosas salieron tranquilamente para el\nMuslim con trapos largos.\n\nComentario:\n\nIfá dice que esta persona debe llevar una vida de devoción para recibir bendiciones.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 adie (ave). 2 juegos de cuentas de rezo de Muslim, 1\nepo (botella de aceite de palma), 1 plato blanco y dinero determinado por el adivinador, ofrecido\na Obatálá.\n\n(Ett (oferendas); 4 eiyele (pombo), 4 adiye (ave), 2 Ségi (fio de contas) , 1 epo (garrafa de\nazeite de dendé), 1 prato branco e certa quantidade de dinheiro determinada pelo 4wo,\noferecidos a Obatálá.)\n\nEs - el - huevo - que - rechaza - al - espíritu - del - niño, - fue - el - esperma - que - rechazó - al -\nespíritu - del - niño, consulta Ifa para la Tierra y los poderes destructivos viviendo en la tierra, en\nel día que la Tierra quería hacer ventas en el mercado. Ifá aconsejó a la Tierra hacer ebo para que\nla Tierra no fuera dañada por los poderes destructivos viviendo en la tierra. La Tierra hizo ebo.\nDesde ese día, todos los beneficios se quedaron con la Tierra.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo para que los ancestros destructivos en su familia no se\nroben su abundancia. Ifá dice que esta persona debe hacer una oferta de amabilidad para sus\ncolegas, para que no se vuelvan envidiosos y destructivos.\n\nEtutu (ofrecimiento): 1 eiyelé (pichón), 1 adie (ave). 1 plato blanco, 1 epo (botella de aceite de\npalma) y 100 nira (dinero), ofrecido a Obata/á. Eéwo (tabú): aceite sin cocinar.\n\n(Ett (oferendas); 1 eiyele (pombo), 1 adiye (ave), 1 prato branco, 1 epo, (garrafa de azeite\nde dend6) e 100 nira (dinheiro nigeriano), oferecidos a Óbatálá. Eéwó (tabu): Óleo cru.)\n\nI I\nI I\nn n\nI I", "origen_id": "0f050839d42857a403843f67"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Otura Meji implica la paz de la mente y la libertad de toda\n             ansiedad. Los hijos de Otura Meji son caballeros de carácter suave.\n               WO - Este es el momento bueno para el éxito en el negocio y las\n                                                                       relaciones.\n            Otura Meji es el decimotercer Odu en el orden fijado por Orunmila.\n       La gente nacida bajo este signo tendrá muchos éxitos con los negocios\nparticularmente en el arte de comprar y vender. Es importante apaciguar a\n     Eşu frecuentemente, porque hay quienes traicionarán sus confidencias o\n             planes para separarlo de su familia. Los hijos de Otura Meji deben\n\naprender a descansar para evitar el “colapso físico y mental”.\n               Si el Odu Otura Meji aparece para un cliente, Ifá dice que el cliente\n            tiene enemigos quienes lo han convertido en persona atolondrada. Así\n           como él está pobre, él no tiene esposa ni relaciones sociales. Él debería,\n     tan rápido como sea posible, ofrecer sacfrficios. Otura Meji dice que debe\n              hacer ofrendas a Ogún, Yemonja y a Ifá. Entonces así, él podrá estar\n           capacitado para vencer a sus enemigos, hacer algún dinero y finalmente\n                                                                tener esposa e hijos.\n\n\n13.1 · Arugbo-nla niise ori fegunfegun adivinó Ifá para Otu, cuando él fue\n      a Ife e hizo su trabajo de adivinación. el habló de sacrificar 2 bastones de\n            caminante y 2 carneras. Él dijo que él no retornaría pronto. Otu hizo el\n                                          sacrificio y permaneció por largo tiempo.\n\n\n13.2 · Arugbo-Oba ni-nso´gbodi´le, Idi-agbani-nse jekujeke adivinó Ifá\n    para Orunmila. Cuando él fue a descubrir y establecer un pueblo. Él habló\n    de sacrificar un grupo de hormigas soldados (owo ijamja), jabón negro, 40\n             cowrie, una cuerda en la sombra, un pedazo de ropa blanca y el árbol\n               odan. Orunmila oyó el aviso y sacrificó. Los Babalawos avisaron a\n      Orunmila de sembrar el árbol Odan en un arbusto y los caracoles. Él lavó\n      su cuerpo con el jabón negro y preparó hojas de Odan y hormigas. Él usó\n                                                      el trapo blanco para cubrirse.\n                Si Ifá encarna en alguien, él debe hacerlo así mismo. El Babalawo\n               hablaría con él para el lugar que él plantó el árbol de Odan descrito.\n\nEventualmente el sitio donde plantó el árbol de Odan se convertirá en\n                                                                            un mercado.\n\n\n13.3 · Okiti-ogan-af´idij´ago adivinó Ifá para Otu. Él fue mandado a\n                  ofrecer 2 tortugas para estar más próspero. Otu oyó y sacrificó. Los\n           Babalawos advirtieron a Otu de no matar las tortugas sino de venderlas.\n                  Luego de ver los sitios, él decidiría el lugar para vender las tortugas.\n            Cuando él llegó al pueblo, le fue ofrecido 80 sacos de monedas por las\n         tortugas. Eşu avisó a Otu de no aceptar el precio, Eşu siempre está a favor\n           de quien haga sacrificio. Cuando el precio se elevó en varios cientos de\n         sacos de monedas. Eşu le dijo que aceptara. Así fue como se hizo rico. El\n            babalawo dijo el día que Otu compró 2 tortugas fueron llamadas Otura\n                                                                                    Meji.\n\n\n13.4 · Olusese awon ni Awo inu-igbo, Elu-odan-afidij´Odu adivinó Ifá para\n     Orunmila. Orunmila habló para que él pudiera dominar el barrio. Orunmila\n                   preguntó ¿cuál es el sacrificio?. Los babalawos dijeron 6 esteras, 6\n         papagallos, 6 chivas, 1200 cowrie. Le fue dicho que las personas de todas\n         partes del mundo vendrían a rendirle honor en su estera. Orunmila hizo el\n         sacrificio lo más rápido posible. Y las personas de todo el mundo vinieron\n          en honor a él sobre la estera como fue predicho por Ifá. Desde ese día los\n                   Babalawos se sientan sobre una estera para hacer sus predicciones.", "origen_id": "265eb6f93fb156fd3eca6317"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la riqueza: dos tortugas que no se matan sino que se venden.", "Para fundar: hormigas guerreras, jabón negro, cuarenta caracoles ensartados, tela blanca y un retoño de odán; sembrar el odán con los caracoles atados y bañarse con el jabón.", "Para gobernar con justicia: seis esteras, seis plumas de loro, seis chivas y dinero.", "Para el viaje largo: dos bastones de caminante y dos carneras.", "Para la devoción: cuatro palomas, cuatro aves, dos sartas de cuentas de rezo, aceite de palma, un plato blanco y dinero para Ọbàtálá.", "Contra los poderes destructivos: una paloma, un ave, un plato blanco, aceite de palma y dinero para Ọbàtálá."], "pasajes": [{"titulo": "Ofrenda en el verso 13.1", "texto": "Arugbó-ńlá niiṣe orí fegunfegun:\nadivinó Ifá para Òtú,\ncuando él estaba yendo a lfẹ\npara hacer su trabajo de adivinación.\nSe le aconsejó ofrecer un sacrificio:\nDos báculos de caminante\ny dos carneras.\nA él se le dijo que no retornaría pronto.\nÒtú escuchó y sacrificó\nÉl permaneció por largo tiempo en Ifè.", "origen_id": "aa8c9167367e32086b965b78"}, {"titulo": "Ofrenda en el verso 13.2", "texto": "Arugbó-Oba ni-nsọ'gbodi'le,\nÌdí-agbani-nṣe jẹkujẹkẹ:\nadivinaron Ifá para Çrúnmilà,\ncuando él estaba yendo en una misión\npara descubrir y establecer un pueblo.\nA él se le aconsejó que sacrificara:\nGrupo de hormigas guerreras (ową ijamja), jabón negro,\ncuarenta cowries que hayan sido ensartados\ncon una cuerda en la oscuridad,\ntela blanca (para hacer una ropa) y una postura de odán.\nỌ̀rúnmìlà escuchó y sacrificó.\nDespués del sacrificio\nlos Babaláwos aconsejaron a Ọ̀rúnmìlà\nque sembrara el odán en una arboleda (manigua)\ny que amarrara la cadena de caracoles a este.\nEl debía lavar su cuerpo con el jabón negro\npreparado con hojas de odán y las hormigas.\nEl usó la tela blanca para cubrir su cuerpo.\nSi este Ifá encarna en alguien,\nel debe ser aconsejado hacer lo mismo.\nLos Babaláwos le dirán con seguridad:\n\"el lugar donde se plantó el árbol de odán\nse convertirá en un mercado\".", "origen_id": "f95d9adafab2f70c511d5bca"}, {"titulo": "Ofrenda en el verso 13.3", "texto": "Ökiti-ogán-af'idij'ago:\nadivinó Ifá para Otú.\nLe aconsejó sacrificar: dos tortugas,\npara convertirse en excesivamente rico.\nOtú oyó y sacrificó.\nEl Babaláwo advirtió a Otú de no matar las tortugas,\nsino que las vendiera.\nLa suerte estaba echada\npara que él decidiera dónde ir a venderlas\nal mejor precio.\nCuando él llegó al pueblo,\nle ofrecieron ochenta sacos de dinero por las tortugas.\nÈṣú avisó a Otú de no aceptar el precio.\nEṣú siempre está a favor de quien sacrifica.\nLa oferta fue aumentando,\ncuando el precio aumento\na cientos de sacos de dinero,\nEṣú avisó a Otú de que aceptara el precio.\nAsí fue como Otú se hizo muy rico.\nLos Babaláwos dijeron:\n\"El día que Otú compró dos tortugas, debe ser llamado Òtúrá Méjì\".", "origen_id": "2f0707a244528e8d7d238372"}, {"titulo": "Ofrenda en el verso 13.4", "texto": "Oluṣpse áwon ni Awo inú-igbó,\n#lu-odàn-afidij'Odù:\nadivinaron Ifá para Ọ̀rúnmìlà.\nA él le fue aconsejado sacrificar\npara que gobernara justamente a su pueblo.\nỌ̀rúnmìlà preguntó: ¿Cuál es el sacrificio?\nLos Babaláwos dijeron:\nmois esteras, seis plumas de loro,\nseis chivas y 1200 cowries.\nLe fue dicho que gentes\nde todas partes del mundo\nvendrían a rendirle honor en su estera.\nỌ̀rúnmìlà hizo el sacrificio tan rápida\ncomo le fue posible,\ny las personas de todas partes del mundo\nvinieron a brindarle honor\nsobre la estera como fue predicho.\nDesde ese día, los Babaláwos\nse sientan sobre una estera\npara hacer sus predicciones.", "origen_id": "a7449aefee18ba073f4612aa"}, {"titulo": "Ofrenda complementaria 1", "texto": "1 eiyelé, 1 adie, 1 plato blanco, 1 epo y 100 nira\n\nDestinatario: Obatálá", "origen_id": "15f4796cb4a1843ed0d157af"}]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù debe ser atendido con frecuencia y aconseja el buen precio. Ògún, Yemọja e Ifá reciben ofrendas para vencer a los enemigos. Ọbàtálá. Tabú: aceite de palma crudo, sin cocinar.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Obatala; Orunmila", "origen_id": "fb1f4af912cef14d8f23c84e"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Odán (Ficus), jabón negro, hormigas guerreras, tela blanca, plumas de loro (ìkóóde), esteras, tortugas, bastones."}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 1", "texto": "aceite sin cocinar", "origen_id": "bf364aac5e30de04bebb02f6"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 13.1 (yorùbá): Arugbó-ńlá niiṣe ori fegunfegun: / a dífá fÒtú, / mi s'awo lọ salẹ lfẹ. / Wọ̀n niki ó rú: / Opa Méjì ati àgùtàn Méjì / Wọ̀n ni: / ko nii tètè bọ / Ôtú gbọ̀ ó rúbọ. / Ò pẹ.", "Verso 13.2 (yorùbá): Arugbó-Oba ni-nsọ'gbodi'le, / Ìdí-agbani-nṣe jẹkujẹkẹ: / li o dífá f'Ọ̀rúnmìlà, / niọ te ilu do. / Wọ̀n niki ó rú: / Qwo ljamja, Ọ̀ṣẹ́, / Ogoji owo ẹyọ ti a sin li òkùnkùn, / aṣo funfun ati igi-odán. / Ọ̀rúnmìlà gbọ̀ ó rú. / Awon Babaláwo ni / ki Ọ̀rúnmìlà mu igi-odán / yi lọ sinu igbó kan, / kiogbin in sibẹ, / kioso ogóji-owó-ẹyọ ti a sin / li okunkun naa mọg / Kiomaa fi Ọ̀ṣẹ́ naa tia ti gun ewé odánso / ati owo-ijamja ma we. / Kiomaa fi aṣg funfun yen bora. / Bi Ifá yi ba bi èniyàn, / ao sọ fún un pe kioṣe bẹẹgegẹ. / Babaláwo naa yoo sọ fún un / pẹlu idaniloju pe: / \"Ibiti o lọ gbin odán si yẹn, / wọ̀n yoo n'ọjá nibẹ\". / pdán: Ficus sp. L., Moraceae; o Ficus THoNNINGII Blume, Moraceae.", "Verso 13.3 (yorùbá): Okiti-ogán-af'idij'ago / li o difá fOtú. / Wọ̀n niki ó rú: Awun Méjì, / wọ̀n ni a di olórò. / Ôtú gbọ̀ ó rú. / Awon babaláwo niki Òtú / maṣe pa àwọn Awun naa, / tita niki ó ta wọn. / Wọ̀n le Ibo lati mọ ibiti oun iba lọ ta wọn / O losi ilu naa, / wọ̀n yợ wo Awun titi de Ogoji okẹ. / Eṣú sọ fún un pe kioma gba. / Eniti ó ba rúbọ ni Èṣú ngbe. / Nigbi wọ̀n yọ' wo Awun titi ni ilu naa / de Qkẹ-aimoye owó / ni Èṣú sọ fún un pe kio gba. / Bẹẹ ni Ờtú di Ọlórọ̀ si. / Awon Babaláwo ni: / \"ljọ ti Ötú ra Awun Méjì, ki ama pee ni: Otúráméji\".", "Verso 13.4 (yorùbá): Oluṣeṣẹ àwon ni Awo inú-igbó, / Flu-ọ̀dàn-afidij'Odù: / a dífá f'Ọ̀rúnmìlà. / Wọ̀n ni ki ó rúbọ / ki qwọ̀ rẹ̀ le ka ilú rẹ̀. / Ọ̀rúnmìlà ni: / kini ebo? / Àwọn Babaláwo ni: / eni mẹfà, ikoodẹ méfà, / ewurẹ mẹfà / ati ẹgbèfà owó ni ebọ. / Wọ̀n ni: / gbogbo ayé lio maama wọ tọọ / wa sori eni naa. / Ọ̀rúnmìlà yara rúbẹ, / gbogbo ayé si nwọ tọọ, / lori eni naa. / Lati ojo naa ni Babaláwo / ti njoko lori eni difá.", "REZO: QUERENCHELE AGUA NIPAPE LODAFUN GUERE NIPAPE ONDAFUN INLA NIPAPE, GUERE NIPAPE LERUBE GUERE NIPAPE QUITE LLEURE LODAFUN ESUCUN ADIFA NIBATI UN CAGUELERIN.", "REZO: PARENCHELE AGUE NIPARO LODAFUN QUE QUERE LAPE PAPE LERUBE QUE QUERE ORUMILA LEFE UN TERI BEBETONILLE LEBE. ASE CUNDIFA IMALE ADIFAFUN BENI SUCU. ALAFIA ADAFUN MALE ADAFUN ORUMILA UN CHERUNLA LEFE ACODE ETI LLARECE ASABEBE UNTE OCU EYA EBETA EWE.", "REZO: CIRIYAN CIRIJAN ARIFA YOKO KANFUN OWERE OLODAFUN OKETE.", "REZO: ADIFAFUN OKUNRIN OKOLORI LODAFUN AKAN.", "REZO: ADIFAFUN ORUNMILA, OGGUN BORO BORO, ALEYO OKO ITA ILEGGUN, LODAFUN ELEGBA.", "REZO: OSHAGRINIYAN BABA NI ORISHA FUN FUN, UMBOWA AIYE OGBORI OSODE OLORI MEYI LARE NI AIYE ASHE OLOFIN ANIWA ORUN OSIYANI ATIWA ORUN ATIWA OLUO KAFEREFUN ORUNMILA, LODAFUN GBOGBO KALENU ORISHA.", "SUYERE: BABA ALAYEO BABA ALAYEO LEKUA UMBO OMINIYO LAYEYEO OKUNI BABA.", "REZO: ALAFIA BORUKU OLORUN KOKOIBERE ABAYIKI SUMAJANA SALAMALEKUN MALEKUN SALA ANGMO SEDA ITANA MEDINA AKANA IBODUNOSATU OMI INA KUPA BELEYO MODUN MODUN LODAFUN SAHNGO KAFEREFUN MALE. REZO: ASOKUN NIFA ADIFAFUN SALE MALE MALE AU SALE AWONSI ABONIRAYE IFA ONIRE OLOFIN OMO IFA ABABANIREGGUN EGGUN OTOLA MAYERE NI AWO OMONIFA SALE MALE MALE OU MALE", "MAYIRE ABONIKUN ORUN ALWARODE EGGUN YEYEKUN ORUN SALE MALE MALE OU SALE AWO ORONIFA IFA KAFEREFUN EGGUN ORUNMILA SHANGO Y OLOFIN.", "REZO: ORUNMILA ASOKUN DIFA IMALE NI AWO ORUNMILA NI INLE NI IBO BAYEKUN AUN LOSILE OMO BABANIREGGUN ORUNMILA AWO OBA BARA NIFE ADIFAFUN OLOFIN ADIFAFUN SHANGO ADIFAFUN ORUNMILA."], "pasajes": [{"titulo": "suyere", "texto_ritual": "ORISHAOKO, DIDE BABA KAREE KARE LAWA.", "origen_id": "55aed68e6f78a97d6953aa7b"}, {"titulo": "suyere", "texto_ritual": "OTURA NIKO OTUA DOLOGUE ASHO IKU YANAYAN ASHE IKU AYE ASHE IKU OLORUN.", "origen_id": "ca552005abf726df5fedd951"}]}]$q$::jsonb),
(14,'9822265aa7cf5937daad6a2048692a24','0b36dded197c743e46e526560eef7177',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Méjì enseña que lograr las cosas por caminos indirectos tiene su recompensa y que la humildad es una gran virtud. Advierte contra las intrigas de enemigos que trabajan para reducir las oportunidades del consultante, que además se ha vuelto conformista. Llama a dedicarse por completo a Ifá: los varones de este Odù deben iniciarse. A quien cree, Ọ̀rúnmìlà le da dinero, pareja, hijos, vida larga y felicidad. Si hay un enfermo, pide ofrendas a Ọbalúayé (Ṣànpọ̀nná) y a las àjẹ́, y también atención médica.", "pasajes": [{"titulo": "Frase clave", "texto": "Irete crea determinación.", "origen_id": "bec8436f76a5d8c3ec5c94f2"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se está conformando con algo que ya no le sirve y eso lo lleva a un problema.", "Desea tener hijos o sufre por no lograrlos (relatos de Òdonràdà e Imò omi).", "Recibe burlas o le preocupa el qué dirán (la misma boca que alaba también ofende).", "Tiene una meta importante, pero su firmeza se volvió terquedad.", "Está cansado o presionado y necesita descansar y atender su cabeza (Orí) antes de decidir.", "Su forma de ser le complica la convivencia con otros (relato del cangrejo Akon en el mercado).", "Va a asumir una responsabilidad espiritual o a iniciar a otros."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que ninguno de los que se inician muera joven.", "Muchos hijos de buen carácter.", "Que las bocas que se burlan se cierren.", "Un compañero fiel que nunca abandona.", "Dinero, pareja, hijos, vida larga y felicidad por la devoción a Ifá."]}, {"titulo": "Ibi y advertencias", "puntos": ["Intrigas de enemigos.", "Conformismo que lleva a la dificultad.", "Estrés, depresión o humillación por fuerzas malévolas.", "Cansancio e impaciencia bajo presión.", "Burla de la gente."]}, {"titulo": "Enseñanza principal", "texto": "La boca que hoy alaba puede mañana insultar: al rico le dicen 'buenos días, señor', al pobre 'buenos días, pobre'. Lo que el ser humano ha perfeccionado es la burla. Quien se cubre con lo que no debe, se mancha."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ìrẹtẹ̀ Méjì dice: \"Servirse de medios indirectos para lograr algo, tiene su recompensa\". La humildad es una virtud muy importante. Este Odù advierte contra intrigas (enredos) de los enemigos, quienes están trabajando duro para reducir nuestras oportunidades de éxito en la vida.", "origen_id": "3e6e385c623c92a67d79225c"}, {"titulo": "Características generales", "texto": "Otros nombres: Ìrẹtẹ̀ Méjì; Ejirete / Èji elemere.\nEn el orden fijo de Ọ̀rúnmìlà el Odù Ìrẹtẹ̀ Méjì ocupa la decimocuarta posición. Este Odù llama a dedicarse totalmente a Ifá. Todos los que tengan este Odù tienen que ser devotos de Ọ̀rúnmìlà, los varones deben ser iniciados para convertirse en Babaláwos. Si los encarnados en este Odù creen en Ifá, Ọ̀rúnmìlà les dará buena fortuna de dinero, esposas, hijos, larga vida y felicidad.\nDe vez en cuando ellos tendrán que propiciar sus cabezas (Orí) con el objetivo de evitar el estrés emocional, la depresión o la humillación provocada por la acción de fuerzas malévolas. Si Ìrẹtẹ̀ Méjì es adivinado para un cliente que está enfermo, Ifá dice que para su rápida recuperación el cliente deberá ejecutar los sacrificios adecuados a Babaluàiyé (Sànpònna) y a las brujas (àjé).\nLos hijos de Ìrẹtẹ̀ Méjì deberán aprender a relajarse, porque es fácil para ellos cansarse, sentirse fatigados, aburridos e impacientes cuando están bajo presión.", "origen_id": "fc64981b6ed5a71d85ba2460"}, {"titulo": "Interpretación tradicional", "texto": "lrete es una omisión de ire te significando presionar ó crear buena fortuna. En términos personales Irete es la determinación testaruda para crear abundancia y moverse hacia la transformación de uno mismo. Cuando ésta testarudez está dirigida hacia metas inapropiadas, se vuelve la fundación para la resistencia al cambio.", "origen_id": "881a167d5f6338f6050e2282"}, {"titulo": "Orientación complementaria", "texto": "Irete representa el movimiento inflexible hacia una meta. La determinación como se manifiesta Irete es la voluntad de satisfacer el destino y para desarrollar el buen carácter. En la manifestacion negativa, la determinación se vuelve resistencia testaruda al crecimiento.", "origen_id": "a84e95e5c47550cc4cfc6e08"}]}, {"titulo": "Relatos reunidos", "puntos": ["Ìrẹ̀n y los dos iniciados. Ìrẹ̀n iba a iniciar en Ifá a dos hijos de Ọlọ́fin y le pidieron ofrendar para que ninguno de los que él iniciara muriera joven. Ofreció, y el día en que Ìrẹ̀n inició a dos personas que no murieron se llamó Ìrẹtẹ̀ Méjì. Ọ̀rúnmìlà también, de camino a Ifẹ̀, ofreció dos palomas y lo demás que marcó Ifá, y le lavaron la cabeza con hojas de tẹ̀tẹ̀ trituradas en agua: ninguno de los que él inicia muere joven.", "El cangrejo y el mantón. Al cangrejo (akàn) le dijeron que su conducta no encajaba con la gente del mercado y que, si quería corregirse, ofreciera un recipiente de aceite de palma y un mantón. Se negó. Un día de mercado llevaba un recipiente de aceite en equilibrio sobre la cabeza; al intentar envolverlo con su mantón, se le cayó encima y el aceite le manchó la ropa. Desde entonces el aceite de palma le tiñó el cuerpo, y así lo lleva en la espalda hasta hoy. Al hijo de este Odù se le advierte que nunca se cubra con un mantón.", "Olúwẹri y el cangrejo fiel. Olúwẹri, espíritu del río, iba a comprar al cangrejo como sirviente. Le dijeron que si lo adquiría nunca más necesitaría de nadie, y le pidieron una palangana nueva, una chiva y ẹfun. Ofreció, puso el ẹfun en la palangana nueva y entregó la chiva. Antes había tenido sirvientes humanos que lo maltrataron y lo abandonaron; solo el cangrejo se quedó con él, y tuvo muchos hijos.", "El cerdo de camadas incontables. Pètèpétè adivinó para Òdonràdà, la cerda, que lloraba por hijos. Le pidieron ofrendar, ofreció, y se volvió la cerda distinguida de camadas que no se pueden contar.", "La boca que alaba y la que insulta. Ajílósòó, el sacerdote de la orilla del camino, adivinó para la boca de los seres humanos, que tiene dos caras. Le pidieron ofrendar para que la misma boca que lo alababa no se usara para insultarlo; ofreció. Si uno tiene dinero, le dicen: buenos días, rico; si es pobre, le dicen: buenos días, pobre. Un saludo vale más que el otro. ¿Qué es lo que el hombre ha perfeccionado en el mundo? La burla. Ifá promete cerrar las bocas que se burlan de esta persona.", "Los niños de Ìpéré Àmúyọ̀. La gente de Ìpéré Àmúyọ̀ iba a criar a sus hijos con aguardiente. Les pidieron ofrendar, cumplieron, y desde ese día sus hijos desarrollaron buen carácter.", "Imọ̀ Omi y las cuentas. La cuenta de abajo a la izquierda y la de abajo a la derecha nunca discuten entre ellas: así adivinaron para Imọ̀ Omi, que quería tener hijos en la tierra. Ofreció y recibió la bendición de los hijos, y Èṣù le puso en la boca este canto: no hay hijos en venta; quiero más a los hijos que a las cuentas. La mujer que quiere hijos ofrece de sus joyas y pide a los antepasados la bendición."], "pasajes": [{"titulo": "Verso 14.1", "texto": "Eliam awo Olüigbó:\nadivinó Ifá para Ọ̀rúnmìlà,\nluando ăl estaba yendo a lfẹ,\nI adivino dijo:\nninguno de los que Ọ̀rúnmìlà ha iniciado morirá joven\".\n, dos palomas y otras cosas®2\ntian de tọ̀tẹ̀\"\"\nsacrificio.\neanuchó y ejecutó el sacrificio,\nPladivino trituró las hojas de tetè en agua\ny esto lo usó para lavar su cabeza.", "origen_id": "06f1a42f46892eceed93f9cc"}, {"titulo": "Verso 14.2", "texto": "Adá-ilé-o-mukankan:\nadivinó Ifá para İrẹn,\ncuando él iba a iniciar a dos hijos de Ọlófin.\nLe fue aconsejado hacer sacrificio.\npara que él estuviera seguro que ninguno\nde los que iniciaría, moriría joven,\nEl escuchó el consejo y sacrificó.\nEl adivino dice:\n\"el día que irẹn inició a dos personas\nquienes no murieron fue llamado \"Ìrẹ-tè-Méjì\".", "origen_id": "9afbb3c8de618eba583ea6f2"}, {"titulo": "Verso 14.3", "texto": "Qdan-ab'oripẹgunpẹgun:\nadivinó Ifá para Akon (el cangrejo).\nEl adivino dijo:\n\"el carácter (conducta) del cangrejo\nno va a encajar (ajustarse)\ncon las personas en el mercado,\npero si quería ajustar esta falta en sí mismo,\ndebería sacrificar\":\nun recipiente de aceite (ata epo) y un mantón.\nAkon se negó a hacer el sacrificio.\nUn día de mercado,\na Akon se le balanceo un recipiente\nde aceite de palma sobre su cabeza,\ncuando intentaba envolverlo con su mantón,\nel pote le cayó en su cabeza\ny el aceite manchó sus ropas.\nDesde ese día el aceite de palma\ntiñó el cuerpo de Akọn,\nAsí ha permanecido sobre su espalda\nhasta hoy día.\nSi alguien es nacido de este Ifá\ndeberá ser advertido\nde nunca usar un mantón (chal)\npara cubrir su cuerpo.", "comentario": "tọ̀tọ̀: AMARANTHUS HYBRIDUS L. subsp. incurvatus (Timeroy) Brenan, ati begbẹẹ: etcetera. Significa otras cosas que agrega el Awo al sacrificio tras Amaranthaceae.\nconsultarlo con Ifá, pueden ser productos o dinero.", "origen_id": "dad7a4969955ecff5fc88995"}, {"titulo": "Verso 14.4", "texto": "Adilu-abidiṣumuṣumu:\nadivinó Ifa para Olúwẹri,\ncuando Olúwẹri iba a comprar\na Akon (cangrejo) como esclavo.\nEl adivino dijo:\n\"si él adquiere ese esclavo\nnunca más necesitará de las personas\"\nUna palangana nueva (Awo-tituna),\nchiva, ẹfún,\ndeberá ser utilizado para el sacrificio.\nOlúweri obedeció y efectuó el ebo,\nAkon tuvo muchos hijos.\nOlúweri inicialmente había comprado\nesclavos humanos.\nEllos lo maltrataron y desertaron de él.\nSólo el cangrejo Akon permaneció con él.\nColocó ẹfún en la palangana nueva\ny ofreció la chiva.", "comentario": "53 Olúweri: un espíritu del río, que representa una faceta o aspecto masculino de Yemoja.\n5ª Awo-titun: plato, fuente, loza, palangana, cacharro, que sea nuevo (sin usar).", "origen_id": "23a2e118db5a5e87819ddc66"}, {"titulo": "Versos complementarios 1 · A", "texto": "Pètèpétè\n ' ' ' ' mónà  ' se ' gbàbú\nA díá fún Òdonràdà`\nNíjó' tí n´ fomi ojúú sògbérè omo\n                               ' '\nEbo\n' '   n wón '  ní ó  se\n                     '\nÓ sì gbébo      ´\n          ' ' nbè\nÓ rúbo'\nAfinjú elédè\n          ' `' ' abomo\n                    ' ' yoyo\n                          ' 'ò\nÒdo òdonràdà\n\nÌretè\n  ' ' Méjì A\nPètèpétè mónà se gbàbú\nAdivinación lanzada para Òdonràdà\nEn el día que ella estaba llorando debido a niños\nEl sacrificio es lo que se recomendó para ella\nElla oyó hablar del sacrificio\nY lo realizó\nEl cerdo distinguido con camadas incontable\nÒdo òdonràdà", "origen_id": "b00439fe9ec0d4716f8bc7e1"}, {"titulo": "Versos complementarios 2 · B", "texto": "Ifá pé òún ó pa enu\n                ' elégàn\n                    ' '  mó' lára eléyiun. Lójú àwon\n                                                  ' 'elégàn\n                                                       '    tí ´n gàn án náà ní ti ríre.\n\nAjílósòó Awo èbá        ' ònà   '\nA díá fún enú  ' '    se    méjì     enu\n                                      ' ènìyàn\nWón '   ní enu\n           '      tí  ón\n                       '     bá   fi  yìn ín\nWón ' ò níí fi bú u\nEbo\n ' ' ni kó´ se '\nÓ gbébo' '   nbè\nÓ rúbo'\nBóo bá lówó\nWon ' a ní pèlé  ' ' o Olówo\nBéèyàn ò sì lówó\nWon ' a ní pèlé  ' ' o ìwo Òtòsì        '\nIfá pèlé   òkan\n       ' ' '         ló yá\nÓ ti yá ju pèlé  ' ' òkan\n                        '         lo'\nPèlé\n   ' '  Olówó       ló    ti yá\nLó ju pèlé   ' ìwo' Òtòsì\n` kín 'layé\nNjé                móo\n                                '\n    '                   ' ' se?\n                              '\nÈgàn\n '\nÈgàn\n '       layé móo  ' ' se '\nÈgàn.\n '\n\nÌretè\n   ' ' Méjì B\nIfá dice que él cerraría las bocas de las personas que se burlan de esta persona. Él está en\nsu presencia que él lo haría.\n\nAjílósòó el camino al lado del sacerdote\nAdivinación lanzada para los portavoces Dobles, la boca de hombre\nEl mes que ellos usaron alabándolo\nLa misma boca no se usaría para abusarlo\nPero él debe realizar sacrificio\nÉl oyó hablar del sacrificio\nY lo realizó\nSi usted es adinerado\nEllos lo llamarían un hombre rico\nSi por otra parte usted es pobre\nEllos dirían ‘hola el hombre pobre’\nIfá, un saludo es mejor,\nEs mejor que el otro\nHola, el hombre rico es mejor\nEs mucho mejor que hola, el hombre pobre\n¿Por consiguiente lo que es esa cosa que el hombre ha perfeccionado?\nBurla\nLa burla es que el hombre ha perfeccionado\nBurla.", "origen_id": "a5b717c8842c5bee7afb0aeb"}, {"titulo": "Relatos y ofrendas", "texto": "ÌRETÉ MEJÌ\n\nAmukikùtù consulta a Ifá para las personas de Ipere Amuyo en el día que iban a usar ginebra para\ncriar a sus' hijos. Ifá aconsejó a las personas de Ipere Amuyo hacer ebo. Las personas de Ipere\nAmuyo hicieron ebo. Desde ese día, los niños de [pere Amuyo desarrollaron buen carácter.\n\nComentario:\n\nIfá dice que esta persona tendrá muchos hijos. Ifá dice que esta persona debe hacer ebo para que\ntenga abundancia y buen carácter.\n\nEtutu (ofrecimiento): 1 adie (ave), 1 eiyelé (pichón), 1 epo (botella de aceite de palma), 1 plato\n\n96\n\nblanco, eko (pastel de harina de maíz) y 40 nira (dinero), ofrecido a Osun y a Ifá.\n(Etutú (oferendas); 1 adiye (ave), 1 eiyele (pombo), 1 epo (garrafa de azeite de dendé), 1\nprato branco, ekó e 40 nira (dinheiro nigeriano), oferecidos a Ósun e Ifá.)\n\nLa - cuenta - de - abajo - en - la - izquierda, - y - la - cuenta - de - abajo — en - la - derecha - nunca\n- discuten - entre - ellas - mismas, consulta Ifá para Imò omi en el día que ella iba a tener hijos en\nla tierra. Ifá aconsejó a Imò omi hacer ebo. Imó omi hizo ebo. Imo omi recibió una bendición de\nhijos. Imo omi cantó y bailó en alabanza al Awo, mientras el Awo alabó a Ifá, mientras Ifá alabó\na Olodumare. Cuando Imó omi empezó a cantar, Esú puso una canción en su boca. Imò omi\ncantó:\nKo de si omo láte, omo wun mi ju ileke.\nKo de si omo láte, omo wun mi ju ilete.\nNo hay hijos en venta, amo a los hijos más que a las\ncuentas.\nNo hay hijos en venta, amo a los hijos más que a las\ncuentas.\nComentario:\nIfá dijo que si una mujer quiere hijos, ella debe hacer ebo con su joyería y pedir a los ancestros\npor una bendición de hijos.\nEtutu (ofrecimiento): 1 eiyelé (pichón), 1 adie (ave), cuentas, eko (pastel de harina de maíz). 1\nepo (botella de aceite de palma), 1 plato blanco y 45 nira (dinero), ofrecido a Osun y a Ifá. Eéwo\n(tabú): gallo, espinaca.\n(Ett (oferendas); 1 eiyele (pombo), 1 adiye (ave), contas, ekó (bolos de milho), 1 epo\n(garrafa de azeite de dendé), 1 prato branco e 45 nira (dinheiro nigeriano), oferecidos a\nÓsun e Ifá. Eéwó (tabu): galo, espinafre.)\n\nI I\nn n\nI I\nn n", "origen_id": "a6e78af3d4f13cd32cd3545c"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Irete Meji dice se paga por rebajarse para conquistar. La\n humildad es una virtud muy importante. Este Odu advierte contra intrigas\n     de los enemigos quienes están tratando de acortar el trabajo de nuestras\n                                         oportunidades para el éxito en la vida.\n       WO - Esta persona marcha hacia su propio tambor y tiene problemas\n                                                                de conformidad.\n                       En el orden fijo de Orunmila el Odu Irete Meji ocupa la\ndécimocuarta posición. Este Odu llama a una total dedicación a Ifá. Todos\n       los hijos de Irete Meji tienen que ser devotos de Orunmila. Los hijos\n     varones deben ser iniciados para convertirse en Babalawos. Si los hijos\n       creen en Ifá, Orunmila les dará buena fortuna para el dinero, esposas,\n                                                   hijos, larga vida y felicidad.\n           De vez en cuando ellos tendrán que rogarse sus cabezas (ori) con el\n objetivo de evitar el estrés emocional o la humillación por las fuerzas del\n mal. Si Irete Meji se marca para un cliente que está enfermo, Ifá dice que\n           para su rápida recuperación el cliente deberá ejecutar los sacrificios\n                               adecuados a (sanponna) y a las hechiceras (aje).\n           Los hijos de Irete Meji, deberán aprender como relajarse porque es\nfácil para ellos convertirse fatigados, aburridos e impacientes cuando están\n                                                                     depresivos.\n\n\n14.1 · Okan awo Oluigbo adivinó Ifá para Orunmila, cuando él estaba\n         yendo a Ife, le fue dicho que ninguno de los que él ha iniciado moriría\n         joven, hojas tete y 2 palomas son sacrificadas. Él escuchó y ejecutó el\n          sacrificio, las tete fue molida en agua para ser utilizadas para lavar su\n                                                                            cabeza.\n\n\n14.2 · Ada-ile-o-mukankan adivinó Ifá para Iren, cuando él iba a iniciar a\n               dos hijos de Olofin, le fue dicho sacrificar. Él atendió el consejo y\n     sacrificó. Él estaba seguro que ninguno que él inició moriría joven, el día\n     que Iren inició a 2 personas quienes no murieron fue llamado Irete Meyi.\n\n\n14.3 · Odan-ab´oripegunpegun adivinó Ifá para Akon (el cangrejo), le fue\n   dicho que él nunca encajaría con las personas en el mercado, pero si quería\n         ajustar esta falta en el mismo, él debería sacrificar 1 pote de aceite (aja\n              epo) y un mantón. Akon negó hacer el sacrificio sobre en un día de\n            mercado Akon balanceó su pote de aceite de palma sobre su cabeza.\n   Cuando él intentó cubrirse con su mantón, el pote le cayó en su cabeza y el\n   aceite manchó sus ropas. El aceite de palma entonces manchó el cuerpo de\n    Akon ese día. Desde ese momento ha permanecido sobre su espalda hasta\n   hoy día. Si alguien es nacido de este Ifá deberá ser advertido de nunca usar\n                                                un mantón para cubrirse su cuerpo.\n\n\n14.4 · Adilu-abidisumusumu profetizó Ifá para Oluweri, quien iba a\n\ncomprar Akon (cangrejo) como un esclavo, le fue dicho que si él adquirió\n el esclavo nunca estaría necesitado de las personas. Una nueva palangana,\n1 chiva, cascarilla, deberá ser utilizado para el sacrificio. Oluweri obedeció\n y efectuó el ebo, Akon tuvo muchos hijos, Oluweri originalmente compró\nesclavos humanos. Ellos lo maltrataron y desertaron de él. Sólo el cangrejo\n       Akon permaneció con él, colocó la cascarilla en la palangana nueva y\n                                                             ofreció la chiva.", "origen_id": "69cbaf4f7573f647741332f5"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los iniciados: dos palomas y lo que marque Ifá; lavar la cabeza con hojas de tẹ̀tẹ̀ en agua.", "Para el carácter: un recipiente de aceite de palma y un mantón.", "Para el compañero fiel: una palangana nueva, una chiva y ẹfun.", "Para hijos de buen carácter: un ave, una paloma, aceite de palma, un plato blanco, ẹ̀kọ (pastel de maíz) y dinero para Ọ̀ṣun y para Ifá.", "Para tener hijos: una paloma, un ave, cuentas, ẹ̀kọ, aceite de palma, un plato blanco y dinero para Ọ̀ṣun y para Ifá.", "Contra la enfermedad: ofrendas a Ọbalúayé y a las àjẹ́."], "pasajes": [{"titulo": "Ofrenda en el verso 14.1", "texto": "Eliam awo Olüigbó:\nadivinó Ifá para Ọ̀rúnmìlà,\nluando ăl estaba yendo a lfẹ,\nI adivino dijo:\nninguno de los que Ọ̀rúnmìlà ha iniciado morirá joven\".\n, dos palomas y otras cosas®2\ntian de tọ̀tẹ̀\"\"\nsacrificio.\neanuchó y ejecutó el sacrificio,\nPladivino trituró las hojas de tetè en agua\ny esto lo usó para lavar su cabeza.", "origen_id": "c95ccc08faa540cd04d53354"}, {"titulo": "Ofrenda en el verso 14.2", "texto": "Adá-ilé-o-mukankan:\nadivinó Ifá para İrẹn,\ncuando él iba a iniciar a dos hijos de Ọlófin.\nLe fue aconsejado hacer sacrificio.\npara que él estuviera seguro que ninguno\nde los que iniciaría, moriría joven,\nEl escuchó el consejo y sacrificó.\nEl adivino dice:\n\"el día que irẹn inició a dos personas\nquienes no murieron fue llamado \"Ìrẹ-tè-Méjì\".", "origen_id": "0a85a7b59426531dd91cbbfb"}, {"titulo": "Ofrenda en el verso 14.3", "texto": "Qdan-ab'oripẹgunpẹgun:\nadivinó Ifá para Akon (el cangrejo).\nEl adivino dijo:\n\"el carácter (conducta) del cangrejo\nno va a encajar (ajustarse)\ncon las personas en el mercado,\npero si quería ajustar esta falta en sí mismo,\ndebería sacrificar\":\nun recipiente de aceite (ata epo) y un mantón.\nAkon se negó a hacer el sacrificio.\nUn día de mercado,\na Akon se le balanceo un recipiente\nde aceite de palma sobre su cabeza,\ncuando intentaba envolverlo con su mantón,\nel pote le cayó en su cabeza\ny el aceite manchó sus ropas.\nDesde ese día el aceite de palma\ntiñó el cuerpo de Akọn,\nAsí ha permanecido sobre su espalda\nhasta hoy día.\nSi alguien es nacido de este Ifá\ndeberá ser advertido\nde nunca usar un mantón (chal)\npara cubrir su cuerpo.", "origen_id": "dafe4943e5da4191f231dafd"}, {"titulo": "Ofrenda en el verso 14.4", "texto": "Adilu-abidiṣumuṣumu:\nadivinó Ifa para Olúwẹri,\ncuando Olúwẹri iba a comprar\na Akon (cangrejo) como esclavo.\nEl adivino dijo:\n\"si él adquiere ese esclavo\nnunca más necesitará de las personas\"\nUna palangana nueva (Awo-tituna),\nchiva, ẹfún,\ndeberá ser utilizado para el sacrificio.\nOlúweri obedeció y efectuó el ebo,\nAkon tuvo muchos hijos.\nOlúweri inicialmente había comprado\nesclavos humanos.\nEllos lo maltrataron y desertaron de él.\nSólo el cangrejo Akon permaneció con él.\nColocó ẹfún en la palangana nueva\ny ofreció la chiva.", "origen_id": "6514902cd5532ccc62e52348"}, {"titulo": "Ofrenda complementaria 1", "texto": "1 adie, 1 eiyelé, 1 epo, 1 plato blanco, eko y 40 nira\n\nDestinatario: Osun e Ifá", "origen_id": "603aded5faede0b825ccb345"}, {"titulo": "Ofrenda complementaria 2", "texto": "1 eiyelé, 1 adie, cuentas, eko, 1 epo, 1 plato blanco y 45 nira\n\nDestinatario: Osun e Ifá", "origen_id": "1a13b599ba2ad1c0c6a83c93"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà pide devoción total; los varones deben iniciarse. Ọ̀ṣun da hijos. Ọbalúayé y las àjẹ́ en caso de enfermedad. Olúwẹri, espíritu del río. Tabúes: el gallo, la espinaca y cubrirse con mantón.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Osun", "origen_id": "c2abcf2fd69b187e21434061"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tẹ̀tẹ̀ (Amaranthus hybridus), ẹfun, aceite de palma, ẹ̀kọ (pastel de maíz), cuentas, palangana nueva."}, {"titulo": "Prohibiciones de los relatos", "pasajes": [{"titulo": "Ofrenda complementaria 2", "texto": "gallo; espinaca", "origen_id": "b191de63180dcd24a08e2baa"}]}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 14.1 (yorùbá): Qkan awo Olúigbó: / li o difá f'Ọ̀rúnmìlà, / nigbi Ọ̀rúnmìlà mi lọ si lfẹ̀ / Wọ̀n ni: / \"iye ẹniti Ọ̀rúnmìlà ba tẹ̀ ko ni ikú\". / Ewé tẹ̀tẹ̀, ẹyẹlé Méjì / ati bẹẹbẹẹ ni ẹbọ / Ó gbọ ó rú. / Wọ̀n gbo ewé tẹ̀tẹ̀ sinu omi / kio fi fọ orí.", "Verso 14.2 (yorùbá): Adá-ilé-o-mukankan: / Il o difá fún lrẹn / niọ tọ̀ âwon Méjì ninu ọmọ Ọlófin. / Wọ̀n niki ó rúbo, / awọn ti o nlọ tẹ̀ ko ni ikú. / Ô gbọ̀ ó rú. / Wọ̀n ni: / \"Vọ ti lrẹn tẹ̀ Méjì ti wọ̀n ko kú / ki a ma pee ni: İrẹ-tè-Méjì\".", "Verso 14.3 (yorùbá): Odan-ab'orípẹgunpẹgun: / li o difá f'Akon. / Wọ̀n ni: / Iwá Akọn koniiba ti ọjà mu, / nitorinaa bi Akọn ba fẹ ki iwà oun / ba ti qjà mu kiowa rú: / Ata-epo ati aṣo olokoleti / Akọn kọ ko rú. / O wa di ojọ qjà, / Akon gbe ata epo rè ru, / o fi pantete, / bi o ti nfe lati da aṣo Olokoleti re bora, / bẹẹ ni ata (ikoko) epo rẹ yi tiosi si oju de, / o fo sii laṣo, / Epo ti o fo si Akon lara ni ojo naa / liosi wa ni ẹhin rẹ̀ titi di ònì yi. / Bi Ifa yi ba bi èniyan, / ki a kilą fun ẹni naa pe: / ko gbodẹ maafi aṣo-olokoleti bo'ra.", "Verso 14.4 (yorùbá): Adilu-abidiṣumuṣumu: / li o dífá f'Olúwẹri5s, / nigbi Olúwẹri mi lo ra Akon l'erú. / Wọ̀n n: / \"erú ti o nlọ rayi konjii / jẹki èniyàn tan ni qwọ̀ rè\". / Awo-titun, ewúrẹ / ati ẹfún li ebọ. / Olúweri gbọ̀ ó rú. / Akọn (bimọ) rẹ pupo. / Ọmo-èniyàn ni Olúwẹri ko ra l'erú. / Wón nbuu ni ibukubu wón si nló. / Akọn nikan ni ko lọ. / Ko çfún sinu awo titun / naa kiopa ewürẹ fún un.", "REZO: EYELEMERE AKORE AYARE EYELEMERE LAFIDAYA EYELEMERE AWAREI FENISHE KIA IFA AYE ADIFAFUN ORUNMILA, ADIFAFUN OSHUN, ADIFAFUN POROYE, PAÑUELOS MARUN ELEBO.", "REZO: EYELEMERE AKOLEMERE POROYE OMO NI OSHUN ONIBARABANIREGUN ORUNMILA MO IFA ONI AWO AKOLEMERE. ORUNMILA LORUBO.", "REZO: INSO RO EBO EI ASHE WADIPOLA ASHE WADIPOLA ODO LOFUN ALABEO ASHE WADIPOLA."]}]$q$::jsonb),
(15,'698070cea7ac1ba9e92453af9504fef2','7180ba6b12d759b20b548669af5f1ace',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Méjì es victoria sobre los enemigos y dominio de las dificultades. Es un tiempo de condiciones cambiantes en los negocios y en las relaciones, pero bueno para el amor y el dinero. Sus hijos llegan a viejos si ofrendan y cuidan su salud; deben fortalecer su fe en Ifá y confiar en su propia inteligencia, porque la falta de fe y de seguridad en sí mismos es su mayor tragedia. Para el amor y la prosperidad ofrecen a Ọ̀ṣun; para vencer a los adversarios, a Ṣàngó y a Ọ̀rúnmìlà.", "pasajes": [{"titulo": "Frase clave", "texto": "Ose crea abundancia a través del rezo.", "origen_id": "a6f63de124d7c93bfa2dba62"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su negocio o su relación pasa por altibajos y busca estabilidad.", "El dinero le llega y se le va (relatos de Ajé, la riqueza).", "Busca amor, matrimonio o hijos.", "Necesita recuperar la confianza y no dejar que el miedo lo domine.", "Va a viajar o quiere ser reconocido (relato de Òtú camino a Ijebu).", "Desea llegar a viejo con bienestar (relato de Arugbó).", "Hizo una ofrenda a medias y eso le afecta (relato de Èjì-Ọ̀ṣẹ́)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vejez larga con el cabello blanco.", "Que el mundo entero lo busque, como busca la riqueza.", "Ser una persona importante.", "Que los malos espíritus no puedan llevárselo.", "Recibir las bendiciones del mundo espiritual en la tierra."]}, {"titulo": "Ibi y advertencias", "puntos": ["Dudar de todo y de todos, aun de la verdad.", "Una riqueza que no se asienta en ningún lugar.", "Ofrendar solo una parte.", "Brujas que quieren llevarse a la persona."]}, {"titulo": "Enseñanza principal", "texto": "Solo la ofrenda salva al ser humano; la vida se vuelve amarga para quien no ofrenda. La cabeza de la tortuga no duele, el hígado del caracol no le duele, la piedra del fondo del río no siente frío."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "El Odù Ọ̀ṣẹ́ Méjì significa victoria sobre los enemigos y control sobre las dificultades.", "origen_id": "e888010bf513299ab315ae76"}, {"titulo": "Características generales", "texto": "Otros nombres: Ọ̀ṣẹ́ Méjì; Èjìòṣé.\nỌ̀ṣẹ́ Méjì es el décimo quinto Odù en el orden inalterable de Ọ̀rúnmìlà. Si los sacrificios adecuados son hechos, los hijos de Ọ̀ṣẹ́ Méjì vivirán hasta una edad avanzada, siempre que cuiden su salud. Para prosperar en la vida ellos tienen que fortalecer su creencia en Ifá y confiar en sus propias capacidades e inteligencias. Para obtener amor, lograr un matrimonio feliz y alcanzar la prosperidad financiera, tienen que hacer los sacrificios apropiados a Oṣun.\nSi Ọ̀ṣẹ́ Méjì es adivinado para un cliente, Ifá le dice que tiene muchos adversarios, para superarlos y conquistarlos, debe ofrendar sacrificios a Sàngó y Ọ̀rúnmìlà. Se cree que Ọ̀rúnmìlà posee enormes poderes para superar a todos los enemigos, tanto en la tierra como en el cielo. En Ọ̀ṣẹ́ Méjì Ifá nos enseña que solo los sacrificios pueden salvar a los seres humanos. La vida se convierte en desagradable para aquel que no sacrifica.\nEs importante para la persona con este Odù reforzar su fe y trabajar en su autoconfianza, no pueden tener miedo a enfrentar las dificultades.\nLa falta de fe, seguridad y autoconfianza en sí mismo es una tragedia para estas personas, si ellos logran sobreponerse a estos problemas lograrán tener control sobre las dificultades y vencer a sus adversarios (enemigos).", "origen_id": "017df691c3be5d8ee27144d3"}, {"titulo": "Interpretación tradicional", "texto": "Ose es el origen de abundancia y fertilidad en el mundo. Simbólicamente Ose está asociado con el agua fresca. La cultura histórica se desarrolla alrededor de manantiales de agua fresca. Ifá enseña que la abundancia y fertilidad son la consecuencia del uso apropiado del poder de la palabra en el rezo (aladura). En su manifestación negativa, el impulso hacia la abundancia puede remplazar al Espíritu como una forma de motivación. Porque Ifá enseña la creencia que los niños son una forma de abundancia. Ose incluye la fascinación de lo erótico como una expresión del deseo a procrear.", "origen_id": "3cf9ba0dc16641551c1fb5ab"}, {"titulo": "Orientación complementaria", "texto": "Ose es la bendición de una vida larga, abundancia y niños que Ifá dice viene a esos que desarrollan buen carácter. La resistencia al desarrollo del buen carácter es centrado en uno mismo y el origen de la avaricia.", "origen_id": "ddfae689f0d571185d684c39"}]}, {"titulo": "Relatos reunidos", "puntos": ["Los dos ancianos. A los ancianos les pidieron una gallina, dieciséis pedazos de ẹfun y una canasta colmada de algodón para llegar a viejos entre los Odù. Ofrecieron y vivieron hasta tener el cabello blanco. Al que envejeció mostrando sus canas entre los Odù se le llamó Àgbà Méjì, los dos ancianos.", "Èjì Ọ̀ṣẹ́ y los bastones rotos. Èjì Ọ̀ṣẹ́ iba a Ifẹ̀ y le pidieron ciento sesenta rollos de algodón y dieciséis bastones. Ofreció solo dos de cada cosa. En el camino se le rompieron los dos bastones, pero no murió, y se dijo: entre todos los Odù, el que rompe dos bastones y no muere se llama Ọ̀ṣẹ́ Méjì. Por haber ofrecido a medias, al hijo de este Odù le flaquea la fe: siempre cuestiona a los sacerdotes y le cuesta creer la verdad.", "La riqueza que todos buscan. La alegría adivinó para Ajé, la riqueza, y le dijo que el mundo entero andaría siempre buscándola. Le pidieron todo lo que la boca puede comer. Ofreció, y el mundo entero es feliz buscando a Ajé.", "La riqueza que no se asienta. Al gallo que usa la cresta como fuego adivinó para Ajé y le pidió, para que tuviera una vida asentada, la pata de un animal muerto sin cuchillo. Ajé se negó, y por eso hasta hoy la riqueza no se queda quieta en ningún lugar.", "Ọ̀rúnmìlà y los malos espíritus. Todos los malos espíritus del mundo querían llevarse a Ọ̀rúnmìlà. Él dijo que también tenía un dueño, su espíritu guardián, que lo libraría de sus manos. Fue con los pájaros blancos del termitero: unos le pidieron kola blanca, otros kola roja, y los que bajaron volando del termitero, pimienta de Guinea. Con eso le prepararon medicina contra la muerte, diciendo: la cabeza de la tortuga no duele, el hígado del caracol no duele, la piedra del fondo del río no siente frío; los malos espíritus no podrán llevárselo.", "La kola y sus hermanitos. La kola venía del cielo a la tierra y le pidieron ofrendar para que los seres humanos no la mataran. Los hermanos menores, los gajitos pequeños, ofrecieron; los mayores no. Por eso la gente parte la kola y se come los gajos grandes, y deja aparte los pequeños. Se mastica kola y se sopla después de marcar el Odù en la pared, para que las brujas no puedan llevarse a la persona.", "Ọ̀tú en Ìjẹ̀bú. Pórómisolé adivinó para Ọ̀tú, que iba de viaje a Ìjẹ̀bú. Ofreció, y desde ese día fue una persona importante.", "Túwàṣe y la bondad del cielo. Cuando llega la noche, las hojas del monte se transforman, y las hojas de gbódógi se vuelven persona: así adivinaron para Túwàṣe Ihùlóko, que quería traer a este mundo el bien del país de los inmortales. Ofreció, y desde ese día ese bien viajó hasta aquí. La fortuna de esta persona está repartida entre el mundo de los espíritus y el de los humanos."], "pasajes": [{"titulo": "Verso 15.1", "texto": "Titọni-nkun'le ti-nmuk'awotọ:\nadivinó Ifá para Arugbó (los ancianos).\nLes fue aconsejado sacrificar:\ngallina, una canasta llena de algodón\ny dieciséis ẹfun,\npara que ellos pudieran alcanzar\nla longevidad entre los Odù.\nEllos escucharon y sacrificaron.\nEllos vivieron hasta ser muy viejos,\ncon su pelo gris.\nAquel que envejeció\nmostrando su cabello gris entre los Odù\nes llamado Àgbàméji (los dos ancianos).", "origen_id": "680b058f9424097cabf25b78"}, {"titulo": "Verso 15.2", "texto": "Oṣẹkẹṣẹkẹ (la alegría):\nadivinó Ifá para Ajé (la riqueza),\nEl adivino dijo:\n\"el mundo entero\nsiempre estaria en busca de ella\".\nElla preguntó: ¿Cuál es el sacrificio?\nSe le dijo que sacrificara cosas comestibles.\nAjé escuchó y sacrificó.\nEl mundo entero está feliz\nde estar en busca de Ajé.\n55 Ohungbogbo ti enu i jẹ ni ebọ: Sacrificar todo aquello que la boca quisiera\ncomer.", "origen_id": "ab6f5ad2c1ca88ebc1c000ec"}, {"titulo": "Verso 15.3", "texto": "Akuko fi Ogbè orí ré ṣe iná:\nadivinó Ifá para Ajé (riqueza).\nA ella se le aconsejó sacrificar\npara alcanzar una vida asentada (estabilidad en un lugar)\nuna parte (pierna) de un animal muerto\nsin el uso de un cuchillo.\nAjé rehúso sacrificar.\nDebido a su negativa,\nhasta el día de hoy,\nAjé nunca se establece en ningún lugar.", "origen_id": "cf7cdc0c7caf1f6e32e8e3a4"}, {"titulo": "Verso 15.4", "texto": "Oluwowegbe'nú-igbó-tefá:\nadivinó Ifá para Èjì-Ọ̀ṣẹ́,\ncuando él estaba yendo a la tierra de lfe.\nle fue aconsejado sacrificar:\nciento sesenta rollos de lana de algodón\ny dieciséis bastones.\nEl sacrificó solo dos de cada elemento.\nCuando él iba en camino a lfè,\nlos dos bastones que el sacrificó se rompieron,\npero él no murió.\nEl Babaláwo dijo:\n\"de todos los Odù,\naquel que rompa dos bastones\ny no muera, deberá ser llamado Oṣéméji\".\nPor eso, cualquier nacido por este Ifá,\nle flaquea la fe, es decir,\nél siempre cuestionará a los Babaláwos.\nEsta persona encuentra difícil creer la verdad.", "comentario": "59 Ekiri Apadafa: pedazo de carne, pierna delantera de un animal que no haya muerto con el uso del cuchillo. N.T..: Significa que el pedazo de carne no debe ser de un animal sacrificado en ceremonia, ni a una deidad, puede ser de un animal cazado, o una pierna comprada en el mercado.", "origen_id": "0d307dba3741667d279d152f"}, {"titulo": "Relatos y ofrendas", "texto": "ÒSÉ MEJÌ\n\nPórómisolé consulta a Ifá para Ótú en el día que Ótú estaba haciendo un viaje a Ijebu. Ifá\naconsejó a Otú hacer ebo. Otú hizo ebo. Desde ese día, Otú fue una persona importante.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo para que sea considerada como una persona importante.\nEtutu (ofrecimientos): 1 eiyelé (pichón), 1 adie (ave), pastel de fríjol, 1 epo (botella de aceite de\npalma), eko (pastel de harina de maíz) y 40 nira (dinero), ofrecido a Orí.\n\n(Ett (oferendas); 1 eiyele (pombo), 1 adiye (ave), bolos de feijáo, 1 epo (garrafa de azeite\nde dendé), ekó (bolos de milho) e 40 nira (dinheiro nigeriano), oferecidos ao Orí.)\n\nCuando - viene - la - noche - las - hojas - del - bosque - se - transforman, mientras - las - hojas -\nGbódógi - se - transforman - en - una - persona, consulta Ifá para Túwase ihuloko en el día que\nTúwase lihuloko quería la bondad de la tierra de los inmortales para que se encontraran en la\ntierra. Ifá aconsejó a Túwase Ihuloko hacer ebo. Túwase Ihuloko hizo ebo. Desde ese día, la\nbondad de la tierra de los inmortales hizo el viaje a la tierra.\n\n97\n\nComentario:\n\nIfá dice que la buena fortuna de esta persona esta dividida entre el reino de: Espíritu y el reino de\nlos humanos. Ifá dice que debe hacer ebo para recibir las bendiciones del Espíritu de la tierra.\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 adie (ave), 1 epo (botella de aceite de palma), 1 plato\nblanco y 3 nira (dinero), ofrecido a Ori.\n\n(Ett (oferendas); 4 eiyele (pombo), 4 adiye (ave), 1 epo (garrafa de azeite de dendé), 1\nprato branco e 30 nira (dinheiro nigeriano), oferecidos ao Orí.)\n\nTr Tr\nI I\nTr Tr\nI I", "origen_id": "ad25c870f29bd139b912aeda"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Oşe Meji implica victoria sobre los enemigos y control sobre las\n                                                                 dificultades.\n              WO – Este es un momento para cambiar las condiciones en los\n  negocios y las relaciones de trabajo. Es un buen momento para el amor y\n                                                                    el dinero.\n                 Oşe Meji es el decimoquinto Odu en el inalterable orden de\n     Orunmila. Si son hechos los sacrificios adecuados, los hijos de Oşe Meji\nvivirán hasta una edad avanzada, velando por el cuidado de su salud. Ellos\n tambien tienen que fortalecer su creencia en Ifá y sus propias capacidades\n para prosperar en la vida. Para el amor, un matrimonio feliz y prosperidad\nfinanciera, deben ser hechos sacrificios apropiados a Osun. Si Oşe Meji es\n\nelegido por un cliente, Ifá dice que el cliente tiene muchos enemigos y\n para conquistarlos, debe ofrendar sacrificios a Şangó y Orunmila. Se cree\n  que Orunmila posee enormes poderes para superar a todos los enemigos,\n   tanto en la tierra como en el cielo. En Oşe Meji, Ifá nos enseña que sólo\n los sacrificios pueden salvar a los seres humanos. La vida es desagradable\n sin sacrificios. La falta de fe o de autoconfianza siempre es una tragedia.\n\n\n15.1 · TItoni-nkun´le ti-nmuk´awoto adivinó Ifá para Arogbo (el\n             anciano). Se le pidió que sacrificara 1 gallina, una jaula llena de\n            algodón y 16 bolas de cascarilla. Para que él pudiera alcanzar una\n         edad ventusta entre los Odu. Él escuchó y sacrificó. Él vivió para ser\n           viejo con el pelo gris. Cualquiera que llegue a la vejez con el pelo\n                     gris entre los Odu es llamado Agbomeji (los 2 ancianos).\n\n\n15.2 · Osekeseke (alegría) adivinó Ifá para Aje (riqueza) se le dijo que\n              el mundo entero siempre estaría en busca de ella. Ella preguntó\n                  “¿cuál es el sacrificio?”. Se le dijo que sacrificara toda cosa\n         comestible. Aje escuchó el consejo y ejecutó el sacrificio. El munto\n                                    entero está feliz de estar en busca de Aje.\n\n\n15.3 · Akuko fi ogbe ori re se ina adivinó Ifá para Aje (riqueza). A ella se le\n\n            aconsejó sacrificar cualquier animal matado sin un cuchillo (ekiri\n     apadafa) para alcanzar una vida estable. Aje rehusó sacrificar. Debido\n             a su negativa, hasta hoy en día, aje nunca se establece en ningún\n\nlugar.\n\n\n15.4 · Oluwewegbe´un-igbo-tefa adivinó Ifá para Eji-oşe. Cuando él iba a ir\n\n             a la tierra de Ife. Se le pidió que sacrificara 160 rollos de lana de\n     algodón y 16 bastones. Él sacrificó solo 2 de cada uno. Cuando iba en\n             el camino, los bastones que él sacrificó se rompieron, pero él no\n          murió. El Babalawo dijo: de todos los Odu, cualquiera que rompa 2\n                           bastones y no muera deberá ser llamado Oşe Meji.\n          Por tanto, cualquiera nacido por este Ifá carece de fe, o sea siempre\n             cuestionará a los Babalawos, porque encuentra difícil creer en la\n                                                                          verdad.", "origen_id": "b622bc09ab54857167db7049"}, {"titulo": "Relato en inglés 1", "texto": "Akgda, the diviner of “One who owns soil,” and “Too long,” the diviner of\n“Causer of pain,” were the ones who cast Ifa for Qrunmila on the day that all the\nevil spirits in the world wanted to carry him away. He said that he, too, had a\nmaster® as they did, and that his master would deliver him from their hands and\nnot let them carry him away.\n\nHe went to the white birds inside the termite hill, to the white- spotted birds\non the left side, and to the white birds who flew to earth from inside the termite\nhill. The white birds inside the termite hill said that Qrunmila should bring\nwhite kola. The white-spotted birds on the left side said Qrunmila should bring\nred kola. The white birds who flew to earth from inside the termite hill said\nthat Qrunmila should bring Guinea pepper.‘ They pounded these things to make\negiri medicine? for Ọrunmila. They said, “The head of tortoise does not ache;\nthe liver of snail does not hurt him; the stone at the bottom of the river does not\nfeel cold.’ They said that the evil spirits would not be able to carry him away.\nWe will pour the divining powder into the stew and eat its", "comentario": "1. The title of one of the diviners of the King of Ife. (See Chapter X.)\nSomething that is too long.\n3. The ancestral guardian soul is sometimes referred to as one’s “master”\n\n(gga).\n\n4, Aframomum melegueta, also known as Maleguetta pepper or “Alligator\nPepper.”\n\n5. Egiri is a kind of medicine to prevent death.\n\n6. After the figure Qs¢ Meji is marked in the divining powder and this\nverse has been recited, the powder is added to a stew made of a small tortoise\nand a small snail, which are removed from their shells, and white kola, red kola,\nGuinea pepper, salt, pepper, and palm oil. This is a charm or medicine to pre-\nvent death known as “not-die” (aiku) or “not-see-death” (ariku, a ri iku); egiri,\nmentioned in the verse was said to be another name for such a charm. Cf. the\nverse recorded by Lijadu (1923: 26).", "origen_id": "ec8e82fe59ae3189b1d69345"}, {"titulo": "Relato en inglés 2", "texto": "We will mark Ọgẹ Meji on the side of a wall with chalk and camwood.!\n\n“Grey hairs make their home on the heads of the aged; dry palm leaves can-\nnot carry burdens? on their shoulders” was the one who cast Ifa for Kola, when\nthey were coming from\n\nheaven to earth. They said that they should sacrifice so that human beings would\nnot be able to kill them. Their little junior siblings were the ones who made the\nsacrifice; the elder siblings did not sacrifice. The junior siblings are the small\nsections of kola nuts® that we set aside. From that time on, people have been\nkilling Kola.*\n\nWe will chew kola and blow it out after we have marked the figure on the\nwall, so that witches will not be able to take this person.\" Three cocks and nine\npence is the sacrifice.", "comentario": "1, The figures Ọṣẹ meji and Ofun meji can be seen drawn for protection in\nchalk and camwood on the wall of houses. Cf. verse 256-6.\n\n2, Literally “do not see the affair of an atiro,’ which is a basketry frame-\nwork used for carrying bundles.\n3. The tiny bits or natural segments (awe) of the kola nut (Cola acuminata)\nare not eaten but picked out and set aside. The verse explains why this is so,\nand why the larger segments are eaten.\n\n4. To split kola is spoken of as to “kill it”; the meaning is that it is eaten.\n\n5, Literally “to encircle,” referring to the fact that a kola nut can be en-\nclosed in the hand; but the meaning here is that they will not be able to kill him.", "origen_id": "10b393128706c314aab36af4"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la vejez: una gallina, una canasta de algodón y dieciséis pedazos de ẹfun.", "Para el viaje: ciento sesenta rollos de algodón y dieciséis bastones, completos.", "Para atraer la riqueza: todo lo que la boca puede comer.", "Para que la riqueza se asiente: la pata delantera de un animal muerto sin cuchillo.", "Contra la muerte: kola blanca, kola roja y pimienta de Guinea; el Odù se marca en iyẹ̀ ìròsùn y se echa en un guiso de tortuguita y caracol pequeño con sal, pimienta y aceite de palma, y se come.", "Contra las brujas: marcar Ọ̀ṣẹ́ Méjì en la pared con ẹfun y osùn; tres gallos y dinero.", "Para ser importante: una paloma, un ave, buñuelos de frijol, aceite de palma, ẹ̀kọ y dinero para Orí.", "Para las bendiciones del cielo: cuatro palomas, cuatro aves, aceite de palma, un plato blanco y dinero para Orí."], "pasajes": [{"titulo": "Ofrenda en el verso 15.1", "texto": "Titọni-nkun'le ti-nmuk'awotọ:\nadivinó Ifá para Arugbó (los ancianos).\nLes fue aconsejado sacrificar:\ngallina, una canasta llena de algodón\ny dieciséis ẹfun,\npara que ellos pudieran alcanzar\nla longevidad entre los Odù.\nEllos escucharon y sacrificaron.\nEllos vivieron hasta ser muy viejos,\ncon su pelo gris.\nAquel que envejeció\nmostrando su cabello gris entre los Odù\nes llamado Àgbàméji (los dos ancianos).", "origen_id": "93bdc751b6e836eb7896d287"}, {"titulo": "Ofrenda en el verso 15.2", "texto": "Oṣẹkẹṣẹkẹ (la alegría):\nadivinó Ifá para Ajé (la riqueza),\nEl adivino dijo:\n\"el mundo entero\nsiempre estaria en busca de ella\".\nElla preguntó: ¿Cuál es el sacrificio?\nSe le dijo que sacrificara cosas comestibles.\nAjé escuchó y sacrificó.\nEl mundo entero está feliz\nde estar en busca de Ajé.\n55 Ohungbogbo ti enu i jẹ ni ebọ: Sacrificar todo aquello que la boca quisiera\ncomer.", "origen_id": "12f16a491db77d773db245b5"}, {"titulo": "Ofrenda en el verso 15.3", "texto": "Akuko fi Ogbè orí ré ṣe iná:\nadivinó Ifá para Ajé (riqueza).\nA ella se le aconsejó sacrificar\npara alcanzar una vida asentada (estabilidad en un lugar)\nuna parte (pierna) de un animal muerto\nsin el uso de un cuchillo.\nAjé rehúso sacrificar.\nDebido a su negativa,\nhasta el día de hoy,\nAjé nunca se establece en ningún lugar.", "origen_id": "70fcf9d8f456157dff8aa6e9"}, {"titulo": "Ofrenda en el verso 15.4", "texto": "Oluwowegbe'nú-igbó-tefá:\nadivinó Ifá para Èjì-Ọ̀ṣẹ́,\ncuando él estaba yendo a la tierra de lfe.\nle fue aconsejado sacrificar:\nciento sesenta rollos de lana de algodón\ny dieciséis bastones.\nEl sacrificó solo dos de cada elemento.\nCuando él iba en camino a lfè,\nlos dos bastones que el sacrificó se rompieron,\npero él no murió.\nEl Babaláwo dijo:\n\"de todos los Odù,\naquel que rompa dos bastones\ny no muera, deberá ser llamado Oṣéméji\".\nPor eso, cualquier nacido por este Ifá,\nle flaquea la fe, es decir,\nél siempre cuestionará a los Babaláwos.\nEsta persona encuentra difícil creer la verdad.", "origen_id": "13df23fb28fd161d233a6077"}, {"titulo": "Ofrenda complementaria 1", "texto": "1 eiyelé, 1 adie, pastel de fríjol, 1 epo, eko y 40 nira\n\nDestinatario: Orí", "origen_id": "5b8069fe605db6840d5eca00"}, {"titulo": "Ofrenda complementaria 2", "texto": "4 eiyelé, 4 adie, 1 epo, 1 plato blanco y cantidad de dinero indicada en la fuente como 3 nira\n\nDestinatario: Orí", "origen_id": "9c5de4f2aa3d2dfd190250c1"}]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀ṣun da amor, matrimonio y dinero. Ṣàngó y Ọ̀rúnmìlà vencen a los adversarios. Orí recibe las ofrendas. Ajé, la riqueza.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Osun", "origen_id": "2bd7b64fe9b5c5258b87435b"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Algodón, ẹfun, osùn (polvo rojo), obì (kola blanca y roja), pimienta de Guinea, tortuga, caracol, bastones."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 15.1 (yorùbá): Titọni-nkun'le ti-nmuk'awotọ: / li o dífá f'Arugbó. / A niki ó rú: / abo-adiyẹ, ago-òwú / ati ẹfun mẹrindilógún, / ki oun le pa ewú s'ẹhin / ninu àwọn Odù. / Ó gbọ̀ ó rú. / Ó pa ewú s'ẹhin / Njẹ eyiti o pa ewú s'ẹhin ninu àwọn / Odù ki a maa pee ni: \"Àgbàméji.\"", "Verso 15.2 (yorùbá): Oṣekẹṣekẹ: / li o dífá f'Ajé, / wọ̀n ni: / \"tirẹ ṣa ni gbogbo ayé / yoo maafi ṣe nà iṣẹ\". / Ó ni: \"kini ẹbọ?\" / A niki o ba le ri bẹẹ, / Ohungbogbo ti enu i jẹ ni ebo. / Ajé gbọ̀ ó rú. / Gbogbo ayé si ńyğ le Ajé ṣẹkẹṣẹkẹ.", "Verso 15.3 (yorùbá): Akuko fi Ogbè orí rẹ̀ ṣe iná: / li o difá f'Ajé. / A niki Ajé / baa le ni ibujoko ki ó rú / Ekiri Apadafa / (Ekiri tiapa laifi obe kan an). / Odimdi kan. / Ajé kọ ko rú. / Nitorinaa titi o fi di ònì olóni yi, / Ajé kii joko s'ibi kan.", "Verso 15.4 (yorùbá): Oluwẹwẹgbe'nú-igbó-tẹfá: / li o difá f'Èji-Ọ̀ṣẹ́ / nhọ s'alẹ lfẹ̀. / Wọ̀n ni ki ó rú: / ati Opa mẹrindilögún. / Opa Méjì ati Qjo-òwú li ó rú. / Ó mura nlọ s'alẹ Ifẹ̀, / bi o ti niọ laipẹ loju ona, / opa Méjì tiorú ṣẹ tan, / ṣùgbọ̀n oun ko kú. / Njẹ Babaláwo ni: / \"Eyiti o ṣẹ opa Méjì / ninu awọn Odu ti ko ku, / ki a maa pee ni: Oséméji\" / Nitorinaa, bi Ifá yi ba bi èniyàn, / gni naa a maa déjà, eyini mipe, / oun yoo ma mu awon awo li eke / Eniti o ṣoro fün lati gba ótitọ̀ gbọ / ni eniti i maa d'gjá.", "REZO: OSHE ALADASHE ONIBARA BANIREGUN IFA MOLOKU FISHE, SHENSHE MOLOKU ADIFAFUN OSHUN.", "REZO: KULU KULOSHE MULUKO UN BABALAWO, LODIFAFUN KANTAPO NIBATI UNLO SIFE LLAMA ODESE ORUNRE OMO OROCO OMO ERAN NIBATI ATAPA OWO LODE ALLO LLIGOBO BOTON LOSI- LLE ONIBIRI. ILE LA POLEDI A UN BABALAWO LODIFAFUN BANLE QUERE ADEFUN.", "REZO: KULU KULUCHE OCHE MOLOCHA MONUKO BABA LODIFAFUN AKATAPON NIBATI INLO SILU LLAMA ADERE ORI ERE OMO AROCO INDE NIBATI OTABA UN ODERE ADIFAFUN ALLOLLI OGODO OTONOULO SILLELE ONI BINI ORUMILA ELBICAN ADIFAFUN YOKO OKANFUN ORUMILA ELBICAN LOLE CHIERE ELESE LELE OIGUA BOBO EBBO KURU ESHU OBINI ORULA OCHUBITANI LOLABE OMODE CEFE ECHUBI LENE AFOFO IGUA- GUO ORUBE.", "REZO: BABA ELLI MEYI KULU KULUCHE KOLLO TIBALOCUCHE OPECHE MULUKU MULUKU ADIFAFUN KAKATAMPO LLAMAGUO ODDUN IRE DEFUNGUO.", "REZO: KULU KULUCHE EYO KOBANI OCHE MULICU A UN BABALAWO LODIFAFUN ACANTAPO NIBATI INLOS ILE LLAMA EDERE ERUNLE OMO A ROCO OMO OCU OLEDE LA NO LA FUN ALLO IGO IGO DOBOTONLE SILE OMI BINI.", "REZO: CHUBU CHERE CHERE ABARE CHERE ACHOLLUA A UN MELLILI ADIFAFUN ARUROYO TICHOMO QUIYA ECHUBU SHERE SHERE ASHE UN EYO AUN MEYIYI SHERE SHERE ADIFAFUN ELLEROLLETON CHOME Y CANA OGUN.", "REZO: OSHE MEYI ORULA EBACUNLO BOBEOMODI OCHUBU CHU OBINI ORUMILA NISISI EBOCORALOLA COCHUBU TENUTIA ORUNLA OCHUBU IRE OWO IRE OMO IRE ARICU BABAGUA.", "SUYERE: IKU IWA KALERO ARUN ILE KALERO EGGUN IWA ILE KALERO. OSHUN WERE WERE ODO OLUN OSHUN KANI SHENSHE LEBO AWO APETEVI NI MALE ILE BANAKUESI OWO IYE LODAFUN OWUNKO FI SI EBBO. SHENSHE OLOWO OSHUN SHENSHE OLOWO OSHUN SHENSHE OLOWO IYA KUENI MOWO OYE SHENSHE OLOWO OSHUN. SHENSHE OLOWO YALORDE MAYEO.", "REZO: KULU KUKUSHE OSHE MULUKU MULUKU LODIFAFUN KANTAPONI- BATI UNLO SILE YAMA ODERE ORUNRE OMO ROCO ERAN NIBATI ATABA AWO LODE LODAFUN AYO YIGODO BUTON LOSILE YALORDE OBINI ORULA ESHUBA TANI ESHUBA LOLA IRE OWO IRE OMO IRE ARIKU BABAGUA.", "REZO: ADDO BUELEGE ADDO BUELEGE AYA, ADIFAFUN AKATAPULTA, KAFEREFUN YALORDE."], "pasajes": [{"titulo": "suyere", "texto_ritual": "AYEFOYU OLOFIN FISHOWA KAYOSHE OU OLOFIN, LODAFUN ORUNMILA.", "origen_id": "193c8097674b5b2de17dc9e7"}, {"titulo": "suyere", "texto_ritual": "BABA AWO OSHE OSHE MOWA OSHE OSHE.", "origen_id": "222dba1570c2e055c53d5bd2"}]}]$q$::jsonb),
(16,'04bae5b381582a1676f616f3c640d9fe','677f1c5839af915f453de72610d309bc',$q$[{"titulo": "Idea central", "texto": "Òfún Méjì, también llamado Ọ̀ràngún Méjì, es buena fortuna de dinero y una vida de dar y recibir con paciencia y compromiso: con las ofrendas correctas el éxito está asegurado. Las cosas están floreciendo. Sus hijos son generosos y, aunque no siempre tengan riquezas, son ricos en sabiduría. No deben vivir donde el viento sopla fuerte porque se sofocan con facilidad. Para prosperar ofrecen a Ajé y a Olókun, y lo más importante es ser bondadosos con los extraños, con la familia y sobre todo con los pobres. Para una mujer joven anuncia embarazo; para quien viaja, un buen viaje si ofrenda.", "pasajes": [{"titulo": "Frase clave", "texto": "Ofun crea la respuesta a rezos que se manifiestan como un milagro.", "origen_id": "7827bb31eaaa3b7388b1d764"}]}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Algo empieza a florecer y necesita sostenerlo con paciencia y compromiso.", "Busca dinero, aunque ya tiene otros bienes: conocimiento, amigos o capacidad de ayudar.", "Va a viajar y quiere que le vaya bien.", "Pregunta por hijos o por el futuro de la familia (relato de Ọlọ́fin y los dieciséis Odù).", "Tiene una deuda u obligación pendiente, quizá heredada (relato de la deuda de las madres de los Odù).", "Siente oposición y busca apoyo (relato de Eléjiórangún).", "Espera respuesta a una petición, una obra o un proyecto (relato de Òrìṣànlá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fortuna de dinero.", "Autoridad que nadie puede cuestionar.", "Abundancia y todas las bendiciones que se necesitan.", "Vencer a los enemigos.", "Un viaje que sale bien.", "Ser cabeza de la familia por haber pagado por todos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Contentarse con tener hijos sin ofrecer por su prosperidad.", "Dificultades para respirar en lugares de mucho viento.", "Deudas de ofrenda que dejaron los mayores."]}, {"titulo": "Enseñanza principal", "texto": "Ningún Ifá es mayor que Èjì Ogbè y ningún signo es mayor que Òfún Méjì. Los sacerdotes no deben estar ansiosos por el dinero, sino por la sabiduría. El que paga por todos llega a ser cabeza de todos."}, {"titulo": "Caracterización y orientación", "pasajes": [{"titulo": "Caracterización", "texto": "Odù Òfún Méjì significa una buena fortuna monetaria. Este llama a tener paciencia y compromiso, o sea una vida de dar y recibir. Con los sacrificios correctos, el éxito quedará garantizado.", "origen_id": "4faadbe92f27f12a9b672f88"}, {"titulo": "Características generales", "texto": "Otros nombres: Òfún Méjì; Ejiòfün / ğràgünméji / Èjiòràgún.\nÒfún Méjì también llamado Ọ̀ràngúnméji es el decimosexto Odù en el orden establecido por Ọ̀rúnmìlà. Para una mujer joven Òfún Méjì implica la posibilidad de quedar embarazada y tener un bebé.\nLos hijos de Òfún Méjì son generosos, ellos pueden que no tengan riquezas, pero ellos serán siempre ricos en sabiduría. Ellos no pueden vivir donde el viento bate fuertemente porque ellos suelen sofocarse fácilmente. Muchos de ellos tienen dificultades en la respiración.\nPara la buena prosperidad financiera, los hijos de Òfún Méjì deberán realizar sacrificios a Ajé y a Olókun.\nLo más importante para ellos es dirigir la bondad hacia los extraños como a los miembros de su familia y especialmente a los necesitados y a los pobres. Si Òfún Méjì es adivinado para un cliente que está planeando un viaje, el cliente puede estar seguro que todo irá bien en el viaje si él o ella realizarán los sacrificios prescritos por Ifá.", "origen_id": "cf72ef779738b2234b343772"}, {"titulo": "Interpretación tradicional", "texto": "Ofun literalmente significa el Espíritu de Blanco. La referencia es a la luz blanca como el Origen de toda manifestación material. Todo lo que vemos en el mundo físico es literalmente creado por la luz. Ofun es el origen del fenómeno o manifestación en el universo. Es la clase de manifestación que regularmente es percibida como un milagro ó como la respuesta de esos rezos ofrecidos en Ose. En su manifestación negativa, Ofun es la creación del fenómeno a través de la invocación que es contraria a las ideas de armonía y balance que sostiene al crecimiento espiritual.", "origen_id": "0b67fe0f71e80ec280eb7563"}, {"titulo": "Orientación complementaria", "texto": "Ofun es descrito como la manifestación de lo milagroso. Ofun es visto solamente por milagros por esos que no entienden la relación entre el reino visible e invisible. El milagro es normal para esos que entienden al awo. La interacción entre el reino visible y el invisible incluye la posibilidad de invocar ambos fenómenos creativo y destructivo. La invocación del fenómeno destructivo es disfunciónal porque es en oposición en el interior verdadero de uno mismo.", "origen_id": "af6c727ccf215f5109e7aa36"}]}, {"titulo": "Relatos reunidos", "puntos": ["Odù crea el carácter de todo. Odù iba a crear el carácter de todas las cosas que venían al mundo. Le pidieron cuatro postes, una calabaza grande con tapa y una cadena, y le aseguraron que nadie cuestionaría su autoridad si clavaba los cuatro postes juntos en la tierra, ponía encima la calabaza y se ataba los postes a las manos con la cadena. Así lo hizo, y el día en que Odù creó el carácter de las personas, los animales y todas las cosas se llamó Odùduwà. Creó todo lo que existe dentro de esa calabaza con tapa, y los seres humanos vivimos todos dentro de ella.", "Ọlọ́fin y los dieciséis hijos. Ọlọ́fin iba a dar a luz a los dieciséis Odù principales. Le dijeron que sus hijos serían pobres, y que si quería que fueran ricos debía ofrecer dieciséis calabazas de ñame machacado, dieciséis de ẹ̀kuru, dieciséis de ọ̀lẹ̀lẹ̀ y dieciséis carneras. Se negó: dijo que le bastaba con darlos a luz. Ofreció solo por sí mismo. Por eso los sacerdotes no deben ansiar el dinero sino la sabiduría y el poder. Además, a Èjì Ogbè y a los otros quince les pidieron ofrecer para pagar la deuda de ofrenda que dejaron sus madres, y se negaron: por eso los sacerdotes rara vez tienen riquezas, aunque son ricos en sabiduría.", "Ọ̀ràngún paga en la frontera. A Ọ̀ràngún Méjì le pidieron una carnera, dieciséis palomas y dinero. El sacerdote dividió la ofrenda y le dio la mitad para que, al volver a casa, rogara a su cabeza. Pero al llegar le avisaron que su madre lo esperaba en el campo junto con sus hermanos mayores, y se fue con ellos llevando los materiales. En la frontera el portero les cobró el paso. Èjì Ogbè, el mayor, no tenía el dinero, ni ninguno de los otros catorce; solo Ọ̀ràngún, el decimosexto, lo tenía, y pagó por todos. Al llegar al campo, los catorce decidieron hacer cabezas de la familia a Èjì Ogbè y a Ọ̀ràngún. Desde entonces se dice que ningún Ifá es mayor que Èjì Ogbè y ningún signo es mayor que Òfún Méjì, y por eso en el ìbò se decide a favor del que salga de los dos.", "Òrìṣàálá y la abundancia. Ogbè el forastero adivinó para Òrìṣàálá cuando buscaba abundancia y le pidió ofrendar para que todo lo que hiciera fuera aprobado. Ofreció y ese día recibió todas las bendiciones que necesitaba. Quien adora a Ọbàtálá debe ofrecerle comida con el rezo de este Odù.", "Eléjì Ọ̀ràngún entre enemigos. Todas las cosas aparecen como espinas que lastiman los pies: así adivinaron para Eléjì Ọ̀ràngún cuando estaba rodeado de enemigos. Ofreció, y desde ese día los derrotó. Este Odù pide ofrenda a Orò, que sostiene el esfuerzo contra los enemigos.", "El ojo que llegó a rey. Corremos a cortar caimitos, caminamos despacio a cortar caimitos, pero como no tenemos a nadie que cuide el árbol siempre los comemos verdes: así adivinaron para el Ojo cuando lo iban a hacer rey. Le pidieron dos palomas, dos huevos, dinero y un trozo de manteca de karité. Ofreció, y por eso nadie ve sin los ojos: el Ojo ve por todos. El Rey del Cielo creará un gran mercado de destino para alguien que afecte a toda su familia, y pondrá a un niño en una posición importante.", "Ifá, el que todos ridiculizaban. No se debe defecar en la finca del que no tiene tiempo de cuidarla, ni andar por su lindero, ni comer sus ñames: así adivinaron para Oníwọ̀nránólé, que es un nombre de Ifá, cuando la gente se burlaba de él una y otra vez. Le dijeron que en su vejez el mundo entero se reuniría a servirle. Ofreció una chiva, una rata, un pescado, una gallina y kola. Ifá dice que alguien a quien en su casa llaman perezoso será dueño de toda la casa.", "Ọ̀rúnmìlà y los cuatrocientos Òrìṣà ante la muerte. Cuando el Rey del Cielo mandaba a la muerte a llamar a los cuatrocientos Òrìṣà, Ọ̀rúnmìlà los reunió, cocinó una olla de caracoles, una de pescado y una de ratas, compró una canasta de papilla de maíz y sacó una tinaja de agua. Después de comer les dijo que fueran juntos y unidos al cielo, no de uno en uno. Pero ante Olódùmarè, los cuatrocientos acusaron a un hombre negro con cuentas ide al cuello de trastornar el mundo, y pidieron que no volviera a la tierra. Olódùmarè preguntó a Èṣù, que los vigilaba, y Èṣù dijo que mentían: ese hombre curaba a los enfermos, comía solo las ratas y pescados que le correspondían, y antes de venir les había dado de comer y beber a todos. Entonces Olódùmarè ató a los cuatrocientos en el cielo y mandó a Ọ̀rúnmìlà y a Èṣù de vuelta a la tierra. Por eso caracoles, pescado, ratas, papilla de maíz y agua se usan en las ofrendas, y por eso Ifá y Èṣù son tan importantes en la tierra. No se rompe un juramento con un amigo.", "El hijo enfermo de Ọ̀rúnmìlà. Ọ̀rúnmìlà y Èṣù encendieron un fuego de leña de munrun: así adivinaron para Ọ̀rúnmìlà cuando la salud de su hijo no era buena. Le pidieron un gallo, seis nueces de kola y dinero para que el niño no muriera. Ofreció y su hijo vivió. Ante un hijo enfermo, además de ofrendar, hay que llevarlo al médico.", "El viaje a Agege. Aṣinṣinrin, adivino del pueblo del Vengador; Ikandu, adivino del pueblo del Malhechor; y la hormiga que barre el suelo con la cola adivinaron para Ọ̀ṣun me da alegría, que es como una pelea repentina, cuando iba a Agege. Le pidieron siete ratas, siete pescados y dinero. Ofreció. Quien va a hacer un viaje a pie debe ofrecer para volver a casa contento."], "pasajes": [{"titulo": "Verso 16.1", "texto": "Ogbaragada:\nadivinó Ifá para Odù,\ncuando él iba a crear\nel carácter de todas las cosas\nque venian al mundo\nLe fue aconsejado hacer sacrificio:\ncuatro postes (pilares), igbá ademu\"\ny una cadena.\nÉl escuchó y efectuó el sacrificio,\nEl adivino le aseguró:\n\"Nadie podrá cuestionar su autoridad,\npara eso,\ndebe encajar los cuatro postes o pilares\njuntos en la tierra,\nsobre estos poner la igbá ademu,\ny usar la cadena\npara atar los pilares a sus manos\".\nÉl obedeció y ejecutó el sacrificio.\nEl día que Odù creó el carácter\nde todas las cosas en el mundo\n(personas, animales y todas las cosas)\nfue llamado Odùduà\n(Odù que creó todo lo que existe\nOòduà, Odùduwà, Olódumare).\nÉl creó todo lo existente dentro la igbá ademu.\nNosotros, los seres humanos,\nestamos viviendo todos dentro esa igbá ademu.\n\" igbå ademu: calabaza grande con tapa.", "origen_id": "9839215db6ca4f1ea9752174"}, {"titulo": "Verso 16.2", "texto": "Arugbo-ilé-fi-ire-sa-kẹjẹkẹjẹ:\nadivinó Ifá para Ọlófin,\ncuando El iba a dar nacimiento\na dieciséis Irúnmale\n(los dieciséis Odù principales)\nEl adivino dijo:\n\"sus hijos serán pobres\"\nSi Él quería que ellos adquirieran riquezas,\ndebía sacrificar:\ndieciséis igbá de ñame hervido machacado,\ndieciséis igbá ekuru,\ndieciséis igbá de olẹlẹ,\ny dieciséis carneras.\nỌlofin rehusó hacer el sacrificio.\nEl dijo que estaba contento\nsólo con dar nacimiento a sus hijos.\nÉl sacrificó sólo para sí mismo\ne ignoró los hijos\n(sacrificó para que nacieran,\nno para que fueran ricos).\nPor lo tanto los Babaláwos\nno deben estar ansiosos por obtener dinero,\nsino de adquirir sabiduría y poder\ndurante su tiempo de vida en el mundo.", "origen_id": "6b0b64db1dc37745ab2636c6"}, {"titulo": "Verso 16.3", "texto": "Bì a ba ni ki abu ilè,\nlẹ̀ a mọ ilẹ̀pa\nadivinó Ifá para Èjìogbè\ny para los otros quince Odù principales.\nLes fue aconsejado hacer sacrificio\npara pagar la deuda de sacrificio\nque debían sus madres.\nEllos rehusaron efectuar el sacrificio.\nEs por esto que los Babaláwos\nnunca poseen riquezas\naunque son ricos en sabiduría", "origen_id": "202640a2ea8f29c8782a6e74"}, {"titulo": "Verso 16.4", "texto": "Agbàgbà-ilúf'idikodi:\nadivinó para Oràngúnméji,\na quien se le pidió que sacrificara:\nuna carnera,\ndieciséis palomas\ny 3200 cowries.\nÉl escuchó y sacrificó.\nEl Babaláwo dividió los materiales del ebo\nen dos partes,\nmanteniendo la mitad para él\ny dándole la otra mitad a Ọ̀ràngúnméjì\npara usarla en rogar su cabeza (Orí)\ncuando retornara a casa.\nCuando llegó a la casa se le dijo a Ọ̀ràngún\nque su madre quería verlo a él\ny a sus hermanos mayores en el campo.\nPor lo tanto él no pudo efectuar el sacrificio\nde propiciar su Ori en la casa.\nTomando los materiales consigo,\nfue a reunirse con sus hermanos mayores\npara que todos pudieran visitar a su madre,\ncomo se los dijo.\nCuando llegaron a la frontera.\nel portero les pidió\nque pagaran el honorario de aduana.\nÈjìogbè, el líder de los Odù\nno tenía los 200 cowries pedidos\ny ninguno de los otros catorce Odù\ntenían dinero para pagar.\nSolo Orångún, el decimosexto Odù,\ntenía el dinero,\nel cual pagó por todos ellos\nantes de que pudieran cruzar la frontera\npara ir al campo.\nPor lo tanto cuando ellos llegaron al campo,\nlos catorce Odù restantes decidieron hacer\ntanto a Èjìogbè como Ọràngún\nla cabeza de la familia.\nDesde ese día,\nhemos llamado a Ọ̀ràngún \"Òfúnméji\"\nDesde ese día hemos dicho\n\"ningún Ifá es mayor que Èjìogbè\"\ny \"ningún signo es mayor que Ofúnméji\"\nPor esta razón cuando\nse hace adivinación con Ibo,\nsi Èjìogbè u Ofúnméji aparecen,\nsiempre se decide por el Ibo\nque este a su favor.", "origen_id": "f0bf04eaae4dfed9c899e861"}, {"titulo": "Relatos y ofrendas", "texto": "ORAGUN MÉ JÌ (ÒFÙN MÉJI)\n\nOgbe - el - extranjero - consulta a Ifa para Orisanlá cuando estaba buscando la abundancia. Ifá\naconsejó a Órisanla hacer ebo. Órisanlá hizo ebo. Desde ese día, Órisanla tuvo todas las\nbendiciones que necesitaba. Kiki ire (rezo para la buena fortuna):\n\nOgbe funfun kenewen o difa fun Orisánlá won ni ko. rúbo, pe.\n\nGbogbo. nkan to n'to ko ni wo, o rubó ojo ti gbogbo nkan to\n\nn'to ko wo mó niyen. Ase.\nOgbe el extranjero consulta a Ifá para Órisanlá que le dijeron que hiciera ebo para que todo lo\nque él estaba haciendo sería sancionado, el hizo ebo y ese fue el día que recibió todas las\nbendiciones que necesitaba. Que así sea.\n\nComentario:\nIfá dice que esta persona debe adorar a Obatalá. Ifá dice que si esta persona es un adorador de\nObatálá, debe de hacer ebo a Obatála para abundancia. Ifá dice que el ofrecimiento debe ser con\nrecitación de este Odu.\nEtutu (ofrecimiento): adimu Obatála.\n(Étùtù (oferendas); Àdìmú Òbàtálá)\n\nTodas -las - cosas - aparecen - como - espinas - que -afectan -los — pies -de - uno, consulta Ifá\npara Eléjiórangún en el día que estaba entre sus enemigos. Ifá aconsejó a Eléjiórangún hacer ebo.\nEléj!órangún hizo ebo. Desde ese día Eléjiorangún derrotó a sus enemigos.\n\nComentario:\n\nIfá dice que esta persona debe hacer ebo a Oro. /fa dice que Oro sostendrá el esfuerzo de esta\npersona para derrotar a sus enemigos.\n\nEtutu (ofrecimiento): 4 eiyelé (pichón), 4 adie (ave), 1 epo (botella de aceite de palma),\"1 plato\nblanco, eko (pastel de harina de maíz) y dinero determinado por el adivinador, ofrecido a Oro.\n(Ett (oferendas); 4 eiyele (pombo), 4 adiye (ave), 1 epo (garrafa de azeite de dendé), 1\nprato branco, ekó (bolos de milho) e certa quantia em dinheiro determinada pelo Awo,\noferecidos a Oro.)", "origen_id": "ebfdf831afa06d1ca6cce650"}, {"titulo": "Versión complementaria de los relatos", "texto": "Odu Ofun Meji significa una buena fortuna monetaria, es un llamado\n     a la paciencia y los compromisos. Una vida para dar y tomar. Con los\n                            sacrificios correctos, el éxito quedará garantizado.\n                                             WO – Las cosas están floreciendo.\n      Ofun Meji también llamado Orangun Meji es el decimosexto Odu en\n          el orden establecido por Orunmila. Para una mujer joven Ofun Meji\nimplica la posibilidad de quedar embarazada y tener un bebé. Los hijos de\n Ofun Meji son generosos, ellos pueden que no tengan riquezas, pero ellos\n\nserán siempre ricos en sabiduría. Ellos no pueden vivir donde el viento\n   bate fuertemente porque ellos suelen sofocarse fácilmente. Muchos de\n                                    ellos tienen dificultades en la respiración.\n    Para la buena prosperidad financiera, los hijos de Ofun Meji deberán\n                                        realizar sacrificios a Aye y a Olokun.\n      Lo más importante para ellos es dirigir la bondad hacia los extraños\n como a los miembros de su familia y especialmente a los necesitados y a\nlos pobres. Si Ofun Meji es llamado por un cliente que está planeando un\n viaje, el cliente debe asegurarse que todo vaya bien en el viaje y él o ella\n                                   realizarán los sacrificios prescritos por Ifá.\n\n\n16.1 · Ogbaragada adivinó Ifá para Odu cuando él iba a crear a todos\n           los diferentes personajes en el mundo. Se le aconsejó sacrificar 4\n            pilares y una cazuela grande teniendo una tapa y una cadena. Él\n    escuchó el consejo y efectuó el sacrificio, le fue asegurado que nadie\n                                                podría cuestionar su autoridad.\n          Por lo tanto, él debía tirar los 4 pilares en la tierra juntos, poner la\n    cazuela sobre ellos y usar la cadena para atar los pilares a sus manos.\n                      Él obedeció y ejecutó el sacrificio como se le instruyó.\n     El día que Odu creó a todos los personajes en el mundo fue llamado\n         Oduduwa (Odu que creó todo lo que existe Oduduwa, Olodomare).\n           Él creó todo lo existente en la cazuela. Nosotros (seres humanos)\n                                 estamos viviendo todos dentro de la cazuela.\n\n\n16.2 · Arugbo-ile-fi-ire-sa-kejekeje adivinó Ifá para Olofin, cuando Él\n           iba a dar nacimiento a 16 Ironmile (Odu principales) fue predicho\n         que los hijos serían pobres. Si él quería que ellos adquirieran dinero,\n          Él debía sacrificar 16 cazuelitas de harina de maíz, 16 cazuelitas de\n         frijoles blancos, 16 olele (hechos con frijoles colorados) y 16 ovejas\n              (carneros). Olofin rehusó hacer el sacrificio. El dijo que estaba\n     contento sólo con dar nacimiento a sus hijos. Él sacrificó sólo para sí\n                                                     mismo e ignoró los hijos.\n           Por lo tanto los babalawos nunca deben estar ansiosos por obtener\n                         dinero sino de adquirir sabiduría y poder en su vida.\n\n\n16.3 · Bi a ba ni ki abu ile, Ile a mo ilepa adivinó Ifá para Ejiogbe y\n             para los otros 15 Odu principales. Se les pidió pagar la deuda de\n                sacrificio propio para sus madres. Ellos rehusaron efectuar el\n             sacrificio. Es por esto que los Babalawos nunca poseen riquezas\n                                                 aunque son ricos en sabiduría\n\n\n16.4 · Agbagba–iluf´idikodi adivinó para Oragun Meji, a quien se le\n    pidió que sacrificara 1 oveja, 16 palomas y 3200 cowrie. Él escuchó y\n            sacrificó. El Babalawo dividió los materiales del ebo en 2 partes,\n          manteniendo la mitad para él y dándole al otra mtiad a Oragún para\n                    usarla para rogar su cabeza (ori) cuando retornara a casa.\n         Cuando llegó a la casa se le dijo a Oragun que su madre quería verlo\n          a él y a sus hermanos mayores en el campo. Por lo tanto él no pudo\n\nefectuar el sacrificio de propiciar su ori en la casa. Tomando los\n         materiales consigo, fue a reunirse con sus hermanos mayores para\n           que todos pudieran visitar a su madre, como se los dijo. Cuando\n         llegaron a la frontera, el oficial de aduana les pidió que pagaran el\n         honorario de aduana. Ejiogbe, el líder de los Odu no tenía los 200\n          cowrie pedidos y ninguno de los otros 14 Odu tenían dinero para\n     pagar. Sólo Oragun, el decimosexto Odu, tenía el dinero, el cual pagó\n          por todos ellos antes de que pudieran cruzar la frontera para ir al\n           campo. Por lo tanto cuando ellos llegaron al campo, los 14 Odu\n     restantes decidieron hacer tanto a Ejiogbe como Oragun la cabeza de\n          la familia. Desde ese día, hemos llamado a Oragun “Ofun Meji”.\n           Desde ese día hemos dicho “ningún Ifá es mayor que Ejiogbe y\n                                     ningún signo es mayor que Ofun Meji”\n     Por esta razón cuando obtenemos mucho ebo en la adivinación de Ifá\n         si Ejiogbe u Ofun Meji son elegidos siempre deciden en su favor.", "origen_id": "637115426794e588f90ae5fe"}, {"titulo": "Relato en inglés 1", "texto": "“We run to pick star apples,’ we walk leisurely to pick star apples; but since\nwe don’t have anyone at the place where star apples grow, we always have to eat\nthem unripened”* was the one who cast Ifa for Eye when he was going to be made\nking. They said Eye should sacrifice two pigeons, two chicken eggs, nine pence\nsix oninis, and a lump of shea butter. We will grind the shea butter with\n\nthe leaf “let me sit down”;? we will kill one of the two pigeons and add its blood;\nwe will break one egg onto the mixture; and with it we will rub our body. Eye\nmade the sacrifice.\n\nIfa says that there is someone for whom the Sky God will create a large\nmarket of destiny, which will affect all his family, just as Eye sees for every-\none.* And there is a young child whom the Sky God will place in a very impor-\ntant position; but he should make a very good sacrifice to avoid an enemy.", "comentario": "1. Seen. 3, verse 54-5,\n2. Because we have no one to watch them, the star apples are stolen as they\nripen, leaving us only unripened ones.\n3. Seen. 3, verse 249-4.\n4. This verse thus explains that, because he made the sacrifice, no one\ncan see without eyes.", "origen_id": "c229ccd526d4f64ab6780509"}, {"titulo": "Relato en inglés 2", "texto": "“Whether it is you or whether it is I, we are not permitted to defecate on\nthe farm of one who is too busy to look after it;1 if we do defecate on the farm\nof one who is too busy to look after it, we must not walk along the boundary of\nhis farm; if we do walk along the boundary of his farm, we must not eat his\nyams\"? was the one who cast Ifa for Oniwgnranole when people were ridiculing\nhim 40,000 times, when they were ridiculing him 60,000 times. They said all\nthe world would gather to serve him in his old age. Oniwgnranole is the name\nthat we call Ifa.3 One she-goat, a rat, a fish, a hen, and kola is the sacrifice.\n\nIfa says there is someone whom all the people of his house are insulting\n\nand are calling lazy; this person will own the entire house in the near future.\nAnd we want to do something; this thing will yield a profit eventually. The whole\nhouse will gather to serve someone in the near future.", "comentario": "1. Alairoju was interpreted as meaning one who is so busy that he doesn’t\nhave time to look after his farm; but the reference may be to a blind man.\n\n2. Prohibitions of this type are known as ghun. Informants compared them\nto tabus (ewg), but were unable to differentiate between them. If either is broken,\none suffers the consequences (jẹ ewọ, jẹ ghun). Abraham gives “I suffered the\npenalty” for ghun hun mi.\n\n3. It is understood that Ifa became so important because he made the sacri-\nfice.", "origen_id": "505f9beec9eb0fa6a156eba9"}, {"titulo": "Relato en inglés 3", "texto": "“Afinkin! is what kills slaves; broken oaths” are what kill friends; curses?\nare what kill thieves; and ancestors are what kill relatives’* and “If the market\nbreaks up suddenly, foreigners are left scattered here and there, traders re-\nmain, and those who have spread their wares for sale remain” were the ones\nwho cast Ifa for the Four Hundred Deities when the Sky God was sending Death\nto call them forty times, when he was sending Death to call them sixty times.\n\nWhen the Sky God sent Death to call all the Four Hundred Deities, Qrun-\nmila called them together. He cooked one pot of snails, one pot of fish, one pot\nof rats, and he bought one basket of cornstarch porridge and drew one jar full of\nwater for them, When they had finished eating and drinking, Qrunmila told them\nthat when they went to heaven this time, they should not go singly; they should go\ntogether and stand united; they should not walk alone. He said, because if they\nstayed together, the Sky God\n\nwould not be able to stop any one of them or be able to detain any one of them.\n\nWhen they came to the Sky God, all the Four Hundred Deities told him that\na black man who was wearing ide beads® around his neck was the one who was\nupsetting the world, and that therefore the Sky God should keep him in heaven\nand not let him return to earth any more.\n\nWhen the Sky God heard this, he called Eshu; he asked him “You are the one\nIhave set to watch them. What do you know about this person of whom they speak?”\nEshu answered, saying they were telling lies against Qrunmila. He said that when-\never any one was ill, the one they said these things about was the one who cured\nthem, and if he received rats or fish as a sacrifice, he only ate those that were\nmeant for him. And then Eshu said that when they were coming to the Sky God\nthis time, “Qrunmila cooked a pot of rats, a pot of fish, and a pot of snails, and\nhe drew a jar of water and bought a basket of cornstarch porridge for them; and\nthey ate and drank before they came before you, oh Olodumare.”\n\nWhen the King of the Sky heard this, he took all the Four Hundred Deities and\ntied them down in the sky; and he said that Qrunmila and Eshu should go back to\nearth. When these two arrived on earth, Qrunmila was happy and he began to\npraise his diviners and to sing:\n\n“We live on earth, we eat rats, oh;\n\n“We live on earth, we eat fish;\n\n“We drink calabashes of odu,” we eat snails.\n\n“Whatever happens concerns the oath that we took together;\n“You lived on earth, you broke your oath to me;\n\n“Whatever happens concerns the oath that we took together.”\n\nIfa says that we should not break an oath with a friend, lest we meet death\nunexpectedly. We have discussed something with someone who wants to break\nhis oath to us, but the people in heaven will judge and punish him. And then there\nis someone who is ill, he will not die; but someone else whom we have not even\nnoticed is the one who will die. All the things that Qrunmila sacrificed at that\ntime are what everyone uses in sacrificing at the present time.®\n\n(The lesson® of this Ifa verse is that “You must not bear false witness\nagainst your companions.’)", "comentario": "1. This could not be explained by informants; but from the context it would\nseem to be something comparable to an oath or a curse. Idowu (1962: 52) gives\nit as Afinti, which he translates as tale-bearing, in a very similar introduction\nto a verse which he ascribes to Ogbe Meji.\n\n2. To take an oath is called to “drink ground” (mulẹ, mu ilẹ), and to break\nan oath to “break ground” (da ile).\n\n3. Seen. 4, verse 248-4.\n\n4. According to informants “those born together” (ajgbi) refers to the an-\ncestors, and “those of one mother” (iyekan) is used loosely here to mean those\nrelated by either the father or the mother. A person who is accused of making\nbad medicine against such a relative or of having sexual relations with a relative’s\nwife is made to take an oath of his innocence. He must eat kola in the main cham-\nber of the compound and repeat “May the ancestors kill me” (if I am guilty) [Ki\najgbi pa mi]. This type of an oath, taken only when there is a dispute within the\nfamily, is considered extremely dangerous, even more so than the public oaths by\nthe Ogunladin in the Qni’s palace. Idowu (1962: 52) gives Alajgbi, translated as\nconsanguinity.\n\n5. When something happens in the market, the customers leave, but those\nwho sell in the market stay to protect their wares, and people who have come from\nother towns remain because they have nowhere else to go.\n6. Ide are the kind of beads worn by babalawo (see Chapter IX), identifying\nthe “black man” as Qrunmila.\n7. Informants could not explain the meaning of odu in this context.\n\n8. The verse explains why snails, fish, rats, cornstarch porridge, and water\nare used in sacrifices to Qlgrun, and why Ifa and Eshu are so important on earth.\n\n9. This moral, which is not recited by the diviners as part of the Ifa verse,\nwas added by the interpreter.", "origen_id": "48d7301ad86878f10860b530"}, {"titulo": "Relato en inglés 4", "texto": "\"Death kindles a fire of epin wood; disease kindles a fire of ita wood; Witches\nand Eshu kindle a fire of munrun-munrun wood”! was the one who cast Ifa for\nQrunmila when his child's health was not good. They said he should sacrifice one\npigeon,", "comentario": "1. Munrun-munrun is an unidentified tree. Firewood from the ita tree (Celtis\nSoyauxii, C. Zenkeri, C. Adolfi-Frederici) is important among the gifts to the\nwife's relatives at marriage. Epin is the Sandpaper tree (Ficus asperifolia).", "origen_id": "535accc71c1bc7c006001955"}]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la autoridad: cuatro postes, una calabaza grande con tapa y una cadena.", "Para hijos prósperos: dieciséis calabazas de ñame machacado, de ẹ̀kuru y de ọ̀lẹ̀lẹ̀, y dieciséis carneras.", "Para la cabeza: una carnera, dieciséis palomas y dinero.", "Para Ọbàtálá: ofrenda de comida (àdìmú) con el rezo del Odù.", "Contra los enemigos: cuatro palomas, cuatro aves, aceite de palma, un plato blanco, ẹ̀kọ y dinero para Orò.", "Para el destino: dos palomas, dos huevos, dinero y manteca de karité; molerla con hojas de 'déjame sentarme', la sangre de una paloma y un huevo, y frotarse el cuerpo.", "Para ser servido en la vejez: una chiva, una rata, un pescado, una gallina y kola.", "Contra la muerte: caracoles, pescado, ratas, papilla de maíz y agua compartidos.", "Protección: marcar Òfún Méjì en la pared con ẹfun y osùn, mascar kola, soplarla y decir que todo mal que venga sobre uno perezca.", "Por el hijo enfermo: un gallo, seis nueces de kola y dinero.", "Para el viaje: siete ratas, siete pescados y dinero."], "pasajes": [{"titulo": "Ofrenda en el verso 16.1", "texto": "Ogbaragada:\nadivinó Ifá para Odù,\ncuando él iba a crear\nel carácter de todas las cosas\nque venian al mundo\nLe fue aconsejado hacer sacrificio:\ncuatro postes (pilares), igbá ademu\"\ny una cadena.\nÉl escuchó y efectuó el sacrificio,\nEl adivino le aseguró:\n\"Nadie podrá cuestionar su autoridad,\npara eso,\ndebe encajar los cuatro postes o pilares\njuntos en la tierra,\nsobre estos poner la igbá ademu,\ny usar la cadena\npara atar los pilares a sus manos\".\nÉl obedeció y ejecutó el sacrificio.\nEl día que Odù creó el carácter\nde todas las cosas en el mundo\n(personas, animales y todas las cosas)\nfue llamado Odùduà\n(Odù que creó todo lo que existe\nOòduà, Odùduwà, Olódumare).\nÉl creó todo lo existente dentro la igbá ademu.\nNosotros, los seres humanos,\nestamos viviendo todos dentro esa igbá ademu.\n\" igbå ademu: calabaza grande con tapa.", "origen_id": "d0c5d8414b6c280921366d2b"}, {"titulo": "Ofrenda en el verso 16.2", "texto": "Arugbo-ilé-fi-ire-sa-kẹjẹkẹjẹ:\nadivinó Ifá para Ọlófin,\ncuando El iba a dar nacimiento\na dieciséis Irúnmale\n(los dieciséis Odù principales)\nEl adivino dijo:\n\"sus hijos serán pobres\"\nSi Él quería que ellos adquirieran riquezas,\ndebía sacrificar:\ndieciséis igbá de ñame hervido machacado,\ndieciséis igbá ekuru,\ndieciséis igbá de olẹlẹ,\ny dieciséis carneras.\nỌlofin rehusó hacer el sacrificio.\nEl dijo que estaba contento\nsólo con dar nacimiento a sus hijos.\nÉl sacrificó sólo para sí mismo\ne ignoró los hijos\n(sacrificó para que nacieran,\nno para que fueran ricos).\nPor lo tanto los Babaláwos\nno deben estar ansiosos por obtener dinero,\nsino de adquirir sabiduría y poder\ndurante su tiempo de vida en el mundo.", "origen_id": "250541655dc8fdb6a187ce54"}, {"titulo": "Ofrenda en el verso 16.3", "texto": "Bì a ba ni ki abu ilè,\nlẹ̀ a mọ ilẹ̀pa\nadivinó Ifá para Èjìogbè\ny para los otros quince Odù principales.\nLes fue aconsejado hacer sacrificio\npara pagar la deuda de sacrificio\nque debían sus madres.\nEllos rehusaron efectuar el sacrificio.\nEs por esto que los Babaláwos\nnunca poseen riquezas\naunque son ricos en sabiduría", "origen_id": "20bef5694d64affe05f9b2c7"}, {"titulo": "Ofrenda en el verso 16.4", "texto": "Agbàgbà-ilúf'idikodi:\nadivinó para Oràngúnméji,\na quien se le pidió que sacrificara:\nuna carnera,\ndieciséis palomas\ny 3200 cowries.\nÉl escuchó y sacrificó.\nEl Babaláwo dividió los materiales del ebo\nen dos partes,\nmanteniendo la mitad para él\ny dándole la otra mitad a Ọ̀ràngúnméjì\npara usarla en rogar su cabeza (Orí)\ncuando retornara a casa.\nCuando llegó a la casa se le dijo a Ọ̀ràngún\nque su madre quería verlo a él\ny a sus hermanos mayores en el campo.\nPor lo tanto él no pudo efectuar el sacrificio\nde propiciar su Ori en la casa.\nTomando los materiales consigo,\nfue a reunirse con sus hermanos mayores\npara que todos pudieran visitar a su madre,\ncomo se los dijo.\nCuando llegaron a la frontera.\nel portero les pidió\nque pagaran el honorario de aduana.\nÈjìogbè, el líder de los Odù\nno tenía los 200 cowries pedidos\ny ninguno de los otros catorce Odù\ntenían dinero para pagar.\nSolo Orångún, el decimosexto Odù,\ntenía el dinero,\nel cual pagó por todos ellos\nantes de que pudieran cruzar la frontera\npara ir al campo.\nPor lo tanto cuando ellos llegaron al campo,\nlos catorce Odù restantes decidieron hacer\ntanto a Èjìogbè como Ọràngún\nla cabeza de la familia.\nDesde ese día,\nhemos llamado a Ọ̀ràngún \"Òfúnméji\"\nDesde ese día hemos dicho\n\"ningún Ifá es mayor que Èjìogbè\"\ny \"ningún signo es mayor que Ofúnméji\"\nPor esta razón cuando\nse hace adivinación con Ibo,\nsi Èjìogbè u Ofúnméji aparecen,\nsiempre se decide por el Ibo\nque este a su favor.", "origen_id": "10528aeb7f197c720d807999"}, {"titulo": "Ofrenda complementaria 1", "texto": "4 eiyelé, 4 adie, 1 epo, 1 plato blanco, eko y dinero determinado por el adivinador\n\nDestinatario: Oró", "origen_id": "5e279633b6bb7b8b86d62c98"}]}, {"titulo": "Relaciones espirituales", "texto": "Odùduwà, creador del carácter de todo. Ọlọ́fin, padre de los dieciséis Odù. Ajé y Olókun dan prosperidad. Ọbàtálá. Orò. Olódùmarè y Èṣù defienden a Ọ̀rúnmìlà.", "pasajes": [{"titulo": "Asociaciones tradicionales", "texto": "Yemo", "origen_id": "903c1bcd50d04a3939dcf035"}]}, {"titulo": "Plantas, alimentos y elementos", "texto": "Calabaza grande con tapa, ẹ̀kuru, ọ̀lẹ̀lẹ̀, ñame machacado, manteca de karité, caimito (ọsàn àgbàlùmọ̀), ẹfun, osùn, obì."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 16.1 (yorùbá): Ọgbaragada: / li o dífá f'Odù / mi a da dede Uwa / (Iwa-tabi gbogbo ohun ti o wa li ayé). / Wọ̀n niki ó rú: / Opo merin, / igbá ademu / ati ẹwọn. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"kosi eniti yoo maa yeẹ lowo wo / nitorinaa kiolo ri opo mẹrin na, / kio gbe igbá yen lee lori, / kiofi ewọn yen / Soo mọ owọ̀ ara rẹ̀\". / Ô gbọ̀ ó ṣe gbọ / naa si Ojude ara re / bi wọ̀n ti sọ fún un. / Ni ljọ ti Odù da gbogbo iwa / [Ohun ti o wa l'ayé) / li a tinpee ni Odùduà / (Odu ti o da gbogbo lwa, / Ooduà, Odùduwà, Olódùmarè) / Ninu igbá naa ni Oun da gbogbo / Uwa si, ninu igbá naa ni gbogbo / (eda-alaayé) wa wa yio.", "Verso 16.2 (yorùbá): Arugbo-ilé-fi-ire-sa-kẹjẹkẹjẹ: / wọ̀n dífá f'Ọlọ̀fin / nlọ bi Irúnmale mẹrindilógún. / Wọ̀n ni: / \"àwọn omọ na ko nii n'owó lọwọ\". / Nitori ki wọ̀n baa le ni owó lọwọ / ki wọ̀n rú: / İgba ewo mérindilógún, / igbá ekuru mẹrindilógún, / igbá olẹlẹ mẹrindilógún, / ati àgùtàn mẹrindilógún. / Ọlọ̀fin kọ ko rú. / Ó ni: bi oun ba ti bimo ṣa, o to, / ebọ ti ara rè lo rú. / Nitorinaa ni àwọn Babaláwo koṣe / nilati ma sare lati ko owó / jẹ bikoṣe lati ko Ọgbọ̀n ati Agbára / jọ ni gbogbo igba wọ̀n li ayé.", "Verso 16.3 (yorùbá): Bi a ba ni ki abu ilẹ̀, / llẹ̀ a mọ ilẹ̀pa: / li o difá f'Èjìogbè / ati àwon Odù Mẹṣdogun / tiiṣe Olódü yokun. / A ni ki wọ̀n rúbọ / ti Ìyá wọn kọsilẹ. / Wọ́n kọ wọ́n ko rú / Nitorinaa ni Babaláwo koṣe jẹ / Ọlọ̀rọ̀ ninu owó bikoṣe ninu Ọgbón.", "Verso 16.4 (yorùbá): Àgbàgbà-ilúf'idikodi, / a difá fOràngúnméji. / A ni ki ó rú: / àgùtàn kan, / ẹyẹlé mẹrindílógún / ati egberindílógún owó. / Ó gbọ̀ ó rú. / Babaláwo pin ohun ẹbọ si Méjì. / O ko apa kan fún ara rẹ̀, / o si ko apakeji fún Çràngúnméji / pe ki o lọ fi bọ Orí ara rè / nigbati o ba delé. / Bi Ọ̀ràngúnméji ti delé ni wọ̀n jiṣẹ / fún un pe lyá re / ti ranse de ilé pe ki oun / ati àwọn gbọ̀n rẹ̀ maa bo ni oko. / Nitorinaa oun ko duro bọ orí ara rè / mọ ni ilé. / O di àwọn ohun-ẹbo naa ru. / O lọ ba àwọn gbọ̀n rẹ̀ lati jüjọ lọ soko / lọ ba lyá wọ̀n gegẹ bi ati jiṣẹ fún un. / Nigbati wọ̀n de enu'bode, / Oni bode bere owó ibode lowo wọn. / Èjìogbè ti iṣe aṣiwaju / gbogbo àwọn Odù / ko ri igbio san fún Onibode, / bẹẹ ni àwọn Odù merinla ti o telee / ko ri owó san, / ayaafi Oràngúnméji, / tiiṣe Odù Ekerindílógún li o ri owó / ibode san ki gbogbo wọ̀n / to le koja los'oko. / Nitorinaa nigbati wọ̀n de oko tan / ni àwọn Odù iyokun wa fi / Ogbèméji ati Ọràngúnméji se olorí. / Lati ojo naa ni a ti npe / Ọ̀ràngúnméji ni \"Òfúnméji.\" / Lati ojọ naa ni a si ti nwipe: / \"A kii d'Ifá bori Èjìogbè, / A kii d'Ifá bori Öfúnméji\" / Nitorinaa biaba dibo tiada Èjìogbè / tabi Öfúnméji / àwọn li a o gba Ibo fun.", "/ OFUN MEYI", "REZO: ORAGUN MEYI ORUNMILA ADIFALLOCO LODAFUN OBATALA KUA SHANGO SHA OBATALA DICE EBICAN LOLO OGGUN SHURE SHANGO SHURE OYURE OBATALA IGUA OMO IGUA OSA OMO IGUA OSA OMO OBATALA ASHE OBATALA ASHE OLUO SHORERE SHANGO OGGUN GUALI GUAYU ENITI KUITICOLA OLORDUMARE.", "REZO: BABA ELLEGUN SIGUN JECUA BABA ORAGUN CAWO CAWOSILE ENI BABA ALA BABALUCHE BABA OMO LORUN ANIMU AUN NICU LODAFUN OBI AFANTICHE OMO ICU EBBO TETE EYELE MEYI AIKORDIE ITANA OBI EKU EYA EPO ABECA OWO.", "REZO: BABA ORAFUN CAIOSILE ONI LACHE BABA OMO REUN OMO ORUBO COLLAMORO ACHE QUINCHE OMI IKU.", "REZO: ORUNMILA ADIFALLOCO ADIFAFUN OBATALA IGUA OMO ERUN OMO ORUBO COLLAMORO ASHE OBATALA ACHOMO TARA OQUE OGUALI GUALLU KUITE KOLA MORCO KAFEQUE.", "REZO: BABA ELLEFUN LLEGUN JEKUA BABA JEKUA BABA ORAGUN KABIOSILE ONI BACHE OMO OLORUN MIOMIO OLORUN ABIMO AUN ICU LODAFUN OBI AFANTICHE OMO IKU OCHE LLEGUN ODAFIN DODO UMBATI LOCHORUN ORISHA IBA OCUNLE EBICAN LONLO COMA DEREU (HABLA YEWA, JEKUA, BABA ).", "REZO: OROFUN MAFUN YEWEDE OFUN LARA OBIRI EFURURU LAKOKU EFURU RU LAKOKE OKERE ORISHADI ARAYE KOWEDO BI BABA OROLU AWA NI", "KOMIO.", "REZO: ASHE OLUZO OLUZO LOBOKA OLUZOLE LOBERE OLUZOLE LOBI OPOLO IGBIN LABOKA LOKA YOGUN ORO BI LAÑERE ESE YOGUN ORUN IBI OPOLO YOGUN EGUI AYALI POPOLO DAFE EKO EBE EKO BOFENU LOLE AYARUN AKUKO, ADIE, ABERE, INIABA, OMI IFA NI EGGUN BABA.", "REZO IYESA: HABA AWA EYEGUN JERI JEKUA BABA AROWO ONIBOSHE BABA EMI OMO OLORUN OUN OMA ABIMO OLOKU LODA OBI EFAN UMBATI OBI EFAN OUN ARUGBO EBBO NURU OMO ABOKUN. ORAGUN MINIKUN ORIWAL LA ONA GURU GURU MOBA KPUI MINU MOBA KPUI YEYE MOBA KPUI NIKABO KUAN TARA TARA MIWAFUN ASHO HOWORUBO.", "REZO: IRE NISHE IYA ELEGBA IRE NISHE IYA OGGUN, IRE NISHE IYA OSHOSI, IRE NISHE IYA OSUN, IRE NISHE IYA GBOGBO ORUNMALE AYOKOTUN GBOGBO ORUMALE YOKOSI BARABA NIGERUN ADIFAFUN ORUNMILA.", "SUYERES: PEREGUN ALAWA LO TUN TUN. PEREGUN ALAWA LO TUN TUN BABA DE MALO AFIBO MINI. PEREGUN ALAWA LO TUN TUN.", "ORUN JUN JUN AWA MI MOKIO. ORUN JUN JUN AWA MI MOKIO. ORUN JUN JUN ORUN JUN JUN.", "ORAYE YEYEO ORAYE NITOWORO NITA NITA WORO AY IL GOGO AYAI GOGO AYAI AGOGORE.", "KAYE REREO OLOWAO KOBALOKUN OTA OBA YAREO OMO SHANGO OLABAO EGUSHE ARERE RIPIN OLALEKUN OBA YAREO.", "REZO: BABA ORAGUN AWA AYEWA BABA AIKA BABA AREWO ONI BASHE BABA AIKA OMI OMOLORUN AUN ABIMI ABEKE LEDA OBI EFUN OUN ABATI OBI EFUN OUN OZAIN ARUGBO EBBO KURU OMO ABOKU EBBO ABOKU EYELE EKO EKU AYAPA AWADO ORI.", "REZO: IREMI YABO IREMI YAYA ADIFAFUN ORUNMILA ADIFAFUN OGGUN ADIFAFUN SHANGO OGGUN OSHOSI ADIFAFUN OSUN ADIFAFUN OLOKUN OBA ARUGBO OKORO AYARE ADIFAFUN ELA."], "pasajes": [{"titulo": "Aseje awúré (Ofun Meji) — para la riqueza", "texto_ritual": "Onígorigo Ata sasa bani kemi amnire monda Loní ké munre temí wá fúnmi Ede loní kí ¡re temí ó dé loní Konko kú kó ohun olodo tówó tówó ni kí won Ó fi máá mú owu náá wá fúnmi Tówó tówó ni konko fi n kure fún olodo", "traduccion": "Onígorigo, ata sasa bani kemi amnire monda. Debes traerme todas mis bendiciones. Que lleguen todas hoy para mí. Las ranas nunca rechazan la voz del río. Es con mucho honor que deben traerme dinero. El honor es el que le da honor al dueño.", "origen_id": "3d021ca7d10d299140196f17"}]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from v where e.numero=v.numero and md5(e.secciones::text)=v.viejo and md5(v.sec::text)=v.nuevo returning e.numero;
